extract_generated_key_value() {
  local output=$1
  local key_kind=$2
  local key_label

  if [[ "${key_kind}" == "private" ]]; then
    key_label='[Pp]rivate'
  else
    key_label='[Pp]ublic'
  fi

  printf '%s\n' "${output}" | sed -nE \
    "s/^[[:space:]]*${key_label}([[:space:]]+|)[Kk]ey[[:space:]]*:?[[:space:]]*([^[:space:]]+)[[:space:]]*$/\\2/p" \
    | head -n 1
}

run_singbox_generate_command() {
  local subcommand=$1
  local label=$2
  local output

  if ! output=$("${SINGBOX_BIN_PATH}" generate "${subcommand}" 2>&1); then
    log_info "${label}生成原始输出: ${output}" >> "${SBV_LOG_FILE}"
    log_error "${label}生成失败，请查看 ${SBV_LOG_FILE}" >&2
  fi

  printf '%s' "${output}"
}

validate_warp_route_mode() {
  case "$1" in
    all|selective) return 0 ;;
    *) return 1 ;;
  esac
}

validate_instance_outbound_policy() {
  case "$1" in
    default|direct|warp) return 0 ;;
    *) return 1 ;;
  esac
}

outbound_policy_display_name() {
  case "$1" in
    direct) printf '强制 direct 出口' ;;
    warp) printf '强制 Warp 出口' ;;
    *) printf '跟随全局路由' ;;
  esac
}

prompt_instance_outbound_policy() {
  local prompt=${1:-"请选择出站策略"}
  local current=${2:-default}
  local default_choice choice

  validate_instance_outbound_policy "${current}" || current="default"
  if [[ ! -t 0 ]]; then
    printf '%s' "${current}"
    return 0
  fi

  case "${current}" in
    direct) default_choice=2 ;;
    warp) default_choice=3 ;;
    *) default_choice=1 ;;
  esac

  echo "实例出站策略:" >&2
  echo "1. 跟随全局路由" >&2
  echo "2. 强制 direct 出口" >&2
  echo "3. 强制 Warp 出口" >&2
  choice=$(prompt_choice "${prompt} [1-3] (当前: $(outbound_policy_display_name "${current}")): " 1 3 "${default_choice}")
  case "${choice}" in
    2) printf 'direct' ;;
    3) printf 'warp' ;;
    *) printf 'default' ;;
  esac
}

validate_inbound_stack_mode() {
  case "$1" in
    ipv4_only|ipv6_only|dual_stack) return 0 ;;
    *) return 1 ;;
  esac
}

validate_outbound_stack_mode() {
  case "$1" in
    ipv4_only|ipv6_only|prefer_ipv4|prefer_ipv6) return 0 ;;
    *) return 1 ;;
  esac
}

inbound_stack_mode_display_name() {
  case "$1" in
    ipv4_only) printf '仅 IPv4' ;;
    ipv6_only) printf '仅 IPv6' ;;
    dual_stack) printf '双栈' ;;
    *) printf '%s' "$1" ;;
  esac
}

outbound_stack_mode_display_name() {
  case "$1" in
    ipv4_only) printf '仅 IPv4' ;;
    ipv6_only) printf '仅 IPv6' ;;
    prefer_ipv4) printf 'IPv4 优先' ;;
    prefer_ipv6) printf 'IPv6 优先' ;;
    *) printf '%s' "$1" ;;
  esac
}

host_ip_stack_display_name() {
  case "$1" in
    dual) printf 'IPv4 / IPv6 双栈' ;;
    ipv6) printf '仅 IPv6' ;;
    *) printf '仅 IPv4' ;;
  esac
}

detect_host_ip_stack() {
  local has_ipv4="n"
  local has_ipv6="n"

  if command -v ip &>/dev/null; then
    if ip -o -4 addr show scope global 2>/dev/null | grep -q .; then
      has_ipv4="y"
    fi

    if ip -o -6 addr show scope global 2>/dev/null | grep -q .; then
      has_ipv6="y"
    fi
  fi

  if [[ "${has_ipv4}" == "y" && "${has_ipv6}" == "y" ]]; then
    printf 'dual'
  elif [[ "${has_ipv6}" == "y" ]]; then
    printf 'ipv6'
  else
    printf 'ipv4'
  fi
}

port_is_in_use() {
  local port=$1

  ss -H -tunlp 2>/dev/null | grep -Eq ":${port}[[:space:]]"
}

pick_random_high_port() {
  local port attempt

  for attempt in $(seq 1 128); do
    port=$((RANDOM % (SB_HIGH_PORT_MAX - SB_HIGH_PORT_MIN + 1) + SB_HIGH_PORT_MIN))
    if ! port_is_in_use "${port}"; then
      printf '%s' "${port}"
      return 0
    fi
  done

  for port in $(seq "${SB_HIGH_PORT_MIN}" "${SB_HIGH_PORT_MAX}"); do
    if ! port_is_in_use "${port}"; then
      printf '%s' "${port}"
      return 0
    fi
  done

  log_error "未找到 ${SB_HIGH_PORT_MIN}-${SB_HIGH_PORT_MAX} 范围内的可用端口。"
}

default_inbound_stack_mode() {
  case "$1" in
    dual) printf 'dual_stack' ;;
    ipv6) printf 'ipv6_only' ;;
    *) printf 'ipv4_only' ;;
  esac
}

default_outbound_stack_mode() {
  printf 'prefer_ipv4'
}

host_supports_inbound_stack_mode() {
  local host_stack=$1
  local inbound_stack_mode=$2

  case "${host_stack}:${inbound_stack_mode}" in
    dual:ipv4_only|dual:ipv6_only|dual:dual_stack|ipv4:ipv4_only|ipv6:ipv6_only) return 0 ;;
    *) return 1 ;;
  esac
}

infer_inbound_stack_mode_from_config() {
  local config_file=$1
  local host_stack=$2
  local listen_address

  listen_address=$(jq -r '.inbounds[0].listen // empty' "${config_file}" 2>/dev/null || true)
  case "${listen_address}" in
    0.0.0.0) printf 'ipv4_only' ;;
    ::)
      if [[ "${host_stack}" == "ipv6" ]]; then
        printf 'ipv6_only'
      else
        printf 'dual_stack'
      fi
      ;;
    *)
      default_inbound_stack_mode "${host_stack}"
      ;;
  esac
}

infer_outbound_stack_mode_from_config() {
  local config_file=$1
  local outbound_stack_mode

  outbound_stack_mode=$(jq -r '.dns.strategy // first(.outbounds[]? | select(.tag == "direct") | .domain_resolver.strategy) // empty' "${config_file}" 2>/dev/null || true)
  if validate_outbound_stack_mode "${outbound_stack_mode}"; then
    printf '%s' "${outbound_stack_mode}"
    return 0
  fi

  default_outbound_stack_mode
}

save_stack_mode_state() {
  mkdir -p "${SB_PROJECT_DIR}"
  cat > "${SB_STACK_STATE_FILE}" <<EOF
STACK_STATE_VERSION=1
INBOUND_STACK_MODE=${SB_INBOUND_STACK_MODE}
OUTBOUND_STACK_MODE=${SB_OUTBOUND_STACK_MODE}
EOF
}

load_stack_mode_state() {
  local host_stack saved_inbound saved_outbound

  host_stack=$(detect_host_ip_stack)
  SB_INBOUND_STACK_MODE=$(default_inbound_stack_mode "${host_stack}")
  SB_OUTBOUND_STACK_MODE=$(default_outbound_stack_mode)

  if [[ -f "${SB_STACK_STATE_FILE}" ]]; then
    # shellcheck disable=SC1090
    source "${SB_STACK_STATE_FILE}"
    saved_inbound=${INBOUND_STACK_MODE:-}
    saved_outbound=${OUTBOUND_STACK_MODE:-}

    if validate_inbound_stack_mode "${saved_inbound}" && host_supports_inbound_stack_mode "${host_stack}" "${saved_inbound}"; then
      SB_INBOUND_STACK_MODE="${saved_inbound}"
    fi

    if validate_outbound_stack_mode "${saved_outbound}"; then
      SB_OUTBOUND_STACK_MODE="${saved_outbound}"
    fi
    return 0
  fi

  if [[ -f "${SINGBOX_CONFIG_FILE}" ]]; then
    SB_INBOUND_STACK_MODE=$(infer_inbound_stack_mode_from_config "${SINGBOX_CONFIG_FILE}" "${host_stack}")
    SB_OUTBOUND_STACK_MODE=$(infer_outbound_stack_mode_from_config "${SINGBOX_CONFIG_FILE}")
  fi
}

ensure_stack_mode_state_loaded() {
  local inbound_valid="n"
  local outbound_valid="n"
  local current_inbound=${SB_INBOUND_STACK_MODE:-}
  local current_outbound=${SB_OUTBOUND_STACK_MODE:-}
  local host_stack

  host_stack=$(detect_host_ip_stack)

  if validate_inbound_stack_mode "${current_inbound}" && host_supports_inbound_stack_mode "${host_stack}" "${current_inbound}"; then
    inbound_valid="y"
  fi

  if validate_outbound_stack_mode "${current_outbound}"; then
    outbound_valid="y"
  fi

  if [[ "${inbound_valid}" == "y" && "${outbound_valid}" == "y" ]]; then
    return 0
  fi

  load_stack_mode_state

  if [[ "${inbound_valid}" == "y" ]]; then
    SB_INBOUND_STACK_MODE="${current_inbound}"
  fi

  if [[ "${outbound_valid}" == "y" ]]; then
    SB_OUTBOUND_STACK_MODE="${current_outbound}"
  fi
}

validate_protocol() {
  local runtime
  runtime=$(protocol_registry_field "$1" runtime_id) || return 1
  [[ "$1" == "${runtime}" ]]
}

protocol_display_name() {
  protocol_registry_field "$1" display_name || printf '%s' "$1"
}

default_node_name_for_protocol() {
  local protocol suffix

  protocol=${1:-vless+reality}
  case "${protocol}" in
    vless+reality) suffix="vless" ;;
    hy2) suffix="hy2" ;;
    anytls) suffix="anytls" ;;
    snell) suffix="snell" ;;
    tuic) suffix="tuic" ;;
    hysteria) suffix="hysteria" ;;
    naive) suffix="naive" ;;
    shadowtls) suffix="shadowtls" ;;
    mixed) suffix="mixed" ;;
    *) suffix="${protocol}" ;;
  esac

  printf '%s-%s' "$(hostname)" "${suffix}"
}

normalize_node_name() {
  local node_name=$1

  node_name=$(trim_whitespace "${node_name}")
  case "${node_name}" in
    *+vless) node_name="${node_name%+vless}-vless" ;;
    *+hy2) node_name="${node_name%+hy2}-hy2" ;;
    *+anytls) node_name="${node_name%+anytls}-anytls" ;;
    *+snell) node_name="${node_name%+snell}-snell" ;;
    *+tuic) node_name="${node_name%+tuic}-tuic" ;;
    *+hysteria) node_name="${node_name%+hysteria}-hysteria" ;;
    *+naive) node_name="${node_name%+naive}-naive" ;;
    *+shadowtls) node_name="${node_name%+shadowtls}-shadowtls" ;;
    *+mixed) node_name="${node_name%+mixed}-mixed" ;;
  esac

  printf '%s' "${node_name}"
}

network_stack_suffix_from_label() {
  case "$1" in
    IPv4|ipv4|v4) printf 'v4' ;;
    IPv6|ipv6|v6) printf 'v6' ;;
    *) printf '' ;;
  esac
}

node_name_for_network_stack() {
  local base_name=$1
  local address_label=${2:-}
  local stack_suffix

  base_name=$(normalize_node_name "${base_name}")
  stack_suffix=$(network_stack_suffix_from_label "${address_label}")
  if [[ -n "${stack_suffix}" ]]; then
    printf '%s-%s' "${base_name}" "${stack_suffix}"
  else
    printf '%s' "${base_name}"
  fi
}

bandwidth_limit_name_suffix() {
  local up_mbps=${1:-}
  local down_mbps=${2:-}
  local parts=()

  if [[ -n "${up_mbps}" ]]; then
    parts+=("U${up_mbps}M")
  fi
  if [[ -n "${down_mbps}" ]]; then
    parts+=("D${down_mbps}M")
  fi

  if [[ ${#parts[@]} -eq 0 ]]; then
    printf ''
  else
    local IFS='-'
    printf '%s' "${parts[*]}"
  fi
}

display_node_name_for_protocol() {
  local protocol=$1
  local base_name=${2:-}
  local address_label=${3:-}
  local up_mbps="" down_mbps="" bandwidth_suffix="" node_name

  protocol=$(normalize_protocol_id "${protocol}" 2>/dev/null || printf '%s' "${protocol}")
  base_name=$(normalize_node_name "${base_name}")
  if [[ -z "${base_name}" ]]; then
    printf ''
    return 0
  fi

  case "${protocol}" in
    vless-reality)
      up_mbps="${SB_VLESS_RATE_LIMIT_UP_MBPS:-}"
      down_mbps="${SB_VLESS_RATE_LIMIT_DOWN_MBPS:-}"
      ;;
    hy2)
      up_mbps="${SB_HY2_UP_MBPS:-}"
      down_mbps="${SB_HY2_DOWN_MBPS:-}"
      ;;
  esac

  bandwidth_suffix=$(bandwidth_limit_name_suffix "${up_mbps}" "${down_mbps}")
  node_name="${base_name}"
  if [[ -n "${bandwidth_suffix}" ]]; then
    node_name="${node_name}-${bandwidth_suffix}"
  fi

  node_name_for_network_stack "${node_name}" "${address_label}"
}

vless_reality_display_node_name() {
  local base_name=$1
  local address_label=${2:-}

  display_node_name_for_protocol "vless-reality" "${base_name}" "${address_label}"
}

protocol_inbound_tag() {
  protocol_registry_field "$1" default_tag
}

protocol_registry_record() {
  local requested=${1:-} record
  local fields=() aliases=() alias
  [[ -n "${requested}" ]] || return 1
  for record in "${SB_PROTOCOL_REGISTRY[@]}"; do
    IFS='|' read -r -a fields <<< "${record}"
    if [[ "${requested}" == "${fields[0]}" ]]; then
      printf '%s' "${record}"
      return 0
    fi
    # Bash 4.2 (CentOS 7) treats an empty array as unset under nounset.
    [[ -n "${fields[20]}" ]] || continue
    IFS=',' read -r -a aliases <<< "${fields[20]}"
    for alias in "${aliases[@]}"; do
      if [[ "${requested}" == "${alias}" ]]; then
        printf '%s' "${record}"
        return 0
      fi
    done
  done
  return 1
}

protocol_registry_field() {
  local record index
  local fields=()
  record=$(protocol_registry_record "${1:-}") || return 1
  IFS='|' read -r -a fields <<< "${record}"
  case "${2:-}" in
    state_id) index=0 ;;
    runtime_id) index=1 ;;
    agent_id) index=2 ;;
    family) index=3 ;;
    preset) index=4 ;;
    role) index=5 ;;
    type) index=6 ;;
    display_name) index=7 ;;
    default_tag) index=8 ;;
    menu_order) index=9 ;;
    client_export) index=10 ;;
    subman_type) index=11 ;;
    listen_networks) index=12 ;;
    traffic_networks) index=13 ;;
    minimum_project_core) index=14 ;;
    multi_instance) index=15 ;;
    certificate_contract) index=16 ;;
    share_formats) index=17 ;;
    probe) index=18 ;;
    handlers) index=21 ;;
    *) return 1 ;;
  esac
  printf '%s' "${fields[index]}"
}

protocol_registry_json() {
  printf '%s\n' "${SB_PROTOCOL_REGISTRY[@]}" | jq -Rn '
    def csv: split(",") | map(select(length > 0));
    [inputs | split("|") | {
      state_id: .[0], runtime_id: .[1], agent_id: .[2], family: .[3],
      preset: .[4], role: .[5], type: .[6], display_name: .[7],
      default_tag: .[8], menu_order: (.[9] | tonumber),
      minimum_project_core: .[14], aliases: (.[20] | csv),
      core_supported: true, implemented: true,
      available: null, availability_reason: "requires_instance_preflight",
      validated: {status: "not_assessed", method: .[18]},
      lifecycle: {deploy: true, takeover: true, edit: true, remove: true},
      client_export: (.[10] == "true"), subman_type: .[11],
      listen_networks: (.[12] | csv), traffic_networks: (.[13] | csv),
      multi_instance: (.[15] == "true"), certificate_contract: .[16],
      share_formats: (.[17] | csv), probe: .[18],
      legacy_capabilities: (.[19] | fromjson), features: (.[19] | fromjson), handlers: (.[21] | csv)
    }]'
}

component_registry_record() {
  local requested=${1:-} record
  local fields=()
  [[ -n "${requested}" ]] || return 1
  for record in "${SB_COMPONENT_REGISTRY[@]}"; do
    IFS='|' read -r -a fields <<< "${record}"
    if [[ "${requested}" == "${fields[0]}" ]]; then
      printf '%s' "${record}"
      return 0
    fi
  done
  return 1
}

component_registry_resolve_id() {
  local role=${1:-} type=${2:-} record
  local fields=()
  [[ -n "${role}" && -n "${type}" ]] || return 1
  for record in "${SB_COMPONENT_REGISTRY[@]}"; do
    IFS='|' read -r -a fields <<< "${record}"
    if [[ "${role}" == "${fields[1]}" && "${type}" == "${fields[2]}" ]]; then
      printf '%s' "${fields[0]}"
      return 0
    fi
  done
  return 1
}

component_registry_field() {
  local record index
  local fields=()
  record=$(component_registry_record "${1:-}") || return 1
  IFS='|' read -r -a fields <<< "${record}"
  case "${2:-}" in
    state_id) index=0 ;;
    role) index=1 ;;
    type) index=2 ;;
    display_name) index=3 ;;
    minimum_project_core) index=4 ;;
    availability) index=5 ;;
    features) index=6 ;;
    *) return 1 ;;
  esac
  printf '%s' "${fields[index]}"
}

component_environment_dependency_json() {
  local name=${1:-} status=${2:-} reason=${3:-} required=${4:-true}
  jq -cn --arg name "${name}" --arg status "${status}" --arg reason "${reason}" \
    --argjson required "${required}" \
    '{name:$name,status:$status,required:$required} +
      (if $reason == "" then {} else {reason:$reason} end)'
}

component_runtime_library_available() {
  local search_path candidate managed_library_path
  managed_library_path=$(singbox_library_path) || return 1
  if [[ -f "${managed_library_path}" && ! -L "${managed_library_path}" && -r "${managed_library_path}" ]]; then
    return 0
  fi
  if command -v ldconfig >/dev/null 2>&1 &&
     ldconfig -p 2>/dev/null | grep -Eq '[[:space:]]libcronet\.so([.[:digit:]]*)?[[:space:]]'; then
    return 0
  fi
  IFS=: read -r -a search_paths <<< "${LD_LIBRARY_PATH:-}"
  for search_path in "${search_paths[@]}"; do
    [[ -n "${search_path}" && "${search_path}" != *$'\n'* && "${search_path}" != *$'\r'* ]] || continue
    candidate="${search_path%/}/libcronet.so"
    [[ -f "${candidate}" && ! -L "${candidate}" && -r "${candidate}" ]] && return 0
  done
  return 1
}

# The version command is the only stable, credential-free way for the
# registry to observe build tags at runtime.  Return 2 when an older or
# wrapper binary does not report a Tags line so callers can distinguish
# "not reported" from a known tag mismatch.  No arbitrary version output is
# exposed to the caller; only a validated, sorted tag array is emitted.
detect_installed_singbox_build_tags_json() {
  [[ -x "${SINGBOX_BIN_PATH}" ]] || return 1

  local version_output tags_line tag_status
  version_output=$("${SINGBOX_BIN_PATH}" version 2>/dev/null) || return 1
  if tags_line=$(printf '%s\n' "${version_output}" | awk '
    index($0, "Tags:") == 1 {
      sub(/^Tags:[[:space:]]*/, "")
      print
      found=1
      exit 0
    }
    END {
      if (!found) exit 2
    }
  '); then
    :
  else
    tag_status=$?
    [[ "${tag_status}" -eq 2 ]] && return 2
    return 1
  fi

  jq -cn --arg tags "${tags_line}" '
    ($tags | if . == "" then [] else split(",") | map(gsub("^[[:space:]]+|[[:space:]]+$"; "")) end) as $values |
    if all($values[]; test("^[A-Za-z0-9][A-Za-z0-9_.+\\-]{0,127}$")) and
       (($values | unique | length) == ($values | length)) then
      ($values | sort)
    else
      error("invalid_build_tags")
    end
  ' || return 1
}

component_registry_environment_probe() {
  local state_id=${1:-} role=${2:-} type=${3:-} minimum=${4:-} availability=${5:-}
  local platform core_version core_status=unavailable core_reason=sing_box_binary_missing
  local overall=unavailable overall_reason=sing_box_binary_missing dependency_rows=()
  local root_status=available
  local command_status command_reason build_tag build_tags_json='[]'
  local build_tags_status=unavailable build_tags_reason=sing_box_binary_missing tag_status

  platform=$(uname -s 2>/dev/null || printf 'unknown')
  if [[ ! -x "${SINGBOX_BIN_PATH}" ]]; then
    core_version=''
  else
    core_version=$(detect_installed_singbox_version 2>/dev/null || true)
    if [[ ! "${core_version}" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
      core_reason=sing_box_version_unavailable
    elif ! singbox_version_at_least "${core_version}" "${minimum}"; then
      core_reason=sing_box_version_too_old
    else
      core_status=available
      core_reason=''
    fi
  fi
  dependency_rows+=("sing_box_binary"$'\t'"${core_status}"$'\t'"${core_reason}"$'\t'"true")
  dependency_rows+=("sing_box_version"$'\t'"$([[ "${core_status}" == available ]] && printf available || printf unavailable)"$'\t'"$([[ "${core_status}" == available ]] && printf '' || printf '%s' "${core_reason}")"$'\t'"true")
  overall_reason=${core_reason}

  if [[ -n "${core_version}" && "${core_reason}" != sing_box_version_unavailable ]]; then
    if build_tags_json=$(detect_installed_singbox_build_tags_json); then
      build_tags_status=available
      build_tags_reason=''
    else
      tag_status=$?
      build_tags_json='[]'
      if [[ "${tag_status}" -eq 2 ]]; then
        build_tags_status=not_assessed
        build_tags_reason=build_tags_not_reported
      else
        build_tags_status=unavailable
        build_tags_reason=sing_box_build_tags_unavailable
      fi
    fi
  elif [[ "${core_reason}" == sing_box_version_unavailable ]]; then
    build_tags_status=not_assessed
    build_tags_reason=sing_box_version_unavailable
  fi

  if [[ "${core_status}" == available ]]; then
    overall=available
    overall_reason=''
  fi

  component_add_dependency() {
    local name=$1 status=$2 reason=${3:-} required=${4:-true} item
    dependency_rows+=("${name}"$'\t'"${status}"$'\t'"${reason}"$'\t'"${required}")
    if [[ "${required}" == true ]]; then
      if [[ "${status}" == unavailable && "${overall}" != unavailable ]]; then
        overall=unavailable
        overall_reason=${reason:-${name}_unavailable}
      elif [[ "${status}" == not_assessed && "${overall}" == available ]]; then
        overall=not_assessed
        overall_reason=${reason:-${name}_not_assessed}
      fi
    fi
  }

  case "${type}" in
    tun|bridge)
      if [[ "${EUID}" -ne 0 ]]; then root_status=unavailable; else root_status=available; fi
      component_add_dependency root "${root_status}" \
        "$([[ "${root_status}" == available ]] && printf '' || printf root_required)" true || return 1
      if command -v ip >/dev/null 2>&1; then
        component_add_dependency iproute2 available '' true || return 1
      else
        component_add_dependency iproute2 unavailable iproute2_missing true || return 1
      fi
      if [[ "${type}" == tun && "${platform}" != Linux ]]; then
        component_add_dependency platform unavailable tun_linux_only true || return 1
      fi
      if [[ "${type}" == bridge ]]; then
        component_add_dependency net_admin available '' false || return 1
      fi
      ;;
    redirect|tproxy)
      if [[ "${EUID}" -ne 0 ]]; then root_status=unavailable; else root_status=available; fi
      component_add_dependency root "${root_status}" \
        "$([[ "${root_status}" == available ]] && printf '' || printf root_required)" true || return 1
      if command -v iptables >/dev/null 2>&1 || command -v nft >/dev/null 2>&1; then
        component_add_dependency transparent_rule_tool available '' true || return 1
      else
        component_add_dependency transparent_rule_tool unavailable transparent_rule_tool_missing true || return 1
      fi
      if [[ "${type}" == tproxy && "${platform}" != Linux ]]; then
        component_add_dependency platform unavailable tproxy_linux_only true || return 1
      fi
      ;;
    cloudflared)
      if command -v cloudflared >/dev/null 2>&1; then
        component_add_dependency cloudflared available '' true || return 1
      else
        component_add_dependency cloudflared unavailable cloudflared_missing true || return 1
      fi
      ;;
    tailscale)
      if command -v tailscale >/dev/null 2>&1; then
        command_status=available; command_reason=''
      else
        command_status=unavailable; command_reason=tailscale_binary_missing
      fi
      component_add_dependency tailscale_daemon "${command_status}" "${command_reason}" true || return 1
      component_add_dependency external_auth not_assessed external_auth_required true || return 1
      ;;
    openconnect)
      component_add_dependency external_auth not_assessed external_auth_required true || return 1
      ;;
    openvpn-client|openvpn-server)
      component_add_dependency external_auth not_assessed external_auth_required true || return 1
      ;;
    tor)
      if command -v tor >/dev/null 2>&1; then
        command_status=available; command_reason=''
      else
        command_status=unavailable; command_reason=tor_binary_missing
      fi
      component_add_dependency tor_binary "${command_status}" "${command_reason}" true || return 1
      ;;
    naive)
      if component_runtime_library_available; then
        component_add_dependency libcronet available '' true || return 1
      else
        component_add_dependency libcronet unavailable libcronet_missing true || return 1
      fi
      ;;
  esac

  if [[ "${availability}" == with_* ]]; then
    build_tag=${availability}
    if [[ "${build_tags_status}" == available ]]; then
      if jq -en --arg tag "${build_tag}" --argjson tags "${build_tags_json}" \
        '$tags | index($tag) != null' >/dev/null; then
        component_add_dependency "build_tag_${build_tag}" available '' true || return 1
      else
        component_add_dependency "build_tag_${build_tag}" unavailable \
          "build_tag_missing_${build_tag}" true || return 1
      fi
    elif [[ "${build_tags_status}" == not_assessed ]]; then
      component_add_dependency "build_tag_${build_tag}" not_assessed \
        "${build_tags_reason}" true || return 1
    else
      component_add_dependency "build_tag_${build_tag}" unavailable \
        "${build_tags_reason}" true || return 1
    fi
  fi

  local dependencies
  dependencies=$(printf '%s\n' "${dependency_rows[@]}" | jq -Rsc '
    split("\n") | map(select(length > 0) | split("\t") |
      {name:.[0],status:.[1],required:(.[3] == "true")} +
      (if .[2] == "" then {} else {reason:.[2]} end))
  ') || return 1
  jq -cn --arg state_id "${state_id}" --arg platform "${platform}" \
    --arg overall "${overall}" --arg reason "${overall_reason}" \
    --arg core_status "${core_status}" --arg core_version "${core_version}" \
    --arg minimum "${minimum}" --arg availability "${availability}" \
    --arg tags_status "${build_tags_status}" --arg tags_reason "${build_tags_reason}" \
    --argjson tags "${build_tags_json}" \
    --argjson dependencies "${dependencies}" \
    '{state_id:$state_id,status:$overall,reason:(if $reason == "" then null else $reason end),
      static_availability:$availability,
      platform:{name:$platform},
      core:{status:$core_status,version:(if $core_version == "" then null else $core_version end),minimum:$minimum,
        build_tags:{status:$tags_status,values:$tags,reason:(if $tags_reason == "" then null else $tags_reason end)}},
      dependencies:$dependencies}'
}

component_registry_environment_bulk_json() {
  local static platform core_version core_probe_reason
  local root_ok=false ip_ok=false transparent_ok=false cloudflared_ok=false
  local tailscale_ok=false tor_ok=false libcronet_ok=false
  local core_tags_json='[]' core_tags_status=unavailable core_tags_reason=sing_box_binary_missing tag_status

  static=$(component_registry_static_json) || return 1
  platform=$(uname -s 2>/dev/null || printf 'unknown')
  core_probe_reason=sing_box_binary_missing
  core_version=''
  if [[ -x "${SINGBOX_BIN_PATH}" ]]; then
    core_version=$(detect_installed_singbox_version 2>/dev/null || true)
    if [[ ! "${core_version}" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
      core_probe_reason=sing_box_version_unavailable
      core_version=''
      core_tags_status=not_assessed
      core_tags_reason=sing_box_version_unavailable
    else
      core_probe_reason=''
      if core_tags_json=$(detect_installed_singbox_build_tags_json); then
        core_tags_status=available
        core_tags_reason=''
      else
        tag_status=$?
        core_tags_json='[]'
        if [[ "${tag_status}" -eq 2 ]]; then
          core_tags_status=not_assessed
          core_tags_reason=build_tags_not_reported
        else
          core_tags_status=unavailable
          core_tags_reason=sing_box_build_tags_unavailable
        fi
      fi
    fi
  fi
  [[ "${EUID}" -eq 0 ]] && root_ok=true
  command -v ip >/dev/null 2>&1 && ip_ok=true
  (command -v iptables >/dev/null 2>&1 || command -v nft >/dev/null 2>&1) && transparent_ok=true
  command -v cloudflared >/dev/null 2>&1 && cloudflared_ok=true
  command -v tailscale >/dev/null 2>&1 && tailscale_ok=true
  command -v tor >/dev/null 2>&1 && tor_ok=true
  component_runtime_library_available && libcronet_ok=true || :

  jq -cn --argjson registry "${static}" --arg platform "${platform}" \
    --arg core_version "${core_version}" --arg core_probe_reason "${core_probe_reason}" \
    --argjson root_ok "${root_ok}" --argjson ip_ok "${ip_ok}" \
    --argjson transparent_ok "${transparent_ok}" --argjson cloudflared_ok "${cloudflared_ok}" \
    --argjson tailscale_ok "${tailscale_ok}" --argjson tor_ok "${tor_ok}" \
    --argjson libcronet_ok "${libcronet_ok}" --arg tags_status "${core_tags_status}" \
    --arg tags_reason "${core_tags_reason}" --argjson core_tags "${core_tags_json}" '
    def version_parts($value): $value | split(".") | map(tonumber);
    def at_least($value; $minimum):
      (version_parts($value)) as $a | (version_parts($minimum)) as $b |
      ($a[0] > $b[0] or
       ($a[0] == $b[0] and ($a[1] > $b[1] or
        ($a[1] == $b[1] and $a[2] >= $b[2]))));
    def dependency($name; $status; $reason; $required):
      {name:$name,status:$status,required:$required} +
      (if $reason == "" then {} else {reason:$reason} end);
    def unavailable($name; $reason; $required):
      dependency($name; "unavailable"; $reason; $required);
    def available($name; $required):
      dependency($name; "available"; ""; $required);
    def not_assessed($name; $reason; $required):
      dependency($name; "not_assessed"; $reason; $required);
    def build_tag_dependencies:
      if (.availability | startswith("with_")) then
        .availability as $tag |
        ("build_tag_" + $tag) as $name |
        if $tags_status == "available" then
          if ($core_tags | index($tag)) == null then
            [unavailable($name; "build_tag_missing_" + $tag; true)]
          else
            [available($name; true)]
          end
        elif $tags_status == "not_assessed" then
          [not_assessed($name; $tags_reason; true)]
        else
          [unavailable($name; $tags_reason; true)]
        end
      else [] end;
    def core:
      if $core_version == "" then
        {status:"unavailable",reason:$core_probe_reason}
      elif at_least($core_version; .minimum_project_core) then
        {status:"available",reason:""}
      else
        {status:"unavailable",reason:"sing_box_version_too_old"}
      end;
    def extra_dependencies:
      if .type == "tun" then
        (if $root_ok then available("root"; true) else unavailable("root"; "root_required"; true) end),
        (if $ip_ok then available("iproute2"; true) else unavailable("iproute2"; "iproute2_missing"; true) end),
        (if $platform == "Linux" then [] else [unavailable("platform"; "tun_linux_only"; true)] end)
      elif .type == "bridge" then
        (if $root_ok then available("root"; true) else unavailable("root"; "root_required"; true) end),
        (if $ip_ok then available("iproute2"; true) else unavailable("iproute2"; "iproute2_missing"; true) end),
        available("net_admin"; false)
      elif .type == "redirect" or .type == "tproxy" then
        (if $root_ok then available("root"; true) else unavailable("root"; "root_required"; true) end),
        (if $transparent_ok then available("transparent_rule_tool"; true)
         else unavailable("transparent_rule_tool"; "transparent_rule_tool_missing"; true) end),
        (if .type == "tproxy" and $platform != "Linux" then
           [unavailable("platform"; "tproxy_linux_only"; true)] else [] end)
      elif .type == "cloudflared" then
        (if $cloudflared_ok then available("cloudflared"; true)
         else unavailable("cloudflared"; "cloudflared_missing"; true) end)
      elif .type == "tailscale" then
        (if $tailscale_ok then available("tailscale_daemon"; true)
         else unavailable("tailscale_daemon"; "tailscale_binary_missing"; true) end),
        not_assessed("external_auth"; "external_auth_required"; true)
      elif .type == "openconnect" or .type == "openvpn-client" or .type == "openvpn-server" then
        not_assessed("external_auth"; "external_auth_required"; true)
      elif .type == "tor" then
        (if $tor_ok then available("tor_binary"; true)
         else unavailable("tor_binary"; "tor_binary_missing"; true) end)
      elif .type == "naive" then
        (if $libcronet_ok then available("libcronet"; true)
         else unavailable("libcronet"; "libcronet_missing"; true) end)
      else [] end;
    def final($core; $dependencies):
      if $core.status == "unavailable" then
        {status:"unavailable",reason:$core.reason}
      elif any($dependencies[]; .required and .status == "unavailable") then
        (first($dependencies[] | select(.required and .status == "unavailable")) |
          {status:"unavailable",reason:(.reason // (.name + "_unavailable"))})
      elif any($dependencies[]; .required and .status == "not_assessed") then
        (first($dependencies[] | select(.required and .status == "not_assessed")) |
          {status:"not_assessed",reason:(.reason // (.name + "_not_assessed"))})
      else {status:"available",reason:null} end;
    $registry | map(
      . as $entry | (core) as $core |
      ([dependency("sing_box_binary"; $core.status; $core.reason; true),
        dependency("sing_box_version"; $core.status; $core.reason; true)] +
       (([extra_dependencies] | flatten) + ($entry | build_tag_dependencies))) as $dependencies |
       (final($core; $dependencies)) as $result |
       {state_id:$entry.state_id,status:$result.status,reason:$result.reason,
       static_availability:$entry.availability,platform:{name:$platform},
       core:{status:$core.status,
             version:(if $core_version == "" then null else $core_version end),
             minimum:$entry.minimum_project_core,
             build_tags:{status:$tags_status,values:$core_tags,
                         reason:(if $tags_reason == "" then null else $tags_reason end)}},
       dependencies:$dependencies}
    )'
}

component_registry_environment_json() {
  component_registry_environment_bulk_json
}

# Refine the registry-level environment observation for one persisted
# component record. The registry cannot know whether an endpoint selected its
# internal gVisor stack or a privileged system interface, so this layer adds
# only configuration-derived requirements. It never performs a login or
# mutates interfaces/routes; missing credentials and external control planes
# remain not_assessed in the base observation.
managed_component_instance_environment_json() {
  local record=${1:-} base=${2:-} role type config state_id registry_record minimum availability
  local dependencies status reason system_mode=internal requires_root=false
  local requires_tun_device=false requires_gvisor=false tags_status tags_reason tags='[]'
  local dependency_name dependency_status dependency_reason dependency_item requirements
  [[ -n "${record}" ]] || return 1
  jq -e 'type == "object" and (.role | type == "string") and
    (.type | type == "string") and (.config | type == "object")' <<< "${record}" >/dev/null 2>&1 || return 1

  role=$(jq -r '.role' <<< "${record}") || return 1
  type=$(jq -r '.type' <<< "${record}") || return 1
  config=$(jq -c '.config' <<< "${record}") || return 1
  state_id=$(component_registry_resolve_id "${role}" "${type}") || return 1

  if [[ -z "${base}" ]]; then
    registry_record=$(component_registry_record "${state_id}") || return 1
    minimum=$(component_registry_field "${state_id}" minimum_project_core) || return 1
    availability=$(component_registry_field "${state_id}" availability) || return 1
    base=$(component_registry_environment_probe "${state_id}" "${role}" "${type}" \
      "${minimum}" "${availability}") || return 1
  fi
  jq -e 'type == "object" and (.state_id | type == "string") and
    (.dependencies | type == "array") and (.core | type == "object")' <<< "${base}" >/dev/null 2>&1 || return 1
  [[ "$(jq -r '.state_id' <<< "${base}")" == "${state_id}" ]] || return 1

  dependencies=$(jq -c '.dependencies' <<< "${base}") || return 1
  status=$(jq -r '.status // "unavailable"' <<< "${base}") || return 1
  reason=$(jq -r '.reason // ""' <<< "${base}") || return 1
  tags_status=$(jq -r '.core.build_tags.status // "unavailable"' <<< "${base}") || return 1
  tags_reason=$(jq -r '.core.build_tags.reason // ""' <<< "${base}") || return 1
  tags=$(jq -c '.core.build_tags.values // []' <<< "${base}") || return 1

  case "${type}" in
    tun)
      requires_root=true
      requires_tun_device=true
      ;;
    bridge)
      # Bridge uses the host bridge API and requires privilege, but it does
      # not create a TUN character device itself.
      requires_root=true
      ;;
    redirect|tproxy)
      requires_root=true
      ;;
    wireguard|openconnect|openvpn-client|openvpn-server)
      if [[ "$(jq -r 'if .system == true then "system" else "internal" end' <<< "${config}")" == system ]]; then
        system_mode=system
        requires_root=true
        if [[ "${type}" != wireguard ]]; then
          requires_tun_device=true
        fi
      else
        requires_gvisor=true
      fi
      ;;
    tailscale)
      if [[ "$(jq -r 'if .system_interface == true then "system" else "internal" end' <<< "${config}")" == system ]]; then
        system_mode=system
        requires_root=true
        requires_tun_device=true
      else
        requires_gvisor=true
      fi
      ;;
  esac

  instance_add_dependency() {
    dependency_name=${1:-}
    dependency_status=${2:-}
    dependency_reason=${3:-}
    [[ -n "${dependency_name}" && -n "${dependency_status}" ]] || return 1
    if jq -e --arg name "${dependency_name}" 'any(.[]; .name == $name)' <<< "${dependencies}" >/dev/null 2>&1; then
      return 0
    fi
    dependency_item=$(component_environment_dependency_json "${dependency_name}" \
      "${dependency_status}" "${dependency_reason}" true) || return 1
    dependencies=$(jq -c --argjson item "${dependency_item}" '. + [$item]' <<< "${dependencies}") || return 1
    if [[ "${dependency_status}" == unavailable && "${status}" != unavailable ]]; then
      status=unavailable
      reason=${dependency_reason:-${dependency_name}_unavailable}
    elif [[ "${dependency_status}" == not_assessed && "${status}" == available ]]; then
      status=not_assessed
      reason=${dependency_reason:-${dependency_name}_not_assessed}
    fi
  }

  if [[ "${requires_root}" == true ]]; then
    if [[ "${EUID}" -eq 0 ]]; then
      instance_add_dependency root available '' || return 1
    else
      instance_add_dependency root unavailable root_required || return 1
    fi
  fi
  if [[ "${requires_tun_device}" == true ]]; then
    if [[ -c /dev/net/tun ]]; then
      instance_add_dependency tun_device available '' || return 1
    else
      instance_add_dependency tun_device unavailable tun_device_missing || return 1
    fi
  fi
  if [[ "${requires_gvisor}" == true ]]; then
    if [[ "${tags_status}" == available ]]; then
      if jq -en --argjson tags "${tags}" '$tags | index("with_gvisor") != null' >/dev/null; then
        instance_add_dependency build_tag_with_gvisor available '' || return 1
      else
        instance_add_dependency build_tag_with_gvisor unavailable build_tag_missing_with_gvisor || return 1
      fi
    elif [[ "${tags_status}" == not_assessed ]]; then
      instance_add_dependency build_tag_with_gvisor not_assessed \
        "${tags_reason:-build_tags_not_reported}" || return 1
    else
      instance_add_dependency build_tag_with_gvisor unavailable \
        "${tags_reason:-sing_box_build_tags_unavailable}" || return 1
    fi
  fi

  requirements=$(jq -cn --arg mode "${system_mode}" --argjson root "${requires_root}" \
    --argjson tun "${requires_tun_device}" --argjson gvisor "${requires_gvisor}" \
    '{system_interface:($mode == "system"),system_mode:$mode,requires_root:$root,
      requires_tun_device:$tun,requires_gvisor:$gvisor}') || return 1
  jq -cn --argjson base "${base}" --arg status "${status}" --arg reason "${reason}" \
    --argjson dependencies "${dependencies}" --argjson requirements "${requirements}" \
    '$base + {status:$status,reason:(if $reason == "" then null else $reason end),
      dependencies:$dependencies,requirements:$requirements,source:"instance_config"}'
}

component_registry_static_json() {
  printf '%s\n' "${SB_COMPONENT_REGISTRY[@]}" | jq -Rn '
    [inputs | split("|") | {
      state_id: .[0], role: .[1], type: .[2], display_name: .[3],
      minimum_project_core: .[4], availability: .[5],
      features: (.[6] | fromjson),
      implemented: true, available: null, availability_reason: .[5],
      validated: {status: "not_assessed", method: "target_sing_box_check"},
      lifecycle: {
        create: true, replace: true, delete: true, rebuild: true, export: true,
        takeover: (.[1] == "inbound" or .[1] == "endpoint" or .[1] == "outbound"), recover: true
      }
    }]'
}

component_registry_json() {
  local environment static
  environment=$(component_registry_environment_json) || return 1
  static=$(component_registry_static_json) || return 1
  jq -cn --argjson static "${static}" --argjson environment "${environment}" '
    $static | map(. as $entry |
      ($environment[] | select(.state_id == $entry.state_id)) as $runtime |
      . + {environment:$runtime})
  '
}

component_registry_inbound_types_json() {
  component_registry_static_json | jq -c '[.[] | select(.role == "inbound") | .type]'
}

component_registry_endpoint_types_json() {
  component_registry_static_json | jq -c '[.[] | select(.role == "endpoint") | .type]'
}

component_registry_outbound_types_json() {
  component_registry_static_json | jq -c '[.[] | select(.role == "outbound") | .type]'
}

list_registered_protocols() {
  local record state_id remainder
  for record in "${SB_PROTOCOL_REGISTRY[@]}"; do
    IFS='|' read -r state_id remainder <<< "${record}"
    printf '%s\n' "${state_id}"
  done
}

protocol_registry_require_handlers() {
  local handler handler_list
  local handlers=()
  handler_list=$(protocol_registry_field "$1" handlers) || return 1
  IFS=',' read -r -a handlers <<< "${handler_list}"
  [[ ${#handlers[@]} -gt 0 ]] || return 1
  for handler in "${handlers[@]}"; do
    if ! declare -F "${handler}" >/dev/null; then
      printf '[ERROR] 协议适配器缺失，未生成配置；请恢复完整的 install.sh。\n' >&2
      return 1
    fi
  done
}

normalize_protocol_id() {
  protocol_registry_field "$1" state_id
}

# Resolve a live core inbound to one managed state adapter.  The core uses the
# same runtime type (`vless`) for ordinary VLESS and VLESS + REALITY, so the
# REALITY TLS material is the discriminator; the historical `vless` alias
# continues to resolve to the REALITY adapter for CLI compatibility.
config_inbound_protocol() {
  local inbound_json=${1:-} inbound_type
  [[ -n "${inbound_json}" ]] || return 1
  inbound_type=$(jq -er '.type' <<< "${inbound_json}") || return 1
  if [[ "${inbound_type}" == "mixed" ]] && [[ "$(jq -r '.tag // empty' <<< "${inbound_json}")" == shadowtls-inner-* ]]; then
    printf 'shadowtls'
    return 0
  fi
  if [[ "${inbound_type}" == "vless" ]]; then
    if jq -e '(.tls.reality? != null)' <<< "${inbound_json}" >/dev/null 2>&1; then
      printf 'vless-reality'
    else
      printf 'vless-plain'
    fi
    return 0
  fi
  normalize_protocol_id "${inbound_type}"
}

config_protocol_jq_filter() {
  case "${1:-}" in
    vless-reality) printf '.type == "vless" and (.tls.reality? != null)' ;;
    vless-plain) printf '.type == "vless" and (.tls.reality? == null)' ;;
    hy2) printf '.type == "hysteria2"' ;;
    shadowtls) printf '.type == "shadowtls"' ;;
    mixed) printf '.type == "mixed" and ((.tag // "") | startswith("shadowtls-inner-") | not)' ;;
    *) printf '.type == "%s"' "${1:-}" ;;
  esac
}

config_protocol_inbound_count() {
  local protocol=${1:-} config_file=${2:-${SINGBOX_CONFIG_FILE:-}} filter
  filter=$(config_protocol_jq_filter "${protocol}") || return 1
  jq -r "[(.inbounds[]? | select(${filter}))] | length" "${config_file}"
}

config_protocol_inbounds_jsonl() {
  local protocol=${1:-} config_file=${2:-${SINGBOX_CONFIG_FILE:-}} filter
  filter=$(config_protocol_jq_filter "${protocol}") || return 1
  jq -c "[.inbounds[]? | select(${filter})][]" "${config_file}"
}

state_protocol_to_runtime() {
  protocol_registry_field "$1" runtime_id
}

runtime_protocol_to_state() {
  normalize_protocol_id "$1"
}

protocol_state_file() {
  local protocol
  protocol=$(normalize_protocol_id "$1") || return 1
  printf '%s/%s.env' "${SB_PROTOCOL_STATE_DIR}" "${protocol}"
}

ensure_protocol_state_dir() {
  mkdir -p "${SB_PROTOCOL_STATE_DIR}"
}

write_env_assignment() {
  local key=$1
  local value=${2-}
  local escaped
  printf -v escaped '%q' "${value}"
  printf '%s=%s\n' "${key}" "${escaped}"
}

acme_extra_json_or_default() {
  local value=${1:-}

  if [[ -n "${value}" ]]; then
    printf '%s' "${value}"
  else
    printf '{}'
  fi
}

vless_reality_instance_dir() {
  printf '%s/vless-reality.d' "${SB_PROTOCOL_STATE_DIR}"
}

validate_vless_reality_instance_id() {
  [[ "$1" =~ ^[a-z0-9][a-z0-9-]*$ ]]
}

validate_port_number() {
  local port=$1
  [[ "${port}" =~ ^[0-9]+$ ]] || return 1
  (( port >= 1 && port <= 65535 ))
}

validate_optional_positive_integer() {
  local value=$1
  [[ -z "${value}" || "${value}" =~ ^[1-9][0-9]*$ ]]
}

validate_vless_reality_alpn_mode() {
  case "${1:-off}" in
    off|h2_http1|http1) return 0 ;;
    *) return 1 ;;
  esac
}

vless_reality_alpn_json_for_mode() {
  local mode=${1:-off}

  case "${mode}" in
    h2_http1) jq -n '["h2", "http/1.1"]' ;;
    http1) jq -n '["http/1.1"]' ;;
    *) jq -n 'null' ;;
  esac
}

vless_reality_alpn_mode_display_name() {
  case "${1:-off}" in
    h2_http1) printf 'h2 + http/1.1' ;;
    http1) printf 'http/1.1' ;;
    *) printf '关闭' ;;
  esac
}

vless_reality_alpn_link_value_for_mode() {
  case "${1:-off}" in
    h2_http1) printf 'h2,http/1.1' ;;
    http1) printf 'http/1.1' ;;
    *) printf '' ;;
  esac
}

validate_optional_email() {
  local value=$1
  [[ -z "${value}" || "${value}" =~ ^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$ ]]
}

validate_non_empty_path() {
  local value=$1
  [[ -n "${value}" && "${value}" != *$'\n'* && "${value}" == /* ]]
}

validate_http_url() {
  local value=$1
  [[ "${value}" =~ ^https?://[^[:space:]/$.?#][^[:space:]]*$ ]]
}

validate_update_interval() {
  local value=$1
  [[ "${value}" =~ ^[1-9][0-9]*[smhd]$ ]]
}

prompt_choice() {
  local prompt=$1 min=$2 max=$3 default=${4:-}
  local value

  while true; do
    read -rp "${prompt}" value || return 1
    value=$(trim_whitespace "${value}")
    if [[ -z "${value}" && -n "${default}" ]]; then
      printf '%s' "${default}"
      return 0
    fi
    if [[ "${value}" =~ ^[0-9]+$ && "${value}" -ge "${min}" && "${value}" -le "${max}" ]]; then
      printf '%s' "${value}"
      return 0
    fi
    log_warn "请输入 ${min}-${max} 范围内的数字。" >&2
  done
}

prompt_yes_no() {
  local prompt=$1 default=${2:-}
  local value

  while true; do
    read -rp "${prompt}" value || return 1
    value=$(trim_whitespace "${value}")
    value=${value,,}
    if [[ -z "${value}" && -n "${default}" ]]; then
      printf '%s' "${default}"
      return 0
    fi
    case "${value}" in
      y|n)
        printf '%s' "${value}"
        return 0
        ;;
      *)
        log_warn "请输入 y 或 n。" >&2
        ;;
    esac
  done
}

prompt_port() {
  local prompt=$1 default=${2:-}
  local value

  while true; do
    read -rp "${prompt}" value || return 1
    value=$(trim_whitespace "${value}")
    [[ -z "${value}" && -n "${default}" ]] && value="${default}"
    if validate_port_number "${value}"; then
      printf '%s' "${value}"
      return 0
    fi
    log_warn "端口必须为 1-65535 的数字。" >&2
  done
}

prompt_optional_positive_integer() {
  local prompt=$1 default=${2:-} label=${3:-数值}
  local value

  while true; do
    read -rp "${prompt}" value || return 1
    value=$(trim_whitespace "${value}")
    [[ -z "${value}" && -n "${default}" ]] && value="${default}"
    if validate_optional_positive_integer "${value}"; then
      printf '%s' "${value}"
      return 0
    fi
    log_warn "${label}必须为空或正整数。" >&2
  done
}

prompt_optional_nonnegative_integer() {
  local prompt=$1 default=${2:-} label=${3:-数值}
  local value

  while true; do
    read -rp "${prompt}" value || return 1
    value=$(trim_whitespace "${value}")
    [[ -z "${value}" && -n "${default}" ]] && value="${default}"
    if [[ -z "${value}" || "${value}" =~ ^[0-9]+$ ]]; then
      printf '%s' "${value}"
      return 0
    fi
    log_warn "${label}必须为空或非负整数。" >&2
  done
}

prompt_update_optional_positive_integer() {
  local prompt=$1 label=${2:-数值}
  local value

  while true; do
    read -rp "${prompt}" value || return 1
    value=$(trim_whitespace "${value}")
    if validate_optional_positive_integer "${value}"; then
      printf '%s' "${value}"
      return 0
    fi
    log_warn "${label}必须为空或正整数。" >&2
  done
}

prompt_optional_choice() {
  local prompt=$1 min=$2 max=$3
  local value

  while true; do
    read -rp "${prompt}" value || return 1
    value=$(trim_whitespace "${value}")
    if [[ -z "${value}" ]]; then
      printf ''
      return 0
    fi
    if [[ "${value}" =~ ^[0-9]+$ && "${value}" -ge "${min}" && "${value}" -le "${max}" ]]; then
      printf '%s' "${value}"
      return 0
    fi
    log_warn "请输入 ${min}-${max} 范围内的数字，或留空保持当前设置。" >&2
  done
}

prompt_optional_email() {
  local prompt=$1 default=${2:-}
  local value

  while true; do
    read -rp "${prompt}" value || return 1
    value=$(trim_whitespace "${value}")
    [[ -z "${value}" && -n "${default}" ]] && value="${default}"
    if validate_optional_email "${value}"; then
      printf '%s' "${value}"
      return 0
    fi
    log_warn "邮箱格式不正确，请输入 user@example.com 或留空。" >&2
  done
}

prompt_required_path() {
  local prompt=$1
  local default=${2:-}
  local value

  while true; do
    read -rp "${prompt}" value || return 1
    value=$(trim_whitespace "${value}")
    [[ -z "${value}" && -n "${default}" ]] && value="${default}"
    if validate_non_empty_path "${value}"; then
      printf '%s' "${value}"
      return 0
    fi
    log_warn "路径必须为绝对路径，例如 /etc/ssl/certs/fullchain.pem。" >&2
  done
}

prompt_optional_domain() {
  local prompt=$1 default=${2:-}
  local value

  while true; do
    read -rp "${prompt}" value || return 1
    value=$(trim_whitespace "${value}")
    [[ -z "${value}" && -n "${default}" ]] && value="${default}"
    if [[ -z "${value}" || "${value}" =~ ^([A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63}$ ]]; then
      printf '%s' "${value}"
      return 0
    fi
    log_warn "域名格式不正确，例如 example.com。" >&2
  done
}

vless_reality_instance_state_file() {
  local instance_id=$1
  validate_vless_reality_instance_id "${instance_id}" || return 1
  printf '%s/%s.env' "$(vless_reality_instance_dir)" "${instance_id}"
}

normalize_csv_list() {
  local value=$1
  value=${value//\"/}
  value=${value//\'/}
  value=${value//\\,/,}
  printf '%s' "${value}"
}

load_vless_reality_protocol_state() {
  local state_file
  state_file=$(protocol_state_file "vless-reality")

  VLESS_REALITY_DEFAULT_INSTANCE_ID="main"
  VLESS_REALITY_INSTANCE_IDS=""
  SB_PRIVATE_KEY=""
  SB_PUBLIC_KEY=""

  [[ -f "${state_file}" ]] || return 0

  unset INSTALLED CONFIG_SCHEMA_VERSION DEFAULT_INSTANCE_ID INSTANCE_IDS
  unset REALITY_PRIVATE_KEY REALITY_PUBLIC_KEY
  # shellcheck disable=SC1090
  source "${state_file}"
  VLESS_REALITY_DEFAULT_INSTANCE_ID="${DEFAULT_INSTANCE_ID:-main}"
  VLESS_REALITY_INSTANCE_IDS=$(normalize_csv_list "${INSTANCE_IDS:-}")
  SB_PRIVATE_KEY="${REALITY_PRIVATE_KEY:-${SB_PRIVATE_KEY:-}}"
  SB_PUBLIC_KEY="${REALITY_PUBLIC_KEY:-${SB_PUBLIC_KEY:-}}"
}

save_vless_reality_protocol_state() {
  local state_file
  state_file=$(protocol_state_file "vless-reality")
  ensure_protocol_state_dir

  {
    write_env_assignment "INSTALLED" "1"
    write_env_assignment "CONFIG_SCHEMA_VERSION" "2"
    write_env_assignment "DEFAULT_INSTANCE_ID" "${VLESS_REALITY_DEFAULT_INSTANCE_ID:-main}"
    printf 'INSTANCE_IDS=%s\n' "${VLESS_REALITY_INSTANCE_IDS:-main}"
    write_env_assignment "REALITY_PRIVATE_KEY" "${SB_PRIVATE_KEY}"
    write_env_assignment "REALITY_PUBLIC_KEY" "${SB_PUBLIC_KEY}"
  } > "${state_file}"
}

load_vless_reality_instance_state() {
  local instance_id=$1
  local state_file
  state_file=$(vless_reality_instance_state_file "${instance_id}") || return 1

  SB_VLESS_INSTANCE_ID="${instance_id}"
  SB_VLESS_INBOUND_TAG=""
  SB_NODE_NAME=""
  SB_PORT=""
  SB_UUID=""
  SB_SNI=""
  SB_SHORT_ID_1=""
  SB_SHORT_ID_2=""
  SB_VLESS_RATE_LIMIT_UP_MBPS=""
  SB_VLESS_RATE_LIMIT_DOWN_MBPS=""
  SB_OUTBOUND_POLICY="default"
  SB_VLESS_ALPN_MODE="off"
  SB_VLESS_TCP_FAST_OPEN="n"

  [[ -f "${state_file}" ]] || return 1

  unset INSTANCE_ID INBOUND_TAG ENABLED NODE_NAME PORT UUID SNI SHORT_ID_1 SHORT_ID_2
  unset RATE_LIMIT_UP_MBPS RATE_LIMIT_DOWN_MBPS ALPN_MODE TCP_FAST_OPEN OUTBOUND_POLICY

  # shellcheck disable=SC1090
  source "${state_file}"
  SB_VLESS_INSTANCE_ID="${INSTANCE_ID:-${instance_id}}"
  SB_VLESS_INBOUND_TAG="${INBOUND_TAG:-}"
  SB_NODE_NAME=$(normalize_node_name "${NODE_NAME:-}")
  SB_PORT="${PORT:-}"
  SB_UUID="${UUID:-}"
  SB_SNI="${SNI:-}"
  SB_SHORT_ID_1="${SHORT_ID_1:-}"
  SB_SHORT_ID_2="${SHORT_ID_2:-}"
  SB_VLESS_RATE_LIMIT_UP_MBPS="${RATE_LIMIT_UP_MBPS:-}"
  SB_VLESS_RATE_LIMIT_DOWN_MBPS="${RATE_LIMIT_DOWN_MBPS:-}"
  if validate_vless_reality_alpn_mode "${ALPN_MODE:-off}"; then
    SB_VLESS_ALPN_MODE="${ALPN_MODE:-off}"
  else
    SB_VLESS_ALPN_MODE="off"
  fi
  case "${TCP_FAST_OPEN:-n}" in
    y|n) SB_VLESS_TCP_FAST_OPEN="${TCP_FAST_OPEN:-n}" ;;
    *) SB_VLESS_TCP_FAST_OPEN="n" ;;
  esac
  if validate_instance_outbound_policy "${OUTBOUND_POLICY:-default}"; then
    SB_OUTBOUND_POLICY="${OUTBOUND_POLICY:-default}"
  else
    SB_OUTBOUND_POLICY="default"
  fi
}

save_vless_reality_instance_state() {
  local instance_id=${SB_VLESS_INSTANCE_ID:-main}
  local state_file
  validate_vless_reality_instance_id "${instance_id}" || log_error "REALITY 实例 ID 非法: ${instance_id}"
  mkdir -p "$(vless_reality_instance_dir)"
  state_file=$(vless_reality_instance_state_file "${instance_id}") || return 1

  {
    write_env_assignment "INSTANCE_ID" "${instance_id}"
    write_env_assignment "INBOUND_TAG" "${SB_VLESS_INBOUND_TAG:-}"
    write_env_assignment "ENABLED" "1"
    write_env_assignment "NODE_NAME" "${SB_NODE_NAME}"
    write_env_assignment "PORT" "${SB_PORT}"
    write_env_assignment "UUID" "${SB_UUID}"
    write_env_assignment "SNI" "${SB_SNI}"
    write_env_assignment "SHORT_ID_1" "${SB_SHORT_ID_1}"
    write_env_assignment "SHORT_ID_2" "${SB_SHORT_ID_2}"
    printf 'RATE_LIMIT_UP_MBPS=%s\n' "${SB_VLESS_RATE_LIMIT_UP_MBPS:-}"
    printf 'RATE_LIMIT_DOWN_MBPS=%s\n' "${SB_VLESS_RATE_LIMIT_DOWN_MBPS:-}"
    write_env_assignment "ALPN_MODE" "${SB_VLESS_ALPN_MODE:-off}"
    write_env_assignment "TCP_FAST_OPEN" "${SB_VLESS_TCP_FAST_OPEN:-n}"
    write_env_assignment "OUTBOUND_POLICY" "${SB_OUTBOUND_POLICY:-default}"
  } > "${state_file}"
}

save_vless_reality_protocol_material_state_if_v2() {
  local state_file current_private_key current_public_key
  state_file=$(protocol_state_file "vless-reality")

  [[ -f "${state_file}" ]] || return 0
  grep -Eq '^CONFIG_SCHEMA_VERSION=(2|'"'2'"'|'\''2'\'')$' "${state_file}" || return 0

  current_private_key="${SB_PRIVATE_KEY}"
  current_public_key="${SB_PUBLIC_KEY}"
  load_vless_reality_protocol_state
  SB_PRIVATE_KEY="${current_private_key}"
  SB_PUBLIC_KEY="${current_public_key}"
  save_vless_reality_protocol_state
}

migrate_vless_reality_state_to_instances_if_needed() {
  local state_file instance_dir main_state backup_state_file
  state_file=$(protocol_state_file "vless-reality")
  instance_dir=$(vless_reality_instance_dir)
  main_state="${instance_dir}/main.env"

  [[ -f "${state_file}" ]] || return 0
  [[ ! -f "${main_state}" ]] || return 0

  reset_vless_reality_state_source_variables
  # shellcheck disable=SC1090
  source "${state_file}"

  if [[ "${CONFIG_SCHEMA_VERSION:-1}" != "1" || -z "${PORT:-}" || -z "${UUID:-}" ]]; then
    return 0
  fi

  backup_state_file="${state_file}.bak.$(date +%Y%m%d%H%M%S)"
  cp "${state_file}" "${backup_state_file}"

  SB_PRIVATE_KEY="${REALITY_PRIVATE_KEY:-}"
  SB_PUBLIC_KEY="${REALITY_PUBLIC_KEY:-}"
  VLESS_REALITY_DEFAULT_INSTANCE_ID="main"
  VLESS_REALITY_INSTANCE_IDS="main"
  save_vless_reality_protocol_state

  SB_VLESS_INSTANCE_ID="main"
  SB_NODE_NAME=$(normalize_node_name "${NODE_NAME:-$(default_node_name_for_protocol "vless+reality")}")
  SB_PORT="${PORT:-443}"
  SB_UUID="${UUID:-}"
  SB_SNI="${SNI:-}"
  SB_SHORT_ID_1="${SHORT_ID_1:-}"
  SB_SHORT_ID_2="${SHORT_ID_2:-}"
  SB_VLESS_RATE_LIMIT_UP_MBPS=""
  SB_VLESS_RATE_LIMIT_DOWN_MBPS=""
  SB_OUTBOUND_POLICY="default"
  save_vless_reality_instance_state
}

list_vless_reality_instance_ids() {
  local instance_dir
  load_vless_reality_protocol_state

  if [[ -n "${VLESS_REALITY_INSTANCE_IDS}" ]]; then
    tr ',' '\n' <<< "${VLESS_REALITY_INSTANCE_IDS}" | sed '/^$/d'
    return 0
  fi

  instance_dir=$(vless_reality_instance_dir)
  [[ -d "${instance_dir}" ]] || return 0

  find "${instance_dir}" -maxdepth 1 -type f -name '*.env' \
    | sed 's|.*/||; s|\.env$||' \
    | sort
}

vless_reality_instance_id_exists() {
  local target=$1 instance_id
  while IFS= read -r instance_id; do
    [[ "${instance_id}" == "${target}" ]] && return 0
  done < <(list_vless_reality_instance_ids)
  return 1
}

vless_reality_bandwidth_profile_exists() {
  local target_up=${1:-}
  local target_down=${2:-}
  local exclude_instance_id=${3:-}
  local instance_id
  local saved_instance_id saved_node_name saved_port saved_uuid saved_sni
  local saved_short_id_1 saved_short_id_2 saved_rate_limit_up saved_rate_limit_down
  local saved_alpn_mode saved_tcp_fast_open

  saved_instance_id="${SB_VLESS_INSTANCE_ID:-}"
  saved_node_name="${SB_NODE_NAME:-}"
  saved_port="${SB_PORT:-}"
  saved_uuid="${SB_UUID:-}"
  saved_sni="${SB_SNI:-}"
  saved_short_id_1="${SB_SHORT_ID_1:-}"
  saved_short_id_2="${SB_SHORT_ID_2:-}"
  saved_rate_limit_up="${SB_VLESS_RATE_LIMIT_UP_MBPS:-}"
  saved_rate_limit_down="${SB_VLESS_RATE_LIMIT_DOWN_MBPS:-}"
  saved_alpn_mode="${SB_VLESS_ALPN_MODE:-off}"
  saved_tcp_fast_open="${SB_VLESS_TCP_FAST_OPEN:-n}"

  migrate_vless_reality_state_to_instances_if_needed
  while IFS= read -r instance_id; do
    [[ -z "${instance_id}" ]] && continue
    [[ -n "${exclude_instance_id}" && "${instance_id}" == "${exclude_instance_id}" ]] && continue
    load_vless_reality_instance_state "${instance_id}" || continue
    if [[ "${SB_VLESS_RATE_LIMIT_UP_MBPS:-}" == "${target_up}" && "${SB_VLESS_RATE_LIMIT_DOWN_MBPS:-}" == "${target_down}" ]]; then
      SB_VLESS_INSTANCE_ID="${saved_instance_id}"
      SB_NODE_NAME="${saved_node_name}"
      SB_PORT="${saved_port}"
      SB_UUID="${saved_uuid}"
      SB_SNI="${saved_sni}"
      SB_SHORT_ID_1="${saved_short_id_1}"
      SB_SHORT_ID_2="${saved_short_id_2}"
      SB_VLESS_RATE_LIMIT_UP_MBPS="${saved_rate_limit_up}"
      SB_VLESS_RATE_LIMIT_DOWN_MBPS="${saved_rate_limit_down}"
      SB_VLESS_ALPN_MODE="${saved_alpn_mode}"
      SB_VLESS_TCP_FAST_OPEN="${saved_tcp_fast_open}"
      return 0
    fi
  done < <(list_vless_reality_instance_ids)

  SB_VLESS_INSTANCE_ID="${saved_instance_id}"
  SB_NODE_NAME="${saved_node_name}"
  SB_PORT="${saved_port}"
  SB_UUID="${saved_uuid}"
  SB_SNI="${saved_sni}"
  SB_SHORT_ID_1="${saved_short_id_1}"
  SB_SHORT_ID_2="${saved_short_id_2}"
  SB_VLESS_RATE_LIMIT_UP_MBPS="${saved_rate_limit_up}"
  SB_VLESS_RATE_LIMIT_DOWN_MBPS="${saved_rate_limit_down}"
  SB_VLESS_ALPN_MODE="${saved_alpn_mode}"
  SB_VLESS_TCP_FAST_OPEN="${saved_tcp_fast_open}"
  return 1
}

build_vless_reality_qos_plan() {
  local state_file instance_id up down direction
  local saved_instance_id saved_node_name saved_port saved_uuid saved_sni
  local saved_short_id_1 saved_short_id_2 saved_rate_limit_up saved_rate_limit_down
  local saved_alpn_mode saved_tcp_fast_open
  state_file=$(protocol_state_file "vless-reality")
  [[ -f "${state_file}" ]] || return 0

  saved_instance_id="${SB_VLESS_INSTANCE_ID:-}"
  saved_node_name="${SB_NODE_NAME:-}"
  saved_port="${SB_PORT:-}"
  saved_uuid="${SB_UUID:-}"
  saved_sni="${SB_SNI:-}"
  saved_short_id_1="${SB_SHORT_ID_1:-}"
  saved_short_id_2="${SB_SHORT_ID_2:-}"
  saved_rate_limit_up="${SB_VLESS_RATE_LIMIT_UP_MBPS:-}"
  saved_rate_limit_down="${SB_VLESS_RATE_LIMIT_DOWN_MBPS:-}"
  saved_alpn_mode="${SB_VLESS_ALPN_MODE:-off}"
  saved_tcp_fast_open="${SB_VLESS_TCP_FAST_OPEN:-n}"

  migrate_vless_reality_state_to_instances_if_needed

  while IFS= read -r instance_id; do
    [[ -z "${instance_id}" ]] && continue
    load_vless_reality_instance_state "${instance_id}" || continue
    up="${SB_VLESS_RATE_LIMIT_UP_MBPS:-}"
    down="${SB_VLESS_RATE_LIMIT_DOWN_MBPS:-}"
    [[ -z "${up}" && -z "${down}" ]] && continue

    if [[ -n "${up}" && -n "${down}" ]]; then
      direction="both"
    elif [[ -n "${up}" ]]; then
      direction="up"
    else
      direction="down"
    fi

    printf '%s|%s|%s|%s\n' "${SB_PORT}" "${direction}" "${up}" "${down}"
  done < <(list_vless_reality_instance_ids)

  SB_VLESS_INSTANCE_ID="${saved_instance_id}"
  SB_NODE_NAME="${saved_node_name}"
  SB_PORT="${saved_port}"
  SB_UUID="${saved_uuid}"
  SB_SNI="${saved_sni}"
  SB_SHORT_ID_1="${saved_short_id_1}"
  SB_SHORT_ID_2="${saved_short_id_2}"
  SB_VLESS_RATE_LIMIT_UP_MBPS="${saved_rate_limit_up}"
  SB_VLESS_RATE_LIMIT_DOWN_MBPS="${saved_rate_limit_down}"
  SB_VLESS_ALPN_MODE="${saved_alpn_mode}"
  SB_VLESS_TCP_FAST_OPEN="${saved_tcp_fast_open}"
}

detect_default_network_interface() {
  local iface

  if ! command -v ip >/dev/null 2>&1; then
    return 1
  fi

  iface=$(ip route show default 2>/dev/null | awk '
    {
      for (i = 1; i <= NF; i++) {
        if ($i == "dev" && (i + 1) <= NF) {
          print $(i + 1)
          exit
        }
      }
    }
  ')
  if [[ -z "${iface}" ]]; then
    iface=$(ip -6 route show default 2>/dev/null | awk '
      {
        for (i = 1; i <= NF; i++) {
          if ($i == "dev" && (i + 1) <= NF) {
            print $(i + 1)
            exit
          }
        }
      }
    ')
  fi
  [[ -n "${iface}" ]] || return 1
  printf '%s\n' "${iface}"
}

vless_reality_qos_hook_for_direction() {
  local direction=$1

  case "${direction}" in
    up) printf 'ingress' ;;
    down) printf 'egress' ;;
    *) return 1 ;;
  esac
}

clear_vless_reality_qos_rules() {
  local iface direction protocol pref port rate hook

  [[ -f "${SB_REALITY_QOS_FILTER_STATE_FILE}" ]] || return 0

  while IFS='|' read -r iface direction protocol pref port rate; do
    [[ -z "${iface}" || -z "${direction}" || -z "${protocol}" || -z "${pref}" ]] && continue
    hook=$(vless_reality_qos_hook_for_direction "${direction}") || continue
    tc filter del dev "${iface}" "${hook}" pref "${pref}" protocol "${protocol}" >/dev/null 2>&1 || true
  done < "${SB_REALITY_QOS_FILTER_STATE_FILE}"

  rm -f "${SB_REALITY_QOS_FILTER_STATE_FILE}"
}

ensure_vless_reality_qos_clsact() {
  local iface=$1

  if tc qdisc show dev "${iface}" 2>/dev/null | grep -qw 'clsact'; then
    return 0
  fi

  if ! tc qdisc add dev "${iface}" clsact >/dev/null 2>&1; then
    log_warn "REALITY 限速规则未应用：无法在网卡 ${iface} 上创建 clsact qdisc。"
    return 1
  fi
}

apply_vless_reality_qos_filter() {
  local iface=$1 direction=$2 port=$3 rate=$4 protocol=$5 pref=$6 state_file=$7
  local quiet=${8:-n}
  local hook port_match

  hook=$(vless_reality_qos_hook_for_direction "${direction}") || return 1
  case "${direction}" in
    up) port_match="dst_port" ;;
    down) port_match="src_port" ;;
    *) return 1 ;;
  esac

  if tc filter add dev "${iface}" "${hook}" protocol "${protocol}" pref "${pref}" \
    flower ip_proto tcp "${port_match}" "${port}" \
    action police rate "${rate}mbit" burst "${SB_REALITY_QOS_BURST}" conform-exceed drop >/dev/null 2>&1; then
    printf '%s|%s|%s|%s|%s|%s\n' "${iface}" "${direction}" "${protocol}" "${pref}" "${port}" "${rate}" >> "${state_file}"
    return 0
  fi

  if [[ "${quiet}" != "y" ]]; then
    log_warn "REALITY 限速规则应用失败：${iface} ${direction} ${protocol} port ${port} rate ${rate}Mbps。"
  fi
  return 1
}

apply_vless_reality_qos_filter_with_retry() {
  local iface=$1 direction=$2 port=$3 rate=$4 protocol=$5 start_pref=$6 state_file=$7
  local pref attempt max_attempts

  pref="${start_pref}"
  max_attempts=100
  for ((attempt = 0; attempt < max_attempts; attempt++)); do
    if apply_vless_reality_qos_filter "${iface}" "${direction}" "${port}" "${rate}" "${protocol}" "${pref}" "${state_file}" "y"; then
      printf '%s\n' "${pref}"
      return 0
    fi
    pref=$((pref + 1))
  done

  log_warn "REALITY 限速规则应用失败：${iface} ${direction} ${protocol} port ${port} rate ${rate}Mbps，已重试 ${max_attempts} 个 pref。"
  return 1
}

apply_vless_reality_qos_plan() {
  local plan=$1 iface tmp_state line port direction up down protocol pref used_pref failures

  clear_vless_reality_qos_rules

  [[ -n "${plan}" ]] || return 0

  iface=$(detect_default_network_interface) || {
    log_warn "REALITY 限速规则未应用：未能识别默认出口网卡。"
    return 0
  }

  ensure_vless_reality_qos_clsact "${iface}" || return 0

  mkdir -p "$(dirname "${SB_REALITY_QOS_FILTER_STATE_FILE}")"
  tmp_state=$(mktemp)
  pref="${SB_REALITY_QOS_FILTER_PREF_START}"
  failures=0

  while IFS= read -r line; do
    [[ -z "${line}" ]] && continue
    IFS='|' read -r port direction up down <<< "${line}"

    if [[ "${direction}" == "up" || "${direction}" == "both" ]]; then
      for protocol in ip ipv6; do
        if used_pref=$(apply_vless_reality_qos_filter_with_retry "${iface}" "up" "${port}" "${up}" "${protocol}" "${pref}" "${tmp_state}"); then
          pref=$((used_pref + 1))
        else
          pref=$((pref + 100))
          failures=$((failures + 1))
        fi
      done
    fi

    if [[ "${direction}" == "down" || "${direction}" == "both" ]]; then
      for protocol in ip ipv6; do
        if used_pref=$(apply_vless_reality_qos_filter_with_retry "${iface}" "down" "${port}" "${down}" "${protocol}" "${pref}" "${tmp_state}"); then
          pref=$((used_pref + 1))
        else
          pref=$((pref + 100))
          failures=$((failures + 1))
        fi
      done
    fi
  done <<< "${plan}"

  if [[ -s "${tmp_state}" ]]; then
    mv "${tmp_state}" "${SB_REALITY_QOS_FILTER_STATE_FILE}"
  else
    rm -f "${tmp_state}"
  fi

  if (( failures > 0 )); then
    log_warn "REALITY 限速规则部分应用失败，请确认系统 iproute2/tc 支持 flower police。"
  else
    log_success "REALITY 端口限速规则已应用。"
  fi
}

refresh_vless_reality_qos_rules() {
  local plan
  plan=$(build_vless_reality_qos_plan)

  if [[ -z "${plan}" ]]; then
    if command -v tc >/dev/null 2>&1; then
      clear_vless_reality_qos_rules
    fi
    log_info "REALITY 未配置限速，跳过 QoS 规则。"
    return 0
  fi

  if ! command -v tc >/dev/null 2>&1; then
    log_warn "未检测到 tc，REALITY 限速规则未应用。"
    return 0
  fi

  apply_vless_reality_qos_plan "${plan}"
}

append_vless_reality_instance_id() {
  local instance_id=$1 ids=()
  local existing

  while IFS= read -r existing; do
    [[ -n "${existing}" ]] && ids+=("${existing}")
  done < <(list_vless_reality_instance_ids)

  if ! protocol_array_contains "${instance_id}" "${ids[@]}"; then
    ids+=("${instance_id}")
  fi

  VLESS_REALITY_INSTANCE_IDS=$(IFS=,; printf '%s' "${ids[*]}")
}

prompt_vless_reality_instance_selection() {
  local instances=() instance_id index choice rate_summary
  mapfile -t instances < <(list_vless_reality_instance_ids)
  if [[ ${#instances[@]} -eq 0 ]]; then
    log_error "当前未检测到 REALITY 实例。"
  fi

  echo -e "\n${BLUE}--- REALITY 实例 ---${NC}"
  index=1
  for instance_id in "${instances[@]}"; do
    load_vless_reality_instance_state "${instance_id}" || continue
    rate_summary=$(vless_reality_rate_limit_summary "${SB_VLESS_RATE_LIMIT_UP_MBPS}" "${SB_VLESS_RATE_LIMIT_DOWN_MBPS}")
    echo "${index}. ${SB_NODE_NAME} | ${instance_id} | ${SB_PORT} | ${rate_summary}"
    index=$((index + 1))
  done
  echo "0. 返回"
  choice=$(prompt_choice "请选择 REALITY 实例: " 0 "${#instances[@]}" "")
  [[ "${choice}" == "0" ]] && return 1
  SELECTED_VLESS_INSTANCE_ID="${instances[$((choice - 1))]}"
}

remove_vless_reality_instance_id_from_list() {
  local remove_id=$1 ids=() instance_id
  while IFS= read -r instance_id; do
    [[ -z "${instance_id}" || "${instance_id}" == "${remove_id}" ]] && continue
    ids+=("${instance_id}")
  done < <(list_vless_reality_instance_ids)
  VLESS_REALITY_INSTANCE_IDS=$(IFS=,; printf '%s' "${ids[*]}")
}

port_in_configured_protocol_state() {
  local target_port=$1 protocol state_file instance_id port

  validate_port_number "${target_port}" || return 1

  while IFS= read -r protocol; do
    [[ -z "${protocol}" ]] && continue
    if [[ "${protocol}" == "vless-reality" ]]; then
      while IFS= read -r instance_id; do
        [[ -z "${instance_id}" ]] && continue
        port=""
        state_file=$(vless_reality_instance_state_file "${instance_id}") || continue
        if [[ -f "${state_file}" ]]; then
          port=$(grep -E '^PORT=' "${state_file}" | tail -n1 | cut -d= -f2- || true)
          port=${port#\'}
          port=${port%\'}
          port=${port#\"}
          port=${port%\"}
          [[ "${port}" == "${target_port}" ]] && return 0
        fi
      done < <(list_vless_reality_instance_ids)
      continue
    fi

    state_file=$(protocol_state_file "${protocol}")
    if [[ -f "${state_file}" ]]; then
      port=$(grep -E '^PORT=' "${state_file}" | tail -n1 | cut -d= -f2- || true)
      port=${port#\'}
      port=${port%\'}
      port=${port#\"}
      port=${port%\"}
      [[ "${port}" == "${target_port}" ]] && return 0
    fi
  done < <(list_installed_protocols)

  return 1
}

vless_reality_inbound_tag_for_instance() {
  local instance_id=$1
  if [[ -n "${SB_VLESS_INBOUND_TAG:-}" ]]; then
    printf '%s' "${SB_VLESS_INBOUND_TAG}"
    return 0
  fi
  if [[ "${instance_id}" == "${VLESS_REALITY_DEFAULT_INSTANCE_ID:-main}" ]]; then
    printf 'vless-in'
  else
    printf 'vless-reality-%s' "${instance_id}"
  fi
}

validate_vless_reality_instance_tags() {
  local instance_id inbound_tag
  local tags=()

  load_vless_reality_protocol_state
  while IFS= read -r instance_id; do
    [[ -n "${instance_id}" ]] || continue
    load_vless_reality_instance_state "${instance_id}" || return 1
    inbound_tag=$(vless_reality_inbound_tag_for_instance "${instance_id}")
    if protocol_array_contains "${inbound_tag}" "${tags[@]}"; then
      return 1
    fi
    tags+=("${inbound_tag}")
  done < <(list_vless_reality_instance_ids)
}

vless_reality_outbound_policy_from_config() {
  local inbound_tag=$1
  local config_file=${2:-${SINGBOX_CONFIG_FILE}}
  local route_count outbound

  route_count=$(jq -r --arg tag "${inbound_tag}" '[.route.rules[]? | select(.inbound == $tag and .action == "route")] | length' "${config_file}") || return 1
  if [[ "${route_count}" == "0" ]]; then
    printf 'default'
    return 0
  fi
  [[ "${route_count}" == "1" ]] || return 1
  outbound=$(jq -r --arg tag "${inbound_tag}" 'first(.route.rules[]? | select(.inbound == $tag and .action == "route") | .outbound) // ""' "${config_file}") || return 1
  case "${outbound}" in
    direct) printf 'direct' ;;
    warp|warp-ep) printf 'warp' ;;
    *) return 1 ;;
  esac
}

subman_config_file_path() {
  printf '%s/subman.env' "${SB_PROJECT_DIR}"
}

normalize_subman_api_url() {
  local url
  url=$(trim_whitespace "${1:-}")
  while [[ "${url}" == */ ]]; do
    url=${url%/}
  done
  printf '%s' "${url}"
}

load_subman_config() {
  local config_file
  config_file=$(subman_config_file_path)

  SUBMAN_API_URL=""
  SUBMAN_API_TOKEN=""
  SUBMAN_NODE_PREFIX=""

  [[ -f "${config_file}" ]] || return 0

  # shellcheck disable=SC1090
  source "${config_file}"
  SUBMAN_API_URL=$(normalize_subman_api_url "${SUBMAN_API_URL:-}")
  SUBMAN_API_TOKEN=${SUBMAN_API_TOKEN:-}
  SUBMAN_NODE_PREFIX=$(trim_whitespace "${SUBMAN_NODE_PREFIX:-}")
}

write_subman_config() {
  local config_file config_dir tmp_file
  config_file=$(subman_config_file_path)
  config_dir=$(dirname "${config_file}")
  mkdir -p "${config_dir}"
  tmp_file=$(mktemp "${config_dir}/.subman.env.tmp.XXXXXX")
  chmod 600 "${tmp_file}"
  {
    write_env_assignment "SUBMAN_API_URL" "${SUBMAN_API_URL}"
    write_env_assignment "SUBMAN_API_TOKEN" "${SUBMAN_API_TOKEN}"
    write_env_assignment "SUBMAN_NODE_PREFIX" "${SUBMAN_NODE_PREFIX}"
  } > "${tmp_file}"
  mv "${tmp_file}" "${config_file}"
  chmod 600 "${config_file}"
}

prompt_subman_config_if_needed() {
  local input_url input_token input_prefix

  load_subman_config

  while [[ -z "${SUBMAN_API_URL}" ]]; do
    read -rp "SubMan API 地址: " input_url
    SUBMAN_API_URL=$(normalize_subman_api_url "${input_url}")
    [[ -z "${SUBMAN_API_URL}" ]] && log_warn "SubMan API 地址不能为空。"
  done

  while [[ -z "${SUBMAN_API_TOKEN}" ]]; do
    read -rp "SubMan API Token: " input_token
    SUBMAN_API_TOKEN=$(trim_whitespace "${input_token}")
    [[ -z "${SUBMAN_API_TOKEN}" ]] && log_warn "SubMan API Token 不能为空。"
  done

  if [[ -z "${SUBMAN_NODE_PREFIX}" ]]; then
    read -rp "SubMan 节点前缀 (默认: $(hostname)): " input_prefix
    SUBMAN_NODE_PREFIX=$(trim_whitespace "${input_prefix}")
    [[ -z "${SUBMAN_NODE_PREFIX}" ]] && SUBMAN_NODE_PREFIX=$(hostname)
  fi

  write_subman_config
}

write_protocol_index() {
  local recorded_version
  recorded_version=$(resolve_protocol_index_singbox_version)
  ensure_protocol_state_dir
  {
    printf 'INSTALLED_PROTOCOLS=%s\n' "$1"
    printf 'PROTOCOL_STATE_VERSION=1\n'
    if [[ -n "${recorded_version}" ]]; then
      printf 'INSTALLED_SINGBOX_VERSION=%s\n' "${recorded_version}"
    fi
  } > "${SB_PROTOCOL_INDEX_FILE}"
}

extract_protocols_from_index() {
  [[ -f "${SB_PROTOCOL_INDEX_FILE}" ]] || return 0
  local installed
  installed=$(grep '^INSTALLED_PROTOCOLS=' "${SB_PROTOCOL_INDEX_FILE}" 2>/dev/null | cut -d'=' -f2- || true)
  installed=${installed//\"/}
  installed=${installed//\'/}
  installed=${installed//\\,/,}
  printf '%s' "${installed}"
}

extract_recorded_singbox_version_from_index() {
  [[ -f "${SB_PROTOCOL_INDEX_FILE}" ]] || return 0

  local recorded_version
  recorded_version=$(grep '^INSTALLED_SINGBOX_VERSION=' "${SB_PROTOCOL_INDEX_FILE}" 2>/dev/null | cut -d'=' -f2- || true)
  recorded_version=${recorded_version//\"/}
  recorded_version=${recorded_version//\'/}
  recorded_version=$(trim_whitespace "${recorded_version}")
  printf '%s' "${recorded_version}"
}

detect_installed_singbox_version() {
  [[ -x "${SINGBOX_BIN_PATH}" ]] || return 0

  local installed_version
  installed_version=$("${SINGBOX_BIN_PATH}" version 2>/dev/null | head -n1 | awk '{print $3}' || true)
  installed_version=$(trim_whitespace "${installed_version}")
  printf '%s' "${installed_version}"
}

singbox_library_path() {
  local bin_dir
  bin_dir=$(dirname "${SINGBOX_BIN_PATH}") || return 1
  printf '%s/lib/libcronet.so' "$(dirname "${bin_dir}")"
}

# Snapshot the optional NaiveProxy runtime separately from the project
# directory.  Core upgrades replace /usr/local/bin/sing-box, while
# libcronet.so lives beside the binary family and therefore needs its own
# rollback record.  The state markers distinguish a managed regular file from
# an unrelated file/symlink that must never be overwritten or removed.
singbox_library_snapshot() {
  local destination=$1
  local lib_path
  local lib_state='absent'
  local marker_state='absent'

  [[ -n "${destination}" && ! -L "${destination}" ]] || return 1
  lib_path=$(singbox_library_path) || return 1
  mkdir -p "${destination}" || return 1

  if [[ -f "${SB_NAIVE_LIBRARY_MARKER}" && ! -L "${SB_NAIVE_LIBRARY_MARKER}" ]]; then
    cp -p -- "${SB_NAIVE_LIBRARY_MARKER}" "${destination}/libcronet.sha256" || return 1
    marker_state='present'
  elif [[ -e "${SB_NAIVE_LIBRARY_MARKER}" || -L "${SB_NAIVE_LIBRARY_MARKER}" ]]; then
    marker_state='unmanaged'
  fi
  if [[ -f "${lib_path}" && ! -L "${lib_path}" ]]; then
    if [[ "${marker_state}" == "present" ]]; then
      cp -p -- "${lib_path}" "${destination}/libcronet.so" || return 1
      lib_state='present'
    else
      lib_state='unmanaged'
    fi
  elif [[ -e "${lib_path}" || -L "${lib_path}" ]]; then
    lib_state='unmanaged'
  fi

  printf '%s\n' "${lib_state}" > "${destination}/library.state" || return 1
  printf '%s\n' "${marker_state}" > "${destination}/marker.state" || return 1
  chmod 600 "${destination}/library.state" "${destination}/marker.state" || return 1
}

singbox_library_restore_snapshot() {
  local snapshot_dir=$1
  local lib_path lib_dir staged expected_hash actual_hash
  local lib_state marker_state
  local status=0

  [[ -d "${snapshot_dir}" && ! -L "${snapshot_dir}" ]] || return 1
  [[ -f "${snapshot_dir}/library.state" && ! -L "${snapshot_dir}/library.state" ]] || return 1
  [[ -f "${snapshot_dir}/marker.state" && ! -L "${snapshot_dir}/marker.state" ]] || return 1
  lib_state=$(tr -d '[:space:]' < "${snapshot_dir}/library.state") || return 1
  marker_state=$(tr -d '[:space:]' < "${snapshot_dir}/marker.state") || return 1
  lib_path=$(singbox_library_path) || return 1
  lib_dir=$(dirname "${lib_path}")

  case "${lib_state}" in
    present)
      [[ -f "${snapshot_dir}/libcronet.so" && ! -L "${snapshot_dir}/libcronet.so" ]] || return 1
      [[ ! -L "${lib_path}" && ! -d "${lib_path}" ]] || return 1
      mkdir -p "${lib_dir}" || return 1
      staged=$(mktemp "${lib_dir}/.libcronet.restore.XXXXXXXX") || return 1
      if ! cp -p -- "${snapshot_dir}/libcronet.so" "${staged}" ||
         ! chmod 0644 "${staged}" ||
         ! mv -f -- "${staged}" "${lib_path}"; then
        rm -f -- "${staged}"
        return 1
      fi
      ;;
    absent)
      if [[ -f "${lib_path}" && ! -L "${lib_path}" ]]; then
        if [[ -f "${SB_NAIVE_LIBRARY_MARKER}" && ! -L "${SB_NAIVE_LIBRARY_MARKER}" ]]; then
          expected_hash=$(tr -d '[:space:]' < "${SB_NAIVE_LIBRARY_MARKER}") || return 1
          actual_hash=$(sha256sum "${lib_path}" | awk '{print $1}') || return 1
          if [[ -n "${expected_hash}" && "${expected_hash}" == "${actual_hash}" ]]; then
            rm -f -- "${lib_path}" || return 1
          else
            status=1
          fi
        fi
      elif [[ -L "${lib_path}" || -d "${lib_path}" ]]; then
        status=1
      fi
      ;;
    unmanaged)
      :
      ;;
    *)
      return 1
      ;;
  esac

  case "${marker_state}" in
    present)
      [[ -f "${snapshot_dir}/libcronet.sha256" && ! -L "${snapshot_dir}/libcronet.sha256" ]] || return 1
      [[ ! -L "${SB_NAIVE_LIBRARY_MARKER}" && ! -d "${SB_NAIVE_LIBRARY_MARKER}" ]] || return 1
      mkdir -p "${SB_PROJECT_DIR}" || return 1
      staged=$(mktemp "${SB_NAIVE_LIBRARY_MARKER}.restore.XXXXXXXX") || return 1
      if ! cp -p -- "${snapshot_dir}/libcronet.sha256" "${staged}" ||
         ! chmod 600 "${staged}" ||
         ! mv -f -- "${staged}" "${SB_NAIVE_LIBRARY_MARKER}"; then
        rm -f -- "${staged}"
        return 1
      fi
      ;;
    absent)
      if [[ -f "${SB_NAIVE_LIBRARY_MARKER}" && ! -L "${SB_NAIVE_LIBRARY_MARKER}" ]]; then
        rm -f -- "${SB_NAIVE_LIBRARY_MARKER}" || return 1
      elif [[ -L "${SB_NAIVE_LIBRARY_MARKER}" || -d "${SB_NAIVE_LIBRARY_MARKER}" ]]; then
        status=1
      fi
      ;;
    unmanaged)
      :
      ;;
    *)
      return 1
      ;;
  esac

  if [[ "${lib_state}" == "present" || "${lib_state}" == "absent" ]] &&
     [[ "$(dirname "${lib_path}")" == "/usr/local/lib" ]] &&
     command -v ldconfig >/dev/null 2>&1; then
    ldconfig || status=1
  fi
  return "${status}"
}

resolve_protocol_index_singbox_version() {
  local installed_version recorded_version

  installed_version=$(detect_installed_singbox_version)
  if [[ -n "${installed_version}" ]]; then
    printf '%s' "${installed_version}"
    return 0
  fi

  recorded_version=$(extract_recorded_singbox_version_from_index)
  if [[ -n "${recorded_version}" ]]; then
    printf '%s' "${recorded_version}"
  fi
}

list_indexed_protocols_raw() {
  local installed protocol
  local protocols=()
  installed=$(extract_protocols_from_index)
  [[ -z "${installed}" ]] && return 0

  IFS=',' read -r -a protocols <<< "${installed}"
  for protocol in "${protocols[@]}"; do
    protocol=$(trim_whitespace "${protocol}")
    [[ -n "${protocol}" ]] && printf '%s\n' "${protocol}"
  done
}

protocol_state_exists() {
  local protocol
  protocol=$(normalize_protocol_id "$1") || return 1
  [[ -f "$(protocol_state_file "${protocol}")" ]]
}

validate_protocol_state_schema() {
  local protocol=$1 state_file=$2 schema
  [[ -f "${state_file}" ]] || return 0
  if [[ "${protocol}" == "mixed" ]]; then
    if grep -Eq "^[[:space:]]*CONFIG_SCHEMA_VERSION=(2|\"2\"|'2')[[:space:]]*$" "${state_file}"; then
      mixed_structured_marker_is_valid "${state_file}" || {
        printf '[ERROR] Mixed schema 2 marker 格式无效；已保留文件，拒绝执行其内容。\n' >&2
        return 1
      }
      return 0
    fi
  fi
  schema=$(sed -n 's/^[[:space:]]*CONFIG_SCHEMA_VERSION=//p' "${state_file}") || return 1
  schema=${schema//\"/}
  schema=${schema//\'/}
  case "${protocol}:${schema:-1}" in
    vless-reality:1|vless-reality:2|vless-plain:2|mixed:1|mixed:2|socks:2|http:2|shadowsocks:2|trojan:2|vmess:2|hy2:1|hy2:2|anytls:1|anytls:2|snell:2|tuic:2|hysteria:2|naive:2|shadowtls:2) return 0 ;;
  esac
  printf '[ERROR] 协议状态格式无法识别；已保留文件，请使用写入该状态的脚本版本恢复。\n' >&2
  return 1
}

validate_protocol_index_for_rebuild() {
  local schema indexed protocol protocols state_file state_id
  # The rebuild clears legacy .env files, including ones not in the index.
  # Validate their identity before permitting that operation.
  for state_file in "${SB_PROTOCOL_STATE_DIR}"/*.env; do
    [[ -e "${state_file}" ]] || continue
    [[ "${state_file}" == "${SB_PROTOCOL_INDEX_FILE}" ]] && continue
    state_id=${state_file##*/}
    state_id=${state_id%.env}
    if ! protocol=$(normalize_protocol_id "${state_id}") || [[ "${protocol}" != "${state_id}" ]]; then
      printf '[ERROR] 发现未识别的协议状态文件；已保留文件，禁止有损重建，请恢复兼容脚本。\n' >&2
      return 1
    fi
    validate_protocol_state_schema "${protocol}" "${state_file}" || return 1
  done
  [[ -f "${SB_PROTOCOL_INDEX_FILE}" ]] || return 0
  schema=$(sed -n 's/^PROTOCOL_STATE_VERSION=//p' "${SB_PROTOCOL_INDEX_FILE}") || return 1
  schema=${schema//\"/}
  schema=${schema//\'/}
  if [[ "${schema:-1}" != "1" ]]; then
    printf '[ERROR] 协议索引格式无法识别；已保留状态，禁止有损重建，请恢复兼容脚本。\n' >&2
    return 1
  fi
  protocols=$(list_indexed_protocols_raw) || return 1
  while IFS= read -r indexed; do
    [[ -n "${indexed}" ]] || continue
    if ! protocol=$(normalize_protocol_id "${indexed}"); then
      printf '[ERROR] 索引包含未知协议；已保留全部条目，请使用支持该协议的脚本。\n' >&2
      return 1
    fi
    validate_protocol_state_schema "${protocol}" "$(protocol_state_file "${protocol}")" || return 1
  done <<< "${protocols}"
}

reconcile_protocol_index_if_needed() {
  local inventory_state_file=${1:-}
  local indexed_protocols=() valid_protocols=()
  local protocol joined_protocols current_protocols

  [[ -f "${SB_PROTOCOL_INDEX_FILE}" ]] || return 0
  validate_protocol_index_for_rebuild || return 1
  validate_live_inbound_inventory "${SINGBOX_CONFIG_FILE}" "${inventory_state_file}" || return 1

  mapfile -t indexed_protocols < <(list_indexed_protocols_raw)
  current_protocols=$(extract_protocols_from_index)

  for protocol in "${indexed_protocols[@]}"; do
    protocol=$(normalize_protocol_id "${protocol}") || return 1
    if protocol_state_exists "${protocol}"; then
      if ! protocol_array_contains "${protocol}" ${valid_protocols[@]+"${valid_protocols[@]}"}; then
        valid_protocols+=("${protocol}")
      fi
    else
      # A stale index entry with no corresponding config is a supported legacy
      # repair. If the live inbound still exists, dropping it would lose data;
      # explicit takeover must reconstruct its state first.
      if [[ -f "${SINGBOX_CONFIG_FILE}" ]]; then
        if ! jq -e 'type == "object"' "${SINGBOX_CONFIG_FILE}" >/dev/null 2>&1 ||
           [[ "$(config_protocol_inbound_count "${protocol}" "${SINGBOX_CONFIG_FILE}" 2>/dev/null || printf 0)" -gt 0 ]]; then
          printf '[ERROR] 协议状态缺失但配置仍需保留；未修改索引，请执行接管以恢复状态。\n' >&2
          return 1
        fi
      fi
      log_warn "检测到无对应状态或运行配置的过期索引条目: ${protocol}" >&2
    fi
  done

  if [[ ${#valid_protocols[@]} -eq 0 ]]; then
    if [[ -f "${SINGBOX_CONFIG_FILE}" ]]; then
      # Keep the original index in the rebuild snapshot. An empty/unrecognized
      # config or a failed state write must not erase it, even in an if/|| call.
      rebuild_protocol_state_from_config || return $?
    fi
    return 0
  fi

  joined_protocols=$(IFS=,; printf '%s' "${valid_protocols[*]}")
  if [[ "${joined_protocols}" != "${current_protocols}" ]]; then
    write_protocol_index "${joined_protocols}"
  fi
}

list_installed_protocols() {
  reconcile_protocol_index_if_needed "${1:-}" || return $?
  list_indexed_protocols_raw
}

list_exportable_client_protocols() {
  local protocol protocols

  protocols=$(list_installed_protocols) || return 1
  while IFS= read -r protocol; do
    [[ -n "${protocol}" ]] || continue
    if [[ "$(protocol_registry_field "${protocol}" client_export)" == "true" ]]; then
      printf '%s\n' "${protocol}"
    fi
  done <<< "${protocols}"
}

save_vless_reality_state() {
  if [[ -z "${SB_UUID}" ]]; then
    SB_UUID=$(uuidgen 2>/dev/null || cat /proc/sys/kernel/random/uuid)
  fi

  if [[ -z "${SB_SHORT_ID_1}" ]]; then
    SB_SHORT_ID_1=$(openssl rand -hex 8)
  fi

  if [[ -z "${SB_SHORT_ID_2}" && "${SB_VLESS_PRESERVE_SINGLE_SHORT_ID:-n}" != "y" ]]; then
    SB_SHORT_ID_2=$(openssl rand -hex 8)
  fi

  VLESS_REALITY_DEFAULT_INSTANCE_ID="${VLESS_REALITY_DEFAULT_INSTANCE_ID:-main}"
  VLESS_REALITY_INSTANCE_IDS="${VLESS_REALITY_INSTANCE_IDS:-${SB_VLESS_INSTANCE_ID:-main}}"
  save_vless_reality_protocol_state
  save_vless_reality_instance_state
}

save_mixed_state() {
  local state_file store_file instance_id current_revision record_file candidate_file state_schema
  state_file=$(protocol_state_file "mixed")

  state_schema=$(sed -n 's/^[[:space:]]*CONFIG_SCHEMA_VERSION=//p' "${state_file}" 2>/dev/null | head -n1 || true)
  state_schema=${state_schema//\"/}
  state_schema=${state_schema//\'/}
  if [[ "${state_schema}" == "2" ]]; then
    mixed_structured_state_active || {
      printf '[ERROR] Mixed 结构化状态无效，未写入状态文件。\n' >&2
      return 1
    }
    store_file=$(mixed_structured_store_file) || return 1
    instance_id=${SB_MIXED_INSTANCE_ID:-${SB_INSTANCE_ID:-}}
    if [[ -z "${instance_id}" ]]; then
      instance_id=$(jq -r '.default_instance_id' "${store_file}") || return 1
    fi
    structured_instance_store_validate_id "${instance_id}" || return 1
    current_revision=$(structured_instance_store_revision "${store_file}") || return 1
    record_file=$(mktemp) || return 1
    candidate_file=$(mktemp) || {
      rm -f -- "${record_file}"
      return 1
    }
    if ! jq -c --arg id "${instance_id}" \
        --arg name "${SB_NODE_NAME:-}" \
        --arg port "${SB_PORT:-}" \
        --arg auth_enabled "${SB_MIXED_AUTH_ENABLED:-}" \
        --arg username "${SB_MIXED_USERNAME:-}" \
        --arg password "${SB_MIXED_PASSWORD:-}" \
        --arg outbound_policy "${SB_OUTBOUND_POLICY:-default}" \
        'first(.instances[] | select(.id == $id) |
          .name = $name |
          .listen.port = ($port | tonumber) |
          .authentication = {
            enabled: ($auth_enabled == "y"),
            username: (if $auth_enabled == "y" then $username else "" end),
            password: (if $auth_enabled == "y" then $password else "" end)
          } |
          .outbound_policy = $outbound_policy)' "${store_file}" > "${record_file}"; then
      rm -f -- "${record_file}" "${candidate_file}"
      return 1
    fi
    if [[ ! -s "${record_file}" ]] ||
       ! structured_instance_store_validate_instance_argument "${record_file}"; then
      rm -f -- "${record_file}" "${candidate_file}"
      printf '[ERROR] Mixed 结构化实例记录无效，未写入状态文件。\n' >&2
      return 1
    fi
    if ! structured_instance_store_candidate mixed "${store_file}" replace \
        "${record_file}" "${current_revision}" > "${candidate_file}" ||
       ! publish_structured_instance_store mixed "${candidate_file}" "${current_revision}"; then
      rm -f -- "${record_file}" "${candidate_file}"
      return 1
    fi
    rm -f -- "${record_file}" "${candidate_file}"
    load_mixed_structured_instance "${instance_id}" || return 1
    return 0
  fi

  if [[ -e "$(mixed_structured_store_file)" ]]; then
    printf '[ERROR] 已有 Mixed 结构化状态或 revision 记录；请使用实例管理入口，未覆盖为 legacy 状态。\n' >&2
    return 1
  fi

  {
    write_env_assignment "INSTALLED" "1"
    write_env_assignment "CONFIG_SCHEMA_VERSION" "1"
    write_env_assignment "NODE_NAME" "${SB_NODE_NAME}"
    write_env_assignment "PORT" "${SB_PORT}"
    write_env_assignment "AUTH_ENABLED" "${SB_MIXED_AUTH_ENABLED}"
    write_env_assignment "USERNAME" "${SB_MIXED_USERNAME}"
    write_env_assignment "PASSWORD" "${SB_MIXED_PASSWORD}"
  } > "${state_file}"
}

save_plain_proxy_state() {
  local protocol=${1:-} state_file store_file current_revision
  local record_file candidate_file operation expected_revision
  local listen_address=${SB_MIXED_LISTEN_ADDRESS:-} port=${SB_PORT:-}
  local auth_enabled=${SB_MIXED_AUTH_ENABLED:-y} username=${SB_MIXED_USERNAME:-} password=${SB_MIXED_PASSWORD:-}
  local tag name policy=${SB_OUTBOUND_POLICY:-default} tls_json='{"enabled":false}' auth_json='{}' network_json='["tcp","udp"]' transport_json='{"type":"none"}' client_trust=certificate instance_id=${SB_INSTANCE_ID:-main}
  local snell_version=${SB_SNELL_VERSION:-6} snell_psk=${SB_SNELL_PSK:-} snell_users_json=${SB_SNELL_USER_JSON:-[]} snell_obfs_mode=${SB_SNELL_OBFS_MODE:-} snell_obfs_host=${SB_SNELL_OBFS_HOST:-} snell_mode=${SB_SNELL_MODE:-}
  local tuic_users_json=${SB_TUIC_AUTH_JSON:-[]} tuic_tls_json=${SB_TUIC_TLS_JSON:-'{"enabled":false}'} tuic_client_trust=${SB_TUIC_CLIENT_TRUST:-system}
  local tuic_congestion_control=${SB_TUIC_CONGESTION_CONTROL:-bbr} tuic_auth_timeout_seconds=${SB_TUIC_AUTH_TIMEOUT_SECONDS:-3} tuic_heartbeat_seconds=${SB_TUIC_HEARTBEAT_SECONDS:-10} tuic_zero_rtt_handshake=${SB_TUIC_ZERO_RTT_HANDSHAKE:-n} tuic_udp_relay_mode=${SB_TUIC_UDP_RELAY_MODE:-native} tuic_udp_over_stream=${SB_TUIC_UDP_OVER_STREAM:-n}
  local hysteria_users_json=${SB_HYSTERIA_AUTH_JSON:-[]} hysteria_tls_json=${SB_HYSTERIA_TLS_JSON:-'{"enabled":false}'} hysteria_client_trust=${SB_HYSTERIA_CLIENT_TRUST:-system}
  local hysteria_up_mbps=${SB_HYSTERIA_UP_MBPS:-100} hysteria_down_mbps=${SB_HYSTERIA_DOWN_MBPS:-100} hysteria_obfs_enabled=${SB_HYSTERIA_OBFS_ENABLED:-n} hysteria_obfs_password=${SB_HYSTERIA_OBFS_PASSWORD:-} hysteria_quic_json=${SB_HYSTERIA_QUIC_JSON:-'{"connection_receive_window":"","disable_path_mtu_discovery":false,"initial_packet_size":0,"max_concurrent_streams":0,"stream_receive_window":""}'}
  local naive_users_json=${SB_NAIVE_AUTH_JSON:-[]} naive_tls_json=${SB_NAIVE_TLS_JSON:-'{"enabled":false}'} naive_client_trust=${SB_NAIVE_CLIENT_TRUST:-system}
  local naive_network_json=${SB_NAIVE_NETWORK_JSON:-'["tcp","udp"]'} naive_quic_congestion_control=${SB_NAIVE_QUIC_CONGESTION_CONTROL:-bbr} naive_quic=${SB_NAIVE_QUIC:-n} naive_insecure_concurrency=${SB_NAIVE_INSECURE_CONCURRENCY:-0} naive_stream_receive_window=${SB_NAIVE_STREAM_RECEIVE_WINDOW:-} naive_quic_session_receive_window=${SB_NAIVE_QUIC_SESSION_RECEIVE_WINDOW:-} naive_extra_headers_json=${SB_NAIVE_EXTRA_HEADERS_JSON:-'{}'}

  if [[ "${protocol}" == "shadowtls" ]]; then
    save_shadowtls_state
    return $?
  fi

  structured_instance_store_protocol "${protocol}" >/dev/null || return 1
  case "${protocol}" in
    socks) tag=${SB_MIXED_INBOUND_TAG:-socks-in}; name=${SB_NODE_NAME:-SOCKS} ;;
    http)
      tag=${SB_MIXED_INBOUND_TAG:-http-in}; name=${SB_NODE_NAME:-HTTP}
      [[ -n "${SB_HTTP_TLS_JSON:-}" ]] || return 1
      tls_json=${SB_HTTP_TLS_JSON}
      validate_http_tls_state_json "${tls_json}" || return 1
      ;;
    shadowsocks)
      tag=${SB_MIXED_INBOUND_TAG:-ss-in}; name=${SB_NODE_NAME:-Shadowsocks}
      [[ -n "${SB_SHADOWSOCKS_AUTH_JSON:-}" && -n "${SB_SHADOWSOCKS_NETWORK_JSON:-}" ]] || return 1
      auth_json=${SB_SHADOWSOCKS_AUTH_JSON}; network_json=${SB_SHADOWSOCKS_NETWORK_JSON}
      jq -e 'type == "object"' <<< "${auth_json}" >/dev/null 2>&1 || return 1
      jq -e 'type == "array" and length > 0' <<< "${network_json}" >/dev/null 2>&1 || return 1
      ;;
    trojan)
      tag=${SB_MIXED_INBOUND_TAG:-trojan-in}; name=${SB_NODE_NAME:-Trojan}
      auth_json=${SB_TROJAN_AUTH_JSON:-[]}; tls_json=${SB_TROJAN_TLS_JSON:-'{"enabled":false}'}
      transport_json=${SB_TROJAN_TRANSPORT_JSON:-'{"type":"none"}'}
      client_trust=${SB_TROJAN_CLIENT_TRUST:-certificate}
      jq -e 'type == "array" and length > 0' <<< "${auth_json}" >/dev/null 2>&1 || return 1
      jq -e 'type == "object"' <<< "${tls_json}" >/dev/null 2>&1 || return 1
      jq -e 'type == "object"' <<< "${transport_json}" >/dev/null 2>&1 || return 1
      [[ "${client_trust}" == certificate || "${client_trust}" == system ]] || return 1
      ;;
    vmess)
      tag=${SB_MIXED_INBOUND_TAG:-vmess-in}; name=${SB_NODE_NAME:-VMess}
      auth_json=${SB_VMESS_AUTH_JSON:-[]}; tls_json=${SB_VMESS_TLS_JSON:-'{"enabled":false}'}
      transport_json=${SB_VMESS_TRANSPORT_JSON:-'{"type":"none"}'}
      client_trust=${SB_VMESS_CLIENT_TRUST:-certificate}
      jq -e 'type == "array" and length > 0' <<< "${auth_json}" >/dev/null 2>&1 || return 1
      jq -e 'type == "object"' <<< "${tls_json}" >/dev/null 2>&1 || return 1
      jq -e 'type == "object"' <<< "${transport_json}" >/dev/null 2>&1 || return 1
      [[ "${client_trust}" == certificate || "${client_trust}" == system ]] || return 1
      ;;
    vless-plain)
      tag=${SB_MIXED_INBOUND_TAG:-vless-plain-in}; name=${SB_NODE_NAME:-VLESS}
      auth_json=${SB_VLESS_PLAIN_AUTH_JSON:-[]}; tls_json=${SB_VLESS_PLAIN_TLS_JSON:-'{"enabled":false}'}
      transport_json=${SB_VLESS_PLAIN_TRANSPORT_JSON:-'{"type":"none"}'}
      client_trust=${SB_VLESS_PLAIN_CLIENT_TRUST:-system}
      jq -e 'type == "array" and length > 0' <<< "${auth_json}" >/dev/null 2>&1 || return 1
      jq -e 'type == "object"' <<< "${tls_json}" >/dev/null 2>&1 || return 1
      jq -e 'type == "object"' <<< "${transport_json}" >/dev/null 2>&1 || return 1
      [[ "${client_trust}" == certificate || "${client_trust}" == system ]] || return 1
      ;;
    snell)
      tag=${SB_MIXED_INBOUND_TAG:-snell-in}; name=${SB_NODE_NAME:-Snell}
      snell_version=${SB_SNELL_VERSION:-6}; snell_psk=${SB_SNELL_PSK:-}; snell_users_json=${SB_SNELL_USER_JSON:-[]}
      snell_obfs_mode=${SB_SNELL_OBFS_MODE:-}; snell_obfs_host=${SB_SNELL_OBFS_HOST:-}; snell_mode=${SB_SNELL_MODE:-}
      ensure_snell_materials || return 1
      snell_version=${SB_SNELL_VERSION}; snell_psk=${SB_SNELL_PSK}; snell_users_json=${SB_SNELL_USER_JSON}
      snell_obfs_mode=${SB_SNELL_OBFS_MODE}; snell_obfs_host=${SB_SNELL_OBFS_HOST}; snell_mode=${SB_SNELL_MODE}
      ;;
    tuic)
      tag=${SB_MIXED_INBOUND_TAG:-tuic-in}; name=${SB_NODE_NAME:-TUIC}
      tuic_users_json=${SB_TUIC_AUTH_JSON:-[]}; tuic_tls_json=${SB_TUIC_TLS_JSON:-'{"enabled":false}'}
      tuic_client_trust=${SB_TUIC_CLIENT_TRUST:-system}
      ensure_tuic_materials || return 1
      tuic_users_json=${SB_TUIC_AUTH_JSON}; tuic_tls_json=${SB_TUIC_TLS_JSON}; tuic_client_trust=${SB_TUIC_CLIENT_TRUST}
      tuic_congestion_control=${SB_TUIC_CONGESTION_CONTROL}; tuic_auth_timeout_seconds=${SB_TUIC_AUTH_TIMEOUT_SECONDS}; tuic_heartbeat_seconds=${SB_TUIC_HEARTBEAT_SECONDS}; tuic_zero_rtt_handshake=${SB_TUIC_ZERO_RTT_HANDSHAKE}; tuic_udp_relay_mode=${SB_TUIC_UDP_RELAY_MODE}; tuic_udp_over_stream=${SB_TUIC_UDP_OVER_STREAM}
      ;;
    hysteria)
      tag=${SB_MIXED_INBOUND_TAG:-hysteria-in}; name=${SB_NODE_NAME:-Hysteria}
      hysteria_users_json=${SB_HYSTERIA_AUTH_JSON:-[]}; hysteria_tls_json=${SB_HYSTERIA_TLS_JSON:-'{"enabled":false}'}
      hysteria_client_trust=${SB_HYSTERIA_CLIENT_TRUST:-system}
      hysteria_up_mbps=${SB_HYSTERIA_UP_MBPS:-100}; hysteria_down_mbps=${SB_HYSTERIA_DOWN_MBPS:-100}
      hysteria_obfs_enabled=${SB_HYSTERIA_OBFS_ENABLED:-n}; hysteria_obfs_password=${SB_HYSTERIA_OBFS_PASSWORD:-}
      hysteria_quic_json=${SB_HYSTERIA_QUIC_JSON:-'{"connection_receive_window":"","disable_path_mtu_discovery":false,"initial_packet_size":0,"max_concurrent_streams":0,"stream_receive_window":""}'}
      ensure_hysteria_materials || return 1
      hysteria_users_json=${SB_HYSTERIA_AUTH_JSON}; hysteria_tls_json=${SB_HYSTERIA_TLS_JSON}; hysteria_client_trust=${SB_HYSTERIA_CLIENT_TRUST}
      hysteria_up_mbps=${SB_HYSTERIA_UP_MBPS}; hysteria_down_mbps=${SB_HYSTERIA_DOWN_MBPS}; hysteria_obfs_enabled=${SB_HYSTERIA_OBFS_ENABLED}; hysteria_obfs_password=${SB_HYSTERIA_OBFS_PASSWORD}; hysteria_quic_json=${SB_HYSTERIA_QUIC_JSON}
      ;;
    naive)
      tag=${SB_MIXED_INBOUND_TAG:-naive-in}; name=${SB_NODE_NAME:-NaiveProxy}
      naive_users_json=${SB_NAIVE_AUTH_JSON:-[]}; naive_tls_json=${SB_NAIVE_TLS_JSON:-'{"enabled":false}'}; naive_client_trust=${SB_NAIVE_CLIENT_TRUST:-system}
      naive_network_json=${SB_NAIVE_NETWORK_JSON:-'["tcp","udp"]'}; naive_quic_congestion_control=${SB_NAIVE_QUIC_CONGESTION_CONTROL:-bbr}; naive_quic=${SB_NAIVE_QUIC:-n}
      naive_insecure_concurrency=${SB_NAIVE_INSECURE_CONCURRENCY:-0}; naive_stream_receive_window=${SB_NAIVE_STREAM_RECEIVE_WINDOW:-}; naive_quic_session_receive_window=${SB_NAIVE_QUIC_SESSION_RECEIVE_WINDOW:-}; naive_extra_headers_json=${SB_NAIVE_EXTRA_HEADERS_JSON:-'{}'}
      ensure_naive_materials || return 1
      naive_users_json=${SB_NAIVE_AUTH_JSON}; naive_tls_json=${SB_NAIVE_TLS_JSON}; naive_client_trust=${SB_NAIVE_CLIENT_TRUST}
      naive_network_json=${SB_NAIVE_NETWORK_JSON}; naive_quic_congestion_control=${SB_NAIVE_QUIC_CONGESTION_CONTROL}; naive_quic=${SB_NAIVE_QUIC}
      naive_insecure_concurrency=${SB_NAIVE_INSECURE_CONCURRENCY}; naive_stream_receive_window=${SB_NAIVE_STREAM_RECEIVE_WINDOW}; naive_quic_session_receive_window=${SB_NAIVE_QUIC_SESSION_RECEIVE_WINDOW}; naive_extra_headers_json=${SB_NAIVE_EXTRA_HEADERS_JSON}
      ;;
    *) return 1 ;;
  esac
  state_file=$(protocol_state_file "${protocol}") || return 1
  if [[ -e "${state_file}" || -L "${state_file}" ]]; then
    [[ -f "${state_file}" && ! -L "${state_file}" ]] || return 1
    validate_protocol_state_schema "${protocol}" "${state_file}" || return 1
    plain_proxy_structured_marker_is_valid "${state_file}" || return 1
  fi
  store_file=$(plain_proxy_structured_store_file "${protocol}") || return 1
  if [[ -f "${state_file}" ]]; then
    [[ -f "${store_file}" && ! -L "${store_file}" ]] || return 1
  elif [[ -e "${store_file}" || -L "${store_file}" ]]; then
    plain_proxy_inactive_store_snapshot "${protocol}" >/dev/null || return 1
  fi
  [[ -n "${listen_address}" ]] || listen_address='127.0.0.1'
  structured_instance_store_validate_id "${instance_id}" || return 1
  [[ -n "${tag}" ]] || return 1
  validate_port_number "${port}" || return 1
  structured_instance_store_validate_address "${listen_address}" || return 1
  if [[ "${protocol}" != shadowsocks && "${protocol}" != snell && "${protocol}" != tuic && "${protocol}" != hysteria && "${protocol}" != naive ]]; then
    case "${auth_enabled}" in y|n) ;; *) return 1 ;; esac
  fi
  if [[ "${protocol}" == http ]]; then
    validate_http_client_connection "${port}" "${auth_enabled}" "${username}" "${password}" || return 1
  elif [[ "${protocol}" != shadowsocks && "${protocol}" != snell && "${protocol}" != tuic && "${protocol}" != hysteria && "${protocol}" != naive && "${protocol}" != trojan && "${protocol}" != vmess && "${protocol}" != vless-plain ]]; then
    validate_mixed_client_connection "${port}" "${auth_enabled}" "${username}" "${password}" || return 1
  fi
  [[ "${policy}" == default || "${policy}" == direct || "${policy}" == warp ]] || return 1
  if [[ "${protocol}" == http || "${protocol}" == trojan || "${protocol}" == vmess || "${protocol}" == vless-plain || "${protocol}" == tuic || "${protocol}" == hysteria || "${protocol}" == naive ]]; then
    jq -e 'type == "object"' <<< "${tls_json}" >/dev/null 2>&1 || return 1
  fi

  record_file=$(mktemp) || return 1
  candidate_file=$(mktemp) || { rm -f -- "${record_file}"; return 1; }
  if ! jq -n -cS --arg id "${instance_id}" --arg name "${name}" --arg tag "${tag}" \
      --arg address "${listen_address}" --argjson port "${port}" \
      --argjson enabled "$([[ "${auth_enabled}" == y ]] && printf true || printf false)" \
      --arg username "${username}" --arg password "${password}" --arg policy "${policy}" --argjson tls "${tls_json}" --argjson auth "${auth_json}" --argjson network "${network_json}" --argjson transport "${transport_json}" --arg client_trust "${client_trust}" --arg protocol "${protocol}" \
      --argjson snell_version "${snell_version}" --arg snell_psk "${snell_psk}" --argjson snell_users "${snell_users_json}" --arg snell_obfs_mode "${snell_obfs_mode}" --arg snell_obfs_host "${snell_obfs_host}" --arg snell_mode "${snell_mode}" \
      --argjson tuic_users "${tuic_users_json}" --argjson tuic_tls "${tuic_tls_json}" --arg tuic_trust "${tuic_client_trust}" --arg tuic_cc "${tuic_congestion_control}" --argjson tuic_auth_timeout "${tuic_auth_timeout_seconds}" --argjson tuic_heartbeat "${tuic_heartbeat_seconds}" --argjson tuic_zero_rtt "$([[ "${tuic_zero_rtt_handshake}" == y ]] && printf true || printf false)" --arg tuic_relay "${tuic_udp_relay_mode}" --argjson tuic_uos "$([[ "${tuic_udp_over_stream}" == y ]] && printf true || printf false)" \
      --argjson hysteria_users "${hysteria_users_json}" --argjson hysteria_tls "${hysteria_tls_json}" --arg hysteria_trust "${hysteria_client_trust}" --argjson hysteria_up "${hysteria_up_mbps}" --argjson hysteria_down "${hysteria_down_mbps}" --argjson hysteria_obfs_enabled "$([[ "${hysteria_obfs_enabled}" == y ]] && printf true || printf false)" --arg hysteria_obfs_password "${hysteria_obfs_password}" --argjson hysteria_quic "${hysteria_quic_json}" \
      --argjson naive_users "${naive_users_json}" --argjson naive_tls "${naive_tls_json}" --arg naive_trust "${naive_client_trust}" --argjson naive_network "${naive_network_json}" --arg naive_cc "${naive_quic_congestion_control}" --argjson naive_quic "$([[ "${naive_quic}" == y ]] && printf true || printf false)" --argjson naive_insecure_concurrency "${naive_insecure_concurrency}" --arg naive_stream_receive_window "${naive_stream_receive_window}" --arg naive_quic_session_receive_window "${naive_quic_session_receive_window}" --argjson naive_extra_headers "${naive_extra_headers_json}" \
      '{id:$id,name:$name,tag:$tag,listen:{address:$address,port:$port},authentication:{enabled:$enabled,username:(if $enabled then $username else "" end),password:(if $enabled then $password else "" end)},outbound_policy:$policy,dependencies:[]} + (if $protocol == "http" then {tls:$tls} elif $protocol == "shadowsocks" then {listen:{address:$address,port:$port,network:$network},authentication:$auth} elif $protocol == "trojan" or $protocol == "vmess" or $protocol == "vless-plain" then {authentication:{users:$auth},tls:$tls,transport:$transport,client_trust:$client_trust} elif $protocol == "snell" then {version:$snell_version,authentication:{psk:$snell_psk,users:$snell_users},obfs_mode:$snell_obfs_mode,obfs_host:$snell_obfs_host,mode:$snell_mode} elif $protocol == "tuic" then {authentication:{users:$tuic_users},tls:$tuic_tls,client_trust:$tuic_trust,tuic:{auth_timeout_seconds:$tuic_auth_timeout,congestion_control:$tuic_cc,heartbeat_seconds:$tuic_heartbeat,udp_over_stream:$tuic_uos,udp_relay_mode:$tuic_relay,zero_rtt_handshake:$tuic_zero_rtt}} elif $protocol == "hysteria" then {authentication:{users:$hysteria_users},tls:$hysteria_tls,client_trust:$hysteria_trust,bandwidth:{up_mbps:$hysteria_up,down_mbps:$hysteria_down},obfs:{enabled:$hysteria_obfs_enabled,password:$hysteria_obfs_password},hysteria:$hysteria_quic} elif $protocol == "naive" then {authentication:{users:$naive_users},tls:$naive_tls,client_trust:$naive_trust,listen:{address:$address,port:$port,network:$naive_network},naive:{quic_congestion_control:$naive_cc,quic:$naive_quic,insecure_concurrency:$naive_insecure_concurrency,stream_receive_window:$naive_stream_receive_window,quic_session_receive_window:$naive_quic_session_receive_window,extra_headers:$naive_extra_headers}} else {} end)' > "${record_file}"; then
    rm -f -- "${record_file}" "${candidate_file}"; return 1
  fi
  structured_instance_store_validate_instance_argument "${record_file}" "${protocol}" || {
    rm -f -- "${record_file}" "${candidate_file}"; return 1;
  }
  if [[ -f "${store_file}" ]]; then
    validate_structured_instance_store "${protocol}" "${store_file}" || { rm -f -- "${record_file}" "${candidate_file}"; return 1; }
    current_revision=$(structured_instance_store_revision "${store_file}") || { rm -f -- "${record_file}" "${candidate_file}"; return 1; }
    expected_revision=${current_revision}
    if jq -e --arg id "${instance_id}" 'any(.instances[]; .id == $id)' "${store_file}" >/dev/null 2>&1; then operation=replace; else operation=create; fi
    structured_instance_store_candidate "${protocol}" "${store_file}" "${operation}" "${record_file}" "${expected_revision}" > "${candidate_file}" || {
      rm -f -- "${record_file}" "${candidate_file}"; return 1;
    }
  else
    structured_instance_store_candidate "${protocol}" "" create "${record_file}" 0 > "${candidate_file}" || {
      rm -f -- "${record_file}" "${candidate_file}"; return 1;
    }
    expected_revision=0
  fi
  if ! publish_structured_instance_store "${protocol}" "${candidate_file}" "${expected_revision}" ||
     ! save_plain_proxy_structured_marker "${protocol}"; then
    rm -f -- "${record_file}" "${candidate_file}"; return 1
  fi
  rm -f -- "${record_file}" "${candidate_file}"
  load_plain_proxy_structured_instance "${protocol}" "${instance_id}"
}

