  set_protocol_defaults vless-plain
  echo -e '\n'"${BLUE}"'--- 配置普通 VLESS ---'"${NC}" >&2
  SB_PORT=$(prompt_port '[VLESS] 端口 (默认当前值): ' "${SB_PORT}") || return 1
