  SB_ADVANCED_ROUTE=$(prompt_yes_no "是否开启高级路由规则 (广告拦截/局域网绕行) [y/n] (默认 y): " "y")
  SB_ENABLE_WARP=$(prompt_yes_no "是否开启 Cloudflare Warp (用于解锁/防送中) [y/n] (默认 n): " "n")

  if [[ "${SB_ENABLE_WARP}" == "y" ]]; then
