      SB_PORT="$(pick_random_high_port)"
      SB_SNI=""
      SB_UUID=""
      SB_PUBLIC_KEY=""
      SB_PRIVATE_KEY=""
      SB_SHORT_ID_1=""
      SB_SHORT_ID_2=""
      SB_MIXED_AUTH_ENABLED="y"
      SB_MIXED_USERNAME=""
      SB_MIXED_PASSWORD=""
      SB_INSTANCE_ID=""
      SB_MIXED_INSTANCE_ID=""
      SB_MIXED_INBOUND_TAG="socks-in"
      SB_MIXED_LISTEN_ADDRESS="127.0.0.1"
      SB_MIXED_STORE_REVISION="0"
