add_warp_domain_entry() {
  ensure_warp_routing_assets

  local domain_entry
  read -rp "请输入域名（= 前缀表示精确匹配，其余默认 suffix 匹配）: " domain_entry
  domain_entry=$(trim_whitespace "${domain_entry}")

  if [[ -z "${domain_entry}" ]]; then
    log_warn "域名为空，未写入。"
    return 1
  fi

  if ! [[ "${domain_entry}" =~ ^=?[A-Za-z0-9._-]+$ ]]; then
    log_warn "域名格式无效，未写入。"
    return 1
  fi

  if grep -Fxq "${domain_entry}" "${SB_WARP_DOMAINS_FILE}" 2>/dev/null; then
    log_warn "域名已存在于 Warp 分流列表。"
    return 1
  fi

  printf '%s\n' "${domain_entry}" >> "${SB_WARP_DOMAINS_FILE}"
  log_success "已写入 Warp 分流域名: ${domain_entry}"
  return 0
}

add_remote_warp_rule_set() {
  ensure_warp_routing_assets

  local tag url update_interval
  read -rp "请输入远程规则集标签: " tag
  tag=$(sanitize_ruleset_tag "$(trim_whitespace "${tag}")")

  if [[ -z "${tag}" ]]; then
    log_warn "标签为空，未写入。"
    return 1
  fi

  while true; do
    read -rp "请输入远程规则集 URL: " url
    url=$(trim_whitespace "${url}")
    validate_http_url "${url}" && break
    log_warn "远程规则集 URL 必须以 http:// 或 https:// 开头。"
  done

  while true; do
    read -rp "请输入更新周期 (默认 1d): " update_interval
    update_interval=$(trim_whitespace "${update_interval:-1d}")
    validate_update_interval "${update_interval}" && break
    log_warn "更新周期格式必须为正整数加单位 s/m/h/d，例如 1d。"
  done

  printf '%s|%s|%s\n' "${tag}" "${url}" "${update_interval:-1d}" >> "${SB_WARP_REMOTE_RULESETS_FILE}"
  log_success "已写入远程 Warp 规则集: ${tag}"
  return 0
}

import_recommended_warp_rule_sets() {
  ensure_warp_routing_assets

  local entry imported_count=0 skipped_count=0

  for entry in "${WARP_RECOMMENDED_RULESETS[@]}"; do
    if grep -Fxq "${entry}" "${SB_WARP_REMOTE_RULESETS_FILE}" 2>/dev/null; then
      skipped_count=$((skipped_count + 1))
      continue
    fi

    printf '%s\n' "${entry}" >> "${SB_WARP_REMOTE_RULESETS_FILE}"
    imported_count=$((imported_count + 1))
  done

  if [[ ${imported_count} -gt 0 ]]; then
    log_success "已导入 ${imported_count} 条推荐 Warp 规则源。"
  fi

  if [[ ${skipped_count} -gt 0 ]]; then
    log_info "已跳过 ${skipped_count} 条已存在的推荐 Warp 规则源。"
  fi

  [[ ${imported_count} -gt 0 ]]
}

check_root() {
  if [[ $EUID -ne 0 ]]; then
    log_error "本脚本必须以 root 用户执行。"
  fi
}

sanitize_sbv_detail() {
  local detail=${1:-}
  local sanitized

  if ! sanitized=$(printf '%s' "${detail}" | tr '\r\n' ' ' | sed -E \
    's#(https?://)[^/@[:space:]]+@#\1[REDACTED]@#g; s#((Proxy-Authorization|Authorization):[[:space:]]*).*$#\1[REDACTED]#I; s#([?&](token|password|secret|key)=)[^&[:space:]]+#\1[REDACTED]#gI'); then
    sanitized='unavailable'
  fi

  sanitized=${sanitized:0:400}
  if [[ -z "${sanitized}" ]]; then
    sanitized='no detail available'
  fi
  printf '%s' "${sanitized}"
}

read_sbv_detail_file() {
  local detail=''

  if [[ -f "${1:-}" ]]; then
    if ! detail=$(head -c "${SBV_CURL_STDERR_MAX_BYTES}" -- "${1}" 2>/dev/null | \
      tr '\r\n' ' '); then
      detail='unable to read diagnostic output'
    fi
  else
    detail='no diagnostic output captured'
  fi

  sanitize_sbv_detail "${detail}"
}

append_sbv_update_log() {
  local level=$1
  local message=$2

  if ! mkdir -p "${SB_PROJECT_DIR}" 2>/dev/null; then
    return 1
  fi
  printf '[%s] [%s] %s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "${level}" "${message}" \
    >> "${SBV_LOG_FILE}" 2>/dev/null
}

reset_sbv_update_context() {
  SBV_UPDATE_OPERATION=''
  SBV_UPDATE_STAGE='precheck'
  SBV_UPDATE_ERROR_CODE=''
  SBV_UPDATE_ERROR_MESSAGE=''
  SBV_UPDATE_ERROR_DETAIL=''
  SBV_UPDATE_COMMAND_EXIT_CODE='0'
  SBV_UPDATE_HINT=''
  SBV_UPDATE_CHANGED='false'
  SBV_UPDATE_ROLLBACK_ATTEMPTED='false'
  SBV_UPDATE_ROLLED_BACK='false'
  SBV_UPDATE_ROLLBACK_OK='false'
  SBV_UPDATE_MANUAL_INTERVENTION_REQUIRED='false'
  SBV_UPDATE_CURRENT_VERSION=''
  SBV_UPDATE_CANDIDATE_VERSION=''
  SBV_UPDATE_TARGET_PATH="${SBV_BIN_PATH}"
  SBV_UPDATE_LOG_FILE="${SBV_LOG_FILE}"
  SBV_UPDATE_TARGET_EXISTS='false'
  SBV_UPDATE_TARGET_WAS_EXECUTABLE='false'
  SBV_UPDATE_TARGET_MODE=''
  SBV_UPDATE_TARGET_UID=''
  SBV_UPDATE_TARGET_GID=''
  SBV_UPDATE_TARGET_HASH=''
  SBV_UPDATE_TARGET_VERSION=''
  SBV_UPDATE_EXPECTED_MODE=''
  SBV_UPDATE_EXPECTED_UID=''
  SBV_UPDATE_EXPECTED_GID=''
  SBV_UPDATE_CANDIDATE_PATH=''
  SBV_UPDATE_CANDIDATE_HASH=''
  SBV_UPDATE_CURL_STDERR_PATH=''
  SBV_UPDATE_BACKUP_PATH=''
  SBV_UPDATE_ROLLBACK_PATH=''
  SBV_UPDATE_LOCK_PATH=''
  SBV_UPDATE_LOCK_HELD='false'
  SBV_UPDATE_COMMITTED='false'
  SBV_UPDATE_NOOP='false'
  SBV_UPDATE_PRESERVE_ARTIFACTS='false'
  SBV_UPDATE_SIGNAL_NAME=''
  SBV_UPDATE_SIGNAL_CODE='0'
  SBV_UPDATE_TRAP_ACTIVE='false'
  SBV_UPDATE_TRAP_RUNNING='false'
  SBV_UPDATE_PREVIOUS_INT_TRAP=''
  SBV_UPDATE_PREVIOUS_TERM_TRAP=''
  SBV_UPDATE_PREVIOUS_HUP_TRAP=''
  SBV_UPDATE_PREVIOUS_ERR_TRAP=''
  SBV_VALIDATED_SCRIPT_VERSION=''
  SBV_SCRIPT_VALIDATION_CODE=''
  SBV_SCRIPT_VALIDATION_DETAIL=''
}

set_sbv_update_error() {
  local operation=${1:-${SBV_UPDATE_OPERATION:-sbv_update}}
  local stage=${2:-${SBV_UPDATE_STAGE:-unknown}}
  local code=${3:-update_failed}
  local message=${4:-操作失败}
  local detail=${5:-}
  local command_exit_code=${6:-0}
  local hint=${7:-}

  SBV_UPDATE_OPERATION=${operation}
  SBV_UPDATE_STAGE=${stage}
  SBV_UPDATE_ERROR_CODE=${code}
  SBV_UPDATE_ERROR_MESSAGE=${message}
  SBV_UPDATE_ERROR_DETAIL=$(sanitize_sbv_detail "${detail}")
  SBV_UPDATE_COMMAND_EXIT_CODE=${command_exit_code}
  SBV_UPDATE_HINT=${hint}
}

report_sbv_update_error() {
  local result='unchanged'
  local operation=${SBV_UPDATE_OPERATION:-sbv_update}
  local display_operation=${operation}
  local detail=${SBV_UPDATE_ERROR_DETAIL:-no detail available}

  case "${operation}" in
    sbv_update|ensure_sbv_local|ensure_sbv_remote) display_operation='sbv 自更新' ;;
    media_check_backend) display_operation='流媒体验证脚本下载' ;;
  esac

  if [[ "${SBV_UPDATE_MANUAL_INTERVENTION_REQUIRED}" == 'true' ]]; then
    result='rollback_failed'
  elif [[ "${SBV_UPDATE_ROLLED_BACK}" == 'true' && "${SBV_UPDATE_ROLLBACK_OK}" == 'true' ]]; then
    result='rolled_back'
  fi

  printf '[ERROR] %s 失败\n' "${display_operation}" >&2
  printf '操作: %s\n' "${operation}" >&2
  printf '操作阶段: %s\n' "${SBV_UPDATE_STAGE:-unknown}" >&2
  printf '错误代码: %s\n' "${SBV_UPDATE_ERROR_CODE:-update_failed}" >&2
  printf '错误消息: %s\n' "${SBV_UPDATE_ERROR_MESSAGE:-操作失败}" >&2
  printf '底层退出码: %s\n' "${SBV_UPDATE_COMMAND_EXIT_CODE:-0}" >&2
  printf '错误详情: %s\n' "${detail}" >&2
  printf '上下文:\n' >&2
  printf '  operation: %s\n' "${operation}" >&2
  printf '  stage: %s\n' "${SBV_UPDATE_STAGE:-unknown}" >&2
  printf '  code: %s\n' "${SBV_UPDATE_ERROR_CODE:-update_failed}" >&2
  printf '  message: %s\n' "${SBV_UPDATE_ERROR_MESSAGE:-操作失败}" >&2
  printf '  detail: %s\n' "${detail}" >&2
  printf '  command_exit_code: %s\n' "${SBV_UPDATE_COMMAND_EXIT_CODE:-0}" >&2
  printf '  hint: %s\n' "${SBV_UPDATE_HINT:-}" >&2
  printf '状态:\n' >&2
  printf '  changed: %s\n' "${SBV_UPDATE_CHANGED}" >&2
  printf '  rollback_attempted: %s\n' "${SBV_UPDATE_ROLLBACK_ATTEMPTED}" >&2
  printf '  rolled_back: %s\n' "${SBV_UPDATE_ROLLED_BACK}" >&2
  printf '  rollback_ok: %s\n' "${SBV_UPDATE_ROLLBACK_OK}" >&2
  printf '  manual_intervention_required: %s\n' \
    "${SBV_UPDATE_MANUAL_INTERVENTION_REQUIRED}" >&2
  printf '  处理结果: %s\n' "${result}" >&2
  printf '版本:\n' >&2
  printf '  current_version: %s\n' "${SBV_UPDATE_CURRENT_VERSION:-unknown}" >&2
  printf '  candidate_version: %s\n' "${SBV_UPDATE_CANDIDATE_VERSION:-unknown}" >&2
  printf '路径:\n' >&2
  printf '  target_path: %s\n' "${SBV_UPDATE_TARGET_PATH}" >&2
  printf '  target_sha256: %s\n' "${SBV_UPDATE_TARGET_HASH:-unknown}" >&2
  printf '  target_mode: %s\n' "${SBV_UPDATE_TARGET_MODE:-unknown}" >&2
  if [[ -n "${SBV_UPDATE_TARGET_UID}" && -n "${SBV_UPDATE_TARGET_GID}" ]]; then
    printf '  target_owner: %s:%s\n' "${SBV_UPDATE_TARGET_UID}" "${SBV_UPDATE_TARGET_GID}" >&2
  else
    printf '  target_owner: unknown\n' >&2
  fi
  if [[ -n "${SBV_UPDATE_BACKUP_PATH}" ]]; then
    printf '  backup_path: %s\n' "${SBV_UPDATE_BACKUP_PATH}" >&2
  fi
  if [[ -n "${SBV_UPDATE_CANDIDATE_PATH}" ]]; then
    printf '  candidate_path: %s\n' "${SBV_UPDATE_CANDIDATE_PATH}" >&2
  fi
  printf '  candidate_sha256: %s\n' "${SBV_UPDATE_CANDIDATE_HASH:-unknown}" >&2
  if [[ -n "${SBV_UPDATE_HINT}" ]]; then
    printf '建议: %s\n' "${SBV_UPDATE_HINT}" >&2
  fi
  printf '日志: %s\n' "${SBV_UPDATE_LOG_FILE}" >&2
  printf '  log_file: %s\n' "${SBV_UPDATE_LOG_FILE}" >&2

  append_sbv_update_log 'ERROR' \
    "${operation} ${SBV_UPDATE_ERROR_CODE:-update_failed}: ${SBV_UPDATE_ERROR_MESSAGE}; result=${result}; changed=${SBV_UPDATE_CHANGED}; rollback_attempted=${SBV_UPDATE_ROLLBACK_ATTEMPTED}; rolled_back=${SBV_UPDATE_ROLLED_BACK}; rollback_ok=${SBV_UPDATE_ROLLBACK_OK}; manual_intervention_required=${SBV_UPDATE_MANUAL_INTERVENTION_REQUIRED}; detail=${detail}" \
    || true
}

extract_sbv_script_version() {
  local script_file=$1
  local match_count
  local script_version

  [[ -f "${script_file}" ]] || return 1
  match_count=$(grep -Ec '^[[:space:]]*readonly[[:space:]]+SCRIPT_VERSION="[0-9]{10}"[[:space:]]*$' \
    "${script_file}" 2>/dev/null || true)
  [[ "${match_count}" == '1' ]] || return 1
  script_version=$(sed -nE \
    's/^[[:space:]]*readonly[[:space:]]+SCRIPT_VERSION="([0-9]{10})"[[:space:]]*$/\1/p' \
    "${script_file}")
  [[ "${script_version}" =~ ^[0-9]{10}$ ]] || return 1
  printf '%s' "${script_version}"
}

set_sbv_script_validation_failure() {
  SBV_SCRIPT_VALIDATION_CODE=$1
  SBV_SCRIPT_VALIDATION_DETAIL=$2
  return 1
}

validate_sbv_script_file() {
  local script_file=$1
  local file_size
  local first_line=''
  local syntax_detail=''
  local script_version=''

  SBV_SCRIPT_VALIDATION_CODE=''
  SBV_SCRIPT_VALIDATION_DETAIL=''
  SBV_VALIDATED_SCRIPT_VERSION=''

  if [[ ! -f "${script_file}" ]]; then
    set_sbv_script_validation_failure 'candidate_missing' '候选文件不存在或不是普通文件'
    return 1
  fi
  if [[ -L "${script_file}" ]]; then
    set_sbv_script_validation_failure 'candidate_symlink' '候选文件是符号链接，已拒绝'
    return 1
  fi
  if ! file_size=$(wc -c < "${script_file}"); then
    set_sbv_script_validation_failure 'candidate_unreadable' '无法读取候选文件大小'
    return 1
  fi
  if (( file_size < SBV_SCRIPT_MIN_SIZE )); then
    set_sbv_script_validation_failure 'candidate_too_small' \
      "候选文件大小 ${file_size} 字节，小于最小要求 ${SBV_SCRIPT_MIN_SIZE} 字节"
    return 1
  fi
  IFS= read -r first_line < "${script_file}" || true
  if [[ "${first_line}" != '#!/usr/bin/env bash' ]]; then
    set_sbv_script_validation_failure 'candidate_shebang_invalid' \
      '候选文件缺少预期的 #!/usr/bin/env bash shebang'
    return 1
  fi
  if LC_ALL=C grep -Eiq '^[[:space:]]*(<!doctype[[:space:]]+html|<html|<body)' \
    "${script_file}"; then
    set_sbv_script_validation_failure 'candidate_html' '候选内容看起来是 HTML 或网关错误页'
    return 1
  fi
  if ! syntax_detail=$(bash -n -- "${script_file}" 2>&1); then
    set_sbv_script_validation_failure 'candidate_syntax_invalid' \
      "Bash 语法校验失败: ${syntax_detail}"
    return 1
  fi
  if ! script_version=$(extract_sbv_script_version "${script_file}"); then
    set_sbv_script_validation_failure 'candidate_version_invalid' \
      '必须存在且只能存在一个 YYYYMMDDXX 格式的 SCRIPT_VERSION'
    return 1
  fi
  if ! grep -Fqx 'readonly PROJECT_AUTHOR="KnowSky404"' "${script_file}"; then
    set_sbv_script_validation_failure 'candidate_identity_mismatch' \
      'PROJECT_AUTHOR 与 sing-box-vps 身份不匹配'
    return 1
  fi
  if ! grep -Fqx 'readonly PROJECT_URL="https://github.com/KnowSky404/sing-box-vps"' \
    "${script_file}"; then
    set_sbv_script_validation_failure 'candidate_identity_mismatch' \
      'PROJECT_URL 与 sing-box-vps 身份不匹配'
    return 1
  fi

  SBV_VALIDATED_SCRIPT_VERSION=${script_version}
  return 0
}

calculate_sbv_sha256() {
  command -v sha256sum >/dev/null 2>&1 || return 127
  sha256sum -- "$1" | awk '{print $1}'
}

get_sbv_file_metadata() {
  local metadata

  if ! metadata=$(stat -c '%a:%u:%g' -- "$1"); then
    return 1
  fi
  IFS=: read -r SBV_UPDATE_TARGET_MODE SBV_UPDATE_TARGET_UID SBV_UPDATE_TARGET_GID <<< \
    "${metadata}"
  [[ -n "${SBV_UPDATE_TARGET_MODE}" && -n "${SBV_UPDATE_TARGET_UID}" && \
    -n "${SBV_UPDATE_TARGET_GID}" ]]
}

sbv_update_signal_handler() {
  local signal_name=$1

  if [[ "${SBV_UPDATE_TRAP_RUNNING}" == 'true' ]]; then
    return 0
  fi
  SBV_UPDATE_TRAP_RUNNING='true'
  SBV_UPDATE_SIGNAL_NAME=${signal_name}
  case "${signal_name}" in
    INT) SBV_UPDATE_SIGNAL_CODE='130' ;;
    TERM) SBV_UPDATE_SIGNAL_CODE='143' ;;
    HUP) SBV_UPDATE_SIGNAL_CODE='129' ;;
    *) SBV_UPDATE_SIGNAL_CODE='1' ;;
  esac
  SBV_UPDATE_TRAP_RUNNING='false'
}

sbv_update_unexpected_error_handler() {
  local command_exit_code=${1:-1}

  if [[ "${SBV_UPDATE_TRAP_RUNNING}" == 'true' || \
    "${SBV_UPDATE_TRAP_ACTIVE}" != 'true' ]]; then
    return 0
  fi
  SBV_UPDATE_TRAP_RUNNING='true'
  if [[ -z "${SBV_UPDATE_ERROR_CODE}" ]]; then
    set_sbv_update_error \
      "${SBV_UPDATE_OPERATION:-sbv_update}" \
      "${SBV_UPDATE_STAGE:-unknown}" \
      'unexpected_error' \
      '更新过程中发生未预期异常' \
      '某个底层命令失败，详细命令内容未记录以避免泄露敏感信息' \
      "${command_exit_code}" \
      '检查日志中的阶段信息，并确认目标脚本及保留的恢复文件状态'
  fi
  SBV_UPDATE_TRAP_RUNNING='false'
}

install_sbv_update_traps() {
  SBV_UPDATE_PREVIOUS_INT_TRAP=$(trap -p INT || true)
  SBV_UPDATE_PREVIOUS_TERM_TRAP=$(trap -p TERM || true)
  SBV_UPDATE_PREVIOUS_HUP_TRAP=$(trap -p HUP || true)
  SBV_UPDATE_PREVIOUS_ERR_TRAP=$(trap -p ERR || true)
  trap 'sbv_update_signal_handler INT' INT
  trap 'sbv_update_signal_handler TERM' TERM
  trap 'sbv_update_signal_handler HUP' HUP
  trap 'sbv_update_unexpected_error_handler "$?"' ERR
  SBV_UPDATE_TRAP_ACTIVE='true'
}

restore_sbv_update_traps() {
  [[ "${SBV_UPDATE_TRAP_ACTIVE}" == 'true' ]] || return 0

  trap - INT TERM HUP ERR
  if [[ -n "${SBV_UPDATE_PREVIOUS_INT_TRAP}" ]]; then
    eval "${SBV_UPDATE_PREVIOUS_INT_TRAP}" || true
  fi
  if [[ -n "${SBV_UPDATE_PREVIOUS_TERM_TRAP}" ]]; then
    eval "${SBV_UPDATE_PREVIOUS_TERM_TRAP}" || true
  fi
  if [[ -n "${SBV_UPDATE_PREVIOUS_HUP_TRAP}" ]]; then
    eval "${SBV_UPDATE_PREVIOUS_HUP_TRAP}" || true
  fi
  if [[ -n "${SBV_UPDATE_PREVIOUS_ERR_TRAP}" ]]; then
    eval "${SBV_UPDATE_PREVIOUS_ERR_TRAP}" || true
  fi
  SBV_UPDATE_TRAP_ACTIVE='false'
}

prepare_sbv_update() {
  local target_dir
  local target_version=''
  local lock_status=0

  SBV_UPDATE_STAGE='precheck'
  target_dir=$(dirname -- "${SBV_BIN_PATH}")
  SBV_UPDATE_LOCK_PATH="${target_dir}/.sbv-update.lock"

  if [[ ! -d "${target_dir}" ]]; then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'precheck' 'target_directory_missing' \
      'sbv 目标目录不存在' "目标目录: ${target_dir}" 1 \
      '确认 /usr/local/bin 存在且当前用户具有 root 权限'
    return 1
  fi
  if [[ -L "${SBV_BIN_PATH}" ]]; then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'precheck' 'target_symlink_unsupported' \
      'sbv 目标是符号链接，已安全拒绝更新' "目标路径: ${SBV_BIN_PATH}" 1 \
      '请先将符号链接解析为受管普通文件后再更新'
    return 1
  fi
  if [[ -e "${SBV_BIN_PATH}" && ! -f "${SBV_BIN_PATH}" ]]; then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'precheck' 'target_not_regular' \
      'sbv 目标不是普通文件，已安全拒绝更新' "目标路径: ${SBV_BIN_PATH}" 1 \
      '移除目录或特殊文件后再重试；目标未发生变更'
    return 1
  fi
  if ! command -v curl >/dev/null 2>&1; then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'precheck' 'curl_unavailable' \
      '找不到 curl，无法下载候选脚本' 'curl command not found' 127 \
      '安装 curl 后重试'
    return 1
  fi
  if ! command -v sha256sum >/dev/null 2>&1; then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'precheck' 'sha256sum_unavailable' \
      '找不到 sha256sum，无法核对候选完整性' 'sha256sum command not found' 127 \
      '安装提供 sha256sum 的系统工具后重试'
    return 1
  fi
  if mkdir "${SBV_UPDATE_LOCK_PATH}" 2>/dev/null; then
    :
  else
    lock_status=$?
    if [[ -e "${SBV_UPDATE_LOCK_PATH}" || -L "${SBV_UPDATE_LOCK_PATH}" ]]; then
      set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'precheck' 'update_in_progress' \
        '已有另一个 sbv 更新事务正在运行' "锁路径: ${SBV_UPDATE_LOCK_PATH}" 1 \
        '等待现有更新结束后再重试；未取得锁时目标未发生变更'
      lock_status=1
    else
      set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'precheck' 'lock_create_failed' \
        '无法创建 sbv 更新锁' "锁路径: ${SBV_UPDATE_LOCK_PATH}" "${lock_status}" \
        '检查目标目录的写权限、磁盘空间和文件系统状态；目标未发生变更'
    fi
    return "${lock_status}"
  fi
  SBV_UPDATE_LOCK_HELD='true'

  if [[ -f "${SBV_BIN_PATH}" ]]; then
    SBV_UPDATE_TARGET_EXISTS='true'
    if [[ -x "${SBV_BIN_PATH}" ]]; then
      SBV_UPDATE_TARGET_WAS_EXECUTABLE='true'
    fi
    if ! get_sbv_file_metadata "${SBV_BIN_PATH}"; then
      set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'precheck' 'target_metadata_failed' \
        '无法读取现有 sbv 的权限或所有者' "目标路径: ${SBV_BIN_PATH}" 1 \
        '检查目标文件及 /usr/local/bin 的权限'
      return 1
    fi
    if ! SBV_UPDATE_TARGET_HASH=$(calculate_sbv_sha256 "${SBV_BIN_PATH}"); then
      set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'precheck' 'target_hash_failed' \
        '无法计算现有 sbv 的 SHA-256' "目标路径: ${SBV_BIN_PATH}" 1 \
        '检查目标文件是否可读'
      return 1
    fi
    if target_version=$(extract_sbv_script_version "${SBV_BIN_PATH}"); then
      SBV_UPDATE_TARGET_VERSION=${target_version}
      SBV_UPDATE_CURRENT_VERSION=${target_version}
    else
      SBV_UPDATE_CURRENT_VERSION=${SCRIPT_VERSION}
    fi
  else
    SBV_UPDATE_CURRENT_VERSION=${SCRIPT_VERSION}
  fi
  return 0
}

create_sbv_candidate() {
  local target_dir

  target_dir=$(dirname -- "${SBV_BIN_PATH}")
  if ! SBV_UPDATE_CANDIDATE_PATH=$(mktemp "${target_dir}/.sbv-candidate.XXXXXXXXXX"); then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'stage' 'candidate_create_failed' \
      '无法创建同目录候选文件' "候选目录: ${target_dir}" 1 \
      '检查目标目录的磁盘空间和权限'
    return 1
  fi
  if ! SBV_UPDATE_CURL_STDERR_PATH=$(mktemp "${target_dir}/.sbv-curl-stderr.XXXXXXXXXX"); then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'stage' 'diagnostic_file_create_failed' \
      '无法创建下载诊断文件' "诊断目录: ${target_dir}" 1 \
      '检查目标目录的磁盘空间和权限'
    return 1
  fi
  return 0
}

classify_sbv_download_error() {
  case "${1:-}" in
    6) printf 'download_dns_failure' ;;
    7) printf 'download_connection_failed' ;;
    18) printf 'download_partial_transfer' ;;
    28) printf 'download_timeout' ;;
    130|143|129) printf 'signal_interrupted' ;;
    *) printf 'download_failed' ;;
  esac
}

stage_sbv_candidate_from_url() {
  local url=$1
  local curl_status=0
  local detail=''

  if ! create_sbv_candidate; then
    return 1
  fi
  if curl -fsSL \
    --connect-timeout "${SBV_CURL_CONNECT_TIMEOUT}" \
    --max-time "${SBV_CURL_MAX_TIME}" \
    --retry "${SBV_CURL_RETRY_COUNT}" \
    --retry-delay "${SBV_CURL_RETRY_DELAY}" \
    -o "${SBV_UPDATE_CANDIDATE_PATH}" "${url}" \
    2>"${SBV_UPDATE_CURL_STDERR_PATH}"; then
    curl_status=0
  else
    curl_status=$?
  fi
  SBV_UPDATE_COMMAND_EXIT_CODE=${curl_status}
  if [[ "${SBV_UPDATE_SIGNAL_CODE}" != '0' ]]; then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'download' 'signal_interrupted' \
      "下载过程中收到 ${SBV_UPDATE_SIGNAL_NAME}，更新已中断" \
      "信号: ${SBV_UPDATE_SIGNAL_NAME}" "${SBV_UPDATE_SIGNAL_CODE}" \
      '重新运行更新；提交前目标脚本保持不变'
    return "${SBV_UPDATE_SIGNAL_CODE}"
  fi
  if [[ "${curl_status}" != '0' ]]; then
    detail=$(read_sbv_detail_file "${SBV_UPDATE_CURL_STDERR_PATH}")
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'download' "$(classify_sbv_download_error "${curl_status}")" \
      '下载最新 sbv 脚本失败' "${detail}" "${curl_status}" \
      '检查 DNS、IPv4/IPv6 出口、路由或 HTTPS_PROXY；原脚本未发生变更'
    return "${curl_status}"
  fi
  return 0
}

stage_sbv_candidate_from_file() {
  local source_file=$1

  if ! create_sbv_candidate; then
    return 1
  fi
  if [[ ! -f "${source_file}" || -L "${source_file}" ]]; then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'stage' 'source_not_regular' \
      '当前脚本来源不是可读取的普通文件' "来源路径: ${source_file}" 1 \
      '请从真实文件路径运行 install.sh'
    return 1
  fi
  if ! cp -p -- "${source_file}" "${SBV_UPDATE_CANDIDATE_PATH}" 2>"${SBV_UPDATE_CURL_STDERR_PATH}"; then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'stage' 'candidate_copy_failed' \
      '无法将当前脚本复制到候选文件' \
      "$(read_sbv_detail_file "${SBV_UPDATE_CURL_STDERR_PATH}")" 1 \
      '检查目标目录的磁盘空间和权限'
    return 1
  fi
  return 0
}

sbv_target_is_healthy() {
  [[ "${SBV_UPDATE_TARGET_EXISTS}" == 'true' ]] || return 1
  [[ -f "${SBV_BIN_PATH}" && -x "${SBV_BIN_PATH}" ]] || return 1
  validate_sbv_script_file "${SBV_BIN_PATH}"
}

validate_sbv_candidate() {
  local candidate_version
  local validation_code
  local validation_detail

  SBV_UPDATE_STAGE='validate'
  if ! validate_sbv_script_file "${SBV_UPDATE_CANDIDATE_PATH}"; then
    validation_code=${SBV_SCRIPT_VALIDATION_CODE:-candidate_invalid}
    validation_detail=${SBV_SCRIPT_VALIDATION_DETAIL:-候选文件校验失败}
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'validate' "${validation_code}" \
      '候选 sbv 脚本校验失败' "${validation_detail}" 1 \
      '拒绝提交候选文件；原脚本未发生变更'
    return 1
  fi
  candidate_version=${SBV_VALIDATED_SCRIPT_VERSION}
  SBV_UPDATE_CANDIDATE_VERSION=${candidate_version}
  if ! SBV_UPDATE_CANDIDATE_HASH=$(calculate_sbv_sha256 "${SBV_UPDATE_CANDIDATE_PATH}"); then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'validate' 'candidate_hash_failed' \
      '无法计算候选 sbv 的 SHA-256' \
      "候选路径: ${SBV_UPDATE_CANDIDATE_PATH}" 1 \
      '拒绝提交候选文件；原脚本未发生变更'
    return 1
  fi

  if [[ "${SBV_UPDATE_CURRENT_VERSION}" =~ ^[0-9]{10}$ ]] && \
    (( 10#${candidate_version} < 10#${SBV_UPDATE_CURRENT_VERSION} )); then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'validate' 'candidate_version_downgrade' \
      '候选 sbv 版本低于当前版本，已拒绝降级' \
      "当前版本: ${SBV_UPDATE_CURRENT_VERSION}; 候选版本: ${candidate_version}" 1 \
      '确认远端分支和当前版本来源后再重试'
    return 1
  fi

  if [[ "${candidate_version}" == "${SBV_UPDATE_CURRENT_VERSION}" ]] && \
    sbv_target_is_healthy; then
    SBV_UPDATE_NOOP='true'
  fi
  return 0
}

create_sbv_backup() {
  local target_dir

  SBV_UPDATE_STAGE='backup'
  if [[ "${SBV_UPDATE_TARGET_EXISTS}" != 'true' ]]; then
    return 0
  fi
  target_dir=$(dirname -- "${SBV_BIN_PATH}")
  if ! SBV_UPDATE_BACKUP_PATH=$(mktemp "${target_dir}/.sbv-backup.XXXXXXXXXX"); then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'backup' 'backup_create_failed' \
      '无法创建受保护的 sbv 备份' "备份目录: ${target_dir}" 1 \
      '检查目标目录的磁盘空间和权限；原脚本未发生变更'
    return 1
  fi
  if ! cp -p -- "${SBV_BIN_PATH}" "${SBV_UPDATE_BACKUP_PATH}"; then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'backup' 'backup_copy_failed' \
      '无法创建现有 sbv 的备份' "目标路径: ${SBV_BIN_PATH}" 1 \
      '检查目标文件是否可读；原脚本未发生变更'
    return 1
  fi
  if ! chmod 0600 "${SBV_UPDATE_BACKUP_PATH}"; then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'backup' 'backup_protect_failed' \
      '无法设置 sbv 备份的 root-only 权限' \
      "备份路径: ${SBV_UPDATE_BACKUP_PATH}" 1 \
      '检查文件系统权限；原脚本未发生变更'
    return 1
  fi
  if ! chown 0:0 "${SBV_UPDATE_BACKUP_PATH}"; then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'backup' 'backup_protect_failed' \
      '无法将 sbv 备份设置为 root 所有' \
      "备份路径: ${SBV_UPDATE_BACKUP_PATH}" 1 \
      '检查文件系统权限；原脚本未发生变更'
    return 1
  fi
  return 0
}

prepare_sbv_candidate_for_commit() {
  local candidate_mode='755'

  if [[ "${SBV_UPDATE_TARGET_EXISTS}" == 'true' && \
    "${SBV_UPDATE_TARGET_WAS_EXECUTABLE}" == 'true' ]]; then
    candidate_mode=${SBV_UPDATE_TARGET_MODE}
  fi
  SBV_UPDATE_EXPECTED_MODE=${candidate_mode}
  if [[ "${SBV_UPDATE_TARGET_EXISTS}" == 'true' ]]; then
    SBV_UPDATE_EXPECTED_UID=${SBV_UPDATE_TARGET_UID}
    SBV_UPDATE_EXPECTED_GID=${SBV_UPDATE_TARGET_GID}
  fi
  if ! chmod "${candidate_mode}" "${SBV_UPDATE_CANDIDATE_PATH}"; then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'commit' 'candidate_chmod_failed' \
      '无法设置候选 sbv 的执行权限' \
      "候选路径: ${SBV_UPDATE_CANDIDATE_PATH}" 1 \
      '检查目标目录的权限；原脚本未发生变更'
    return 1
  fi
  if [[ "${SBV_UPDATE_TARGET_EXISTS}" == 'true' ]] && \
    ! chown "${SBV_UPDATE_TARGET_UID}:${SBV_UPDATE_TARGET_GID}" \
      "${SBV_UPDATE_CANDIDATE_PATH}"; then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'commit' 'candidate_chown_failed' \
      '无法保留 sbv 原有所有者' \
      "候选路径: ${SBV_UPDATE_CANDIDATE_PATH}" 1 \
      '检查 chown 权限；原脚本未发生变更'
    return 1
  fi
  return 0
}

commit_sbv_candidate() {
  SBV_UPDATE_STAGE='commit'
  if ! prepare_sbv_candidate_for_commit; then
    return 1
  fi
  if ! mv -f -- "${SBV_UPDATE_CANDIDATE_PATH}" "${SBV_BIN_PATH}"; then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'commit' 'atomic_replace_failed' \
      '无法原子替换 sbv 目标文件' \
      "候选路径: ${SBV_UPDATE_CANDIDATE_PATH}" 1 \
      '检查目标目录权限和文件系统状态；原脚本未发生变更'
    return 1
  fi
  SBV_UPDATE_COMMITTED='true'
  SBV_UPDATE_CHANGED='true'
  return 0
}

postcheck_sbv_update() {
  local actual_hash
  local actual_mode
  local actual_uid
  local actual_gid

  SBV_UPDATE_STAGE='postcheck'
  if [[ ! -f "${SBV_BIN_PATH}" || -L "${SBV_BIN_PATH}" ]]; then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'postcheck' 'target_missing_after_commit' \
      '提交后未找到有效的 sbv 目标文件' "目标路径: ${SBV_BIN_PATH}" 1 \
      '事务将尝试恢复更新前的脚本'
    return 1
  fi
  if ! validate_sbv_script_file "${SBV_BIN_PATH}"; then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'postcheck' 'postcheck_validation_failed' \
      '提交后的 sbv 脚本校验失败' \
      "${SBV_SCRIPT_VALIDATION_DETAIL:-目标校验失败}" 1 \
      '事务将尝试恢复更新前的脚本'
    return 1
  fi
  if [[ "${SBV_VALIDATED_SCRIPT_VERSION}" != "${SBV_UPDATE_CANDIDATE_VERSION}" ]]; then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'postcheck' 'postcheck_version_mismatch' \
      '提交后的 sbv 版本与候选版本不一致' \
      "目标版本: ${SBV_VALIDATED_SCRIPT_VERSION}; 候选版本: ${SBV_UPDATE_CANDIDATE_VERSION}" 1 \
      '事务将尝试恢复更新前的脚本'
    return 1
  fi
  if ! actual_hash=$(calculate_sbv_sha256 "${SBV_BIN_PATH}"); then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'postcheck' 'postcheck_hash_failed' \
      '无法计算提交后 sbv 的 SHA-256' "目标路径: ${SBV_BIN_PATH}" 1 \
      '事务将尝试恢复更新前的脚本'
    return 1
  fi
  if [[ "${actual_hash}" != "${SBV_UPDATE_CANDIDATE_HASH}" ]]; then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'postcheck' 'postcheck_hash_mismatch' \
      '提交后的 sbv SHA-256 与候选不一致' \
      "候选哈希: ${SBV_UPDATE_CANDIDATE_HASH}; 目标哈希: ${actual_hash}" 1 \
      '事务将尝试恢复更新前的脚本'
    return 1
  fi
  if [[ ! -x "${SBV_BIN_PATH}" ]]; then
    set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'postcheck' 'postcheck_not_executable' \
      '提交后的 sbv 不可执行' "目标路径: ${SBV_BIN_PATH}" 1 \
      '事务将尝试恢复更新前的脚本'
    return 1
  fi
  if [[ "${SBV_UPDATE_TARGET_EXISTS}" == 'true' ]]; then
    if ! actual_mode=$(stat -c '%a' -- "${SBV_BIN_PATH}") || \
      ! actual_uid=$(stat -c '%u' -- "${SBV_BIN_PATH}") || \
      ! actual_gid=$(stat -c '%g' -- "${SBV_BIN_PATH}"); then
      set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'postcheck' 'postcheck_metadata_failed' \
        '无法读取提交后 sbv 的权限或所有者' "目标路径: ${SBV_BIN_PATH}" 1 \
        '事务将尝试恢复更新前的脚本'
      return 1
    fi
    if [[ "${actual_mode}" != "${SBV_UPDATE_EXPECTED_MODE}" || \
      "${actual_uid}" != "${SBV_UPDATE_EXPECTED_UID}" || \
      "${actual_gid}" != "${SBV_UPDATE_EXPECTED_GID}" ]]; then
      set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" 'postcheck' 'postcheck_metadata_mismatch' \
        '提交后的 sbv 权限或所有者与预期不一致' \
        "实际: ${actual_mode}:${actual_uid}:${actual_gid}; 预期: ${SBV_UPDATE_EXPECTED_MODE}:${SBV_UPDATE_EXPECTED_UID}:${SBV_UPDATE_EXPECTED_GID}" 1 \
        '事务将尝试恢复更新前的脚本'
      return 1
    fi
  fi
  return 0
}

restore_sbv_backup() {
  local target_dir
  local restore_path

  target_dir=$(dirname -- "${SBV_BIN_PATH}")
  if [[ "${SBV_UPDATE_TARGET_EXISTS}" != 'true' ]]; then
    if ! rm -f -- "${SBV_BIN_PATH}"; then
      return 1
    fi
    return 0
  fi
  [[ -f "${SBV_UPDATE_BACKUP_PATH}" ]] || return 1
  if ! restore_path=$(mktemp "${target_dir}/.sbv-rollback.XXXXXXXXXX"); then
    return 1
  fi
  SBV_UPDATE_ROLLBACK_PATH=${restore_path}
  if ! cp -p -- "${SBV_UPDATE_BACKUP_PATH}" "${restore_path}"; then
    rm -f -- "${restore_path}" || true
    return 1
  fi
  if ! chmod "${SBV_UPDATE_TARGET_MODE}" "${restore_path}"; then
    rm -f -- "${restore_path}" || true
    return 1
  fi
  if ! chown "${SBV_UPDATE_TARGET_UID}:${SBV_UPDATE_TARGET_GID}" "${restore_path}"; then
    rm -f -- "${restore_path}" || true
    return 1
  fi
  if ! mv -f -- "${restore_path}" "${SBV_BIN_PATH}"; then
    rm -f -- "${restore_path}" || true
    return 1
  fi
  SBV_UPDATE_ROLLBACK_PATH=''
  return 0
}

verify_sbv_rollback() {
  local restored_hash

  if [[ "${SBV_UPDATE_TARGET_EXISTS}" != 'true' ]]; then
    [[ ! -e "${SBV_BIN_PATH}" && ! -L "${SBV_BIN_PATH}" ]] || return 1
    return 0
  fi
  [[ -f "${SBV_BIN_PATH}" && ! -L "${SBV_BIN_PATH}" ]] || return 1
  validate_sbv_script_file "${SBV_BIN_PATH}" || return 1
  if [[ "${SBV_UPDATE_TARGET_WAS_EXECUTABLE}" == 'true' && \
    ! -x "${SBV_BIN_PATH}" ]]; then
    return 1
  fi
  [[ "${SBV_VALIDATED_SCRIPT_VERSION}" == "${SBV_UPDATE_TARGET_VERSION}" ]] || return 1
  restored_hash=$(calculate_sbv_sha256 "${SBV_BIN_PATH}") || return 1
  [[ "${restored_hash}" == "${SBV_UPDATE_TARGET_HASH}" ]] || return 1
  [[ "$(stat -c '%a' -- "${SBV_BIN_PATH}")" == "${SBV_UPDATE_TARGET_MODE}" ]] || return 1
  [[ "$(stat -c '%u' -- "${SBV_BIN_PATH}")" == "${SBV_UPDATE_TARGET_UID}" ]] || return 1
  [[ "$(stat -c '%g' -- "${SBV_BIN_PATH}")" == "${SBV_UPDATE_TARGET_GID}" ]] || return 1
  return 0
}

preserve_sbv_recovery_artifacts() {
  local target_dir
  local retained_candidate=''

  SBV_UPDATE_PRESERVE_ARTIFACTS='true'
  target_dir=$(dirname -- "${SBV_BIN_PATH}")
  if [[ -f "${SBV_BIN_PATH}" ]]; then
    if retained_candidate=$(mktemp "${target_dir}/.sbv-candidate-retained.XXXXXXXXXX"); then
      if cp -p -- "${SBV_BIN_PATH}" "${retained_candidate}" && \
        chmod 0600 "${retained_candidate}" && chown 0:0 "${retained_candidate}"; then
        SBV_UPDATE_CANDIDATE_PATH=${retained_candidate}
      else
        rm -f -- "${retained_candidate}" || true
      fi
    fi
  fi
}

cleanup_sbv_update() {
  if [[ "${SBV_UPDATE_PRESERVE_ARTIFACTS}" != 'true' ]]; then
    rm -f -- \
      "${SBV_UPDATE_CANDIDATE_PATH}" \
      "${SBV_UPDATE_CURL_STDERR_PATH}" \
      "${SBV_UPDATE_ROLLBACK_PATH}" \
      "${SBV_UPDATE_BACKUP_PATH}" 2>/dev/null || true
  fi
  if [[ "${SBV_UPDATE_LOCK_HELD}" == 'true' ]]; then
    rmdir "${SBV_UPDATE_LOCK_PATH}" 2>/dev/null || true
    SBV_UPDATE_LOCK_HELD='false'
  fi
}

finish_sbv_update_failure() {
  local result_status=${1:-1}
  local original_status=${result_status}
  local original_error_code=''

  if [[ -z "${SBV_UPDATE_ERROR_CODE}" ]]; then
    if [[ -n "${SBV_UPDATE_SIGNAL_NAME}" ]]; then
      set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" "${SBV_UPDATE_STAGE:-unknown}" \
        'signal_interrupted' "更新过程中收到 ${SBV_UPDATE_SIGNAL_NAME}" \
        "信号: ${SBV_UPDATE_SIGNAL_NAME}" "${SBV_UPDATE_SIGNAL_CODE}" \
        '重新运行更新；提交前目标脚本保持不变'
    else
      set_sbv_update_error "${SBV_UPDATE_OPERATION:-sbv_update}" "${SBV_UPDATE_STAGE:-unknown}" \
        'update_failed' 'sbv 更新事务失败' '未提供额外诊断信息' "${result_status}" \
        '原脚本未发生变更，检查日志后重试'
    fi
  fi

  if [[ "${SBV_UPDATE_COMMITTED}" == 'true' ]]; then
    SBV_UPDATE_ROLLBACK_ATTEMPTED='true'
    if restore_sbv_backup && verify_sbv_rollback; then
      SBV_UPDATE_ROLLED_BACK='true'
      SBV_UPDATE_ROLLBACK_OK='true'
    else
      original_error_code=${SBV_UPDATE_ERROR_CODE:-update_failed}
      SBV_UPDATE_ERROR_CODE='rollback_failed'
      SBV_UPDATE_ERROR_MESSAGE='提交后失败且自动恢复未通过最终校验'
      SBV_UPDATE_ERROR_DETAIL=$(sanitize_sbv_detail \
        "${SBV_UPDATE_ERROR_DETAIL}; 原始错误码: ${original_error_code}")
      SBV_UPDATE_MANUAL_INTERVENTION_REQUIRED='true'
      result_status=1
      preserve_sbv_recovery_artifacts
      SBV_UPDATE_HINT='请使用保留的 backup_path 和 candidate_path 人工恢复，并重新校验 bash -n、版本、SHA-256 与执行权限'
    fi
  fi

  cleanup_sbv_update
  restore_sbv_update_traps
  report_sbv_update_error
  if [[ "${SBV_UPDATE_MANUAL_INTERVENTION_REQUIRED}" != 'true' ]]; then
    result_status=${original_status}
  fi
  return "${result_status}"
}

finish_sbv_update_success() {
  cleanup_sbv_update
  restore_sbv_update_traps
  if [[ "${SBV_UPDATE_NOOP}" == 'true' ]]; then
    printf '[INFO] sbv 已是当前版本 %s，事务 no-op，目标文件未替换（changed: false）。\n' \
      "${SBV_UPDATE_CURRENT_VERSION}"
  else
    printf '[SUCCESS] sbv 已完成原子更新到版本 %s（changed: true）。候选 SHA-256 已在本地提交后核对。\n' \
      "${SBV_UPDATE_CANDIDATE_VERSION}"
  fi
  return 0
}

sbv_update_transaction() {
  local operation=$1
  local source_kind=$2
  local source=$3
  local result_status=1

  reset_sbv_update_context
  SBV_UPDATE_OPERATION=${operation}
  SBV_UPDATE_TARGET_PATH=${SBV_BIN_PATH}
  SBV_UPDATE_LOG_FILE=${SBV_LOG_FILE}
  install_sbv_update_traps

  if prepare_sbv_update; then
    :
  else
    result_status=$?
    finish_sbv_update_failure "${result_status}" || return $?
    return 0
  fi
  if [[ -n "${SBV_UPDATE_SIGNAL_NAME}" ]]; then
    result_status=${SBV_UPDATE_SIGNAL_CODE}
    finish_sbv_update_failure "${result_status}" || return $?
    return 0
  fi

  SBV_UPDATE_STAGE='stage'
  case "${source_kind}" in
    url)
      if stage_sbv_candidate_from_url "${source}"; then
        :
      else
        result_status=$?
        finish_sbv_update_failure "${result_status}" || return $?
        return 0
      fi
      ;;
    file)
      if stage_sbv_candidate_from_file "${source}"; then
        :
      else
        result_status=$?
        finish_sbv_update_failure "${result_status}" || return $?
        return 0
      fi
      ;;
    *)
      set_sbv_update_error "${operation}" 'stage' 'source_kind_invalid' \
        '未知的 sbv 候选来源类型' "来源类型: ${source_kind}" 1 \
        '使用 file 或 url 来源'
      finish_sbv_update_failure 1 || return $?
      return 0
      ;;
  esac
  if [[ -n "${SBV_UPDATE_SIGNAL_NAME}" ]]; then
    result_status=${SBV_UPDATE_SIGNAL_CODE}
    finish_sbv_update_failure "${result_status}" || return $?
    return 0
  fi

  if validate_sbv_candidate; then
    :
  else
    result_status=$?
    finish_sbv_update_failure "${result_status}" || return $?
    return 0
  fi
  if [[ "${SBV_UPDATE_NOOP}" == 'true' ]]; then
    finish_sbv_update_success
    return 0
  fi
  if create_sbv_backup; then
    :
  else
    result_status=$?
    finish_sbv_update_failure "${result_status}" || return $?
    return 0
  fi
  if commit_sbv_candidate; then
    :
  else
    result_status=$?
    finish_sbv_update_failure "${result_status}" || return $?
    return 0
  fi
  if [[ -n "${SBV_UPDATE_SIGNAL_NAME}" ]]; then
    result_status=${SBV_UPDATE_SIGNAL_CODE}
    finish_sbv_update_failure "${result_status}" || return $?
    return 0
  fi
  SBV_UPDATE_STAGE='postcheck'
  if postcheck_sbv_update; then
    :
  else
    result_status=$?
    finish_sbv_update_failure "${result_status}" || return $?
    return 0
  fi
  if [[ -n "${SBV_UPDATE_SIGNAL_NAME}" ]]; then
    result_status=${SBV_UPDATE_SIGNAL_CODE}
    finish_sbv_update_failure "${result_status}" || return $?
    return 0
  fi
  finish_sbv_update_success
}

finish_sbv_artifact_failure() {
  local result_status=${1:-1}

  cleanup_sbv_update
  restore_sbv_update_traps
  report_sbv_update_error
  return "${result_status}"
}

finish_sbv_artifact_success() {
  cleanup_sbv_update
  restore_sbv_update_traps
  return 0
}

download_shell_artifact_atomically() {
  local operation=$1
  local url=$2
  local target=$3
  local target_dir
  local target_name
  local lock_path
  local lock_status=0
  local curl_status=0
  local detail=''
  local file_size
  local first_line=''
  local syntax_detail=''
  local target_existed='false'
  local old_mode='0755'
  local old_uid=''
  local old_gid=''
  local old_hash=''
  local actual_mode=''
  local actual_uid=''
  local actual_gid=''
  local restore_hash=''
  local retained_candidate=''
  local result_status=1
  local expected_mode='755'
  local postcheck_failed='false'
  local postcheck_code='postcheck_failed'

  reset_sbv_update_context
  SBV_UPDATE_OPERATION=${operation}
  SBV_UPDATE_TARGET_PATH=${target}
  SBV_UPDATE_LOG_FILE=${SBV_LOG_FILE}
  target_dir=$(dirname -- "${target}")
  target_name=${target##*/}
  lock_path="${target_dir}/.${target_name}.update.lock"
  SBV_UPDATE_LOCK_PATH=${lock_path}

  if [[ ! -d "${target_dir}" ]]; then
    set_sbv_update_error "${operation}" 'precheck' 'target_directory_missing' \
      '可执行 artifact 目标目录不存在' "目标目录: ${target_dir}" 1 \
      '检查目标目录的权限'
    report_sbv_update_error
    return 1
  fi
  if [[ -L "${target}" || ( -e "${target}" && ! -f "${target}" ) ]]; then
    set_sbv_update_error "${operation}" 'precheck' 'target_not_regular' \
      '可执行 artifact 目标不是普通文件' "目标路径: ${target}" 1 \
      '检查目标路径后重试；目标未发生变更'
    report_sbv_update_error
    return 1
  fi

  install_sbv_update_traps
  if mkdir "${lock_path}" 2>/dev/null; then
    :
  else
    lock_status=$?
    if [[ -e "${lock_path}" || -L "${lock_path}" ]]; then
      set_sbv_update_error "${operation}" 'precheck' 'update_in_progress' \
        '已有另一个可执行 artifact 更新事务正在运行' "锁路径: ${lock_path}" 1 \
        '等待现有更新结束后再重试；未取得锁时目标未发生变更'
      lock_status=1
    else
      set_sbv_update_error "${operation}" 'precheck' 'lock_create_failed' \
        '无法创建可执行 artifact 更新锁' "锁路径: ${lock_path}" "${lock_status}" \
        '检查目标目录的写权限、磁盘空间和文件系统状态；目标未发生变更'
    fi
    finish_sbv_artifact_failure "${lock_status}" || return $?
    return 0
  fi
  SBV_UPDATE_LOCK_HELD='true'
  if [[ -n "${SBV_UPDATE_SIGNAL_NAME}" ]]; then
    result_status=${SBV_UPDATE_SIGNAL_CODE}
    set_sbv_update_error "${operation}" 'precheck' 'signal_interrupted' \
      "更新过程中收到 ${SBV_UPDATE_SIGNAL_NAME}" \
      "信号: ${SBV_UPDATE_SIGNAL_NAME}" "${result_status}" \
      '重新运行更新；提交前目标 artifact 保持不变'
    finish_sbv_artifact_failure "${result_status}" || return $?
    return 0
  fi
  if [[ -L "${target}" || ( -e "${target}" && ! -f "${target}" ) ]]; then
    set_sbv_update_error "${operation}" 'precheck' 'target_not_regular' \
      '加锁后发现 artifact 目标不是普通文件' "目标路径: ${target}" 1 \
      '检查目标路径后重试；目标未发生变更'
    finish_sbv_artifact_failure 1 || return $?
    return 0
  fi

  SBV_UPDATE_STAGE='stage'
  if ! SBV_UPDATE_CANDIDATE_PATH=$(mktemp "${target_dir}/.${target_name}.candidate.XXXXXXXXXX"); then
    set_sbv_update_error "${operation}" 'stage' 'candidate_create_failed' \
      '无法创建可执行 artifact 候选文件' "候选目录: ${target_dir}" 1 \
      '检查目标目录的磁盘空间和权限'
    finish_sbv_artifact_failure 1 || return $?
    return 0
  fi
  if ! SBV_UPDATE_CURL_STDERR_PATH=$(mktemp "${target_dir}/.${target_name}.stderr.XXXXXXXXXX"); then
    set_sbv_update_error "${operation}" 'stage' 'diagnostic_file_create_failed' \
      '无法创建下载诊断文件' "诊断目录: ${target_dir}" 1 \
      '检查目标目录的磁盘空间和权限'
    finish_sbv_artifact_failure 1 || return $?
    return 0
  fi
  if curl -fsSL \
    --connect-timeout "${SBV_CURL_CONNECT_TIMEOUT}" \
    --max-time "${SBV_CURL_MAX_TIME}" \
    --retry "${SBV_CURL_RETRY_COUNT}" \
    --retry-delay "${SBV_CURL_RETRY_DELAY}" \
    -o "${SBV_UPDATE_CANDIDATE_PATH}" "${url}" \
    2>"${SBV_UPDATE_CURL_STDERR_PATH}"; then
    curl_status=0
  else
    curl_status=$?
  fi
  SBV_UPDATE_COMMAND_EXIT_CODE=${curl_status}
  if [[ "${SBV_UPDATE_SIGNAL_CODE}" != '0' ]]; then
    result_status=${SBV_UPDATE_SIGNAL_CODE}
    set_sbv_update_error "${operation}" 'download' 'signal_interrupted' \
      "下载过程中收到 ${SBV_UPDATE_SIGNAL_NAME}，更新已中断" \
      "信号: ${SBV_UPDATE_SIGNAL_NAME}" "${result_status}" \
      '重新运行更新；提交前目标 artifact 保持不变'
    finish_sbv_artifact_failure "${result_status}" || return $?
    return 0
  fi
  if [[ "${curl_status}" != '0' ]]; then
    detail=$(read_sbv_detail_file "${SBV_UPDATE_CURL_STDERR_PATH}")
    set_sbv_update_error "${operation}" 'download' "$(classify_sbv_download_error "${curl_status}")" \
      '下载可执行 artifact 失败' "${detail}" "${curl_status}" \
      '检查 DNS、IPv4/IPv6 出口、路由或 HTTPS_PROXY；原文件未发生变更'
    finish_sbv_artifact_failure "${curl_status}" || return $?
    return 0
  fi

  SBV_UPDATE_STAGE='validate'
  if ! file_size=$(wc -c < "${SBV_UPDATE_CANDIDATE_PATH}"); then
    set_sbv_update_error "${operation}" 'validate' 'artifact_size_check_failed' \
      '无法读取下载的 artifact 大小' "候选路径: ${SBV_UPDATE_CANDIDATE_PATH}" 1 \
      '拒绝提交远程内容；原文件未发生变更'
    finish_sbv_artifact_failure 1 || return $?
    return 0
  fi
  if (( file_size < SBV_ARTIFACT_MIN_SIZE )); then
    set_sbv_update_error "${operation}" 'validate' 'artifact_too_small' \
      '下载的可执行 artifact 为空或过小' "文件大小: ${file_size} 字节" 1 \
      '拒绝提交远程内容；原文件未发生变更'
    finish_sbv_artifact_failure 1 || return $?
    return 0
  fi
  IFS= read -r first_line < "${SBV_UPDATE_CANDIDATE_PATH}" || true
  if [[ ! "${first_line}" =~ ^#!.*(bash|sh)([[:space:]]|$) ]]; then
    set_sbv_update_error "${operation}" 'validate' 'artifact_shebang_invalid' \
      '远程 artifact 缺少可识别的 Shell shebang' "首行: ${first_line}" 1 \
      '拒绝提交远程内容；原文件未发生变更'
    finish_sbv_artifact_failure 1 || return $?
    return 0
  fi
  if LC_ALL=C grep -Eiq '^[[:space:]]*(<!doctype[[:space:]]+html|<html|<body)' \
    "${SBV_UPDATE_CANDIDATE_PATH}"; then
    set_sbv_update_error "${operation}" 'validate' 'artifact_html' \
      '远程 artifact 看起来是 HTML 或网关错误页' 'HTML marker detected' 1 \
      '拒绝提交远程内容；原文件未发生变更'
    finish_sbv_artifact_failure 1 || return $?
    return 0
  fi
  if ! syntax_detail=$(bash -n -- "${SBV_UPDATE_CANDIDATE_PATH}" 2>&1); then
    set_sbv_update_error "${operation}" 'validate' 'artifact_syntax_invalid' \
      '远程 artifact 未通过 Bash 语法校验' "${syntax_detail}" 1 \
      '拒绝提交远程内容；原文件未发生变更'
    finish_sbv_artifact_failure 1 || return $?
    return 0
  fi
  if [[ -n "${SBV_UPDATE_SIGNAL_NAME}" ]]; then
    result_status=${SBV_UPDATE_SIGNAL_CODE}
    set_sbv_update_error "${operation}" 'validate' 'signal_interrupted' \
      "校验过程中收到 ${SBV_UPDATE_SIGNAL_NAME}，更新已中断" \
      "信号: ${SBV_UPDATE_SIGNAL_NAME}" "${result_status}" \
      '重新运行更新；提交前目标 artifact 保持不变'
    finish_sbv_artifact_failure "${result_status}" || return $?
    return 0
  fi

  if [[ -f "${target}" ]]; then
    target_existed='true'
    SBV_UPDATE_TARGET_EXISTS='true'
    if ! get_sbv_file_metadata "${target}"; then
      set_sbv_update_error "${operation}" 'backup' 'target_metadata_failed' \
        '无法读取现有 artifact 的权限或所有者' "目标路径: ${target}" 1 \
        '检查目标文件权限；原文件未发生变更'
      finish_sbv_artifact_failure 1 || return $?
      return 0
    fi
    old_mode=${SBV_UPDATE_TARGET_MODE}
    old_uid=${SBV_UPDATE_TARGET_UID}
    old_gid=${SBV_UPDATE_TARGET_GID}
    if ! old_hash=$(calculate_sbv_sha256 "${target}"); then
      set_sbv_update_error "${operation}" 'backup' 'target_hash_failed' \
        '无法计算现有 artifact 的 SHA-256' "目标路径: ${target}" 1 \
        '检查目标文件是否可读；原文件未发生变更'
      finish_sbv_artifact_failure 1 || return $?
      return 0
    fi
    SBV_UPDATE_TARGET_HASH=${old_hash}
    if ! SBV_UPDATE_TARGET_VERSION=$(extract_sbv_script_version "${target}"); then
      SBV_UPDATE_TARGET_VERSION='unknown'
    fi
    SBV_UPDATE_CURRENT_VERSION=${SBV_UPDATE_TARGET_VERSION}
    if ! SBV_UPDATE_BACKUP_PATH=$(mktemp "${target_dir}/.${target_name}.backup.XXXXXXXXXX"); then
      set_sbv_update_error "${operation}" 'backup' 'backup_create_failed' \
        '无法创建现有 artifact 的受保护备份' "目标目录: ${target_dir}" 1 \
        '原文件未发生变更；检查目标目录的权限'
      finish_sbv_artifact_failure 1 || return $?
      return 0
    fi
    if ! cp -p -- "${target}" "${SBV_UPDATE_BACKUP_PATH}"; then
      set_sbv_update_error "${operation}" 'backup' 'backup_copy_failed' \
        '无法复制现有 artifact 到受保护备份' "目标路径: ${target}" 1 \
        '原文件未发生变更；检查目标目录的权限'
      finish_sbv_artifact_failure 1 || return $?
      return 0
    fi
    if ! chmod 0600 "${SBV_UPDATE_BACKUP_PATH}" || \
      ! chown 0:0 "${SBV_UPDATE_BACKUP_PATH}"; then
      set_sbv_update_error "${operation}" 'backup' 'backup_protect_failed' \
        '无法将 artifact 备份设置为 root-only' \
        "备份路径: ${SBV_UPDATE_BACKUP_PATH}" 1 \
        '检查文件系统权限；原文件未发生变更'
      finish_sbv_artifact_failure 1 || return $?
      return 0
    fi
  else
    SBV_UPDATE_CURRENT_VERSION='unknown'
  fi

  if [[ -n "${SBV_UPDATE_SIGNAL_NAME}" ]]; then
    result_status=${SBV_UPDATE_SIGNAL_CODE}
    set_sbv_update_error "${operation}" 'backup' 'signal_interrupted' \
      "备份阶段收到 ${SBV_UPDATE_SIGNAL_NAME}，更新已中断" \
      "信号: ${SBV_UPDATE_SIGNAL_NAME}" "${result_status}" \
      '重新运行更新；提交前目标 artifact 保持不变'
    finish_sbv_artifact_failure "${result_status}" || return $?
    return 0
  fi

  if [[ "${target_existed}" == 'true' && -x "${target}" ]]; then
    expected_mode=${old_mode}
  fi
  SBV_UPDATE_EXPECTED_MODE=${expected_mode}
  if ! chmod "${expected_mode}" "${SBV_UPDATE_CANDIDATE_PATH}"; then
    set_sbv_update_error "${operation}" 'commit' 'candidate_chmod_failed' \
      '无法设置 artifact 执行权限' "候选路径: ${SBV_UPDATE_CANDIDATE_PATH}" 1 \
      '原文件未发生变更'
    finish_sbv_artifact_failure 1 || return $?
    return 0
  fi
  if [[ "${target_existed}" == 'true' ]] && \
    ! chown "${old_uid}:${old_gid}" "${SBV_UPDATE_CANDIDATE_PATH}"; then
    set_sbv_update_error "${operation}" 'commit' 'candidate_chown_failed' \
      '无法保留 artifact 原有所有者' \
      "候选路径: ${SBV_UPDATE_CANDIDATE_PATH}" 1 \
      '原文件未发生变更'
    finish_sbv_artifact_failure 1 || return $?
    return 0
  fi
  if [[ -n "${SBV_UPDATE_SIGNAL_NAME}" ]]; then
    result_status=${SBV_UPDATE_SIGNAL_CODE}
    set_sbv_update_error "${operation}" 'commit' 'signal_interrupted' \
      "提交前收到 ${SBV_UPDATE_SIGNAL_NAME}，更新已中断" \
      "信号: ${SBV_UPDATE_SIGNAL_NAME}" "${result_status}" \
      '重新运行更新；提交前目标 artifact 保持不变'
    finish_sbv_artifact_failure "${result_status}" || return $?
    return 0
  fi
  if [[ "${target_existed}" == 'true' ]]; then
    SBV_UPDATE_EXPECTED_UID=${old_uid}
    SBV_UPDATE_EXPECTED_GID=${old_gid}
  else
    SBV_UPDATE_EXPECTED_MODE='755'
  fi
  SBV_UPDATE_STAGE='commit'
  if ! mv -f -- "${SBV_UPDATE_CANDIDATE_PATH}" "${target}"; then
    set_sbv_update_error "${operation}" 'commit' 'atomic_replace_failed' \
      '无法原子替换可执行 artifact' "目标路径: ${target}" 1 \
      '原文件未发生变更'
    finish_sbv_artifact_failure 1 || return $?
    return 0
  fi
  SBV_UPDATE_COMMITTED='true'
  SBV_UPDATE_CHANGED='true'

  SBV_UPDATE_STAGE='postcheck'
  if [[ -n "${SBV_UPDATE_SIGNAL_NAME}" ]]; then
    postcheck_failed='true'
    postcheck_code='signal_interrupted'
    result_status=${SBV_UPDATE_SIGNAL_CODE}
    detail="信号: ${SBV_UPDATE_SIGNAL_NAME}"
    SBV_UPDATE_COMMAND_EXIT_CODE=${result_status}
  elif [[ ! -f "${target}" || -L "${target}" ]]; then
    postcheck_failed='true'
    postcheck_code='postcheck_target_invalid'
    detail="目标路径: ${target}"
    SBV_UPDATE_COMMAND_EXIT_CODE='1'
  elif ! bash -n -- "${target}" 2>"${SBV_UPDATE_CURL_STDERR_PATH}"; then
    postcheck_failed='true'
    postcheck_code='postcheck_syntax_invalid'
    detail=$(read_sbv_detail_file "${SBV_UPDATE_CURL_STDERR_PATH}")
    SBV_UPDATE_COMMAND_EXIT_CODE='1'
  elif [[ ! -x "${target}" ]]; then
    postcheck_failed='true'
    postcheck_code='postcheck_not_executable'
    detail="目标路径: ${target}"
    SBV_UPDATE_COMMAND_EXIT_CODE='1'
  elif [[ "${target_existed}" == 'true' ]]; then
    if ! actual_mode=$(stat -c '%a' -- "${target}") || \
      ! actual_uid=$(stat -c '%u' -- "${target}") || \
      ! actual_gid=$(stat -c '%g' -- "${target}"); then
      postcheck_failed='true'
      postcheck_code='postcheck_metadata_failed'
      detail="目标路径: ${target}"
      SBV_UPDATE_COMMAND_EXIT_CODE='1'
    elif [[ "${actual_mode}" != "${SBV_UPDATE_EXPECTED_MODE}" || \
      "${actual_uid}" != "${old_uid}" || \
      "${actual_gid}" != "${old_gid}" ]]; then
      postcheck_failed='true'
      postcheck_code='postcheck_metadata_mismatch'
      detail="实际: ${actual_mode}:${actual_uid}:${actual_gid}; 预期: ${SBV_UPDATE_EXPECTED_MODE}:${old_uid}:${old_gid}"
      SBV_UPDATE_COMMAND_EXIT_CODE='1'
    fi
  fi
  if [[ "${postcheck_failed}" != 'true' ]]; then
    finish_sbv_artifact_success
    return 0
  fi

  SBV_UPDATE_ROLLBACK_ATTEMPTED='true'
  if [[ "${target_existed}" == 'true' ]]; then
    if SBV_UPDATE_ROLLBACK_PATH=$(mktemp "${target_dir}/.${target_name}.rollback.XXXXXXXXXX") && \
      cp -p -- "${SBV_UPDATE_BACKUP_PATH}" "${SBV_UPDATE_ROLLBACK_PATH}" && \
      chmod "${old_mode}" "${SBV_UPDATE_ROLLBACK_PATH}" && \
      chown "${old_uid}:${old_gid}" "${SBV_UPDATE_ROLLBACK_PATH}" && \
      mv -f -- "${SBV_UPDATE_ROLLBACK_PATH}" "${target}" && \
      [[ -f "${target}" && ! -L "${target}" ]] && \
      bash -n -- "${target}" && \
      [[ "$(stat -c '%a' -- "${target}")" == "${old_mode}" ]] && \
      [[ "$(stat -c '%u' -- "${target}")" == "${old_uid}" ]] && \
      [[ "$(stat -c '%g' -- "${target}")" == "${old_gid}" ]] && \
      restore_hash=$(calculate_sbv_sha256 "${target}") && [[ "${restore_hash}" == "${old_hash}" ]]; then
      SBV_UPDATE_ROLLBACK_PATH=''
      SBV_UPDATE_ROLLED_BACK='true'
      SBV_UPDATE_ROLLBACK_OK='true'
      set_sbv_update_error "${operation}" 'postcheck' "${postcheck_code}" \
        '提交后的 artifact 校验失败，已恢复原文件' "${detail}" \
        "${SBV_UPDATE_COMMAND_EXIT_CODE:-1}" \
        '原文件已恢复，未保留无效远程内容'
      result_status=${SBV_UPDATE_COMMAND_EXIT_CODE:-1}
      finish_sbv_artifact_failure "${result_status}" || return $?
      return 0
    fi
  elif rm -f -- "${target}" && [[ ! -e "${target}" && ! -L "${target}" ]]; then
    SBV_UPDATE_ROLLED_BACK='true'
    SBV_UPDATE_ROLLBACK_OK='true'
    set_sbv_update_error "${operation}" 'postcheck' "${postcheck_code}" \
      '提交后的 artifact 校验失败，已删除原本不存在的无效目标' "${detail}" \
      "${SBV_UPDATE_COMMAND_EXIT_CODE:-1}" \
      '原目标原本不存在；请重新运行下载'
    result_status=${SBV_UPDATE_COMMAND_EXIT_CODE:-1}
    finish_sbv_artifact_failure "${result_status}" || return $?
    return 0
  fi

  if [[ -f "${target}" && ! -L "${target}" ]]; then
    if retained_candidate=$(mktemp "${target_dir}/.${target_name}.candidate-retained.XXXXXXXXXX") && \
      cp -p -- "${target}" "${retained_candidate}" && \
      chmod 0600 "${retained_candidate}" && chown 0:0 "${retained_candidate}"; then
      SBV_UPDATE_CANDIDATE_PATH=${retained_candidate}
    else
      rm -f -- "${retained_candidate}" 2>/dev/null || true
    fi
  fi
  SBV_UPDATE_PRESERVE_ARTIFACTS='true'
  set_sbv_update_error "${operation}" 'postcheck' 'rollback_failed' \
    '提交后的 artifact 校验失败且自动恢复失败' "${detail}" \
    "${SBV_UPDATE_COMMAND_EXIT_CODE:-1}" \
    '保留的备份和候选文件可能需要人工恢复'
  SBV_UPDATE_MANUAL_INTERVENTION_REQUIRED='true'
  finish_sbv_artifact_failure 1 || return $?
  return 0
}

# Check for script update status. This is a read-only best-effort operation;
# unlike a mutating update it reports unavailable instead of propagating a
# network failure into the menu loop.
check_script_status() {
  local remote_content=''
  local remote_version=''

  if ! remote_content=$(curl -fsSL \
    --connect-timeout 5 \
    --max-time 15 \
    --retry 1 \
    --retry-delay 1 \
    "${SBV_UPDATE_URL}" 2>/dev/null); then
    SCRIPT_VER_STATUS="${RED}(无法检测更新: 网络不可用)${NC}"
    return 0
  fi

  if ! remote_version=$(printf '%s\n' "${remote_content}" | sed -nE \
    's/^[[:space:]]*readonly[[:space:]]+SCRIPT_VERSION="([0-9]{10})"[[:space:]]*$/\1/p' \
    | awk 'NF { count += 1; value = $0 } END { if (count == 1) print value }'); then
    SCRIPT_VER_STATUS="${RED}(无法检测更新: 响应解析失败)${NC}"
    return 0
  fi
  if [[ -z "${remote_version}" ]]; then
    SCRIPT_VER_STATUS="${RED}(无法检测更新: 响应无有效版本)${NC}"
    return 0
  fi

  if (( 10#${remote_version} > 10#${SCRIPT_VERSION} )); then
    SCRIPT_VER_STATUS="${YELLOW}(有新版本: ${remote_version})${NC}"
  else
    SCRIPT_VER_STATUS="${GREEN}(已是最新)${NC}"
  fi
  return 0
}

manual_update_script() {
  local result_status=0

  log_info "正在从 GitHub 获取最新脚本..."
  if sbv_update_transaction 'sbv_update' url "${SBV_UPDATE_URL}"; then
    if [[ "${SBV_UPDATE_NOOP}" == 'true' ]]; then
      log_info "当前 sbv 已是最新版本。"
    else
      log_success "脚本已原子更新到 ${SBV_UPDATE_CANDIDATE_VERSION}，请重新运行 sbv。"
    fi
    return 0
  else
    result_status=$?
  fi
  return "${result_status}"
}

ensure_sbv_command_installed() {
  local source_file=$0
  local result_status=0

  if [[ "${source_file}" == "${SBV_BIN_PATH}" || "${source_file}" == 'sbv' ]]; then
    return 0
  fi

  if [[ -f "${source_file}" && ! -L "${source_file}" ]]; then
    log_info "正在同步全局命令: sbv..."
    if sbv_update_transaction 'ensure_sbv_local' file "${source_file}"; then
      log_success "全局命令 sbv 已同步为当前脚本版本。"
      return 0
    else
      result_status=$?
    fi
    log_warn "当前脚本同步失败（退出码 ${result_status}），将尝试远程候选。"
  fi

  log_info "正在安装全局命令: sbv..."
  if sbv_update_transaction 'ensure_sbv_remote' url "${SBV_UPDATE_URL}"; then
    log_success "全局命令 sbv 安装成功。"
    return 0
  else
    result_status=$?
  fi

  if [[ -f "${source_file}" && ! -L "${source_file}" ]]; then
    log_warn "全局命令安装失败（退出码 ${result_status}），请稍后重试或人工安装。"
  else
    log_warn "全局命令安装失败（退出码 ${result_status}），后续可重新运行一键安装命令。"
  fi
  return "${result_status}"
}

exit_script() {
  echo ""
  log_info "已退出脚本。后续可运行 sbv 再次进入管理菜单。"
  exit 0
}

# Check for sing-box version
check_sb_version() {
  local current_sb_ver

  if [[ -f "${SINGBOX_BIN_PATH}" ]]; then
    current_sb_ver=$("${SINGBOX_BIN_PATH}" version 2>/dev/null | head -n1 | awk '{print $3}' || true)
    if [[ -z "${current_sb_ver}" ]]; then
      SB_VER_STATUS="${YELLOW}(版本检测失败)${NC}"
    elif [[ "${current_sb_ver}" != "${SB_SUPPORT_MAX_VERSION}" ]]; then
      SB_VER_STATUS="${YELLOW}(当前版本: ${current_sb_ver}, 建议更新到: ${SB_SUPPORT_MAX_VERSION})${NC}"
    else
      SB_VER_STATUS="${GREEN}(已是适配的最佳版本: ${current_sb_ver})${NC}"
    fi
  else
    SB_VER_STATUS="${RED}(未安装)${NC}"
  fi
}

# Check and Enable BBR
enable_bbr() {
  local current_cc
  current_cc=$(sysctl net.ipv4.tcp_congestion_control | awk '{print $3}')
  if [[ "${current_cc}" == "bbr" ]]; then
    log_success "BBR 拥塞控制已开启。"
  else
    log_warn "BBR 拥塞控制未开启，正在尝试开启..."
    set_sysctl_conf_value "net.core.default_qdisc" "fq" "/etc/sysctl.conf"
    set_sysctl_conf_value "net.ipv4.tcp_congestion_control" "bbr" "/etc/sysctl.conf"
    sysctl -p /etc/sysctl.conf
    log_success "BBR 开启成功。"
  fi
}

set_sysctl_conf_value() {
  local key=$1
  local value=$2
  local config_file=${3:-/etc/sysctl.conf}
  local escaped_key
  local escaped_value

  escaped_key=$(printf '%s' "${key}" | sed 's/[][\/.^$*]/\\&/g')
  escaped_value=$(printf '%s' "${value}" | sed 's/[\/&]/\\&/g')

  touch "${config_file}"
  if grep -qE "^[[:space:]]*${escaped_key}[[:space:]]*=" "${config_file}"; then
    sed -i -E "s|^[[:space:]]*${escaped_key}[[:space:]]*=.*|${key}=${escaped_value}|" "${config_file}"
  else
    printf '%s=%s\n' "${key}" "${value}" >> "${config_file}"
  fi
}

# Open firewall port
open_firewall_port() {
  local port=${1:-} networks transport status selected_transport=${3:-}
  local transports=()
  [[ "${port}" =~ ^[1-9][0-9]{0,4}$ && ${port} -le 65535 ]] || return 1
  networks=$(protocol_registry_field "${2:-${SB_PROTOCOL}}" listen_networks) || return 1
  IFS=, read -r -a transports <<< "${networks}"
  [[ ${#transports[@]} -gt 0 ]] || return 1
  for transport in "${transports[@]}"; do
    [[ "${transport}" == tcp || "${transport}" == udp ]] || return 1
  done
  # A committed listener plan may narrow a protocol's default networks. Keep
  # legacy two-argument calls, but never expand a selected instance network.
  # Validate before touching any backend, including explicitly empty input.
  if [[ $# -ge 3 ]]; then
    [[ "${selected_transport}" == tcp || "${selected_transport}" == udp ]] || return 1
    [[ ",${networks}," == *",${selected_transport},"* ]] || return 1
    transports=("${selected_transport}")
  fi
  log_info "正在尝试放行端口 ${port}..."
  for transport in "${transports[@]}"; do
    # UFW
    if command -v ufw &>/dev/null && ufw status | grep -q "Status: active"; then
      if ufw allow "${port}/${transport}" &>/dev/null; then :; else
        status=$?; printf '[ERROR] firewall_open: ufw_failed; external_state_may_be_partial\n' >&2; return "${status}"
      fi
    fi

    # Firewalld
    if command -v firewall-cmd &>/dev/null && firewall-cmd --state &>/dev/null; then
      if firewall-cmd --permanent --add-port="${port}/${transport}" &>/dev/null &&
         firewall-cmd --reload &>/dev/null; then :; else
        status=$?; printf '[ERROR] firewall_open: firewalld_failed; external_state_may_be_partial\n' >&2; return "${status}"
      fi
    fi

    # Iptables
    if command -v iptables &>/dev/null; then
      if iptables -C INPUT -p "${transport}" --dport "${port}" -j ACCEPT &>/dev/null; then :; else
        status=$?
        if [[ ${status} -ne 1 ]]; then
          printf '[ERROR] firewall_open: iptables_inspection_failed; external_state_may_be_partial\n' >&2; return "${status}"
        fi
        if iptables -I INPUT -p "${transport}" --dport "${port}" -j ACCEPT &>/dev/null; then :; else
          status=$?; printf '[ERROR] firewall_open: iptables_insert_failed; external_state_may_be_partial\n' >&2; return "${status}"
        fi
      fi
      log_warn "裸 iptables 规则通常只对当前运行时生效；如需持久化，请确认系统已配置规则保存机制。"
    fi
  done
  log_success "端口 ${port} 防火墙配置尝试完成。"
}

# A listener plan concerns fixed listening sockets, not tunneled traffic. In
# particular Mixed reserves TCP here; its SOCKS UDP relays use dynamic sockets.
# It deliberately refuses unmodelled binding scopes instead of guessing that a
# resource is unused. Tags are owners in this projection, not new instance IDs.
canonical_listener_address() {
  local address=${1:-} left right part zeros result='' word
  local ipv4_tail ipv4_prefix octet ipv4_group_high ipv4_group_low
  local groups=() tail_groups=() octets=()
  # Normalize an IPv4 suffix before expanding the IPv6 groups.  The validator
  # accepts both compressed and full IPv4-embedded spellings; leaving the
  # dotted tail in place would make the hexadecimal parser treat it as an
  # arithmetic expression and reject a valid listener.
  if [[ "${address}" == *.* && "${address}" == *:* ]]; then
    ipv4_tail=${address##*:}
    ipv4_prefix=${address%:*}
    IFS=. read -r -a octets <<< "${ipv4_tail}"
    [[ ${#octets[@]} -eq 4 ]] || return 1
    for octet in "${octets[@]}"; do
      [[ "${octet}" =~ ^(0|[1-9][0-9]{0,2})$ ]] || return 1
      (( 10#${octet} <= 255 )) || return 1
    done
    printf -v ipv4_group_high '%x' \
      "$((10#${octets[0]} * 256 + 10#${octets[1]}))"
    printf -v ipv4_group_low '%x' \
      "$((10#${octets[2]} * 256 + 10#${octets[3]}))"
    address="${ipv4_prefix}:${ipv4_group_high}:${ipv4_group_low}"
  fi
  structured_instance_store_validate_address "${address}" || return 1
  if [[ "${address}" != *:* ]]; then printf '%s' "${address}"; return 0; fi
  if [[ "${address}" == *::* ]]; then
    left=${address%%::*}; right=${address#*::}
    [[ -z "${left}" ]] || IFS=: read -r -a groups <<< "${left}"
    [[ -z "${right}" ]] || IFS=: read -r -a tail_groups <<< "${right}"
    zeros=$((8 - ${#groups[@]} - ${#tail_groups[@]}))
    while (( zeros > 0 )); do groups+=(0); zeros=$((zeros - 1)); done
    if [[ ${#tail_groups[@]} -gt 0 ]]; then groups+=("${tail_groups[@]}"); fi
  else
    IFS=: read -r -a groups <<< "${address}"
  fi
  for part in "${groups[@]}"; do
    printf -v word '%04x' "$((16#${part}))"
    result+="${result:+:}${word}"
  done
  if [[ "${result}" == 0000:0000:0000:0000:0000:ffff:* ]]; then
    printf '%d.%d.%d.%d' "$((16#${groups[6]} >> 8))" "$((16#${groups[6]} & 255))" \
      "$((16#${groups[7]} >> 8))" "$((16#${groups[7]} & 255))"
  else
    printf '%s' "${result}"
  fi
}

managed_listener_plan_json() {
  local registry components projected addresses address canonical normalized='[]' result
  registry=$(protocol_registry_json) || return 1
  components=$(component_registry_static_json) || return 1
  # Parse once, project only non-secret resource fields, and capture all output
  # before emission. Input is bounded by the file wrapper or the typed store.
  if ! projected=$(jq -cs --argjson registry "${registry}" --argjson components "${components}" '
    def require($ok): if $ok then . else error("invalid_listener") end;
    # Only an explicitly modelled adapter may select its fixed listeners.
    # NetworkList accepts a string or list; absent/null/[] mean defaults.
    # This is independent of traffic_networks (e.g. SOCKS UDP over TCP).
    def networks($inbound; $entry):
      if ($entry.advanced // false) then
        if ($inbound.type == "tun" or $inbound.type == "cloudflared") then []
        else
          (if $inbound.type == "redirect" then ["tcp"]
           elif ($inbound.type == "direct" or $inbound.type == "tproxy") then
             ($inbound.network // ["tcp", "udp"] |
               if type == "string" then [.] elif type == "array" then . else error("invalid_listener") end)
           else error("invalid_listener") end) as $defaults |
          require(($defaults | length) > 0 and all($defaults[]; . == "tcp" or . == "udp")) |
          require(($defaults | unique | length) == ($defaults | length)) |
          $defaults
        end
      else
        $entry.listen_networks |
        require(type == "array" and length > 0) |
        require(all(.[]; . == "tcp" or . == "udp")) |
        require((unique | length) == length) | . as $defaults |
        if ($inbound | has("network")) then
          require($entry.features.listen_network_selection == true) |
          ($inbound.network | if . == null then []
            elif type == "string" then [.] elif type == "array" then .
            else error("invalid_listener") end) as $requested |
          require(all($requested[]; . == "tcp" or . == "udp")) |
          require(($requested | unique | length) == ($requested | length)) |
          require(all($requested[]; . as $network | $defaults | index($network) != null)) |
          if ($requested | length) == 0 then $defaults
          else [$defaults[] | . as $network | select($requested | index($network) != null)] end
        elif $entry.features.listen_transport_projection == true then
          (($inbound.transport.type // "none")) as $transport |
          if $transport == "quic" then ["udp"]
          elif $transport == "none" or $transport == "http" or $transport == "ws" or $transport == "grpc" then ["tcp"]
          else error("invalid_listener") end
        else $defaults end
      end;
    require(length == 1) | .[0] | require(type == "object") |
    require((.inbounds | type) == "array") |
    require((has("endpoints") | not) or (.endpoints | type) == "array") |
    require(all((.endpoints // [])[]; . as $endpoint |
      any($components[]; .role == "endpoint" and .type == $endpoint.type))) |
    require(all((.endpoints // [])[]; ((.listen_port // 0) | type == "number" and . == floor and . >= 0 and . <= 65535))) |
    . as $root | .inbounds | require(length <= 256) |
    require(all(.[]; type == "object" and
      (.tag | type == "string" and length > 0 and (test("[\u0000-\u001f\u007f]") | not)) and
      (.type | type == "string") and
      ((has("listen") | not) or (.listen | type == "string" and length > 0 and (test("[\u0000-\u0020\u007f]") | not))) and
      (if (.type == "tun" or .type == "cloudflared") then
         ((.listen_port // 0) == 0)
       else
         (.listen_port | type == "number" and . == floor and . >= 1 and . <= 65535)
       end) and
      ((.netns // "") == "") and ((.bind_interface // "") == "") and ((.reuse_addr // false) == false))) |
    require((map(.tag) | unique | length) == length) |
    (map(. as $inbound |
      ([$registry[] | select(
        if $inbound.type == "vless" then
          .state_id == (if $inbound.tls.reality? != null then "vless-reality" else "vless-plain" end)
        else .type == $inbound.type end
      ) | . + {advanced:false}] +
       [$components[] | select(.role == "inbound" and .type == $inbound.type) | . + {advanced:true}]) |
      require(length == 1) | .[0] as $entry |
      networks($inbound; $entry)[] |
      {owner:$inbound.tag, protocol:($entry.state_id // $entry.type), address:($inbound.listen // "127.0.0.1"),
       transport:., port:$inbound.listen_port})
      ) +
      [($root.endpoints // [])[] | select((.listen_port // 0) > 0) |
       {owner:.tag, protocol:(.type + "-endpoint"), address:(.listen // "0.0.0.0"),
        transport:(if .type == "openvpn-server" then (.network // "udp") else "udp" end),
        port:.listen_port}]
  ' 2>/dev/null); then
    printf '[ERROR] listener_resources: unmodelled_or_invalid_listener\n' >&2
    return 1
  fi
  addresses=$(jq -r '[.[].address] | unique[]' <<< "${projected}") || return 1
  while IFS= read -r address; do
    [[ -n "${address}" ]] || continue
    canonical=$(canonical_listener_address "${address}") || {
      printf '[ERROR] listener_resources: invalid_address\n' >&2; return 1;
    }
    normalized=$(jq -c --arg original "${address}" --arg canonical "${canonical}" \
      '. + [{original:$original,canonical:$canonical}]' <<< "${normalized}") || return 1
  done <<< "${addresses}"
  result=$(jq -c --argjson normalized "${normalized}" '
    map(. as $item | ($normalized[] | select(.original == $item.address) | .canonical) as $address |
      .address=$address | .family=(if $address | contains(":") then "ipv6" else "ipv4" end) |
      .dual_stack=($address == "0000:0000:0000:0000:0000:0000:0000:0000"))
  ' <<< "${projected}") || return 1
  printf '%s\n' "${result}"
}

managed_listener_plan() (
  umask 077
  local file=${1:-} snapshot result
  [[ -f "${file}" && ! -L "${file}" && -r "${file}" ]] || {
    printf '[ERROR] listener_resources: unreadable_config\n' >&2; return 1;
  }
  # No credentials in argv, no unbounded reads and no reread after validation.
  snapshot=$(mktemp /tmp/sbv-listener-plan.XXXXXX) || return 1
  trap 'if ! rm -f -- "${snapshot}"; then printf "[ERROR] listener_resources: cleanup_failed\n" >&2; fi' EXIT
  trap 'exit 130' INT
  trap 'exit 143' TERM
  trap 'exit 129' HUP
  head -c 4194305 -- "${file}" > "${snapshot}" || return 1
  if [[ $(wc -c < "${snapshot}") -gt 4194304 ]]; then
    printf '[ERROR] listener_resources: oversized_config\n' >&2; return 1
  fi
  result=$(managed_listener_plan_json < "${snapshot}") || return $?
  rm -f -- "${snapshot}" || return $?
  trap - EXIT INT TERM HUP
  printf '%s\n' "${result}"
)

validate_listener_plan_json() {
  if ! jq -e '
    def overlap($a; $b):
      $a.dual_stack or $b.dual_stack or
      ($a.family == $b.family and ($a.address == $b.address or
        ($a.family == "ipv4" and ($a.address == "0.0.0.0" or $b.address == "0.0.0.0"))));
    . as $items | all(range(0; length); . as $i |
      all(range($i+1; $items|length); . as $j |
        ($items[$i].transport != $items[$j].transport or
         $items[$i].port != $items[$j].port or (overlap($items[$i]; $items[$j]) | not))))
  ' >/dev/null 2>&1; then
    printf '[ERROR] listener_resources: listener_conflict\n' >&2
    return 1
  fi
}

validate_managed_listener_resources() {
  local plan
  plan=$(managed_listener_plan "${1:-}") || return $?
  validate_listener_plan_json <<< "${plan}"
}

# Close only fixed-port transports with no remaining owner. Legacy rules are
# broad (all addresses/families), so any remaining address retains the rule.
# This reference guard does not establish ownership of pre-existing user rules.
# Missing live config is allowed only by the explicit all-protocol removal path.
# Close firewall port (reverse of open_firewall_port)
singbox_service_confirmed_stopped() {
  local active_state
  active_state=$(systemctl show sing-box --property=ActiveState --value 2>/dev/null) || {
    printf '[ERROR] firewall_cleanup: service_state_unavailable; rules_unchanged\n' >&2; return 1;
  }
  [[ "${active_state}" == inactive ]] || {
    printf '[ERROR] firewall_cleanup: service_not_stopped; rules_unchanged\n' >&2; return 1;
  }
}

close_firewall_port() {
  local port=${1:-} mode=${2:-remaining} plan old_plan transports transport status
  [[ "${port}" =~ ^[1-9][0-9]{0,4}$ && ${port} -le 65535 ]] || return 1
  if [[ "${mode}" == all_removed && ! -e "${SINGBOX_CONFIG_FILE}" && ! -L "${SINGBOX_CONFIG_FILE}" &&
        ! -e "${SB_PROTOCOL_INDEX_FILE}" && ! -L "${SB_PROTOCOL_INDEX_FILE}" ]]; then
    singbox_service_confirmed_stopped || return $?
    plan='[]'
  elif [[ "${mode}" == remaining ]]; then
    plan=$(managed_listener_plan "${SINGBOX_CONFIG_FILE}") || {
      printf '[ERROR] firewall_cleanup: inventory_unavailable; rules_unchanged\n' >&2
      return 1
    }
  else
    printf '[ERROR] firewall_cleanup: invalid_removal_state; rules_unchanged\n' >&2
    return 1
  fi
  old_plan=$(managed_listener_plan "${SINGBOX_CONFIG_FILE}.bak") || {
    printf '[ERROR] firewall_cleanup: previous_inventory_unavailable; rules_unchanged\n' >&2
    return 1
  }
  transports=$(jq -r --argjson port "${port}" --argjson old "${old_plan}" '
    . as $owners | [$old[] | select(.port == $port) | .transport] | unique[] | . as $transport |
    select(any($owners[]; .port == $port and .transport == $transport) | not)
  ' <<< "${plan}") || return 1
  [[ -n "${transports}" ]] || {
    log_info "端口 ${port} 仍有实例引用，保留防火墙规则。"
    return 0
  }
  log_info "正在尝试关闭端口 ${port}..."
  while IFS= read -r transport; do
    if command -v ufw &>/dev/null && ufw status | grep -q "Status: active"; then
      if ufw delete allow "${port}/${transport}" &>/dev/null; then :; else
        status=$?; printf '[ERROR] firewall_cleanup: ufw_failed; external_state_may_be_partial\n' >&2; return "${status}"
      fi
    fi
    if command -v firewall-cmd &>/dev/null && firewall-cmd --state &>/dev/null; then
      if firewall-cmd --permanent --remove-port="${port}/${transport}" &>/dev/null &&
         firewall-cmd --reload &>/dev/null; then :; else
        status=$?; printf '[ERROR] firewall_cleanup: firewalld_failed; external_state_may_be_partial\n' >&2; return "${status}"
      fi
    fi
    if command -v iptables &>/dev/null; then
      if iptables -C INPUT -p "${transport}" --dport "${port}" -j ACCEPT &>/dev/null; then
        if iptables -D INPUT -p "${transport}" --dport "${port}" -j ACCEPT &>/dev/null; then :; else
          status=$?; printf '[ERROR] firewall_cleanup: iptables_delete_failed; external_state_may_be_partial\n' >&2; return "${status}"
        fi
      else
        status=$?
        if [[ ${status} -ne 1 ]]; then
          printf '[ERROR] firewall_cleanup: iptables_inspection_failed; external_state_may_be_partial\n' >&2
          return "${status}"
        fi
      fi
    fi
  done <<< "${transports}"
  log_info "端口 ${port} 防火墙规则清理尝试完成。"
}

# Instance firewall transactions deliberately use a separate ownership ledger
# from the legacy coarse port helpers above.  These functions are a narrow
# transaction primitive for callers which already have a committed old/new
# listener plan.  They never infer ownership from a port alone: a rule is
# either positively observed before it is recorded, or it is created by this
# transaction with a deterministic marker.
readonly INSTANCE_FIREWALL_SCHEMA_VERSION="1"
readonly INSTANCE_FIREWALL_LEDGER_FILE="${SB_PROJECT_DIR}/managed-firewall.json"

instance_firewall_journal_path_valid() {
  local journal_file=${1:-} journal_dir
  [[ -n "${journal_file}" && "${journal_file}" != */ && "${journal_file}" != "${SB_PROJECT_DIR}"/* ]] || return 1
  [[ "${journal_file}" != *$'\n'* && "${journal_file}" != *$'\r'* ]] || return 1
  journal_dir=$(dirname -- "${journal_file}") || return 1
  [[ -d "${journal_dir}" && ! -L "${journal_dir}" ]] || return 1
  [[ ! -e "${journal_file}" || ! -L "${journal_file}" ]] || return 1
}

instance_firewall_write_json_atomic() {
  local destination=$1 payload=$2 destination_dir candidate
  destination_dir=$(dirname -- "${destination}") || return 1
  [[ -d "${destination_dir}" && ! -L "${destination_dir}" ]] || return 1
  [[ ! -e "${destination}" || ! -L "${destination}" ]] || return 1
  jq -e . >/dev/null 2>&1 <<< "${payload}" || return 1
  candidate=$(mktemp "${destination_dir}/.$(basename -- "${destination}").candidate.XXXXXX") || return 1
  if ! printf '%s\n' "${payload}" > "${candidate}" ||
     ! chmod 600 "${candidate}" ||
     ! mv -f -- "${candidate}" "${destination}"; then
    rm -f -- "${candidate}"
    return 1
  fi
}

instance_firewall_empty_ledger() {
  printf '{"schema_version":%s,"rules":[]}\n' "${INSTANCE_FIREWALL_SCHEMA_VERSION}"
}

instance_firewall_ledger_validate() {
  jq -ce --argjson version "${INSTANCE_FIREWALL_SCHEMA_VERSION}" '
    def clean_string:
      type == "string" and length > 0 and (test("[\u0000-\u001f\u007f]") | not);
    def ref_valid:
      . as $instance |
      type == "object" and
      (.owner | clean_string) and
      (.protocol | clean_string) and
      (.address | clean_string) and
      (.transport | type == "string" and test("^(tcp|udp)$")) and
      (.port | type == "number" and . == floor and . >= 1 and . <= 65535);
    def rule_valid:
      type == "object" and
      (.backend | type == "string" and test("^(ufw|firewalld|iptables|ip6tables)$")) and
      (.family | type == "string" and test("^(any|ipv4|ipv6)$")) and
      (.address | clean_string) and
      (.transport | type == "string" and test("^(tcp|udp)$")) and
      (.port | type == "number" and . == floor and . >= 1 and . <= 65535) and
      (.comment | clean_string) and
      (.refs | type == "array" and length <= 4096 and all(.[]; ref_valid));
    def ledger_valid:
      type == "object" and .schema_version == $version and
      (.rules | type == "array" and length <= 4096 and all(.[]; rule_valid)) and
      (([.rules[] | [.backend,.family,.address,.transport,.port] | @json] | unique | length) == (.rules | length));
    select(type == "object" and ledger_valid)
  '
}

instance_firewall_read_ledger() {
  local ledger_file=${INSTANCE_FIREWALL_LEDGER_FILE}
  if [[ ! -e "${ledger_file}" ]]; then
    instance_firewall_empty_ledger
    return 0
  fi
  [[ -f "${ledger_file}" && ! -L "${ledger_file}" && -r "${ledger_file}" ]] || return 1
  [[ "$(stat -c '%a' "${ledger_file}")" == 600 ]] || return 1
  instance_firewall_ledger_validate < "${ledger_file}"
}

instance_firewall_plan_file() {
  local config_file=${1:-}
  [[ -f "${config_file}" && ! -L "${config_file}" && -r "${config_file}" ]] || return 1
  managed_listener_plan "${config_file}"
}

instance_firewall_targets_json() {
  local plan_json=${1:-}
  jq -ce '
    def loopback:
      (.family == "ipv4" and (.address | test("^127\\."))) or
      (.family == "ipv6" and .address == "0000:0000:0000:0000:0000:0000:0000:0001");
    def physical:
      if .dual_stack then
        [{family:"ipv4",address:"0.0.0.0"},{family:"ipv6",address:"::"}]
      else [{family:.family,address:.address}]
      end;
    [ .[] as $listener |
      ($listener | physical[]) as $physical |
      {owner:$listener.owner,protocol:$listener.protocol,address:$physical.address,
       family:$physical.family,transport:$listener.transport,port:$listener.port} |
      select(loopback | not)
    ] | unique_by([.owner,.protocol,.address,.family,.transport,.port])
  ' <<< "${plan_json}"
}

instance_firewall_backend_state() {
  local backend=${1:-} status
  case "${backend}" in
    ufw)
      command -v ufw >/dev/null 2>&1 || return 2
      LC_ALL=C ufw status >/dev/null 2>&1 || return 3
      LC_ALL=C ufw status 2>/dev/null | grep -Fq 'Status: active' || return 2
      ;;
    firewalld)
      command -v firewall-cmd >/dev/null 2>&1 || return 2
      firewall-cmd --state >/dev/null 2>&1 || {
        status=$?
        [[ ${status} -eq 1 ]] && return 2
        return "${status}"
      }
      ;;
    iptables|ip6tables)
      command -v "${backend}" >/dev/null 2>&1 || return 2
      ;;
    *) return 1 ;;
  esac
  return 0
}

instance_firewall_rule_comment() {
  local backend=$1 family=$2 transport=$3 port=$4 address=$5
  local digest
  digest=$(printf '%s\0' "${backend}" "${family}" "${transport}" "${port}" "${address}" | sha256sum | awk '{print $1}') || return 1
  [[ "${digest}" =~ ^[[:xdigit:]]{64}$ ]] || return 1
  printf 'sbv-instance-%s' "${digest:0:24}"
}

instance_firewall_ufw_status_match() {
  local family=$1 address=$2 transport=$3 port=$4 comment=${5:-} require_marker=${6:-0}
  local line rule_text line_comment rule prefix first second target canonical_target target_family target_matched=0
  rule="${port}/${transport}"
  while IFS= read -r line; do
    # Comments are opaque data, never action/port/family tokens. Preserve
    # them separately only for the exact ownership comparison below.
    rule_text=${line%%' # '*}
    line_comment=''
    [[ "${line}" != *' # '* ]] || line_comment=${line#*' # '}
    [[ "${rule_text}" != *' ALLOW OUT '* ]] || continue
    if [[ "${rule_text}" == *' ALLOW IN '* ]]; then
      prefix=${rule_text%% ALLOW IN *}
    elif [[ "${rule_text}" == *' ALLOW '* ]]; then
      prefix=${rule_text%% ALLOW *}
    else
      continue
    fi
    [[ "${prefix}" =~ (^|[[:space:]])${rule}([[:space:]]|$) ]] || continue
    target=''
    if [[ "${prefix}" == *' on '* ]]; then
      target=${prefix##* on }
      target=${target%% *}
    else
      read -r first second _ <<< "${prefix}"
      [[ "${first}" == "${rule}" || "${first}" == "${rule}"\ * ]] || target=${first}
    fi
    target=${target#\[}
    target=${target%\]}
    target=${target%/32}
    target=${target%/128}
    if [[ -z "${target}" || "${target}" == Anywhere ]]; then
      [[ "${family}" == ipv4 && "${rule_text}" != *'(v6)'* ||
         "${family}" == ipv6 && "${rule_text}" == *'(v6)'* ]] || continue
    elif [[ "${target}" == "Anywhere (v6)" ]]; then
      [[ "${family}" == ipv6 ]] || continue
    else
      canonical_target=$(canonical_listener_address "${target}") || return 3
      target_family=ipv4
      [[ "${canonical_target}" == *:* ]] && target_family=ipv6
      [[ "${target_family}" == "${family}" && "${canonical_target}" == "${address}" ]] || continue
    fi
    target_matched=1
    if [[ "${require_marker}" == 0 ]]; then
      return 0
    fi
    # UFW's delete operation ignores comments, so ownership requires the
    # complete comment field to match exactly.  A substring is not evidence
    # of ownership (for example, an external suffix/prefix marker).
    [[ -n "${line_comment}" && "${line_comment}" == "${comment}" ]] && return 0
  done
  [[ "${require_marker}" == 1 && ${target_matched} -eq 1 ]] && return 4
  return 1
}

instance_firewall_rule_query() {
  local backend=$1 family=$2 transport=$3 port=$4 address=$5 comment=${6:-} require_marker=${7:-0} status
  case "${backend}" in
    ufw)
      [[ "${family}" == ipv4 || "${family}" == ipv6 ]] || return 3
      [[ -n "${comment}" || "${require_marker}" == 0 ]] || return 3
      LC_ALL=C ufw status 2>/dev/null | instance_firewall_ufw_status_match \
        "${family}" "${address}" "${transport}" "${port}" "${comment}" "${require_marker}"
      status=$?
      [[ ${status} -eq 0 || ${status} -eq 1 || ${status} -eq 4 ]] || return "${status}"
      return "${status}"
      ;;
    firewalld)
      local runtime_status permanent_status
      firewall-cmd --query-port="${port}/${transport}" >/dev/null 2>&1
      runtime_status=$?
      [[ ${runtime_status} -eq 0 || ${runtime_status} -eq 1 ]] || return "${runtime_status}"
      firewall-cmd --permanent --query-port="${port}/${transport}" >/dev/null 2>&1
      permanent_status=$?
      [[ ${permanent_status} -eq 0 || ${permanent_status} -eq 1 ]] || return "${permanent_status}"
      [[ ${runtime_status} -eq 0 && ${permanent_status} -eq 0 ]] && return 0
      return 1
      ;;
    iptables|ip6tables)
      local binary="${backend}" destination_args=()
      [[ "${family}" == ipv4 && "${backend}" == iptables ||
         "${family}" == ipv6 && "${backend}" == ip6tables ]] || return 3
      if [[ "${address}" != 0.0.0.0 && "${address}" != :: ]]; then
        destination_args=(-d "${address}")
      fi
      "${binary}" -C INPUT -p "${transport}" ${destination_args[@]+"${destination_args[@]}"} --dport "${port}" \
        -m comment --comment "${comment}" -j ACCEPT >/dev/null 2>&1
      status=$?
      [[ ${status} -eq 0 || ${status} -eq 1 ]] || return "${status}"
      return "${status}"
      ;;
    *) return 1 ;;
  esac
}

instance_firewall_rule_command() {
  local action=$1 backend=$2 family=$3 transport=$4 port=$5 address=$6 comment=$7
  local operation binary=''
  case "${action}" in create) operation=-I ;; delete) operation=-D ;; *) return 1 ;; esac
  case "${backend}" in
    iptables) binary=iptables; [[ "${family}" == ipv4 ]] || return 1 ;;
    ip6tables) binary=ip6tables; [[ "${family}" == ipv6 ]] || return 1 ;;
    ufw)
      [[ "${family}" == ipv4 || "${family}" == ipv6 ]] || return 1
      local ufw_address
      if [[ "${family}" == ipv6 ]]; then
        ufw_address=${address}
        [[ "${ufw_address}" == :: ]] && ufw_address=::/0
      else
        ufw_address=${address}
        [[ "${ufw_address}" == 0.0.0.0 ]] && ufw_address=0.0.0.0/0
      fi
      if [[ "${action}" == create ]]; then
        ufw allow in proto "${transport}" to "${ufw_address}" port "${port}" comment "${comment}"
      else
        ufw delete allow in proto "${transport}" to "${ufw_address}" port "${port}" comment "${comment}"
      fi
      return $?
      ;;
    firewalld)
      # firewalld has independent runtime/permanent rule sets and no portable
      # ownership marker for a plain port rule.  Never mutate either set here:
      # callers must provision both zones explicitly and then re-run prepare.
      return 1
      ;;
    *) return 1 ;;
  esac
  local destination_args=()
  if [[ "${address}" != 0.0.0.0 && "${address}" != :: ]]; then
    destination_args=(-d "${address}")
  fi
  "${binary}" "${operation}" INPUT -p "${transport}" ${destination_args[@]+"${destination_args[@]}"} --dport "${port}" \
    -m comment --comment "${comment}" -j ACCEPT
}

instance_firewall_targets_for_rule() {
  local targets=$1 backend=$2 family=$3 address=$4 transport=$5 port=$6
  jq -c --arg backend "${backend}" --arg family "${family}" --arg address "${address}" \
    --arg transport "${transport}" --argjson port "${port}" '
    map(select(.family == $family and .address == $address and .transport == $transport and .port == $port)) |
    map({owner,protocol,address,transport,port})
  ' <<< "${targets}"
}

instance_firewall_refs_for_rule() {
  local targets=$1 backend=$2 family=$3 address=$4 transport=$5 port=$6
  if [[ "${backend}" == firewalld ]]; then
    jq -c --arg transport "${transport}" --argjson port "${port}" \
      'map(select(.transport == $transport and .port == $port)) | map({owner,protocol,address,transport,port})' <<< "${targets}"
  else
    instance_firewall_targets_for_rule "${targets}" "${backend}" "${family}" "${address}" "${transport}" "${port}"
  fi
}

instance_firewall_ledger_rule_json() {
  local backend=$1 family=$2 address=$3 transport=$4 port=$5 comment=$6 refs=$7
  jq -cn --arg backend "${backend}" --arg family "${family}" --arg address "${address}" \
    --arg transport "${transport}" --argjson port "${port}" --arg comment "${comment}" \
    --argjson refs "${refs}" \
    '{backend:$backend,family:$family,address:$address,transport:$transport,port:$port,comment:$comment,refs:$refs}'
}

instance_firewall_journal_write() {
  local journal_file=$1 payload=$2
  instance_firewall_journal_path_valid "${journal_file}" || return 1
  instance_firewall_write_json_atomic "${journal_file}" "${payload}"
}

instance_firewall_journal_update() {
  local journal_file=$1 filter=$2
  local current updated
  [[ -f "${journal_file}" && ! -L "${journal_file}" ]] || return 1
  current=$(jq -ce . "${journal_file}") || return 1
  updated=$(jq -ce "${filter}" <<< "${current}") || return 1
  instance_firewall_write_json_atomic "${journal_file}" "${updated}"
}

instance_firewall_journal_validate() {
  local journal_file=${1:-}
  [[ -f "${journal_file}" && ! -L "${journal_file}" && -r "${journal_file}" ]] || return 1
  [[ "$(stat -c '%a' "${journal_file}")" == 600 ]] || return 1
  jq -ce --argjson version "${INSTANCE_FIREWALL_SCHEMA_VERSION}" '
    def clean_string:
      type == "string" and length > 0 and (test("[\u0000-\u001f\u007f]") | not);
    def ref_valid:
      type == "object" and
      (.owner | clean_string) and (.protocol | clean_string) and
      (.address | clean_string) and
      (.transport | type == "string" and test("^(tcp|udp)$")) and
      (.port | type == "number" and . == floor and . >= 1 and . <= 65535);
    def rule_valid:
      type == "object" and
      (.backend | type == "string" and test("^(ufw|firewalld|iptables|ip6tables)$")) and
      (.family | type == "string" and test("^(any|ipv4|ipv6)$")) and
      (.address | clean_string) and
      (.transport | type == "string" and test("^(tcp|udp)$")) and
      (.port | type == "number" and . == floor and . >= 1 and . <= 65535) and
      (.comment | clean_string) and
      (.refs | type == "array" and length <= 4096 and all(.[]; ref_valid));
    def ledger_valid:
      type == "object" and .schema_version == $version and
      (.rules | type == "array" and length <= 4096 and all(.[]; rule_valid)) and
      (([.rules[] | [.backend,.family,.address,.transport,.port] | @json] | unique | length) == (.rules | length));
    def operation_valid:
      type == "object" and
      (.id | clean_string) and
      (.backend | type == "string" and test("^(ufw|firewalld|iptables|ip6tables)$")) and
      (.family | type == "string" and test("^(any|ipv4|ipv6)$")) and
      (.address | clean_string) and
      (.transport | type == "string" and test("^(tcp|udp)$")) and
      (.port | type == "number" and . == floor and . >= 1 and . <= 65535) and
      (.comment | clean_string) and
      (.action | type == "string" and test("^(create|delete|preserve|unavailable)$")) and
      (.ownership | type == "string" and test("^(owned|preexisting|unowned)$")) and
      ((.action != "create" and .action != "delete") or .ownership == "owned") and
      (.action != "unavailable" or .ownership == "unowned") and
      (.refs_before | type == "array" and length <= 4096 and all(.[]; ref_valid)) and
      (.refs_after | type == "array" and length <= 4096 and all(.[]; ref_valid)) and
      (.state | type == "string" and test("^(planned|intent|applied|preserved|unavailable)$")) and
      (.rollback_state | type == "string" and test("^(none|intent|applied|already_compensated|uncertain)$"));
    def backend_status_valid:
      type == "object" and
      (.backend | type == "string" and test("^(ufw|firewalld|iptables|ip6tables)$")) and
      (.state | type == "string" and test("^(available|unavailable|external-managed)$"));
    def diagnostic_valid:
      type == "object" and (.code | clean_string) and
      (.severity | type == "string" and test("^(warning|error)$"));
    . as $journal |
    select(
      ($journal.schema_version == $version) and
      ($journal.status | type == "string" and test("^(prepared|applying|applied|committed|apply_failed|rolling_back|rolled_back|rollback_failed|rollback_uncertain)$")) and
      ($journal.before_ledger_exists | type == "boolean") and
      ($journal.before_ledger | ledger_valid) and
      ($journal.after_ledger | ledger_valid) and
      ($journal.operations | type == "array" and length <= 4096 and all(.[]; operation_valid) and ([.[] | .id] | unique | length) == length) and
      ($journal.backend_statuses | type == "array" and length <= 4 and all(.[]; backend_status_valid) and ([.[] | .backend] | unique | length) == length) and
      ($journal.diagnostics | type == "array" and length <= 4096 and all(.[]; diagnostic_valid))
    )
  ' "${journal_file}"
}

instance_firewall_prepare_failure() {
  local journal_file=$1 code=$2 result_status=${3:-1}
  local payload
  payload=$(jq -cn --argjson version "${INSTANCE_FIREWALL_SCHEMA_VERSION}" --arg code "${code}" \
    '{schema_version:$version,status:"prepare_failed",error_code:$code,before_ledger_exists:false,before_ledger:{schema_version:$version,rules:[]},after_ledger:{schema_version:$version,rules:[]},operations:[],diagnostics:[{code:$code,severity:"error"}]}') || return 1
  instance_firewall_journal_write "${journal_file}" "${payload}" || return 1
  return "${result_status}"
}

instance_firewall_prepare() {
  local old_config=${1:-} new_config=${2:-} journal_file=${3:-}
  local old_plan new_plan old_targets new_targets before_ledger
  local backend state backend_statuses='[]' diagnostics='[]' candidates selected_frontend=raw
  local ufw_state firewalld_state
  local operations='[]' after_rules='[]' candidate_json candidate_count index
  local rule_backend rule_family rule_address rule_transport rule_port comment
  local local_rule_family local_rule_address
  local refs_before refs_after ledger_rule query_status action ownership
  local journal_payload processed_key existing_key already_processed before_ledger_exists=false
  local processed_keys=()

  instance_firewall_journal_path_valid "${journal_file}" || return 1
  if [[ -n "${old_config}" && -e "${old_config}" ]]; then
    old_plan=$(instance_firewall_plan_file "${old_config}") || {
      instance_firewall_prepare_failure "${journal_file}" invalid_old_plan || :; return 1;
    }
  else
    old_plan='[]'
  fi
  new_plan=$(instance_firewall_plan_file "${new_config}") || {
    instance_firewall_prepare_failure "${journal_file}" invalid_new_plan || :; return 1;
  }
  old_targets=$(instance_firewall_targets_json "${old_plan}") || {
    instance_firewall_prepare_failure "${journal_file}" invalid_old_targets || :; return 1;
  }
  new_targets=$(instance_firewall_targets_json "${new_plan}") || {
    instance_firewall_prepare_failure "${journal_file}" invalid_new_targets || :; return 1
  }
  before_ledger=$(instance_firewall_read_ledger) || {
    instance_firewall_prepare_failure "${journal_file}" invalid_ledger || :; return 1;
  }
  [[ -e "${INSTANCE_FIREWALL_LEDGER_FILE}" ]] && before_ledger_exists=true
  candidates=$(jq -cn --argjson old "${old_targets}" --argjson new "${new_targets}" --argjson ledger "${before_ledger}" '
    def families: ["ipv4","ipv6"];
    def candidate($x):
      if $x.family == "ipv4" then
        [{family:"ipv4",address:(if $x.address == "0.0.0.0" then "0.0.0.0" else $x.address end),transport:$x.transport,port:$x.port}]
      else [{family:"ipv6",address:(if $x.address == "::" then "::" else $x.address end),transport:$x.transport,port:$x.port}]
      end;
    ([ $old[], $new[] ] | map(candidate(.)) | (add // [])) as $physical |
    ([$physical[]] + [$ledger.rules[] | {family:.family,address:.address,transport:.transport,port:.port}]) |
    unique_by([.family,.address,.transport,.port])
  ') || {
    instance_firewall_prepare_failure "${journal_file}" invalid_candidates || :; return 1;
  }
  for backend in ufw firewalld iptables ip6tables; do
    if instance_firewall_backend_state "${backend}"; then
      backend_statuses=$(jq -c --arg backend "${backend}" '. + [{backend:$backend,state:"available"}]' <<< "${backend_statuses}") || return 1
    else
      state=$?
      if [[ ${state} -eq 2 ]]; then
        backend_statuses=$(jq -c --arg backend "${backend}" '. + [{backend:$backend,state:"unavailable"}]' <<< "${backend_statuses}") || return 1
        diagnostics=$(jq -c --arg backend "${backend}" '. + [{code:"backend_unavailable",backend:$backend,severity:"warning"}]' <<< "${diagnostics}") || return 1
      else
        instance_firewall_prepare_failure "${journal_file}" backend_inspection_failed || :; return 1
      fi
    fi
  done
  ufw_state=$(jq -r '.[] | select(.backend == "ufw") | .state' <<< "${backend_statuses}") || return 1
  firewalld_state=$(jq -r '.[] | select(.backend == "firewalld") | .state' <<< "${backend_statuses}") || return 1
  if [[ "${ufw_state}" == available && "${firewalld_state}" == available ]]; then
    instance_firewall_prepare_failure "${journal_file}" backend_conflict || :; return 1
  elif [[ "${ufw_state}" == available ]]; then
    selected_frontend=ufw
  elif [[ "${firewalld_state}" == available ]]; then
    selected_frontend=firewalld
  fi
  if [[ "${selected_frontend}" != raw ]]; then
    backend_statuses=$(jq -c --arg frontend "${selected_frontend}" '
      map(if (.backend == "iptables" or .backend == "ip6tables")
          then .state = "external-managed" else . end)
    ' <<< "${backend_statuses}") || return 1
    diagnostics=$(jq -c --arg frontend "${selected_frontend}" '
      . + [{code:"backend_external_managed",frontend:$frontend,backend:"iptables",severity:"warning"},
           {code:"backend_external_managed",frontend:$frontend,backend:"ip6tables",severity:"warning"}]
    ' <<< "${diagnostics}") || return 1
  fi

  candidate_count=$(jq -r 'length' <<< "${candidates}") || return 1
  index=0
  while [[ ${index} -lt ${candidate_count} ]]; do
    candidate_json=$(jq -c ".[$index]" <<< "${candidates}") || return 1
    rule_family=$(jq -r '.family' <<< "${candidate_json}") || return 1
    rule_address=$(jq -r '.address' <<< "${candidate_json}") || return 1
    rule_transport=$(jq -r '.transport' <<< "${candidate_json}") || return 1
    rule_port=$(jq -r '.port' <<< "${candidate_json}") || return 1
    for backend in ufw firewalld iptables ip6tables; do
      if [[ "${backend}" == ufw || "${backend}" == firewalld ]]; then
        [[ "${rule_family}" == ipv4 || "${rule_family}" == ipv6 || "${rule_family}" == any ]] || continue
        if [[ "${backend}" == firewalld ]]; then
          local_rule_family=any
          local_rule_address='*'
        else
          local_rule_family=${rule_family}
          local_rule_address=${rule_address}
        fi
      elif [[ "${backend}" == iptables && "${rule_family}" == ipv4 ]]; then
        local_rule_family=ipv4; local_rule_address=${rule_address}
      elif [[ "${backend}" == ip6tables && "${rule_family}" == ipv6 ]]; then
        local_rule_family=ipv6; local_rule_address=${rule_address}
      else
        continue
      fi
      processed_key="${backend}|${local_rule_family}|${local_rule_address}|${rule_transport}|${rule_port}"
      if [[ "${backend}" == ufw || "${backend}" == firewalld ]]; then
        already_processed=0
        for existing_key in ${processed_keys[@]+"${processed_keys[@]}"}; do
          [[ "${existing_key}" == "${processed_key}" ]] && already_processed=1
        done
        [[ ${already_processed} -eq 0 ]] || continue
        processed_keys+=("${processed_key}")
      fi
      state=$(jq -r --arg backend "${backend}" '.[] | select(.backend == $backend) | .state' <<< "${backend_statuses}") || return 1
      refs_before=$(instance_firewall_refs_for_rule "${old_targets}" "${backend}" "${local_rule_family}" "${local_rule_address}" "${rule_transport}" "${rule_port}") || return 1
      refs_after=$(instance_firewall_refs_for_rule "${new_targets}" "${backend}" "${local_rule_family}" "${local_rule_address}" "${rule_transport}" "${rule_port}") || return 1
      ledger_rule=$(jq -c --arg backend "${backend}" --arg family "${local_rule_family}" --arg address "${local_rule_address}" \
        --arg transport "${rule_transport}" --argjson port "${rule_port}" \
        '[.rules[] | select(.backend == $backend and .family == $family and .address == $address and .transport == $transport and .port == $port)] | if length == 1 then .[0] else null end' <<< "${before_ledger}") || return 1
      comment=$(instance_firewall_rule_comment "${backend}" "${local_rule_family}" "${rule_transport}" "${rule_port}" "${local_rule_address}") || return 1
      action=preserve; ownership=preexisting
      if [[ "${state}" != available ]]; then
        if [[ "${ledger_rule}" != null ]]; then
          instance_firewall_prepare_failure "${journal_file}" owned_backend_unavailable || :; return 1
        fi
        [[ "${refs_after}" == '[]' ]] && continue
        action=unavailable; ownership=unowned
      else
        if [[ "${ledger_rule}" != null ]]; then
          if [[ "${backend}" == firewalld ]]; then
            instance_firewall_prepare_failure "${journal_file}" firewalld_owned_unsupported || :; return 1
          fi
          query_status=0
          instance_firewall_rule_query "${backend}" "${local_rule_family}" "${rule_transport}" "${rule_port}" "${local_rule_address}" "${comment}" 1 || query_status=$?
          if [[ ${query_status} -ne 0 ]]; then
            instance_firewall_prepare_failure "${journal_file}" owned_rule_inspection_failed || :; return 1
          fi
          ownership=owned
          [[ "${refs_after}" == '[]' ]] && action=delete
        elif [[ "${refs_after}" != '[]' ]]; then
          query_status=0
          instance_firewall_rule_query "${backend}" "${local_rule_family}" "${rule_transport}" "${rule_port}" "${local_rule_address}" "${comment}" || query_status=$?
          case ${query_status} in
            0) action=preserve; ownership=preexisting ;;
            1)
              if [[ "${backend}" == firewalld ]]; then
                instance_firewall_prepare_failure "${journal_file}" firewalld_requires_manual_setup || :; return 1
              fi
              action=create; ownership=owned
              ;;
            *) instance_firewall_prepare_failure "${journal_file}" rule_inspection_failed || :; return 1 ;;
          esac
        else
          continue
        fi
      fi
      if [[ "${action}" == preserve && "${ownership}" == preexisting && "${refs_after}" == '[]' ]]; then
        continue
      fi
      if [[ "${ownership}" == owned && "${refs_after}" != '[]' ]]; then
        after_rules=$(jq -c --arg backend "${backend}" --arg family "${local_rule_family}" --arg address "${local_rule_address}" \
          --arg transport "${rule_transport}" --argjson port "${rule_port}" --arg comment "${comment}" --argjson refs "${refs_after}" \
          '. + [{backend:$backend,family:$family,address:$address,transport:$transport,port:$port,comment:$comment,refs:$refs}]' <<< "${after_rules}") || return 1
      fi
      operations=$(jq -c --arg id "op-${index}-${backend}" --arg backend "${backend}" --arg family "${local_rule_family}" \
        --arg address "${local_rule_address}" --arg transport "${rule_transport}" --argjson port "${rule_port}" \
        --arg comment "${comment}" --arg action "${action}" --arg ownership "${ownership}" --argjson before "${refs_before}" --argjson after "${refs_after}" \
        '. + [{id:$id,backend:$backend,family:$family,address:$address,transport:$transport,port:$port,comment:$comment,action:$action,ownership:$ownership,refs_before:$before,refs_after:$after,state:"planned",rollback_state:"none"}]' <<< "${operations}") || return 1
    done
    index=$((index + 1))
  done
  # UFW reloads its generated iptables chains when a rule is changed.  Apply
  # UFW operations before direct iptables operations so UFW cannot flush rules
  # that this transaction has just created; rollback traverses this order in
  # reverse and remains equally safe.
  operations=$(jq -c 'sort_by((if .backend == "ufw" then 0 elif .backend == "firewalld" then 1 elif .backend == "iptables" then 2 else 3 end), .id)' <<< "${operations}") || return 1
  after_rules=$(jq -c 'unique_by([.backend,.family,.address,.transport,.port])' <<< "${after_rules}") || return 1
  journal_payload=$(jq -cn --argjson version "${INSTANCE_FIREWALL_SCHEMA_VERSION}" --argjson before_exists "${before_ledger_exists}" \
    --argjson before "${before_ledger}" \
    --argjson rules "${after_rules}" --argjson operations "${operations}" --argjson backends "${backend_statuses}" --argjson diagnostics "${diagnostics}" \
    '{schema_version:$version,status:"prepared",before_ledger_exists:$before_exists,before_ledger:$before,after_ledger:{schema_version:$version,rules:$rules},operations:$operations,backend_statuses:$backends,diagnostics:$diagnostics}') || return 1
  instance_firewall_journal_write "${journal_file}" "${journal_payload}"
}

instance_firewall_apply() {
  local journal_file=${1:-} journal status index count operation action backend family address transport port comment op_state
  local verify_status
  local mutation_status=0
  instance_firewall_journal_path_valid "${journal_file}" || return 1
  journal=$(instance_firewall_journal_validate "${journal_file}") || return 1
  status=$(jq -r '.status' <<< "${journal}") || return 1
  [[ "${status}" == prepared || "${status}" == applying || "${status}" == applied ||
     "${status}" == apply_failed || "${status}" == committed ]] || return 1
  [[ "${status}" == committed ]] && return 0
  instance_firewall_journal_update "${journal_file}" '.status="applying"' || return 1
  count=$(jq -r '.operations | length' <<< "${journal}") || return 1
  index=0
  while [[ ${index} -lt ${count} ]]; do
    operation=$(jq -c ".operations[$index]" "${journal_file}") || return 1
    op_state=$(jq -r '.state' <<< "${operation}") || return 1
    [[ "${op_state}" == applied || "${op_state}" == unavailable || "${op_state}" == preserved ]] && { index=$((index + 1)); continue; }
    [[ "${op_state}" == planned ]] || return 1
    action=$(jq -r '.action' <<< "${operation}") || return 1
    if [[ "${action}" == unavailable || "${action}" == preserve ]]; then
      instance_firewall_journal_update "${journal_file}" ".operations[$index].state=\"preserved\"" || return 1
      index=$((index + 1)); continue
    fi
    backend=$(jq -r '.backend' <<< "${operation}") || return 1
    family=$(jq -r '.family' <<< "${operation}") || return 1
    address=$(jq -r '.address' <<< "${operation}") || return 1
    transport=$(jq -r '.transport' <<< "${operation}") || return 1
    port=$(jq -r '.port' <<< "${operation}") || return 1
    comment=$(jq -r '.comment' <<< "${operation}") || return 1
    instance_firewall_journal_update "${journal_file}" ".operations[$index].state=\"intent\"" || return 1
    if instance_firewall_rule_command "${action}" "${backend}" "${family}" "${transport}" "${port}" "${address}" "${comment}"; then
      verify_status=0
      instance_firewall_rule_query "${backend}" "${family}" "${transport}" "${port}" "${address}" "${comment}" 1 || verify_status=$?
      if [[ ("${action}" == create && ${verify_status} -eq 0) ||
            ("${action}" == delete && ${verify_status} -eq 1) ]]; then
        instance_firewall_journal_update "${journal_file}" ".operations[$index].state=\"applied\"" || return 1
      else
        instance_firewall_journal_update "${journal_file}" ".status=\"apply_failed\" | .error_code=\"backend_mutation_unconfirmed\"" || return 1
        return 1
      fi
    else
      mutation_status=$?
      instance_firewall_journal_update "${journal_file}" ".status=\"apply_failed\" | .error_code=\"backend_mutation_failed\"" || return "${mutation_status}"
      return "${mutation_status}"
    fi
    index=$((index + 1))
  done
  if ! mkdir -p "${SB_PROJECT_DIR}" ||
     ! instance_firewall_write_json_atomic "${INSTANCE_FIREWALL_LEDGER_FILE}" "$(jq -c '.after_ledger' "${journal_file}")"; then
    instance_firewall_journal_update "${journal_file}" '.status="apply_failed" | .error_code="ledger_persist_failed"' || return 1
    return 1
  fi
  instance_firewall_journal_update "${journal_file}" '.status="applied"' || return 1
}

instance_firewall_restore_ledger() {
  local journal_file=$1 before_exists before_ledger
  before_exists=false
  if jq -e '.before_ledger_exists == true' "${journal_file}" >/dev/null 2>&1; then
    before_exists=true
  fi
  before_ledger=$(jq -c '.before_ledger' "${journal_file}") || return 1
  if [[ "${before_exists}" == true ]]; then
    instance_firewall_write_json_atomic "${INSTANCE_FIREWALL_LEDGER_FILE}" "${before_ledger}"
  else
    [[ ! -L "${INSTANCE_FIREWALL_LEDGER_FILE}" ]] || return 1
    if [[ -e "${INSTANCE_FIREWALL_LEDGER_FILE}" ]]; then
      rm -f -- "${INSTANCE_FIREWALL_LEDGER_FILE}" || return $?
    fi
  fi
}

instance_firewall_rollback() {
  local journal_file=${1:-} journal status count index operation action backend family address transport port comment op_state rollback_action
  local query_status mutation_status result_status=0
  instance_firewall_journal_path_valid "${journal_file}" || return 1
  journal=$(instance_firewall_journal_validate "${journal_file}") || return 1
  status=$(jq -r '.status' <<< "${journal}") || return 1
  [[ "${status}" == prepared || "${status}" == applying || "${status}" == applied ||
     "${status}" == committed || "${status}" == apply_failed || "${status}" == rolling_back ||
     "${status}" == rollback_failed || "${status}" == rollback_uncertain ||
     "${status}" == rolled_back ]] || return 1
  instance_firewall_journal_update "${journal_file}" '.status="rolling_back"' || return 1
  count=$(jq -r '.operations | length' <<< "${journal}") || return 1
  index=$((count - 1))
  while [[ ${index} -ge 0 ]]; do
    operation=$(jq -c ".operations[$index]" "${journal_file}") || return 1
    action=$(jq -r '.action' <<< "${operation}") || return 1
    op_state=$(jq -r '.state' <<< "${operation}") || return 1
    [[ "${action}" == create || "${action}" == delete ]] || { index=$((index - 1)); continue; }
    [[ "${op_state}" == applied || "${op_state}" == intent ]] || { index=$((index - 1)); continue; }
    backend=$(jq -r '.backend' <<< "${operation}") || return 1
    family=$(jq -r '.family' <<< "${operation}") || return 1
    address=$(jq -r '.address' <<< "${operation}") || return 1
    transport=$(jq -r '.transport' <<< "${operation}") || return 1
    port=$(jq -r '.port' <<< "${operation}") || return 1
    comment=$(jq -r '.comment' <<< "${operation}") || return 1
    query_status=0
    instance_firewall_rule_query "${backend}" "${family}" "${transport}" "${port}" "${address}" "${comment}" 1 || query_status=$?
    if [[ "${op_state}" == intent ]]; then
      if [[ ("${action}" == create && ${query_status} -eq 0) || ("${action}" == delete && ${query_status} -eq 1) ]]; then
        instance_firewall_journal_update "${journal_file}" ".operations[$index].rollback_state=\"uncertain\"" || return 1
        result_status=1
      fi
      if [[ ${query_status} -ne 0 && ${query_status} -ne 1 ]]; then
        instance_firewall_journal_update "${journal_file}" ".operations[$index].rollback_state=\"uncertain\"" || return 1
        result_status=1
      fi
      index=$((index - 1)); continue
    fi
    if [[ ${query_status} -eq 0 && "${action}" == create ]]; then
      rollback_action=delete
    elif [[ ${query_status} -eq 1 && "${action}" == delete ]]; then
      rollback_action=create
    elif [[ ${query_status} -eq 0 && "${action}" == delete || ${query_status} -eq 1 && "${action}" == create ]]; then
      instance_firewall_journal_update "${journal_file}" ".operations[$index].rollback_state=\"already_compensated\"" || return 1
      index=$((index - 1)); continue
    else
      instance_firewall_journal_update "${journal_file}" ".operations[$index].rollback_state=\"uncertain\"" || return 1
      result_status=1; index=$((index - 1)); continue
    fi
    instance_firewall_journal_update "${journal_file}" ".operations[$index].rollback_state=\"intent\"" || return 1
    if instance_firewall_rule_command "${rollback_action}" "${backend}" "${family}" "${transport}" "${port}" "${address}" "${comment}"; then
      query_status=0
      instance_firewall_rule_query "${backend}" "${family}" "${transport}" "${port}" "${address}" "${comment}" 1 || query_status=$?
      if [[ ("${rollback_action}" == delete && ${query_status} -eq 1) ||
            ("${rollback_action}" == create && ${query_status} -eq 0) ]]; then
        instance_firewall_journal_update "${journal_file}" ".operations[$index].rollback_state=\"applied\"" || return 1
      else
        instance_firewall_journal_update "${journal_file}" ".operations[$index].rollback_state=\"uncertain\"" || return 1
        result_status=1
      fi
    else
      mutation_status=$?
      instance_firewall_journal_update "${journal_file}" '.status="rollback_failed" | .error_code="compensation_failed"' || return 1
      result_status=${mutation_status:-1}
    fi
    index=$((index - 1))
  done
  if ! instance_firewall_restore_ledger "${journal_file}"; then
    instance_firewall_journal_update "${journal_file}" '.status="rollback_failed" | .error_code="ledger_restore_failed"' || return 1
    return 1
  fi
  if [[ ${result_status} -eq 0 ]]; then
    instance_firewall_journal_update "${journal_file}" '.status="rolled_back"' || return 1
  else
    instance_firewall_journal_update "${journal_file}" '.status="rollback_uncertain" | .error_code="external_state_uncertain"' || return 1
  fi
  return "${result_status}"
}

instance_firewall_commit() {
  local journal_file=${1:-} status
  instance_firewall_journal_path_valid "${journal_file}" || return 1
  instance_firewall_journal_validate "${journal_file}" >/dev/null || return 1
  status=$(jq -r '.status' "${journal_file}") || return 1
  [[ "${status}" == applied || "${status}" == committed ]] || return 1
  [[ "${status}" == committed ]] || instance_firewall_journal_update "${journal_file}" '.status="committed"'
}


# Verify configuration file
check_config_valid() {
  log_info "正在校验配置文件有效性..."
  if ! validate_config_file; then
    log_error "配置文件校验失败，请检查配置细节。"
  fi
  log_success "配置文件校验成功。"
}

validate_config_file() {
  "${SINGBOX_BIN_PATH}" check -c "${SINGBOX_CONFIG_FILE}"
}

# Check for port conflict
check_port_conflict() {
  local port=$1
  if port_is_in_use "${port}"; then
    local process
    process=$(ss -tunlp | grep ":${port} " | awk '{print $7}' | cut -d'"' -f2 | head -n1)
    log_warn "端口 ${port} 已被进程 [${process}] 占用。"
    echo "1. 保留占用进程并改用随机端口"
    echo "2. 使用随机端口"
    echo "3. 手动输入新端口"
    port_choice=$(prompt_choice "请选择操作 [1-3]: " 1 3 "")

    case "${port_choice}" in
      1|2)
        SB_PORT="$(pick_random_high_port)"
        log_success "已保留占用进程，并自动切换到随机端口: ${SB_PORT}"
        ;;
      3)
        SB_PORT=$(prompt_port "请输入新端口: " "")
        check_port_conflict "${SB_PORT}"
        ;;
    esac
  fi
}

get_os_info() {
  if [[ -f /etc/os-release ]]; then
    source /etc/os-release
    OS_NAME=$ID
    OS_VERSION=$VERSION_ID
  elif [[ -f /etc/redhat-release ]]; then
    OS_NAME="centos"
    OS_VERSION=$(grep -oE '[0-9]+' /etc/redhat-release | head -n1)
  else
    log_error "不支持的操作系统。"
  fi
}

get_arch() {
  local arch_raw
  arch_raw=$(uname -m)
  case "${arch_raw}" in
    x86_64) ARCH="amd64" ;;
    aarch64) ARCH="arm64" ;;
    *) log_error "不支持的架构: ${arch_raw}" ;;
  esac
}

# --- System Check & Dependencies ---
install_dependencies() {
  log_info "正在安装必要的基础依赖..."
  case "${OS_NAME}" in
    debian|ubuntu)
      apt-get update -y
      apt-get install -y curl wget jq tar openssl uuid-runtime qrencode iproute2
      ;;
    centos|almalinux|rocky)
      yum install -y curl wget jq tar openssl util-linux qrencode iproute
      ;;
  esac
  log_success "基础依赖安装完成。"
}

# --- Sing-box Manager ---
get_latest_version() {
  if [[ "${SB_VERSION}" == "latest" ]]; then
    log_info "正在获取最新版本号..."
    local latest_tag=$(curl -s "https://api.github.com/repos/SagerNet/sing-box/releases/latest" | jq -r .tag_name | sed 's/^v//')
    if [[ -z "${latest_tag}" || "${latest_tag}" == "null" ]]; then
      SB_VERSION="${SB_SUPPORT_MAX_VERSION}"
    else
      SB_VERSION="${latest_tag}"
      if [[ "${SB_VERSION}" != "${SB_SUPPORT_MAX_VERSION}" ]]; then
        log_warn "注意：最新版本 (${SB_VERSION}) 高于适配版本 (${SB_SUPPORT_MAX_VERSION})，可能存在兼容性风险。"
        sleep 2
      fi
    fi
  fi
}

replace_singbox_binary_atomically() {
  local source_file=$1
  local target_dir
  local staged_binary=""

  [[ -f "${source_file}" ]] || return 1
  target_dir=$(dirname "${SINGBOX_BIN_PATH}")
  [[ -d "${target_dir}" ]] || return 1
  staged_binary=$(mktemp "${target_dir}/.sing-box.restore.XXXXXXXX") || return 1

  if ! cp -p -- "${source_file}" "${staged_binary}" ||
     ! chmod 0755 "${staged_binary}" ||
     ! mv -f -- "${staged_binary}" "${SINGBOX_BIN_PATH}"; then
    rm -f -- "${staged_binary}"
    return 1
  fi
}

restore_singbox_update_artifacts() {
  local binary_backup=$1
  local library_backup_dir=$2
  local status=0

  if ! replace_singbox_binary_atomically "${binary_backup}"; then
    status=1
  fi
  if ! singbox_library_restore_snapshot "${library_backup_dir}"; then
    status=1
  fi
  return "${status}"
}

install_binary() {
  local download_url="https://github.com/SagerNet/sing-box/releases/download/v${SB_VERSION}/sing-box-${SB_VERSION}-linux-${ARCH}.tar.gz"
  local temp_dir="/tmp/sing-box-install"
  local bin_path
  local lib_source
  local lib_path
  local lib_dir
  local staged_lib
  local staged_marker
  
  # Ensure we are in a valid directory before cleanup/extraction
  cd /tmp
  
  # Cleanup before start
  rm -rf "${temp_dir}"
  mkdir -p "${temp_dir}"
  
  log_info "开始下载 sing-box ${SB_VERSION}..."
  if ! wget -O "${temp_dir}/sb.tar.gz" "${download_url}"; then
    log_error "下载 sing-box 失败。"
  fi
  
  log_info "正在解压并安装..."
  if ! tar -xzf "${temp_dir}/sb.tar.gz" -C "${temp_dir}"; then
    log_error "解压失败。"
  fi
  
  bin_path=$(find "${temp_dir}" -name "sing-box" -type f -print -quit)
  if [[ -z "${bin_path}" ]]; then
    log_error "找不到 sing-box 二进制文件。"
  fi
  
  if ! replace_singbox_binary_atomically "${bin_path}"; then
    log_error "安装 sing-box 二进制失败。"
  fi

  # Official Linux pure-Go archives include the optional libcronet runtime
  # beside the binary.  Keep a managed copy in the sibling lib directory so
  # NaiveProxy client outbounds can load it without relying on an extracted
  # temporary archive.  An unowned existing library is never overwritten.
  lib_source=$(find "${temp_dir}" -name "libcronet.so" -type f -print -quit)
  if [[ -n "${lib_source}" ]]; then
    lib_path=$(singbox_library_path) || log_error "无法确定 libcronet.so 安装路径。"
    lib_dir=$(dirname "${lib_path}")
    if [[ -e "${lib_path}" && ! -f "${SB_NAIVE_LIBRARY_MARKER}" ]]; then
      log_warn "发现未由 sbv 管理的 ${lib_path}，保留现有文件并跳过 libcronet.so 替换。"
    else
      if ! mkdir -p "${lib_dir}"; then
        log_error "创建 libcronet.so 目录失败。"
      fi
      staged_lib=$(mktemp "${lib_dir}/.libcronet.XXXXXXXX") || \
        log_error "创建 libcronet.so staging 文件失败。"
      if ! cp -p -- "${lib_source}" "${staged_lib}" ||
         ! chmod 0644 "${staged_lib}" ||
         ! mv -f -- "${staged_lib}" "${lib_path}"; then
        rm -f -- "${staged_lib}"
        log_error "安装 libcronet.so 失败。"
      fi
      staged_marker=$(mktemp "${SB_NAIVE_LIBRARY_MARKER}.XXXXXXXX") || \
        log_error "创建 libcronet.so 标记文件失败。"
      if ! sha256sum "${lib_path}" | awk '{print $1}' > "${staged_marker}" ||
         ! chmod 600 "${staged_marker}" ||
         ! mv -f -- "${staged_marker}" "${SB_NAIVE_LIBRARY_MARKER}"; then
        rm -f -- "${staged_marker}"
        log_error "提交 libcronet.so 标记文件失败。"
      fi
      if command -v ldconfig >/dev/null 2>&1; then
        if ! ldconfig; then
          log_warn "ldconfig 未能刷新 libcronet.so 缓存；运行 NaiveProxy 客户端时请设置 LD_LIBRARY_PATH=${lib_dir}。"
        fi
      else
        log_warn "未找到 ldconfig；运行 NaiveProxy 客户端时请设置 LD_LIBRARY_PATH=${lib_dir}。"
      fi
    fi
  else
    log_warn "下载归档未包含 libcronet.so；NaiveProxy 客户端运行时依赖仍不可用。"
  fi

  # Final Cleanup
  rm -rf "${temp_dir}"
  log_success "二进制文件安装成功并已清理临时文件。"
}

setup_service() {
  log_info "配置 systemd 服务..."
  cat > "${SINGBOX_SERVICE_FILE}" <<EOF
[Unit]
Description=sing-box service
After=network.target nss-lookup.target
[Service]
CapabilityBoundingSet=CAP_NET_ADMIN CAP_NET_BIND_SERVICE CAP_NET_RAW
AmbientCapabilities=CAP_NET_ADMIN CAP_NET_BIND_SERVICE CAP_NET_RAW
ExecStart=${SINGBOX_BIN_PATH} run -c ${SINGBOX_CONFIG_FILE}
Restart=on-failure
RestartSec=10s
LimitNOFILE=infinity
[Install]
WantedBy=multi-user.target
EOF
  systemctl daemon-reload
  systemctl enable sing-box >/dev/null 2>&1

  if ! ensure_sbv_command_installed; then
    log_warn "全局命令 sbv 未能完成同步；当前安装流程继续，但请稍后手动重试。"
  fi
}

service_file_needs_repair() {
  [[ -f "${SINGBOX_SERVICE_FILE}" ]] || return 0
  grep -Fqx "ExecStart=${SINGBOX_BIN_PATH} run -c ${SINGBOX_CONFIG_FILE}" "${SINGBOX_SERVICE_FILE}" || return 0
  return 1
}

# --- Protocol State Helpers ---
list_effective_protocols() {
  local inventory_state_file=${1:-} installed
  installed=$(extract_protocols_from_index)

  if [[ -n "${installed}" ]]; then
    list_installed_protocols "${inventory_state_file}"
    return $?
  fi

  validate_protocol_index_for_rebuild || return 1
  runtime_protocol_to_state "${SB_PROTOCOL}" || return 1
  printf '\n'
}

load_protocol_state() {
  local protocol state_file state_mode=${2:-mutable} mixed_schema socks_schema
  protocol=$(normalize_protocol_id "$1") || return 1
  state_file=$(protocol_state_file "${protocol}") || return 1
  mixed_schema=""
  socks_schema=""
  if [[ "${protocol}" == "mixed" && -f "${state_file}" ]]; then
    if grep -Eq "^[[:space:]]*CONFIG_SCHEMA_VERSION=(2|\"2\"|'2')[[:space:]]*$" "${state_file}"; then
      mixed_schema=2
    else
      mixed_schema=$(sed -n 's/^[[:space:]]*CONFIG_SCHEMA_VERSION=//p' "${state_file}" | head -n1) || return 1
      mixed_schema=${mixed_schema//\"/}
      mixed_schema=${mixed_schema//\'/}
    fi
  fi
  if [[ ("${protocol}" == "vless-plain" || "${protocol}" == "socks" || "${protocol}" == "http" || "${protocol}" == "shadowsocks" || "${protocol}" == "trojan" || "${protocol}" == "vmess" || "${protocol}" == "anytls" || "${protocol}" == "hy2" || "${protocol}" == "snell" || "${protocol}" == "tuic" || "${protocol}" == "hysteria" || "${protocol}" == "naive" || "${protocol}" == "shadowtls") && -f "${state_file}" ]]; then
    socks_schema=$(sed -n 's/^[[:space:]]*CONFIG_SCHEMA_VERSION=//p' "${state_file}" | head -n1) || return 1
    socks_schema=${socks_schema//\"/}
    socks_schema=${socks_schema//\'/}
  fi
  validate_protocol_state_schema "${protocol}" "${state_file}" || return 1
  if [[ "${protocol}" == "vless-reality" && "${state_mode}" != "read-only" ]]; then
    migrate_vless_reality_state_to_instances_if_needed
  fi
  state_file=$(protocol_state_file "${protocol}")

  if [[ ! -f "${state_file}" ]]; then
    [[ "${state_mode}" == "read-only" ]] && return 1
    if [[ "$(runtime_protocol_to_state "${SB_PROTOCOL}")" == "${protocol}" ]]; then
      return 0
    fi
    log_error "未找到协议状态文件: ${state_file}"
  fi

  # Schema-2 Mixed markers are data-only metadata.  Dispatch before sourcing
  # the file, and fail closed if a concurrent rewrite leaves a schema-2 marker
  # malformed; schema-1 legacy loading below remains unchanged.
  if [[ "${protocol}" == "mixed" && "${mixed_schema}" == "2" ]]; then
    mixed_structured_marker_is_valid "${state_file}" || return 1
    load_mixed_structured_instance || return 1
    return 0
  fi
  if [[ "${protocol}" == "mixed" ]]; then
    if mixed_structured_marker_is_valid "${state_file}"; then
      load_mixed_structured_instance || return 1
      return 0
    fi
    if grep -Eq "^[[:space:]]*CONFIG_SCHEMA_VERSION=(2|\"2\"|'2')[[:space:]]*$" "${state_file}"; then
      mixed_schema=2
    else
      mixed_schema=$(sed -n 's/^[[:space:]]*CONFIG_SCHEMA_VERSION=//p' "${state_file}" | head -n1) || return 1
      mixed_schema=${mixed_schema//\"/}
      mixed_schema=${mixed_schema//\'/}
    fi
    [[ "${mixed_schema}" == "2" ]] && return 1
  fi

  # SOCKS has no legacy .env representation.  Dispatch only a validated
  # schema-2 marker to the typed store and reject every older/unknown shape
  # before it can be sourced as shell code.
  if [[ "${protocol}" == "vless-plain" || "${protocol}" == "socks" || "${protocol}" == "http" || "${protocol}" == "shadowsocks" || "${protocol}" == "trojan" || "${protocol}" == "vmess" || ("${protocol}" == "anytls" && "${socks_schema}" == "2") || ("${protocol}" == "hy2" && "${socks_schema}" == "2") || ("${protocol}" == "snell" && "${socks_schema}" == "2") || ("${protocol}" == "tuic" && "${socks_schema}" == "2") || ("${protocol}" == "hysteria" && "${socks_schema}" == "2") || ("${protocol}" == "naive" && "${socks_schema}" == "2") || ("${protocol}" == "shadowtls" && "${socks_schema}" == "2") ]]; then
    [[ "${socks_schema}" == "2" ]] || return 1
    plain_proxy_structured_marker_is_valid "${state_file}" || return 1
    load_plain_proxy_structured_instance "${protocol}" || return 1
    return 0
  fi

  unset ACME_EXTRA_JSON || true
  # shellcheck disable=SC1090
  source "${state_file}"

  case "${protocol}" in
    vless-reality)
      if [[ "${CONFIG_SCHEMA_VERSION:-1}" == "2" ]]; then
        load_vless_reality_protocol_state
        load_vless_reality_instance_state "${VLESS_REALITY_DEFAULT_INSTANCE_ID:-main}" || true
        unset NODE_NAME PORT UUID SNI SHORT_ID_1 SHORT_ID_2
      fi
      SB_PROTOCOL="vless+reality"
      SB_NODE_NAME="${NODE_NAME:-${SB_NODE_NAME:-$(default_node_name_for_protocol "vless+reality")}}"
      SB_PORT="${PORT:-${SB_PORT:-443}}"
      SB_UUID="${UUID:-${SB_UUID:-}}"
      SB_SNI="${SNI:-${SB_SNI:-$SB_REALITY_SNI_FALLBACK}}"
      SB_PRIVATE_KEY="${REALITY_PRIVATE_KEY:-${SB_PRIVATE_KEY:-}}"
      SB_PUBLIC_KEY="${REALITY_PUBLIC_KEY:-${SB_PUBLIC_KEY:-}}"
      SB_SHORT_ID_1="${SHORT_ID_1:-${SB_SHORT_ID_1:-}}"
      SB_SHORT_ID_2="${SHORT_ID_2:-${SB_SHORT_ID_2:-}}"
      SB_MIXED_AUTH_ENABLED="y"
      SB_MIXED_USERNAME=""
      SB_MIXED_PASSWORD=""
      SB_HY2_DOMAIN=""
      SB_HY2_PASSWORD=""
      SB_HY2_USER_NAME=""
      SB_HY2_UP_MBPS=""
      SB_HY2_DOWN_MBPS=""
      SB_HY2_OBFS_ENABLED="n"
      SB_HY2_OBFS_TYPE=""
      SB_HY2_OBFS_PASSWORD=""
      SB_HY2_TLS_MODE="acme"
      SB_HY2_ACME_MODE="http"
      SB_HY2_ACME_EMAIL=""
      SB_HY2_ACME_DOMAIN=""
      SB_HY2_ACME_EXTRA_JSON='{}'
      SB_HY2_DNS_PROVIDER="cloudflare"
      SB_HY2_CF_API_TOKEN=""
      SB_HY2_CERT_PATH=""
      SB_HY2_KEY_PATH=""
      SB_HY2_MASQUERADE=""
      SB_ANYTLS_DOMAIN=""
      SB_ANYTLS_PASSWORD=""
      SB_ANYTLS_USER_NAME=""
      SB_ANYTLS_TLS_MODE="acme"
      SB_ANYTLS_ACME_MODE="http"
      SB_ANYTLS_ACME_EMAIL=""
      SB_ANYTLS_ACME_DOMAIN=""
      SB_ANYTLS_ACME_EXTRA_JSON='{}'
      SB_ANYTLS_DNS_PROVIDER="cloudflare"
      SB_ANYTLS_CF_API_TOKEN=""
      SB_ANYTLS_CERT_PATH=""
      SB_ANYTLS_KEY_PATH=""
      ;;
    mixed)
      if [[ "${CONFIG_SCHEMA_VERSION:-1}" == "2" ]]; then
        load_mixed_structured_instance || return 1
        return 0
      fi
      SB_PROTOCOL="mixed"
      SB_NODE_NAME=$(normalize_node_name "${NODE_NAME:-$(default_node_name_for_protocol "mixed")}")
      SB_PORT="${PORT:-1080}"
      SB_UUID=""
