      SB_MIXED_AUTH_ENABLED="${AUTH_ENABLED:-y}"
      SB_MIXED_USERNAME="${USERNAME:-}"
      SB_MIXED_PASSWORD="${PASSWORD:-}"
      SB_HY2_DOMAIN=""
