      SB_ANYTLS_KEY_PATH=""
      ;;
    hy2)
      SB_PROTOCOL="hy2"
      SB_NODE_NAME=$(normalize_node_name "${NODE_NAME:-$(default_node_name_for_protocol "hy2")}")
      SB_PORT="${PORT:-443}"
