    --arg tag "anytls-in" \
    --arg listen "$(stack_inbound_listen_address)" \
    --arg port "${SB_PORT}" \
    --arg user_name "${SB_ANYTLS_USER_NAME}" \
    --arg password "${SB_ANYTLS_PASSWORD}" \
    --arg domain "${SB_ANYTLS_DOMAIN}" \
    --arg tls_mode "${SB_ANYTLS_TLS_MODE}" \
    --arg cert_path "${SB_ANYTLS_CERT_PATH}" \
    --arg key_path "${SB_ANYTLS_KEY_PATH}" \
    --arg certificate_provider "$(anytls_certificate_provider_tag)" \
    --arg use_certificate_provider "${use_certificate_provider}" \
    --argjson acme "${acme_json:-null}" \
    '{
      "type": "anytls",
      "tag": $tag,
      "listen": $listen,
      "listen_port": ($port | tonumber),
      "users": [
        {
          "name": $user_name,
          "password": $password
        }
      ],
      "tls": (
        {
          "enabled": true,
          "server_name": $domain
        } + (
          if $tls_mode == "manual" then
            {
              "certificate_path": $cert_path,
              "key_path": $key_path
            }
          elif $use_certificate_provider == "y" then
            {
              "certificate_provider": $certificate_provider
            }
          else
            {
              "acme": $acme
            }
          end
        )
      )
    }'
}

build_certificate_provider_for_protocol() {
  local protocol
  protocol=$(normalize_protocol_id "$1") || return 1

  case "${protocol}" in
    vless-reality|vless-plain|mixed|socks|http|shadowsocks|trojan|vmess|snell|tuic|hysteria|naive|shadowtls) return 0 ;; # HTTP/VLESS/Trojan/VMess/Snell/TUIC/Hysteria/Naive/ShadowTLS use no certificate provider.
    hy2) build_hy2_certificate_provider_json ;;
    anytls) build_anytls_certificate_provider_json ;;
    *) return 1 ;;
  esac
}

build_inbound_for_protocol() {
  local protocol
  protocol=$(normalize_protocol_id "$1") || return 1

  case "${protocol}" in
    vless-reality) build_vless_inbound_json ;;
    vless-plain) build_vless_plain_inbound_json ;;
    mixed) build_mixed_inbound_json ;;
    socks) build_socks_inbound_json ;;
    http) build_http_inbound_json ;;
    shadowsocks) build_shadowsocks_inbound_json ;;
    trojan) build_trojan_inbound_json ;;
    vmess) build_vmess_inbound_json ;;
    hy2) build_hy2_inbound_json ;;
    anytls) build_anytls_inbound_json ;;
    snell) build_snell_inbound_json ;;
    tuic) build_tuic_inbound_json ;;
    hysteria) build_hysteria_inbound_json ;;
    naive) build_naive_inbound_json ;;
    shadowtls) build_shadowtls_inbound_json ;;
    *) return 1 ;;
  esac
}

build_vless_reality_route_rules_json() {
  local tmp_rules tmp_snis instance_id inbound_tag sni instance_ids
  tmp_rules=$(mktemp) || return 1
  if ! tmp_snis=$(mktemp); then
    rm -f "${tmp_rules}"
    return 1
  fi

  if ! load_vless_reality_protocol_state; then
    rm -f "${tmp_rules}" "${tmp_snis}"
    return 1
  fi
  if ! instance_ids=$(list_vless_reality_instance_ids); then
    rm -f "${tmp_rules}" "${tmp_snis}"
    return 1
  fi
  while IFS= read -r instance_id; do
    [[ -z "${instance_id}" ]] && continue
    if ! load_vless_reality_instance_state "${instance_id}"; then
      rm -f "${tmp_rules}" "${tmp_snis}"
      return 1
    fi
    inbound_tag=$(vless_reality_inbound_tag_for_instance "${instance_id}")
    if ! jq -n --arg inbound_tag "${inbound_tag}" '{ "inbound": $inbound_tag, "action": "sniff" }' >> "${tmp_rules}"; then
      rm -f "${tmp_rules}" "${tmp_snis}"
      return 1
    fi
    [[ -n "${SB_SNI}" ]] && printf '%s\n' "${SB_SNI}" >> "${tmp_snis}"
  done <<< "${instance_ids}"

  while IFS= read -r sni; do
    [[ -z "${sni}" ]] && continue
    if ! jq -n --arg sni "${sni}" '{ "domain": [ $sni ], "action": "direct" }' >> "${tmp_rules}"; then
      rm -f "${tmp_rules}" "${tmp_snis}"
      return 1
    fi
  done < <(sort -u "${tmp_snis}")

  if ! jq -s '.' "${tmp_rules}"; then
    rm -f "${tmp_rules}" "${tmp_snis}"
    return 1
  fi

  rm -f "${tmp_rules}" "${tmp_snis}"
}

build_vless_reality_instance_outbound_rules_json() {
  local tmp_rules instance_id inbound_tag outbound instance_ids
  tmp_rules=$(mktemp) || return 1

  if ! load_vless_reality_protocol_state; then
    rm -f "${tmp_rules}"
    return 1
  fi
  if ! instance_ids=$(list_vless_reality_instance_ids); then
    rm -f "${tmp_rules}"
    return 1
  fi
  while IFS= read -r instance_id; do
    [[ -z "${instance_id}" ]] && continue
    if ! load_vless_reality_instance_state "${instance_id}"; then
      rm -f "${tmp_rules}"
      return 1
    fi
    case "${SB_OUTBOUND_POLICY:-default}" in
      direct) outbound="direct" ;;
      warp)
        outbound="warp-ep"
        ;;
      *) continue ;;
    esac
    inbound_tag=$(vless_reality_inbound_tag_for_instance "${instance_id}")
    if ! jq -n \
      --arg inbound_tag "${inbound_tag}" \
      --arg outbound "${outbound}" \
      '{ "inbound": $inbound_tag, "action": "route", "outbound": $outbound }' >> "${tmp_rules}"; then
      rm -f "${tmp_rules}"
      return 1
    fi
  done <<< "${instance_ids}"

  if ! jq -s '.' "${tmp_rules}"; then
    rm -f "${tmp_rules}"
    return 1
  fi

  rm -f "${tmp_rules}"
}

build_vless_plain_route_rules_json() {
  local store_file
  plain_proxy_structured_state_active vless-plain || return 1
  store_file=$(plain_proxy_structured_store_file vless-plain) || return 1
  render_structured_instance_route_rules vless-plain "${store_file}"
}

vless_reality_has_warp_outbound_policy() {
  local instance_id

  load_vless_reality_protocol_state
  while IFS= read -r instance_id; do
    [[ -z "${instance_id}" ]] && continue
    load_vless_reality_instance_state "${instance_id}" || continue
    [[ "${SB_OUTBOUND_POLICY:-default}" == "warp" ]] && return 0
  done < <(list_vless_reality_instance_ids)

  return 1
}

instance_outbound_requires_warp() {
  local protocol state_file schema store_file

  while IFS= read -r protocol; do
    [[ -z "${protocol}" ]] && continue
    case "${protocol}" in
      vless-reality)
        vless_reality_has_warp_outbound_policy && return 0
        ;;
      vless-plain|mixed|socks|http|shadowsocks|trojan|vmess|anytls|hy2|snell|tuic|hysteria|naive|shadowtls)
        state_file=$(protocol_state_file "${protocol}") || return 1
        schema=$(sed -n 's/^[[:space:]]*CONFIG_SCHEMA_VERSION=//p' "${state_file}" 2>/dev/null || true)
        schema=${schema//\"/}
        schema=${schema//\'/}
        if [[ "${schema}" == "2" ]]; then
          plain_proxy_structured_state_active "${protocol}" || return 1
          store_file=$(plain_proxy_structured_store_file "${protocol}") || return 1
          jq -e 'any(.instances[]; .outbound_policy == "warp")' "${store_file}" >/dev/null 2>&1 && return 0
        fi
        ;;
    esac
  done < <(list_effective_protocols)

  return 1
}

build_protocol_route_rules() {
  local protocol
  protocol=$(normalize_protocol_id "$1") || return 1

  case "${protocol}" in
    vless-reality)
      build_vless_reality_route_rules_json
      ;;
    mixed)
      local state_file schema
      state_file=$(protocol_state_file "mixed") || return 1
      schema=$(sed -n 's/^[[:space:]]*CONFIG_SCHEMA_VERSION=//p' "${state_file}" 2>/dev/null || true)
      schema=${schema//\"/}
      schema=${schema//\'/}
      if [[ "${schema}" == "2" ]]; then
        mixed_structured_state_active || return 1
        render_structured_instance_route_rules mixed "$(mixed_structured_store_file)"
      else
        jq -n '[{ "inbound": "mixed-in", "action": "sniff" }]'
      fi
      ;;
      vless-plain|socks|http|shadowsocks|trojan|vmess|hysteria|naive|shadowtls)
      local state_file
      state_file=$(protocol_state_file "${protocol}") || return 1
      plain_proxy_structured_state_active "${protocol}" || return 1
      render_structured_instance_route_rules "${protocol}" "$(plain_proxy_structured_store_file "${protocol}")"
      ;;
    anytls)
      local state_file schema
      state_file=$(protocol_state_file "${protocol}") || return 1
      schema=$(sed -n 's/^[[:space:]]*CONFIG_SCHEMA_VERSION=//p' "${state_file}" 2>/dev/null | head -n1 || true)
      schema=${schema//\"/}
      schema=${schema//\'/}
      if [[ "${schema}" == "2" ]]; then
        plain_proxy_structured_state_active "${protocol}" || return 1
        render_structured_instance_route_rules "${protocol}" "$(plain_proxy_structured_store_file "${protocol}")"
      else
        jq -n '[{ "inbound": "anytls-in", "action": "sniff" }]'
      fi
      ;;
    hy2)
      local state_file schema
      state_file=$(protocol_state_file "${protocol}") || return 1
      schema=$(sed -n 's/^[[:space:]]*CONFIG_SCHEMA_VERSION=//p' "${state_file}" 2>/dev/null | head -n1 || true)
      schema=${schema//\"/}
      schema=${schema//\'/}
      if [[ "${schema}" == "2" ]]; then
        plain_proxy_structured_state_active hy2 || return 1
        render_structured_instance_route_rules hy2 "$(plain_proxy_structured_store_file hy2)"
      else
        jq -n '[{ "inbound": "hy2-in", "action": "sniff" }]'
      fi
      ;;
    snell)
      plain_proxy_structured_state_active snell || return 1
      render_structured_instance_route_rules snell "$(plain_proxy_structured_store_file snell)"
      ;;
    tuic)
      plain_proxy_structured_state_active tuic || return 1
      render_structured_instance_route_rules tuic "$(plain_proxy_structured_store_file tuic)"
      ;;
    hysteria)
      plain_proxy_structured_state_active hysteria || return 1
      render_structured_instance_route_rules hysteria "$(plain_proxy_structured_store_file hysteria)"
      ;;
    naive)
      plain_proxy_structured_state_active naive || return 1
      render_structured_instance_route_rules naive "$(plain_proxy_structured_store_file naive)"
      ;;
    *) return 1 ;;
  esac
}

# A stream of inbound/provider objects, or exactly one route array. Empty output
# is valid only for the explicit none/optional provider contract in the registry.
append_protocol_fragment() {
  local protocol=$1 kind=$2 destination=$3 fragment expected_type contract
  protocol_registry_require_handlers "${protocol}" || return 1
  expected_type=$(protocol_registry_field "${protocol}" type) || return 1
  contract=$(protocol_registry_field "${protocol}" certificate_contract) || return 1
  case "${kind}" in
    inbound) fragment=$(build_inbound_for_protocol "${protocol}") || return $? ;;
    certificate) fragment=$(build_certificate_provider_for_protocol "${protocol}") || return $? ;;
    route) fragment=$(build_protocol_route_rules "${protocol}") || return $? ;;
    *) return 1 ;;
  esac
  if ! jq -es --arg kind "${kind}" --arg expected_type "${expected_type}" --arg contract "${contract}" '
    def tagged: type == "object" and (.tag | type == "string" and length > 0);
    if $kind == "inbound" then
      length > 0 and (if $expected_type == "shadowtls" then
        all(.[]; tagged and ((.type == "shadowtls") or (.type == "mixed" and (.tag | startswith("shadowtls-inner-")))))
      else all(.[]; tagged and .type == $expected_type) end)
    elif $kind == "certificate" then
      if $contract == "none" then length == 0
      elif $contract == "optional" then all(.[]; tagged and (.type | type == "string" and length > 0))
      else false end
    else length == 1 and (.[0] | type == "array" and all(.[]; type == "object")) end
  ' >/dev/null 2>&1 <<< "${fragment}"; then
    printf '[ERROR] 协议生成器返回无效片段，未发布配置。\n' >&2
    return 1
  fi
  printf '%s\n' "${fragment}" >> "${destination}"
}

# --- Managed advanced components -------------------------------------------------
# Advanced inbounds, endpoints and outbounds are stored as typed JSON records.
# They intentionally have their own CAS state file so that adding a TUN or an
# endpoint cannot silently change the share-link protocol index.  The config
# graph validator remains the final reference/dep-cycle gate; these helpers
# provide the state, identity, exposure and transaction guards before a
# candidate reaches that validator.
managed_component_state_default_json() {
  jq -cn --argjson schema "${SB_COMPONENT_STATE_SCHEMA_VERSION}" \
    '{schema_version:$schema,revision:0,components:[]}'
}

managed_component_state_id_valid() {
  [[ "${1:-}" =~ ^[a-z0-9][a-z0-9_-]{0,63}$ ]]
}

managed_component_tag_valid() {
  local tag=${1:-}
  [[ -n "${tag}" && ${#tag} -le 128 && "${tag}" != *[[:space:]]* &&
    "${tag}" != *$'\n'* && "${tag}" != *$'\r'* ]]
}

# Validate the SSH outbound contract instead of treating its config as an
# unbounded core-JSON passthrough.  The allowlist follows the sing-box 1.14
# SSHOutboundOptions plus its shared Dial Fields.  Secrets are only inspected
# for shape here; this function never prints the input or embeds it in an
# error.  An empty host_key remains an explicit upstream-compatible choice
# (sing-box accepts any host key), while inventory reports that weaker mode.
managed_component_ssh_config_validate_json() {
  local config=${1:-}
  [[ -n "${config}" ]] || return 1
  jq -e '
    def safe_string:
      type == "string" and (any(explode[]; . < 32 or . == 127) | not);
    def nonempty_safe_string:
      safe_string and length > 0;
    def listable_nonempty_string:
      (type == "string" and length > 0) or
      (type == "array" and length > 0 and
        all(.[]; type == "string" and length > 0));
    def optional_safe_string($name):
      (has($name) | not) or (.[$name] | safe_string);
    def optional_string($name):
      (has($name) | not) or (.[$name] | type == "string");
    def optional_listable_safe_string($name):
      (has($name) | not) or
      (.[$name] |
        ((type == "string" and safe_string) or
         (type == "array" and all(.[]; nonempty_safe_string))));
    def optional_listable_private_key($name):
      (has($name) | not) or
      (.[$name] |
        ((type == "string") or
         (type == "array" and all(.[]; type == "string" and length > 0))));
    def optional_bool($name):
      (has($name) | not) or (.[$name] | type == "boolean");
    def optional_network_types($name):
      (has($name) | not) or
      (.[$name] |
        ((type == "string" and (length == 0 or IN("wifi","cellular","ethernet","other"))) or
         (type == "array" and all(.[]; type == "string" and
           IN("wifi","cellular","ethernet","other")))));
    def optional_duration($name):
      (has($name) | not) or (.[$name] | safe_string);
    def optional_routing_mark:
      (has("routing_mark") | not) or
      (.routing_mark |
        ((type == "number" and . == floor and . >= 0 and . <= 4294967295) or
         (type == "string" and (length == 0 or test("^0x[0-9a-fA-F]+$")))));
    def optional_network_strategy:
      (has("network_strategy") | not) or
      (.network_strategy | type == "string" and IN("","default","hybrid","fallback"));
    type == "object" and
    ((keys - [
      "server","server_port","user","password","private_key",
      "private_key_path","private_key_passphrase","host_key",
      "host_key_algorithms","client_version","cipher","mac",
      "kex_algorithm","detour","bind_interface","inet4_bind_address",
      "inet6_bind_address","bind_address_no_port","protect_path","routing_mark",
      "reuse_addr","netns","connect_timeout","tcp_fast_open",
      "tcp_multi_path","disable_tcp_keep_alive","tcp_keep_alive",
      "tcp_keep_alive_interval","udp_fragment","domain_resolver",
      "network_strategy","network_type","fallback_network_type",
      "fallback_delay"
    ]) | length == 0) and
    (.server | nonempty_safe_string) and
    ((has("server_port") | not) or
      (.server_port | type == "number" and . == floor and . >= 1 and . <= 65535)) and
    optional_safe_string("user") and
    optional_string("password") and
    optional_listable_private_key("private_key") and
    optional_safe_string("private_key_path") and
    optional_string("private_key_passphrase") and
    optional_listable_safe_string("host_key") and
    optional_listable_safe_string("host_key_algorithms") and
    optional_safe_string("client_version") and
    optional_listable_safe_string("cipher") and
    optional_listable_safe_string("mac") and
    optional_listable_safe_string("kex_algorithm") and
    optional_safe_string("detour") and
    optional_safe_string("bind_interface") and
    optional_safe_string("inet4_bind_address") and
    optional_safe_string("inet6_bind_address") and
    optional_bool("bind_address_no_port") and
    optional_safe_string("protect_path") and
    optional_routing_mark and
    optional_bool("reuse_addr") and
    optional_safe_string("netns") and
    optional_duration("connect_timeout") and
    optional_bool("tcp_fast_open") and
    optional_bool("tcp_multi_path") and
    optional_bool("disable_tcp_keep_alive") and
    optional_duration("tcp_keep_alive") and
    optional_duration("tcp_keep_alive_interval") and
    optional_bool("udp_fragment") and
    ((has("domain_resolver") | not) or
      (.domain_resolver | type == "string" or type == "object")) and
    optional_network_strategy and
    optional_network_types("network_type") and
    optional_network_types("fallback_network_type") and
    optional_duration("fallback_delay") and
    (
      ((.password? // "") | type == "string" and length > 0) or
      ((.private_key? // null) |
        if . == null then false else listable_nonempty_string end) or
      ((.private_key_path? // "") | nonempty_safe_string)
    ) and
    (
      ((.private_key_passphrase? // "") | type == "string" and length == 0) or
      ((.private_key? // null) |
        if . == null then false else listable_nonempty_string end) or
      ((.private_key_path? // "") | nonempty_safe_string)
    )
  ' <<< "${config}" >/dev/null 2>&1 || return 1
}

# Validate the Tor outbound contract against sing-box 1.14.0.  Tor has no
# server/authentication fields: the managed record controls the Tor runtime
# (external executable or embedded build), its torrc map, extra arguments and
# shared Dial Fields.  The embedded form is accepted for upstream
# compatibility, but inventory marks it unverified because the default
# sing-box build does not include embedded Tor.
managed_component_tor_config_validate_json() {
  local config=${1:-}
  [[ -n "${config}" ]] || return 1
  jq -e '
    def safe_string:
      type == "string" and (any(explode[]; . < 32 or . == 127) | not);
    def optional_safe_string($name):
      (has($name) | not) or (.[$name] | safe_string);
    def optional_bool($name):
      (has($name) | not) or (.[$name] | type == "boolean");
    def optional_duration($name):
      (has($name) | not) or (.[$name] | safe_string);
    def optional_routing_mark:
      (has("routing_mark") | not) or
      (.routing_mark |
        ((type == "number" and . == floor and . >= 0 and . <= 4294967295) or
         (type == "string" and (length == 0 or test("^0x[0-9a-fA-F]+$")))));
    def optional_network_strategy:
      (has("network_strategy") | not) or
      (.network_strategy | type == "string" and IN("","default","hybrid","fallback"));
    def optional_network_types($name):
      (has($name) | not) or
      (.[$name] |
        ((type == "string" and (length == 0 or IN("wifi","cellular","ethernet","other"))) or
         (type == "array" and all(.[]; type == "string" and
           IN("wifi","cellular","ethernet","other")))));
    def optional_extra_args:
      (has("extra_args") | not) or
      (.extra_args | type == "array" and all(.[]; safe_string));
    def optional_torrc:
      (has("torrc") | not) or
      (.torrc | type == "object" and
        all(to_entries[]; (.key | safe_string) and (.value | safe_string)));
    type == "object" and
    ((keys - [
      "executable_path","extra_args","data_directory","torrc",
      "detour","bind_interface","inet4_bind_address",
      "inet6_bind_address","bind_address_no_port","protect_path",
      "routing_mark","reuse_addr","netns","connect_timeout",
      "tcp_fast_open","tcp_multi_path","disable_tcp_keep_alive",
      "tcp_keep_alive","tcp_keep_alive_interval","udp_fragment",
      "domain_resolver","network_strategy","network_type",
      "fallback_network_type","fallback_delay"
    ]) | length == 0) and
    optional_safe_string("executable_path") and
    optional_extra_args and
    optional_safe_string("data_directory") and
    optional_torrc and
    optional_safe_string("detour") and
    optional_safe_string("bind_interface") and
    optional_safe_string("inet4_bind_address") and
    optional_safe_string("inet6_bind_address") and
    optional_bool("bind_address_no_port") and
    optional_safe_string("protect_path") and
    optional_routing_mark and
    optional_bool("reuse_addr") and
    optional_safe_string("netns") and
    optional_duration("connect_timeout") and
    optional_bool("tcp_fast_open") and
    optional_bool("tcp_multi_path") and
    optional_bool("disable_tcp_keep_alive") and
    optional_duration("tcp_keep_alive") and
    optional_duration("tcp_keep_alive_interval") and
    optional_bool("udp_fragment") and
    ((has("domain_resolver") | not) or
      (.domain_resolver | type == "string" or type == "object")) and
    optional_network_strategy and
    optional_network_types("network_type") and
    optional_network_types("fallback_network_type") and
    optional_duration("fallback_delay")
  ' <<< "${config}" >/dev/null 2>&1 || return 1
}

# Validate the SOCKS outbound contract against sing-box 1.14.0.  This is a
# managed client-side dialer, not a share-link inbound: keep the upstream
# server/auth/network/UoT fields and the shared Dial Fields, while rejecting
# deprecated domain_strategy and arbitrary JSON passthrough before CAS or
# takeover publication.
managed_component_socks_config_validate_json() {
  local config=${1:-}
  [[ -n "${config}" ]] || return 1
  jq -e '
    def safe_string:
      type == "string" and (any(explode[]; . < 32 or . == 127) | not);
    def nonempty_safe_string:
      safe_string and length > 0;
    def optional_safe_string($name):
      (has($name) | not) or (.[$name] | safe_string);
    def optional_bool($name):
      (has($name) | not) or (.[$name] | type == "boolean");
    def optional_duration($name):
      (has($name) | not) or (.[$name] | safe_string);
    def optional_routing_mark:
      (has("routing_mark") | not) or
      (.routing_mark |
        ((type == "number" and . == floor and . >= 0 and . <= 4294967295) or
         (type == "string" and (length == 0 or test("^0x[0-9a-fA-F]+$")))));
    def optional_network_strategy:
      (has("network_strategy") | not) or
      (.network_strategy | type == "string" and IN("","default","hybrid","fallback"));
    def optional_network_types($name):
      (has($name) | not) or
      (.[$name] |
        ((type == "string" and (length == 0 or IN("wifi","cellular","ethernet","other"))) or
         (type == "array" and all(.[]; type == "string" and
           IN("wifi","cellular","ethernet","other")))));
    def optional_network($name):
      (has($name) | not) or
      (.[$name] |
        ((type == "string" and (length == 0 or IN("tcp","udp"))) or
         (type == "array" and all(.[]; type == "string" and IN("tcp","udp")))));
    def optional_udp_over_tcp:
      (has("udp_over_tcp") | not) or
      (.udp_over_tcp |
        (type == "boolean" or
         (type == "object" and
          ((keys - ["enabled","version"]) | length == 0) and
          ((has("enabled") | not) or (.enabled | type == "boolean")) and
          ((has("version") | not) or
            (.version | type == "number" and . == floor and . >= 1 and . <= 2)))));
    type == "object" and
    ((keys - [
      "server","server_port","version","username","password","network",
      "udp_over_tcp","detour","bind_interface","inet4_bind_address",
