  ' <<< "${config}" >/dev/null 2>&1
}

# Component route rules are data owned by the component state store.  Do not
# pass arbitrary objects through to the top-level sing-box route list: an
# unknown field could otherwise survive state/CAS and only fail (or change
# meaning) after publication.  This is the project-facing subset of the
# sing-box 1.14 default/logical rule union and route actions.  Values that are
# intentionally opaque to the project (CIDR/domain expressions and duration
# strings) are still constrained to safe scalar/listable forms.
managed_component_route_rules_validate_json() {
  local rules=${1:-}
  [[ -n "${rules}" ]] || return 1
  jq -e '
    def max_list_items: 64;
    def safe_string:
      type == "string" and (any(explode[]; . < 32 or . == 127) | not);
    def nonempty_safe_string:
      safe_string and length > 0;
    def listable_string:
      ((type == "string" and safe_string) or
       (type == "array" and length > 0 and length <= max_list_items and all(.[]; safe_string) and
        (length == (unique | length))));
    def listable_nonempty_string:
      ((type == "string" and nonempty_safe_string) or
       (type == "array" and length > 0 and length <= max_list_items and all(.[]; nonempty_safe_string) and
        (length == (unique | length))));
    def listable_enum($values):
      ((type == "string" and IN($values[])) or
       (type == "array" and length > 0 and length <= max_list_items and all(.[]; type == "string" and IN($values[])) and
        (length == (unique | length))));
    def optional_string($name):
      (has($name) | not) or (.[$name] | safe_string);
    def optional_nonempty_string($name):
      (has($name) | not) or (.[$name] | nonempty_safe_string);
    def optional_listable_string($name):
      (has($name) | not) or (.[$name] | listable_string);
    def optional_listable_nonempty_string($name):
      (has($name) | not) or (.[$name] | listable_nonempty_string);
    def optional_bool($name):
      (has($name) | not) or (.[$name] | type == "boolean");
    def optional_uint($name; $max):
      (has($name) | not) or
      (.[$name] | type == "number" and . == floor and . >= 0 and . <= $max);
    def optional_int32($name):
      (has($name) | not) or
      (.[$name] | type == "number" and . == floor and
        . >= -2147483648 and . <= 2147483647);
    def optional_listable_int32($name):
      (has($name) | not) or
      (.[$name] |
        ((type == "number" and . == floor and . >= -2147483648 and . <= 2147483647) or
         (type == "array" and length > 0 and length <= max_list_items and all(.[]; type == "number" and . == floor and
           . >= -2147483648 and . <= 2147483647) and (length == (unique | length)))));
    def optional_listable_uint16($name):
      (has($name) | not) or
      (.[$name] |
        ((type == "number" and . == floor and . >= 0 and . <= 65535) or
         (type == "array" and length > 0 and length <= max_list_items and all(.[]; type == "number" and . == floor and
           . >= 0 and . <= 65535) and (length == (unique | length)))));
    def optional_uint32($name): optional_uint($name; 4294967295);
    def optional_duration($name):
      (has($name) | not) or (.[$name] | nonempty_safe_string);
    def optional_strategy($name):
      (has($name) | not) or
      (.[$name] | type == "string" and
        IN("","as_is","prefer_ipv4","prefer_ipv6","ipv4_only","ipv6_only"));
    def optional_route_network_strategy($name):
      (has($name) | not) or
      (.[$name] | type == "string" and IN("default","hybrid","fallback"));
    def optional_interface_address:
      (has("interface_address") | not) or
      (.interface_address | type == "object" and length <= max_list_items and
        all(to_entries[];
          (.key | nonempty_safe_string) and
          (.value | listable_nonempty_string)));
    def optional_network_interface_address:
      (has("network_interface_address") | not) or
      (.network_interface_address | type == "object" and length <= max_list_items and
        all(to_entries[];
          (.key | type == "string" and IN("wifi","cellular","ethernet","other")) and
          (.value | listable_nonempty_string)));
    def optional_default_interface_address:
      (has("default_interface_address") | not) or
      (.default_interface_address | listable_nonempty_string);
    def optional_match_fields:
      optional_listable_string("inbound") and
      optional_uint("ip_version"; 6) and
      ((has("ip_version") | not) or (.ip_version | IN(4,6))) and
      ((has("network") | not) or (.network | listable_enum(["tcp","udp","icmp"]))) and
      optional_listable_string("auth_user") and
      ((has("protocol") | not) or (.protocol | listable_enum(["tls","http","quic","dns","stun","bittorrent","dtls","ssh","rdp","ntp"]))) and
      optional_listable_string("client") and
      optional_listable_string("domain") and
      optional_listable_string("domain_suffix") and
      optional_listable_string("domain_keyword") and
      optional_listable_string("domain_regex") and
      optional_listable_string("geosite") and
      optional_listable_string("source_geoip") and
      optional_listable_string("geoip") and
      optional_listable_string("source_ip_cidr") and
      optional_bool("source_ip_is_private") and
      optional_listable_string("ip_cidr") and
      optional_bool("ip_is_private") and
      optional_listable_uint16("source_port") and
      optional_listable_string("source_port_range") and
      optional_listable_uint16("port") and
      optional_listable_string("port_range") and
      optional_listable_string("process_name") and
      optional_listable_string("process_path") and
      optional_listable_string("process_path_regex") and
      optional_listable_string("package_name") and
      optional_listable_string("package_name_regex") and
      optional_listable_string("user") and
      optional_listable_int32("user_id") and
      optional_string("clash_mode") and
      ((has("network_type") | not) or (.network_type | listable_enum(["wifi","cellular","ethernet","other"]))) and
      optional_bool("network_is_expensive") and
      optional_bool("network_is_constrained") and
      optional_listable_string("wifi_ssid") and
      optional_listable_string("wifi_bssid") and
      optional_interface_address and
      optional_network_interface_address and
      optional_default_interface_address and
      optional_listable_string("source_mac_address") and
      optional_listable_string("source_hostname") and
      optional_listable_string("preferred_by") and
      optional_listable_string("rule_set") and
      optional_bool("rule_set_ip_cidr_match_source") and
      optional_bool("invert");
    def optional_route_action_fields:
      optional_string("outbound") and
      optional_string("override_address") and
      optional_uint("override_port"; 65535) and
      optional_route_network_strategy("network_strategy") and
      optional_uint32("fallback_delay") and
      optional_bool("udp_disable_domain_unmapping") and
      optional_bool("udp_connect") and
      optional_duration("udp_timeout") and
      optional_bool("tls_fragment") and
      optional_duration("tls_fragment_fallback_delay") and
      optional_bool("tls_record_fragment") and
      optional_string("tls_spoof") and
      ((has("tls_spoof_method") | not) or (.tls_spoof_method | type == "string" and
        IN("wrong-sequence","wrong-checksum","wrong-ack","wrong-md5","wrong-timestamp")));
    def route_options_nonempty:
      ((.override_address // "") != "") or
      ((.override_port // 0) != 0) or
      ((.network_strategy // "") != "") or
      ((.fallback_delay // 0) != 0) or
      ((.udp_disable_domain_unmapping // false) == true) or
      ((.udp_connect // false) == true) or
      ((.udp_timeout // "") != "") or
      ((.tls_fragment // false) == true) or
      ((.tls_fragment_fallback_delay // "") != "") or
      ((.tls_record_fragment // false) == true) or
      ((.tls_spoof // "") != "") or
      ((.tls_spoof_method // "") != "");
    def route_rule($nested; $depth):
      if $depth > 8 then false
      elif type != "object" then false
      elif (($nested and ((keys - [
              "type","mode","rules","invert","inbound","ip_version","network","auth_user",
              "protocol","client","domain","domain_suffix","domain_keyword","domain_regex","geosite",
              "source_geoip","geoip","source_ip_cidr","source_ip_is_private","ip_cidr","ip_is_private",
              "source_port","source_port_range","port","port_range","process_name","process_path",
              "process_path_regex","package_name","package_name_regex","user","user_id","clash_mode",
              "network_type","network_is_expensive","network_is_constrained","wifi_ssid","wifi_bssid",
              "interface_address","network_interface_address","default_interface_address","source_mac_address",
              "source_hostname","preferred_by","rule_set","rule_set_ip_cidr_match_source","invert"
            ]) | length != 0)) or
            ($nested and (.type // "") != "logical" and (has("mode") or has("rules"))) or
            (keys | length > 128)) then false
      elif (($nested | not) and
            ((keys - [
              "type","mode","rules","inbound","ip_version","network","auth_user","protocol","client",
              "domain","domain_suffix","domain_keyword","domain_regex","geosite","source_geoip",
              "geoip","source_ip_cidr","source_ip_is_private","ip_cidr","ip_is_private",
              "source_port","source_port_range","port","port_range","process_name","process_path",
              "process_path_regex","package_name","package_name_regex","user","user_id","clash_mode",
              "network_type","network_is_expensive","network_is_constrained","wifi_ssid","wifi_bssid",
              "interface_address","network_interface_address","default_interface_address","source_mac_address",
              "source_hostname","preferred_by","rule_set","rule_set_ip_cidr_match_source","invert",
              "action","outbound","override_address","override_port","network_strategy","fallback_delay",
              "udp_disable_domain_unmapping","udp_connect","udp_timeout","tls_fragment",
              "tls_fragment_fallback_delay","tls_record_fragment","tls_spoof","tls_spoof_method",
              "method","no_drop","sniffer","timeout","server","strategy","disable_cache",
              "disable_optimistic_cache","rewrite_ttl","client_subnet","remove_client_subnet"
            ]) | length != 0)) then false
      elif (.type // "") == "logical" then
        ((keys - ["type","mode","rules","invert","action","outbound","override_address",
          "override_port","network_strategy","fallback_delay","udp_disable_domain_unmapping",
          "udp_connect","udp_timeout","tls_fragment","tls_fragment_fallback_delay",
          "tls_record_fragment","tls_spoof","tls_spoof_method","method","no_drop","sniffer",
          "timeout","server","strategy","disable_cache","disable_optimistic_cache","rewrite_ttl",
          "client_subnet","remove_client_subnet"]) | length == 0) and
        (.mode | type == "string" and IN("and","or")) and
        (.rules | type == "array" and length > 0 and length <= 64 and all(.[]; route_rule(true; ($depth + 1)))) and
        optional_bool("invert") and
        (if $nested then
           (has("action") | not)
         else
           (del(.type,.mode,.rules,.invert) | route_rule(false; $depth))
         end)
      elif ((.type // "") == "" or .type == "default") then
        (has("mode") | not) and (has("rules") | not) and
        optional_match_fields and
        ((has("action") | not) or (.action | type == "string" and
          IN("route","route-options","direct","bypass","reject","hijack-dns","sniff","resolve"))) and
        (if ((.action // "route") | IN("route","bypass")) then
           optional_route_action_fields and
           ((has("method") | not) and (has("no_drop") | not) and (has("sniffer") | not)) and
           ((has("timeout") | not) and (has("server") | not) and (has("strategy") | not) and
            (has("disable_cache") | not) and (has("disable_optimistic_cache") | not) and
            (has("rewrite_ttl") | not) and (has("client_subnet") | not) and (has("remove_client_subnet") | not))
         elif .action == "route-options" then
           (has("outbound") | not) and optional_route_action_fields and route_options_nonempty and
           ((.tls_fragment // false) != true or (.tls_record_fragment // false) != true) and
           ((has("method") | not) and (has("no_drop") | not) and (has("sniffer") | not)) and
           ((has("timeout") | not) and (has("server") | not) and (has("strategy") | not) and
            (has("disable_cache") | not) and (has("disable_optimistic_cache") | not) and
            (has("rewrite_ttl") | not) and (has("client_subnet") | not) and (has("remove_client_subnet") | not))
         elif .action == "reject" then
           ((has("method") | not) or (.method | type == "string" and IN("","default","drop","reply"))) and
           optional_bool("no_drop") and
           ((.method // "") != "drop" or (.no_drop // false) != true) and
           ((keys - ["type","inbound","ip_version","network","auth_user","protocol","client",
             "domain","domain_suffix","domain_keyword","domain_regex","geosite","source_geoip",
             "geoip","source_ip_cidr","source_ip_is_private","ip_cidr","ip_is_private","source_port",
             "source_port_range","port","port_range","process_name","process_path","process_path_regex",
             "package_name","package_name_regex","user","user_id","clash_mode","network_type",
             "network_is_expensive","network_is_constrained","wifi_ssid","wifi_bssid","interface_address",
             "network_interface_address","default_interface_address","source_mac_address","source_hostname",
             "preferred_by","rule_set","rule_set_ip_cidr_match_source","invert","action","method","no_drop"])
             | length == 0)
         elif .action == "hijack-dns" then
           ((keys - ["type","inbound","ip_version","network","auth_user","protocol","client",
             "domain","domain_suffix","domain_keyword","domain_regex","geosite","source_geoip",
             "geoip","source_ip_cidr","source_ip_is_private","ip_cidr","ip_is_private","source_port",
             "source_port_range","port","port_range","process_name","process_path","process_path_regex",
             "package_name","package_name_regex","user","user_id","clash_mode","network_type",
             "network_is_expensive","network_is_constrained","wifi_ssid","wifi_bssid","interface_address",
             "network_interface_address","default_interface_address","source_mac_address","source_hostname",
             "preferred_by","rule_set","rule_set_ip_cidr_match_source","invert","action"])
             | length == 0)
         elif .action == "sniff" then
           ((has("sniffer") | not) or (.sniffer | listable_enum(["tls","http","quic","dns","stun","bittorrent","dtls","ssh","rdp","ntp"]))) and
           optional_duration("timeout") and
           ((keys - ["type","inbound","ip_version","network","auth_user","protocol","client",
             "domain","domain_suffix","domain_keyword","domain_regex","geosite","source_geoip",
             "geoip","source_ip_cidr","source_ip_is_private","ip_cidr","ip_is_private","source_port",
             "source_port_range","port","port_range","process_name","process_path","process_path_regex",
             "package_name","package_name_regex","user","user_id","clash_mode","network_type",
             "network_is_expensive","network_is_constrained","wifi_ssid","wifi_bssid","interface_address",
             "network_interface_address","default_interface_address","source_mac_address","source_hostname",
             "preferred_by","rule_set","rule_set_ip_cidr_match_source","invert","action","sniffer","timeout"])
             | length == 0)
         elif .action == "resolve" then
           optional_string("server") and optional_duration("timeout") and optional_strategy("strategy") and
           optional_bool("disable_cache") and optional_bool("disable_optimistic_cache") and
           optional_uint32("rewrite_ttl") and optional_string("client_subnet") and
           ((keys - ["type","inbound","ip_version","network","auth_user","protocol","client",
             "domain","domain_suffix","domain_keyword","domain_regex","geosite","source_geoip",
             "geoip","source_ip_cidr","source_ip_is_private","ip_cidr","ip_is_private","source_port",
             "source_port_range","port","port_range","process_name","process_path","process_path_regex",
             "package_name","package_name_regex","user","user_id","clash_mode","network_type",
             "network_is_expensive","network_is_constrained","wifi_ssid","wifi_bssid","interface_address",
             "network_interface_address","default_interface_address","source_mac_address","source_hostname",
             "preferred_by","rule_set","rule_set_ip_cidr_match_source","invert","action","server","timeout",
             "strategy","disable_cache","disable_optimistic_cache","rewrite_ttl","client_subnet"])
             | length == 0)
         elif .action == "direct" then
           ((keys - ["type","inbound","ip_version","network","auth_user","protocol","client",
             "domain","domain_suffix","domain_keyword","domain_regex","geosite","source_geoip",
             "geoip","source_ip_cidr","source_ip_is_private","ip_cidr","ip_is_private","source_port",
             "source_port_range","port","port_range","process_name","process_path","process_path_regex",
             "package_name","package_name_regex","user","user_id","clash_mode","network_type",
             "network_is_expensive","network_is_constrained","wifi_ssid","wifi_bssid","interface_address",
             "network_interface_address","default_interface_address","source_mac_address","source_hostname",
             "preferred_by","rule_set","rule_set_ip_cidr_match_source","invert","action"])
             | length == 0)
         else false end)
      else false end;
    type == "array" and length <= 128 and all(.[]; route_rule(false; 0))
  ' <<< "${rules}" >/dev/null 2>&1 || return 1
}

managed_component_state_validate_record() {
  local record=${1:-} role type tag registry_id config route_rules
  [[ -n "${record}" ]] || return 1
  jq -s -e '
    if length != 1 then false
    else .[0] |
      type == "object" and
      ((keys - ["id","role","type","tag","enabled","route_rules","config"]) | length == 0) and
      (.id | type == "string") and (.role | type == "string") and
      (.type | type == "string") and (.tag | type == "string")
    end
  ' <<< "${record}" >/dev/null 2>&1 || return 1
  role=$(jq -r '.role // empty' <<< "${record}") || return 1
  type=$(jq -r '.type // empty' <<< "${record}") || return 1
  tag=$(jq -r '.tag // empty' <<< "${record}") || return 1
  registry_id=$(component_registry_resolve_id "${role}" "${type}") || return 1
  managed_component_state_id_valid "$(jq -r '.id // empty' <<< "${record}")" || return 1
  managed_component_tag_valid "${tag}" || return 1
  jq -e '.role | IN("inbound","endpoint","outbound")' <<< "${record}" >/dev/null 2>&1 || return 1
  jq -e '.enabled | type == "boolean"' <<< "${record}" >/dev/null 2>&1 || return 1
  jq -e '.config | type == "object" and (has("type") | not) and (has("tag") | not)' \
    <<< "${record}" >/dev/null 2>&1 || return 1
  route_rules=$(jq -c '.route_rules // []' <<< "${record}") || return 1
  managed_component_route_rules_validate_json "${route_rules}" || return 1
  config=$(jq -c '.config' <<< "${record}") || return 1

  # Reject the two built-in outbound owners.  Custom direct/block records are
  # supported, while replacing the safety defaults requires a future explicit
  # migration rather than creating duplicate tags in the generated graph.
  if [[ "${role}" == outbound && ("${tag}" == direct || "${tag}" == block) ]]; then
    return 1
  fi

  case "${role}:${type}" in
    inbound:direct)
      managed_component_direct_config_validate_json "${config}" || return 1
      ;;
    inbound:redirect)
      managed_component_redirect_config_validate_json "${config}" || return 1
      ;;
    inbound:tproxy)
      managed_component_tproxy_config_validate_json "${config}" || return 1
      ;;
    inbound:tun)
      managed_component_tun_config_validate_json "${config}" || return 1
      ;;
    inbound:cloudflared)
      managed_component_cloudflared_config_validate_json "${config}" || return 1
      ;;
    endpoint:wireguard)
      managed_component_wireguard_config_validate_json "${config}" || return 1
      ;;
    endpoint:tailscale)
      managed_component_tailscale_config_validate_json "${config}" || return 1
      ;;
    endpoint:openconnect)
      managed_component_openconnect_config_validate_json "${config}" || return 1
      ;;
    endpoint:openvpn-client)
      managed_component_openvpn_client_config_validate_json "${config}" || return 1
      ;;
    endpoint:openvpn-server)
      managed_component_openvpn_server_config_validate_json "${config}" || return 1
      ;;
    outbound:selector|outbound:urltest)
      managed_component_group_config_validate_json "${type}" "${config}" || return 1
      ;;
    outbound:ssh)
      managed_component_ssh_config_validate_json "${config}" || return 1
      ;;
    outbound:tor)
      managed_component_tor_config_validate_json "${config}" || return 1
      ;;
    outbound:socks)
      managed_component_socks_config_validate_json "${config}" || return 1
      ;;
    outbound:http)
      managed_component_http_config_validate_json "${config}" || return 1
      ;;
    outbound:shadowsocks)
      managed_component_shadowsocks_config_validate_json "${config}" || return 1
      ;;
    outbound:anytls)
      managed_component_anytls_config_validate_json "${config}" || return 1
      ;;
    outbound:snell)
      managed_component_snell_config_validate_json "${config}" || return 1
      ;;
    outbound:hysteria2)
      managed_component_hysteria2_config_validate_json "${config}" || return 1
      ;;
    outbound:hysteria)
      managed_component_hysteria_config_validate_json "${config}" || return 1
      ;;
    outbound:tuic)
      managed_component_tuic_config_validate_json "${config}" || return 1
      ;;
    outbound:naive)
      managed_component_naive_config_validate_json "${config}" || return 1
      ;;
    outbound:shadowtls)
      managed_component_shadowtls_config_validate_json "${config}" || return 1
      ;;
    outbound:vless|outbound:vmess|outbound:trojan)
      managed_component_v2ray_outbound_config_validate_json "${type}" "${config}" || return 1
      ;;
    outbound:direct)
      managed_component_direct_outbound_config_validate_json "${config}" || return 1
      ;;
    outbound:block)
      managed_component_block_outbound_config_validate_json "${config}" || return 1
      ;;
    outbound:bridge)
      managed_component_bridge_outbound_config_validate_json "${config}" || return 1
      ;;
    *) return 1 ;;
  esac
  [[ -n "${registry_id}" ]]
}

managed_component_state_validate_json() {
  local state=${1:-} record
  [[ -n "${state}" ]] || return 1
  jq -s -e --argjson schema "${SB_COMPONENT_STATE_SCHEMA_VERSION}" '
    if length != 1 then false
    else .[0] |
      type == "object" and
      ((keys - ["schema_version","revision","components"]) | length == 0) and
      .schema_version == $schema and
      (.revision | type == "number" and . == floor and . >= 0 and . <= 9007199254740991) and
      (.components | type == "array" and length <= 128) and
      (([.components[]?.id] | unique | length) == (.components | length)) and
      (([.components[]?.tag] | unique | length) == (.components | length)) and
      all(.components[]; type == "object" and
        (.id | type == "string") and (.role | type == "string") and
        (.type | type == "string") and (.tag | type == "string") and
        (.enabled | type == "boolean") and (.config | type == "object") and
        ((.route_rules // []) | type == "array"))
    end
  ' <<< "${state}" >/dev/null 2>&1 || return 1
  while IFS= read -r record; do
    [[ -n "${record}" ]] || continue
    managed_component_state_validate_record "${record}" || return 1
  done < <(jq -c '.components[]' <<< "${state}")
}

managed_component_state_json() (
  local snapshot result
  if [[ ! -e "${SB_COMPONENT_STATE_FILE}" ]]; then
    managed_component_state_default_json
    return 0
  fi
  [[ -f "${SB_COMPONENT_STATE_FILE}" && ! -L "${SB_COMPONENT_STATE_FILE}" && -r "${SB_COMPONENT_STATE_FILE}" ]] || return 1
  snapshot=$(mktemp /tmp/sbv-components.XXXXXX) || return 1
  trap 'rm -f -- "${snapshot}"' EXIT
  head -c 4194305 -- "${SB_COMPONENT_STATE_FILE}" > "${snapshot}" || return 1
  [[ "$(wc -c < "${snapshot}")" -le 4194304 ]] || return 1
  result=$(jq -cS '.' "${snapshot}") || return 1
  managed_component_state_validate_json "${result}" || return 1
  printf '%s\n' "${result}"
)

managed_component_normalize_input_file() (
  local input=${1:-} snapshot result
  [[ -f "${input}" && ! -L "${input}" && -r "${input}" ]] || return 1
  snapshot=$(mktemp /tmp/sbv-component-record.XXXXXX) || return 1
  trap 'rm -f -- "${snapshot}"' EXIT
  head -c 1048577 -- "${input}" > "${snapshot}" || return 1
  [[ "$(wc -c < "${snapshot}")" -le 1048576 ]] || return 1
  result=$(jq -cS '
    if type != "object" then error("record") else . as $r |
      if ($r | has("config")) and
         ((($r | keys) - ["id","role","type","tag","enabled","route_rules","config"]) | length > 0)
      then error("unknown_record_field") else
      {
        id: $r.id,
        role: $r.role,
        type: $r.type,
        tag: $r.tag,
        enabled: ($r.enabled // true),
        route_rules: ($r.route_rules // []),
        config: (if ($r | has("config")) then $r.config
                 else $r | del(.id,.role,.type,.tag,.enabled,.route_rules) end)
      }
      end
    end' "${snapshot}") || return 1
  managed_component_state_validate_record "${result}" || return 1
  printf '%s\n' "${result}"
)

managed_component_render_json() {
  local state=${1:-}
  [[ -n "${state}" ]] || state=$(managed_component_state_json) || return 1
  managed_component_state_validate_json "${state}" || return 1
  jq -c '
    def enabled: select(.enabled == true);
    .components as $components |
    {
      inbounds: [$components[] | enabled | select(.role == "inbound") |
        .config + {type:.type, tag:.tag}],
      endpoints: [$components[] | enabled | select(.role == "endpoint") |
        .config + {type:.type, tag:.tag}],
      outbounds: [$components[] | enabled | select(.role == "outbound") |
        .config + {type:.type, tag:.tag}],
      route_rules: [$components[] | enabled | (.route_rules // [])[]]
    }' <<< "${state}"
}

# An auto-routed TUN must have an explicit host-route loop guard.  The
# generator can safely add auto_detect_interface when the existing route does
# not choose another interface, but it must not silently override an operator's
# explicit unsafe setting.  This is a config-level guard only; it does not
# claim to manage the host's complete policy-routing or firewall state.
managed_component_tun_route_options_json() {
  local components=${1:-} route='{}'
  [[ -n "${components}" ]] || return 1
  jq -e 'type == "object" and (.inbounds | type == "array")' <<< "${components}" >/dev/null 2>&1 || return 1
  if ! jq -e 'any(.inbounds[]?; .type == "tun" and .auto_route == true)' <<< "${components}" >/dev/null 2>&1; then
    printf '{}\n'
    return 0
  fi
  if [[ -e "${SINGBOX_CONFIG_FILE}" ]]; then
    [[ -f "${SINGBOX_CONFIG_FILE}" && ! -L "${SINGBOX_CONFIG_FILE}" && -r "${SINGBOX_CONFIG_FILE}" ]] || return 1
    route=$(jq -c 'if has("route") then .route else {} end' "${SINGBOX_CONFIG_FILE}") || return 1
    jq -e 'type == "object" and
      ((has("auto_detect_interface") | not) or (.auto_detect_interface | type == "boolean")) and
      ((has("default_interface") | not) or (.default_interface | type == "string"))' \
      <<< "${route}" >/dev/null 2>&1 || return 1
    if jq -e '.auto_detect_interface == false and
      ((.default_interface // "") == "")' <<< "${route}" >/dev/null 2>&1; then
      printf '[ERROR] component_route: tun_auto_route_loop_guard_conflict; 请启用 route.auto_detect_interface 或设置 route.default_interface。\n' >&2
      return 1
    fi
    if jq -e 'has("auto_detect_interface") or
      (has("default_interface") and ((.default_interface // "") | length > 0))' \
      <<< "${route}" >/dev/null 2>&1; then
      jq -c 'with_entries(select(.key == "auto_detect_interface" or
        (.key == "default_interface" and ((.value // "") | length > 0))))' <<< "${route}"
      return 0
    fi
  fi
  printf '%s\n' '{"auto_detect_interface":true}'
}

# Inspect resources which are created by a running transparent inbound.  The
# sing-box process owns TUN interfaces, iproute2 rules/routes and auto-redirect
# nftables state; the installer must not try to infer ownership from arbitrary
# host rules or delete an operator's policy.  Redirect/TProxy listeners still
# need an operator-owned PREROUTING policy, so those resources are explicitly
# reported as not assessed rather than being mistaken for a complete data
# plane.  This function is read-only and bounded: it is used by diagnose and
# never mutates the network namespace.
managed_component_transparent_resources_json() (
  local config_file=${1:-${SINGBOX_CONFIG_FILE:-}} service_state=${2:-unknown}
  local snapshot records='[]' resources='[]' status=not_assessed reason=service_inactive
  local tun_count=0 bridge_count=0 system_endpoint_count=0 record tag type interface_name auto_route auto_redirect
  local table_index rule_index link_status route_status rule_status nft_status
  local bridge_name bound_interface bridge_interface_name bridge_port bridge_index
  local bridge_table bridge_rule bridge_octet bridge_configured_table bridge_configured_rule
  local system_interface_name system_addresses system_mtu system_address_count system_reason_prefix
  local expected_address expected_addr expected_prefix actual_mtu
  local interface_status address_status mtu_status
  local link_file address_file rule_file route_file nft_file output_size
  [[ -f "${config_file}" && ! -L "${config_file}" && -r "${config_file}" ]] || return 1
  snapshot=$(mktemp -d /tmp/sbv-transparent-resources.XXXXXX) || return 1
  trap 'rm -rf -- "${snapshot}"' EXIT INT TERM HUP
  head -c 4194305 -- "${config_file}" > "${snapshot}/config.json" || return 1
  [[ "$(wc -c < "${snapshot}/config.json")" -le 4194304 ]] || return 1
  records=$(jq -c '
    [
      (.inbounds[]? | select(.type == "tun" or .type == "redirect" or .type == "tproxy") |
        {tag:(.tag // ""),type:.type,interface_name:(.interface_name // "tun0"),
         auto_route:(.auto_route // false),auto_redirect:(.auto_redirect // false),
         table_index:(.iproute2_table_index // null),rule_index:(.iproute2_rule_index // null),
         bridge_name:(.bridge_name // "bridge"),bound_interface:(.interface // ""),
         listen:(.listen // ""),listen_port:(.listen_port // 0),system_interface:false,
         addresses:[],mtu:null}),
      (.outbounds[]? | select(.type == "bridge") |
        {tag:(.tag // ""),type:.type,interface_name:(.interface_name // "tun0"),
         auto_route:(.auto_route // false),auto_redirect:(.auto_redirect // false),
         table_index:(.iproute2_table_index // null),rule_index:(.iproute2_rule_index // null),
         bridge_name:(.bridge_name // "bridge"),bound_interface:(.interface // ""),
         listen:(.listen // ""),listen_port:(.listen_port // 0),system_interface:false,
         addresses:[],mtu:null}),
      (.endpoints[]? |
        select((.type == "openvpn-client" or .type == "openvpn-server") and .system == true) |
        {tag:(.tag // ""),type:.type,interface_name:(.name // ""),
         auto_route:false,auto_redirect:false,table_index:null,rule_index:null,
         bridge_name:"",bound_interface:"",listen:(.listen // ""),listen_port:(.listen_port // 0),
         system_interface:true,
         addresses:(if ((.address? // null) | type) == "array" then
                      [.address[] | select(type == "string" and length > 0)]
                    elif ((.address? // null) | type) == "string" and (.address | length > 0) then
                      [.address]
                    else [] end),
         mtu:(if ((.mtu? // null) | type) == "number" and (.mtu // 0) > 0 then .mtu else 1500 end)})
      ,(.endpoints[]? |
        select(
          ((.type == "wireguard" or .type == "openconnect") and .system == true) or
          (.type == "tailscale" and .system_interface == true)
        ) |
        {tag:(.tag // ""),type:.type,
         interface_name:(if .type == "tailscale" then (.system_interface_name // "") else (.name // "") end),
         auto_route:false,auto_redirect:false,table_index:null,rule_index:null,
         bridge_name:"",bound_interface:"",listen:(.listen // ""),listen_port:(.listen_port // 0),
         system_interface:true,
         addresses:(if ((.address? // null) | type) == "array" then
                      [.address[] | select(type == "string" and length > 0)]
                    elif ((.address? // null) | type) == "string" and (.address | length > 0) then
                      [.address]
                    else [] end),
         mtu:(if .type == "wireguard" then
                (if ((.mtu? // null) | type) == "number" and (.mtu // 0) > 0 then .mtu else 1408 end)
              elif .type == "tailscale" then
                (if ((.system_interface_mtu? // null) | type) == "number" and (.system_interface_mtu // 0) > 0 then .system_interface_mtu else 0 end)
              else
                (if ((.mtu? // null) | type) == "number" and (.mtu // 0) > 0 then .mtu else 0 end)
              end)})
    ]
  ' "${snapshot}/config.json") || return 1
  tun_count=$(jq -r '[.[] | select(.type == "tun")] | length' <<< "${records}") || return 1
  bridge_count=$(jq -r '[.[] | select(.type == "bridge")] | length' <<< "${records}") || return 1
  system_endpoint_count=$(jq -r '[.[] | select(.system_interface == true)] | length' <<< "${records}") || return 1
  if [[ "${service_state}" != active ]]; then
    jq -cn --arg status "${status}" --arg reason "${reason}" --argjson resources "${records}" \
      '{status:$status,reason:$reason,service_active:false,resources:($resources | map({tag,type,listen,listen_port,interface_name:(if .system_interface then .interface_name else null end),resource_scope:(if .type == "tun" or .type == "bridge" or .system_interface then "core_owned" else "operator_policy_required" end),status:"not_assessed",reason:"service_inactive"})),limitations:["redirect/tproxy host policy rules are not installer-owned","TUN/bridge/system endpoint interfaces are core-owned resources and require a running core"]}'
    return 0
  fi
  if (( tun_count == 0 && bridge_count == 0 && system_endpoint_count == 0 )) && ! jq -e 'any(.[]; .type == "redirect" or .type == "tproxy")' <<< "${records}" >/dev/null 2>&1; then
    jq -cn '{status:"available",reason:null,service_active:true,resources:[],limitations:[]}'
    return 0
  fi
  if (( tun_count == 0 && bridge_count == 0 && system_endpoint_count == 0 )); then
    jq -cn --argjson resources "${records}" \
      '{status:"not_assessed",reason:"host_policy_rules_not_managed",service_active:true,
        resources:($resources | map({tag,type,listen,listen_port,
          resource_scope:"operator_policy_required",status:"not_assessed",
          reason:"host_policy_rules_not_managed"})),
        limitations:["redirect/tproxy host policy rules are not installer-owned"]}'
    return 0
  fi
  status=available
  reason=''
  link_file="${snapshot}/link.json"
  if ! command -v ip >/dev/null 2>&1; then
    status=unavailable
    reason=iproute2_missing
  elif (( tun_count > 0 || bridge_count > 0 )); then
    rule_file="${snapshot}/rule.json"
    route_file="${snapshot}/route.json"
    if ! ip -j rule show > "${rule_file}" 2>"${snapshot}/rule.stderr"; then
      status=unavailable
      reason=iproute2_rule_probe_failed
    elif [[ "$(wc -c < "${rule_file}")" -gt 1048576 ]]; then
      status=unavailable
      reason=iproute2_rule_probe_oversized
    elif ! jq -e 'type == "array"' "${rule_file}" >/dev/null 2>&1; then
      status=unavailable
      reason=iproute2_rule_probe_invalid
    elif ! ip -j route show table all > "${route_file}" 2>"${snapshot}/route.stderr"; then
      status=unavailable
      reason=iproute2_route_probe_failed
    elif [[ "$(wc -c < "${route_file}")" -gt 1048576 ]]; then
      status=unavailable
      reason=iproute2_route_probe_oversized
    elif ! jq -e 'type == "array"' "${route_file}" >/dev/null 2>&1; then
      status=unavailable
      reason=iproute2_route_probe_invalid
    fi
  fi
  if (( tun_count > 0 || bridge_count > 0 )) && [[ "${status}" == available ]]; then
    if command -v nft >/dev/null 2>&1; then
      nft_file="${snapshot}/nft.json"
      if nft -j list ruleset > "${nft_file}" 2>"${snapshot}/nft.stderr"; then
        output_size=$(wc -c < "${nft_file}") || output_size=0
        if (( output_size > 2097152 )); then
          nft_status=oversized
        elif jq -e 'type == "object"' "${nft_file}" >/dev/null 2>&1; then
          nft_status=observed
        else
          nft_status=invalid
        fi
      else
        nft_status=probe_failed
      fi
    else
      nft_status=missing
    fi
  else
    nft_status=not_required
  fi
  while IFS= read -r record; do
    [[ -n "${record}" ]] || continue
    tag=$(jq -r '.tag' <<< "${record}") || return 1
    type=$(jq -r '.type' <<< "${record}") || return 1
    if jq -e '.system_interface == true' <<< "${record}" >/dev/null 2>&1; then
      system_interface_name=$(jq -r '.interface_name // ""' <<< "${record}") || return 1
      system_addresses=$(jq -c '.addresses // []' <<< "${record}") || return 1
      system_mtu=$(jq -r '.mtu // 1500' <<< "${record}") || return 1
      case "${type}" in
        wireguard) system_reason_prefix=wireguard_system ;;
        tailscale) system_reason_prefix=tailscale_system ;;
        openconnect) system_reason_prefix=openconnect_system ;;
        openvpn-client|openvpn-server) system_reason_prefix=openvpn_system ;;
        *) system_reason_prefix=system_endpoint ;;
      esac
      address_file="${snapshot}/addr.json"
      interface_status=not_assessed
      address_status=not_assessed
      mtu_status=not_assessed
      if [[ "${system_mtu}" == 0 ]]; then
        mtu_status=not_required
      fi
      if [[ -z "${system_interface_name}" ]]; then
        if [[ "${status}" == available ]]; then
          status=not_assessed
          reason=${system_reason_prefix}_interface_name_unset
        fi
      elif [[ ! "${system_interface_name}" =~ ^[A-Za-z0-9_.-]{1,15}$ ]]; then
        if [[ "${status}" == available ]]; then
          status=not_assessed
          reason=${system_reason_prefix}_interface_name_invalid
        fi
      elif [[ "${status}" == unavailable ]]; then
        interface_status=not_probed
        address_status=not_probed
        mtu_status=not_probed
      else
        interface_status=missing
        if [[ "${system_mtu}" != 0 ]]; then
          mtu_status=missing
        fi
        if ip -j link show dev "${system_interface_name}" > "${link_file}" 2>"${snapshot}/link.stderr"; then
          if [[ "$(wc -c < "${link_file}")" -le 1048576 ]] &&
             jq -e 'type == "array"' "${link_file}" >/dev/null 2>&1 &&
             jq -e --arg name "${system_interface_name}" 'any(.[]; .ifname == $name)' "${link_file}" >/dev/null 2>&1; then
            interface_status=present
            actual_mtu=$(jq -r --arg name "${system_interface_name}" \
              '[.[] | select(.ifname == $name) | .mtu][0] // empty' "${link_file}") || return 1
            if [[ -n "${actual_mtu}" && "${actual_mtu}" == "${system_mtu}" ]]; then
              mtu_status=present
            fi
          fi
        fi
        system_address_count=$(jq -r 'length' <<< "${system_addresses}") || return 1
        if (( system_address_count == 0 )); then
          address_status=not_required
        elif [[ "${interface_status}" == present ]]; then
          address_status=present
          if ! ip -j addr show dev "${system_interface_name}" > "${address_file}" 2>"${snapshot}/addr.stderr" ||
             [[ ! -f "${address_file}" ]] ||
             [[ "$(wc -c < "${address_file}")" -gt 1048576 ]] ||
             ! jq -e 'type == "array"' "${address_file}" >/dev/null 2>&1; then
            address_status=missing
          else
            while IFS= read -r expected_address; do
              [[ -n "${expected_address}" ]] || continue
              if [[ "${expected_address}" != */* ]]; then
                address_status=missing
                break
              fi
              expected_addr=${expected_address%/*}
              expected_prefix=${expected_address##*/}
              if ! jq -e --arg addr "${expected_addr}" --arg prefix "${expected_prefix}" \
                'any(.[]?.addr_info[]?; (.local // "") == $addr and (((.prefixlen // "") | tostring) == $prefix))' \
                "${address_file}" >/dev/null 2>&1; then
                address_status=missing
                break
              fi
            done < <(jq -r '.[]' <<< "${system_addresses}")
          fi
        else
          address_status=not_probed
        fi
      fi
      record=$(jq -c --argjson item "${record}" --arg link "${interface_status}" \
        --arg addresses "${address_status}" --arg mtu "${mtu_status}" \
        '{tag:$item.tag,type:$item.type,interface_name:$item.interface_name,system_interface:true,
          expected_addresses:$item.addresses,expected_mtu:$item.mtu,resource_scope:"core_owned",
          interface:{status:$link},interface_addresses:{status:$addresses},mtu:{status:$mtu}}' \
        <<< "${record}") || return 1
      if [[ "${status}" != unavailable && -n "${system_interface_name}" &&
            "${system_interface_name}" =~ ^[A-Za-z0-9_.-]{1,15}$ &&
            ( "${interface_status}" != present ||
              ( "${mtu_status}" != present && "${mtu_status}" != not_required ) ||
              ( "${address_status}" != present && "${address_status}" != not_required ) ) ]]; then
        status=unavailable
        reason=${system_reason_prefix}_runtime_resources_missing
      fi
      resources=$(jq -c --argjson item "${record}" '. + [$item]' <<< "${resources}") || return 1
      continue
    fi
    if [[ "${type}" == bridge ]]; then
      bridge_name=$(jq -r '.bridge_name // "bridge"' <<< "${record}") || return 1
      [[ "${bridge_name}" =~ ^[A-Za-z0-9_.-]{1,15}$ ]] || return 1
      bound_interface=$(jq -r '.bound_interface // ""' <<< "${record}") || return 1
      bridge_interface_name=''
      bridge_port=''
      if [[ "${status}" == available ]]; then
        bridge_interface_name=$(jq -r --arg base "${bridge_name}" '
          [.[] | (.dev // "") | tostring |
            select(. == $base or (startswith($base) and
              (.[($base | length):] | test("^[0-9]+$"))))] |
          unique | if length == 1 then .[0] else "" end
        ' "${route_file}") || return 1
        bridge_port=$(jq -r --arg interface "${bridge_interface_name}" '
          [.[] | select((.dev // "") == $interface and
            ((.dst // "") | test("^192\\.0\\.2\\.[0-9]{1,3}$")) and
            (((.table // "main") | tostring) == "main")) | .dst] |
          unique | if length == 1 then .[0] else "" end
        ' "${route_file}") || return 1
      fi
      bridge_index=-1
      if [[ "${bridge_port}" =~ ^192\.0\.2\.([0-9]+)$ ]]; then
        bridge_octet=$((10#${BASH_REMATCH[1]}))
        if (( bridge_octet >= 1 && bridge_octet <= 254 )); then
          bridge_index=$((bridge_octet - 1))
        fi
      fi
      bridge_configured_table=$(jq -r 'if ((.table_index | type) == "number") then .table_index | tostring else "0" end' <<< "${record}") || return 1
      bridge_configured_rule=$(jq -r 'if ((.rule_index | type) == "number") then .rule_index | tostring else "0" end' <<< "${record}") || return 1
      [[ "${bridge_configured_table}" =~ ^[0-9]+$ && "${bridge_configured_rule}" =~ ^[0-9]+$ ]] || return 1
      (( bridge_configured_table <= 2147483647 && bridge_configured_rule <= 2147483647 )) || return 1
      bridge_table=0
      if [[ -n "${bound_interface}" ]]; then
        if (( bridge_configured_table > 0 )); then
          bridge_table=${bridge_configured_table}
        elif (( bridge_index >= 0 )); then
          bridge_table=$((2200 + bridge_index))
        else
          bridge_table=-1
        fi
      fi
      if (( bridge_configured_rule > 0 )); then
        bridge_rule=${bridge_configured_rule}
      else
        bridge_rule=100
      fi
      link_status=missing
      if [[ "${status}" == available && "${bridge_interface_name}" =~ ^[A-Za-z0-9_.-]{1,15}$ ]] &&
         ip -j link show dev "${bridge_interface_name}" > "${link_file}" 2>"${snapshot}/link.stderr"; then
        if [[ "$(wc -c < "${link_file}")" -le 1048576 ]] && jq -e 'type == "array"' "${link_file}" >/dev/null 2>&1 &&
           jq -e --arg name "${bridge_interface_name}" 'any(.[]; .ifname == $name)' "${link_file}" >/dev/null 2>&1; then
          link_status=present
        fi
      elif [[ "${status}" != available ]]; then
        link_status=not_probed
      fi
      route_status=missing
      rule_status=missing
      if [[ "${status}" != available ]]; then
        route_status=not_probed
        rule_status=not_probed
      elif [[ "${bridge_interface_name}" =~ ^[A-Za-z0-9_.-]{1,15}$ &&
            "${bridge_port}" =~ ^192\.0\.2\.[0-9]{1,3}$ && "${bridge_table}" != -1 ]]; then
        if jq -e --arg dst "${bridge_port}" --arg interface "${bridge_interface_name}" \
          'any(.[]; (.dst // "") == $dst and (.dev // "") == $interface and
            (((.table // "main") | tostring) == "main"))' "${route_file}" >/dev/null 2>&1; then
          route_status=present
        fi
        if jq -e --argjson priority "${bridge_rule}" --arg interface "${bridge_interface_name}" \
          --arg table "$(if (( bridge_table == 0 )); then printf main; else printf '%s' "${bridge_table}"; fi)" \
          --argjson to_priority "$((bridge_rule + 1))" --arg dst "${bridge_port}" \
          'any(.[]; (.priority == $priority) and (.iif // "") == $interface and
            (((.table // "main") | tostring) == $table)) and
           any(.[]; (.priority == $to_priority) and (.dst // "") == $dst and
            (((.table // "main") | tostring) == "main"))' "${rule_file}" >/dev/null 2>&1; then
          rule_status=present
        fi
        if (( bridge_table > 0 )) && ! jq -e --arg table "${bridge_table}" --arg interface "${bound_interface}" \
          'any(.[]; (((.table // "main") | tostring) == $table) and
            (((.dst // "") == "default" and (.dev // "") == $interface) or
             ((.type // "") == "blackhole" and (.dst // "") == "default")))' \
          "${route_file}" >/dev/null 2>&1; then
          route_status=missing
        fi
      fi
      record=$(jq -c --argjson item "${record}" --arg scope core_owned --arg iface "${bridge_interface_name}" \
        --arg port "${bridge_port}" --arg table "${bridge_table}" --arg rule "${bridge_rule}" \
        --arg link "${link_status}" --arg route "${route_status}" --arg rule_status "${rule_status}" \
        --arg nft "${nft_status}" \
        '{tag:$item.tag,type:$item.type,bridge_name:$item.bridge_name,bound_interface:$item.bound_interface,
          interface_name:$iface,bridge_port:$port,route_table:($table|tonumber),rule_priority:($rule|tonumber),
          resource_scope:$scope,interface:{status:$link},policy_routing:{status:$route},rule:{status:$rule_status},
          bridge_netfilter:{status:(if $nft == "observed" then "observed" else "not_assessed" end),ownership:"core_dynamic"}}' \
        <<< "${record}") || return 1
      if [[ "${status}" == available &&
            ( "${link_status}" != present || "${route_status}" != present || "${rule_status}" != present ) ]]; then
        status=unavailable
        reason=bridge_runtime_resources_missing
      fi
      resources=$(jq -c --argjson item "${record}" '. + [$item]' <<< "${resources}") || return 1
      continue
    fi
    if [[ "${type}" != tun ]]; then
      resources=$(jq -c --argjson item "${record}" '. + [($item | {
        tag,type,listen,listen_port,
        resource_scope:"operator_policy_required",status:"not_assessed",
        reason:"host_policy_rules_not_managed"})]' <<< "${resources}") || return 1
      [[ "${status}" == available ]] && { status=not_assessed; reason=host_policy_rules_not_managed; }
      continue
    fi
    interface_name=$(jq -r '.interface_name' <<< "${record}") || return 1
    [[ "${interface_name}" =~ ^[A-Za-z0-9_.-]{1,15}$ ]] || return 1
    auto_route=$(jq -r '.auto_route' <<< "${record}") || return 1
    auto_redirect=$(jq -r '.auto_redirect' <<< "${record}") || return 1
    table_index=$(jq -r 'if ((.table_index | type) == "number" and .table_index > 0) then .table_index elif ((.table_index | type) == "array" and ((.table_index[0] // 0) > 0)) then .table_index[0] else 2022 end' <<< "${record}") || return 1
    rule_index=$(jq -r 'if ((.rule_index | type) == "number" and .rule_index > 0) then .rule_index elif ((.rule_index | type) == "array" and ((.rule_index[0] // 0) > 0)) then .rule_index[0] else 9000 end' <<< "${record}") || return 1
    link_status=missing
    if [[ "${status}" == available ]] && ip -j link show dev "${interface_name}" > "${link_file}" 2>"${snapshot}/link.stderr"; then
      if [[ "$(wc -c < "${link_file}")" -le 1048576 ]] && jq -e 'type == "array"' "${link_file}" >/dev/null 2>&1; then
        if jq -e --arg name "${interface_name}" 'any(.[]; .ifname == $name)' "${link_file}" >/dev/null 2>&1; then
          link_status=present
        else
          link_status=missing
        fi
      else
        link_status=invalid
      fi
    elif [[ "${status}" != available ]]; then
      link_status=not_probed
    fi
    route_status=not_required
    rule_status=not_required
    if [[ "${auto_route}" == true ]]; then
      if [[ "${status}" == available ]]; then
        if jq -e --argjson priority "${rule_index}" --arg table "${table_index}" \
          'any(.[]; (.priority == $priority) and ((.table // "") | tostring) == $table)' "${rule_file}" >/dev/null 2>&1; then
          rule_status=present
        else
          rule_status=missing
        fi
        if jq -e --arg table "${table_index}" --arg name "${interface_name}" \
          'any(.[]; ((.table // "main") | tostring) == $table and (.dev // "") == $name)' "${route_file}" >/dev/null 2>&1; then
          route_status=present
        else
          route_status=missing
        fi
      else
        route_status=not_probed
        rule_status=not_probed
      fi
    fi
    record=$(jq -c --argjson item "${record}" --arg scope core_owned --arg link "${link_status}" \
      --arg route "${route_status}" --arg rule "${rule_status}" --arg nft "${nft_status}" \
      '{tag:$item.tag,type:$item.type,interface_name:$item.interface_name,auto_route:$item.auto_route,
        auto_redirect:$item.auto_redirect,resource_scope:$scope,
        interface:{status:$link},policy_routing:{status:$route},rule:{status:$rule},
        auto_redirect_rules:{status:(if $item.auto_redirect then $nft else "not_required" end),ownership:"core_dynamic"}}' \
      <<< "${record}") || return 1
    if [[ "${link_status}" != present || ( "${auto_route}" == true && ("${route_status}" != present || "${rule_status}" != present)) ]]; then
      status=unavailable
      reason=tun_runtime_resources_missing
    elif [[ "${auto_redirect}" == true && "${nft_status}" != observed ]]; then
      status=not_assessed
      reason=auto_redirect_rules_not_observed
    fi
    resources=$(jq -c --argjson item "${record}" '. + [$item]' <<< "${resources}") || return 1
  done < <(jq -c '.[]' <<< "${records}")
  jq -cn --arg status "${status}" --arg reason "${reason}" --argjson resources "${resources}" \
    '{status:$status,reason:(if $reason == "" then null else $reason end),service_active:true,resources:$resources,
      limitations:["redirect/tproxy host policy rules are not installer-owned","bridge forwarding/NAT policy is core-dynamic and observation only","system endpoint interfaces, addresses and MTU are observed but routes and packet payload are not claimed","reported core-owned state is observation only"]}'
)

managed_component_transparent_runtime_healthy() {
  local config_file=${1:-} report

  [[ -f "${config_file}" && ! -L "${config_file}" && -r "${config_file}" ]] || return 1
  report=$(managed_component_transparent_resources_json "${config_file}" active) || return 1
  jq -e '
    type == "object" and
    .service_active == true and
    (.resources | type == "array" and length > 0) and
    any(.resources[];
      .type == "tun" or .type == "bridge" or
      (.system_interface == true and (.interface_name // "") != "")) and
    (all(.resources[] | select(.type == "tun");
      .interface.status == "present" and
      ((.auto_route != true) or
       (.policy_routing.status == "present" and .rule.status == "present")) and
      ((.auto_redirect != true) or .auto_redirect_rules.status == "observed")))
    and
    (all(.resources[] | select(.type == "bridge");
      .interface.status == "present" and
      .policy_routing.status == "present" and .rule.status == "present"))
    and
    (all(.resources[] | select(.system_interface == true and (.interface_name // "") != "");
      .interface.status == "present" and
      (.interface_addresses.status == "present" or .interface_addresses.status == "not_required") and
      (.mtu.status == "present" or .mtu.status == "not_required")))
  ' <<< "${report}" >/dev/null 2>&1
}

# A core restart can report active before it has finished publishing a
# dynamically allocated TUN/rule/route set.  Keep the transaction fail-closed,
# but give those core-owned resources a short bounded convergence window.
managed_component_transparent_runtime_healthy_with_retry() {
  local config_file=${1:-} attempt=0
  while (( attempt < 10 )); do
    if managed_component_transparent_runtime_healthy "${config_file}"; then
      return 0
    fi
    ((attempt += 1))
    (( attempt < 10 )) && sleep 0.2
  done
  return 1
}

managed_component_state_candidate() {
  local state=${1:-} operation=${2:-} record=${3:-} target_id=${4:-}
  local candidate
  managed_component_state_validate_json "${state}" || return 1
  if [[ "${operation}" == create || "${operation}" == replace ]]; then
    managed_component_state_validate_record "${record}" || return 1
  fi
  if ! candidate=$(jq -c --arg operation "${operation}" --arg target "${target_id}" \
    --argjson record "${record:-null}" '
      . as $state |
      if $operation == "create" then
        if any($state.components[]; .id == $record.id or .tag == $record.tag) then error("duplicate")
        else $state | .components += [$record] | .revision = (.revision + 1) end
      elif $operation == "replace" then
        if any($state.components[]; .id == $record.id) then
          $state | .components |= map(if .id == $record.id then $record else . end) |
          .revision = (.revision + 1)
        else error("missing") end
      elif $operation == "delete" then
        ([$state.components[] | select(.id == $target)] | first) as $existing |
        if $existing == null then error("missing")
        elif any($state.components[] | select(.id != $target); [.. | strings | select(. == $existing.tag)] | length > 0) then error("referenced")
        else $state | .components |= map(select(.id != $target)) | .revision = (.revision + 1) end
      else error("operation") end
    ' <<< "${state}" 2>/dev/null); then
    return 1
  fi
  managed_component_state_validate_json "${candidate}" || return 1
  printf '%s\n' "${candidate}"
}

managed_component_takeover_id() {
  local role=${1:-} type=${2:-} tag=${3:-} safe_tag digest candidate
  [[ -n "${role}" && -n "${type}" && -n "${tag}" ]] || return 1
  if [[ "${tag}" =~ ^[a-z0-9][a-z0-9_-]{0,47}$ ]]; then
    safe_tag=${tag}
    candidate="${role}-${type}-${safe_tag}"
  else
    digest=$(printf '%s:%s:%s' "${role}" "${type}" "${tag}" | sha256sum | awk '{print substr($1,1,16)}') || return 1
    candidate="${role}-${type}-${digest}"
  fi
  [[ ${#candidate} -le 64 ]] || candidate="${role}-${type}-$(printf '%s' "${candidate}" | sha256sum | awk '{print substr($1,1,16)}')"
  managed_component_state_id_valid "${candidate}" || return 1
  printf '%s' "${candidate}"
}

managed_component_live_takeover_records_json() (
  local state=${1:-} registry inbound_types endpoint_types outbound_types source_objects object role type tag id config route_rules record
  local config_snapshot
  local records=() existing_id
  [[ -n "${state}" ]] || return 1
  [[ -f "${SINGBOX_CONFIG_FILE}" && ! -L "${SINGBOX_CONFIG_FILE}" && -r "${SINGBOX_CONFIG_FILE}" ]] || return 2
  config_snapshot=$(mktemp /tmp/sbv-component-live.XXXXXX) || return 1
  trap 'rm -f -- "${config_snapshot}"' EXIT
  head -c 4194305 -- "${SINGBOX_CONFIG_FILE}" > "${config_snapshot}" || return 4
  [[ "$(wc -c < "${config_snapshot}")" -le 4194304 ]] || return 4
  managed_component_state_validate_json "${state}" || return 1
  registry=$(component_registry_static_json) || return 1
  inbound_types=$(jq -c '[.[] | select(.role == "inbound") | .type]' <<< "${registry}") || return 1
  endpoint_types=$(jq -c '[.[] | select(.role == "endpoint") | .type]' <<< "${registry}") || return 1
  outbound_types=$(jq -c '[.[] | select(.role == "outbound") | .type]' <<< "${registry}") || return 1
  source_objects=$(jq -c --argjson inbound_types "${inbound_types}" --argjson endpoint_types "${endpoint_types}" \
    --argjson outbound_types "${outbound_types}" '
    if type != "object" then error("invalid_document") else
      if any(.outbounds[]?;
             . as $outbound |
             ($outbound.tag // "") != "warp-ep" and
             (($outbound_types | index($outbound.type // "")) == null)) then
        error("unknown_outbound_type")
      elif any(.outbounds[]?;
               (.tag // "") != "warp-ep" and
               (((.tag // "") == "direct" and (.type // "") != "direct") or
                ((.tag // "") == "block" and (.type // "") != "block"))) then
        error("reserved_outbound_tag")
      else
      ([.inbounds // [] | .[] | select(.type as $type | $inbound_types | index($type) != null) |
        {role:"inbound",object:.}] +
       [.endpoints // [] | .[] |
        select((.tag // "") != "warp-ep") |
        select(.type as $type | $endpoint_types | index($type) != null) |
        {role:"endpoint",object:.}] +
       [.outbounds // [] | .[] |
        if ((((.tag // "") == "warp-ep") or
             (.type == "direct" and (.tag // "") == "direct") or
             (.type == "block" and (.tag // "") == "block")) | not) then
          {role:"outbound",object:.}
        else empty end])[]
      end
    end
  ' "${config_snapshot}" 2>/dev/null) || return 4
  while IFS= read -r object; do
    [[ -n "${object}" ]] || continue
    role=$(jq -r '.role' <<< "${object}") || return 4
    type=$(jq -r '.object.type // empty' <<< "${object}") || return 4
    tag=$(jq -r '.object.tag // empty' <<< "${object}") || return 4
    managed_component_tag_valid "${tag}" || return 4
    existing_id=$(jq -r --arg role "${role}" --arg type "${type}" --arg tag "${tag}" \
      '.components[] | select(.role == $role and .type == $type and .tag == $tag) | .id' <<< "${state}" | head -n1) || return 1
    if [[ -n "${existing_id}" ]]; then
      id=${existing_id}
    else
      id=$(managed_component_takeover_id "${role}" "${type}" "${tag}") || return 4
    fi
    config=$(jq -c '.object | del(.type,.tag)' <<< "${object}") || return 4
    if [[ "${role}" == outbound ]]; then
      route_rules=$(jq -c --arg tag "${tag}" '[.route.rules[]? |
        select((.outbound == $tag) or ((.outbound | type) == "array" and ((.outbound | index($tag)) != null)))]' \
        "${config_snapshot}") || return 4
    else
      route_rules=$(jq -c --arg tag "${tag}" '[.route.rules[]? |
        select((.inbound == $tag) or ((.inbound | type) == "array" and ((.inbound | index($tag)) != null)))]' \
      "${config_snapshot}") || return 4
    fi
    record=$(jq -cn --arg id "${id}" --arg role "${role}" --arg type "${type}" --arg tag "${tag}" \
      --argjson config "${config}" --argjson route_rules "${route_rules}" \
      '{id:$id,role:$role,type:$type,tag:$tag,enabled:true,route_rules:$route_rules,config:$config}') || return 4
    managed_component_state_validate_record "${record}" || return 4
    records+=("${record}")
  done <<< "${source_objects}"
  ((${#records[@]} > 0)) || return 3
  printf '%s\n' "${records[@]}" | jq -scS '.'
)

managed_component_state_takeover_candidate() {
  local state=${1:-} records=${2:-} candidate
  managed_component_state_validate_json "${state}" || return 1
  jq -e 'type == "array" and length > 0 and all(.[]; type == "object")' <<< "${records}" >/dev/null 2>&1 || return 1
  if ! candidate=$(jq -cS --argjson records "${records}" '
    . as $state |
    reduce $records[] as $record (.;
      if any(.components[]; .role == $record.role and .type == $record.type and .tag == $record.tag) then
        .components |= map(if .role == $record.role and .type == $record.type and .tag == $record.tag
                           then ($record | .id = .id) else . end)
      elif any(.components[]; .id == $record.id or .tag == $record.tag) then
        error("component_conflict")
      else
        .components += [$record]
      end) |
    if .components == $state.components then . else .revision = (.revision + 1) end
  ' <<< "${state}" 2>/dev/null); then
    return 1
  fi
  managed_component_state_validate_json "${candidate}" || return 1
  printf '%s\n' "${candidate}"
}

managed_component_takeover_preserves_live_config() {
  local old_config=${1:-} new_config=${2:-} registry inbound_types endpoint_types
  [[ -f "${old_config}" && ! -L "${old_config}" && -f "${new_config}" && ! -L "${new_config}" ]] || return 1
  [[ "$(wc -c < "${old_config}")" -le 4194304 && "$(wc -c < "${new_config}")" -le 4194304 ]] || return 1
  registry=$(component_registry_static_json) || return 1
  inbound_types=$(jq -c '[.[] | select(.role == "inbound") | .type]' <<< "${registry}") || return 1
  endpoint_types=$(jq -c '[.[] | select(.role == "endpoint") | .type]' <<< "${registry}") || return 1
  jq -se --argjson inbound_types "${inbound_types}" --argjson endpoint_types "${endpoint_types}" '
    def preserves($new; $old):
      (($new | type) == ($old | type)) and
      (if ($new | type) == "object" or ($new | type) == "array" then
         ($new | contains($old))
       else
         $new == $old
       end);
    def root_object_arrays:
      ["inbounds","endpoints","outbounds","certificate_providers","http_clients","services","network_namespaces"];
    def root_fields_preserved($old; $new):
      ($old | keys) as $keys |
      ($keys | all(.[]; . as $key |
        if (root_object_arrays | index($key)) != null then true
        elif ($new | has($key)) then preserves($new[$key]; $old[$key])
        else false end));
    def objects($root):
      ([($root.inbounds // [])[]? | {role:"inbound",object:.}] +
       [($root.endpoints // [])[]? | {role:"endpoint",object:.}] +
       [($root.outbounds // [])[]? | {role:"outbound",object:.}] +
       [($root.certificate_providers // [])[]? | {role:"certificate_provider",object:.}] +
       [($root.http_clients // [])[]? | {role:"http_client",object:.}] +
       [($root.services // [])[]? | {role:"service",object:.}] +
       [($root.network_namespaces // [])[]? | {role:"network_namespace",object:.}]);
    .[0] as $old |
    .[1] as $new |
    objects($old) as $old_objects |
    objects($new) as $new_objects |
    root_fields_preserved($old; $new) as $root_ok |
    ($old_objects | map(
      . as $item |
      {
        supported:(
          if $item.role == "inbound" then
            ($inbound_types | index($item.object.type // "")) != null
          elif $item.role == "endpoint" then
            ($endpoint_types | index($item.object.type // "")) != null
          else true end),
        preserved:any($new_objects[];
          .role == $item.role and
          (.object.type // "") == ($item.object.type // "") and
          (.object.tag // "") == ($item.object.tag // "") and
          (.object | contains($item.object)))
      }
    ) | all(.[]; .supported and .preserved)) as $objects_ok |
    ($old.route.rules // []) as $old_rules |
    ($new.route.rules // []) as $new_rules |
    ($old_rules | all(.[]; . as $rule | any($new_rules[]; . == $rule))) as $rules_ok |
    ($root_ok and $objects_ok and $rules_ok)
  ' <(jq -cS . "${old_config}") <(jq -cS . "${new_config}") >/dev/null 2>&1
}

managed_component_requires_public_confirmation() {
  local record=${1:-}
  jq -e '
    if .role == "inbound" then
      (.type == "tun" or .type == "cloudflared" or
       (((.config.listen // "") != "127.0.0.1") and
        ((.config.listen // "") != "::1") and
        ((.config.listen // "") != "localhost")))
    elif .role == "endpoint" and .type == "openvpn-server" then true
    else false end
  ' <<< "${record}" >/dev/null 2>&1
}

managed_component_write_state() (
  local state=${1:-} candidate backup
  managed_component_state_validate_json "${state}" || return 1
  [[ ! -L "${SB_PROJECT_DIR}" && ! -L "${SB_COMPONENT_STATE_FILE}" &&
     ! -L "${SB_COMPONENT_STATE_FILE}.bak" ]] || return 1
  mkdir -p "${SB_PROJECT_DIR}" || return 1
  candidate=$(mktemp "${SB_PROJECT_DIR}/.components.json.candidate.XXXXXX") || return 1
  trap 'rm -f -- "${candidate}" "${backup:-}"' EXIT
  printf '%s\n' "${state}" > "${candidate}" || return 1
  chmod 600 "${candidate}" || return 1
  if [[ -f "${SB_COMPONENT_STATE_FILE}" ]]; then
    backup=$(mktemp "${SB_PROJECT_DIR}/.components.json.backup.XXXXXX") || return 1
    cp -p "${SB_COMPONENT_STATE_FILE}" "${backup}" || return 1
    chmod 600 "${backup}" || return 1
    mv -f "${backup}" "${SB_COMPONENT_STATE_FILE}.bak" || return 1
    backup=""
  fi
  mv -f "${candidate}" "${SB_COMPONENT_STATE_FILE}" || return 1
  trap - EXIT
)

managed_component_inventory_json() {
  local state registry component_records component component_id role type base environment
  local instance_environments='[]' instance_environment_rows=()
  state=$(managed_component_state_json) || return 1
  registry=$(component_registry_json) || return 1
  component_records=$(jq -c '.components[]' <<< "${state}") || return 1
  while IFS= read -r component; do
    [[ -n "${component}" ]] || continue
    component_id=$(jq -r '.id' <<< "${component}") || return 1
    role=$(jq -r '.role' <<< "${component}") || return 1
    type=$(jq -r '.type' <<< "${component}") || return 1
    base=$(jq -ce --arg role "${role}" --arg type "${type}" \
      'first(.[] | select(.role == $role and .type == $type) | .environment) // empty' \
      <<< "${registry}") || return 1
    environment=$(managed_component_instance_environment_json "${component}" "${base}") || return 1
    instance_environment_rows+=("$(jq -cn --arg id "${component_id}" --argjson environment "${environment}" \
      '{id:$id,environment:$environment}')")
  done <<< "${component_records}"
  if ((${#instance_environment_rows[@]} > 0)); then
    instance_environments=$(printf '%s\n' "${instance_environment_rows[@]}" | jq -sc '.') || return 1
  fi
  jq -cn --argjson state "${state}" --argjson registry "${registry}" \
    --argjson instance_environments "${instance_environments}" '
    {
      schema: "1",
      action: "component-list",
      revision: $state.revision,
      components: [ $state.components[] |
        . as $component |
        ($registry[] | select(.role == $component.role and .type == $component.type)) as $entry |
        {id:$component.id, role:$component.role, type:$component.type, tag:$component.tag,
         enabled:$component.enabled, registry_id:$entry.state_id,
         display_name:$entry.display_name, availability:$entry.availability,
         environment:$entry.environment,
         instance_environment:(first($instance_environments[] |
           select(.id == $component.id) | .environment) // $entry.environment),
         minimum_project_core:$entry.minimum_project_core,
         config_keys:($component.config | keys), route_rule_count:(($component.route_rules // []) | length)} |
        if (.role == "outbound" and .type == "ssh") then
          . + {host_key_verification:(
            if (($component.config.host_key? // null) |
                if type == "array" then length > 0
                elif type == "string" then length > 0
                else false end)
            then "pinned" else "unverified" end)}
        elif (.role == "outbound" and .type == "tor") then
          . + {runtime_mode:(
            if (($component.config.executable_path? // null) |
                if type == "string" then length > 0 else false end)
            then "external" else "embedded_unverified" end)}
        elif (.role == "outbound" and (.type == "selector" or .type == "urltest")) then
          . + {member_count:(($component.config.outbounds // []) | length)}
        else . end
      ],
      supported: $registry
    }'
}

managed_component_diagnose_json() {
  local state inventory config_status graph_status listener_status core_status
  local config_present=false service_state=unknown firewall_status=not_configured firewall_rules=0
  local instance_pending=false component_pending=false component_transaction_phase=none ledger
  local transparent_resources='{"status":"not_assessed","reason":"config_missing","service_active":false,"resources":[],"limitations":[]}'

  state=$(managed_component_state_json) || return 1
  inventory=$(managed_component_inventory_json) || return 1

  if [[ ! -e "${SINGBOX_CONFIG_FILE}" ]]; then
    config_status=missing
    graph_status=not_run
    listener_status=not_run
    core_status=not_run
  elif [[ -f "${SINGBOX_CONFIG_FILE}" && ! -L "${SINGBOX_CONFIG_FILE}" && -r "${SINGBOX_CONFIG_FILE}" ]]; then
    config_present=true
    config_status=present
    if validate_managed_component_graph "${SINGBOX_CONFIG_FILE}" >/dev/null 2>&1; then
      graph_status=passed
    else
      graph_status=failed
    fi
    if validate_managed_listener_resources "${SINGBOX_CONFIG_FILE}" >/dev/null 2>&1; then
      listener_status=passed
    else
      listener_status=failed
    fi
    if [[ -x "${SINGBOX_BIN_PATH}" ]]; then
      if "${SINGBOX_BIN_PATH}" check -c "${SINGBOX_CONFIG_FILE}" >/dev/null 2>&1; then
        core_status=passed
      else
        core_status=failed
      fi
    else
      core_status=unavailable
    fi
  else
    config_status=untrusted
    graph_status=not_run
    listener_status=not_run
    core_status=not_run
  fi

  if command -v systemctl >/dev/null 2>&1; then
    service_state=$(systemctl is-active sing-box 2>/dev/null || printf 'unknown')
  fi
  if [[ "${config_present}" == true ]]; then
    transparent_resources=$(managed_component_transparent_resources_json "${SINGBOX_CONFIG_FILE}" "${service_state}") || \
      transparent_resources='{"status":"unavailable","reason":"resource_probe_failed","service_active":false,"resources":[],"limitations":[]}'
  fi
  if [[ -e "${INSTANCE_FIREWALL_LEDGER_FILE}" ]]; then
    if ledger=$(instance_firewall_read_ledger); then
      firewall_status=available
      firewall_rules=$(jq -r '.rules | length' <<< "${ledger}") || firewall_rules=0
    else
      firewall_status=unavailable
    fi
  fi
  [[ -e "${SB_PROJECT_DIR}.instance-write.lock" ]] && instance_pending=true
  if [[ -e "${SB_COMPONENT_TRANSACTION_DIR}" ]]; then
    component_pending=true
    if [[ -f "${SB_COMPONENT_TRANSACTION_DIR}/transaction.json" &&
          ! -L "${SB_COMPONENT_TRANSACTION_DIR}/transaction.json" ]] &&
       component_transaction_phase=$(jq -r '.phase // "untrusted"' \
         "${SB_COMPONENT_TRANSACTION_DIR}/transaction.json"); then
      :
    else
      component_transaction_phase=untrusted
    fi
  fi

  jq -cn --arg schema "${AGENT_OUTPUT_SCHEMA_VERSION}" --arg revision "$(jq -r '.revision' <<< "${state}")" \
    --arg config_status "${config_status}" --arg graph_status "${graph_status}" \
    --arg listener_status "${listener_status}" --arg core_status "${core_status}" \
    --arg service_state "${service_state:-unknown}" --arg firewall_status "${firewall_status}" \
    --argjson config_present "${config_present}" --argjson component_count "$(jq -r '.components | length' <<< "${state}")" \
    --argjson firewall_rules "${firewall_rules}" --argjson instance_pending "${instance_pending}" \
    --argjson component_pending "${component_pending}" --arg component_phase "${component_transaction_phase}" \
    --argjson inventory "${inventory}" --argjson transparent_resources "${transparent_resources}" \
    '{schema:$schema,action:"component-diagnose",
      state:{revision:($revision|tonumber),component_count:$component_count,valid:true},
      config:{status:$config_status,present:$config_present,graph:$graph_status,listener_resources:$listener_status,core_check:$core_status},
      service:{active_state:$service_state},
      firewall:{ledger_status:$firewall_status,managed_rule_count:$firewall_rules},
      transactions:{instance_write_pending:$instance_pending,component_write_pending:$component_pending,
        component_write_phase:$component_phase},
      transparent_resources:$transparent_resources,
      components:$inventory.components,supported:$inventory.supported}'
}

managed_component_export_json() {
  local component_id=${1:-} expected_revision=${2:-} state revision record
  managed_component_state_id_valid "${component_id}" || return 1
  state=$(managed_component_state_json) || return 1
  revision=$(jq -r '.revision | tostring' <<< "${state}") || return 1
  if [[ -n "${expected_revision}" && "${expected_revision}" != "${revision}" ]]; then
    return 2
  fi
  record=$(jq -c --arg id "${component_id}" '.components[] | select(.id == $id)' <<< "${state}") || return 1
  [[ -n "${record}" ]] || return 3
  jq -cn --arg revision "${revision}" --argjson component "${record}" \
    '{action:"component-export",revision:($revision|tonumber),sensitive:true,component:$component}'
}

managed_component_state_matches_live_config() {
  local config_file=${1:-} state_file=${2:-} state registry outbound_types snapshot_dir
  [[ -f "${config_file}" && ! -L "${config_file}" ]] || return 1
  if [[ -n "${state_file}" ]]; then
    snapshot_dir=${state_file%/project/components.json}
    [[ "${state_file}" == "${snapshot_dir}/project/components.json" ]] || return 1
    managed_state_snapshot_is_valid "${snapshot_dir}" || return 1
    if [[ -f "${state_file}" && ! -L "${state_file}" && -r "${state_file}" ]]; then
      state=$(jq -cS '.' "${state_file}") || return 1
      managed_component_state_validate_json "${state}" || return 1
    elif [[ ! -e "${state_file}" ]]; then
      state=$(managed_component_state_default_json) || return 1
    else
      return 1
    fi
  else
    state=$(managed_component_state_json) || return 1
  fi
  registry=$(component_registry_static_json) || return 1
  outbound_types=$(jq -c '[.[] | select(.role == "outbound") | .type]' <<< "${registry}") || return 1
  jq -e --argjson state "${state}" --argjson outbound_types "${outbound_types}" '
    def managed($role; $type; $tag):
      any($state.components[]; .role == $role and .type == $type and .tag == $tag and .enabled == true);
    (all(.inbounds[]?;
      if (.type | IN("direct","tun","redirect","tproxy","cloudflared")) then
        managed("inbound"; .type; (.tag // ""))
      else true end)) and
    (all(.endpoints[]?;
      if (.type | IN("wireguard","tailscale","openconnect","openvpn-client","openvpn-server")) then
        ((.tag // "") == "warp-ep") or managed("endpoint"; .type; (.tag // ""))
      else true end)) and
    # Proxy protocol adapters generate client outbounds only for exports; the
    # server configuration registered custom outbounds are component-owned.
    # Keep the two built-in safety owners out of the state contract.
    (all(.outbounds[]?;
      . as $outbound |
      if (($outbound.tag // "") == "warp-ep") then
        true
      elif (($outbound_types | index($outbound.type // "")) != null) and
         ((($outbound.type == "direct" and ($outbound.tag // "") == "direct") or
           ($outbound.type == "block" and ($outbound.tag // "") == "block")) | not) then
        managed("outbound"; ($outbound.type // ""); ($outbound.tag // ""))
      elif (($outbound.tag // "") == "direct" or ($outbound.tag // "") == "block") then
        (($outbound.type // "") == ($outbound.tag // ""))
      elif (($outbound_types | index($outbound.type // "")) == null) then
        false
      else true end))
  ' "${config_file}" >/dev/null 2>&1
}

managed_component_state_apply() {
  local operation=${1:-} expected=${2:-} input=${3:-} target_id=${4:-} allow_public=${5:-n}
  local state current_revision record candidate snapshot service_restarted=false state_changed=true
  local role type tag result_record old_config old_listener_plan new_listener_plan
  local takeover_records takeover_status result_count=0
  local firewall_journal=""
  local firewall_summary='{"status":"not_attempted","backends":[],"diagnostics":[]}'
  local result_id candidate_revision lock_dir="${SB_COMPONENT_TRANSACTION_DIR}" before_active=false owner_pid owner_start=""
  local inventory_state_file=""
  MANAGED_COMPONENT_LAST_ERROR=""
  MANAGED_COMPONENT_LAST_RESULT=""
  result_record='{}'
  [[ ${EUID} -eq 0 ]] || { MANAGED_COMPONENT_LAST_ERROR=root_required; return 1; }
  [[ ! -L "${SB_PROJECT_DIR}" ]] || { MANAGED_COMPONENT_LAST_ERROR=component_write_failed; return 1; }
  mkdir -p "${SB_PROJECT_DIR}" || { MANAGED_COMPONENT_LAST_ERROR=component_write_failed; return 1; }
  acquire_managed_write_lock || { MANAGED_COMPONENT_LAST_ERROR=component_write_busy; return 1; }
  if [[ -e "${SB_PROJECT_DIR}.instance-write.lock" || -L "${SB_PROJECT_DIR}.instance-write.lock" ]]; then
    MANAGED_COMPONENT_LAST_ERROR=instance_transaction_pending
    return 1
  fi
  state=$(managed_component_state_json) || { MANAGED_COMPONENT_LAST_ERROR=state_invalid; return 1; }
  current_revision=$(jq -r '.revision | tostring' <<< "${state}") || { MANAGED_COMPONENT_LAST_ERROR=state_invalid; return 1; }
  [[ "${expected}" == "${current_revision}" ]] || { MANAGED_COMPONENT_LAST_ERROR=revision_mismatch; return 1; }
  [[ ! -e "${lock_dir}" && ! -L "${lock_dir}" ]] || {
    MANAGED_COMPONENT_LAST_ERROR=component_transaction_pending
    return 1
  }
  owner_pid=${BASHPID:-$$}
  owner_start=$(awk '{print $22}' "/proc/${owner_pid}/stat") || {
    MANAGED_COMPONENT_LAST_ERROR=component_transaction_begin_failed
    return 1
  }
  [[ "${owner_start}" =~ ^[0-9]+$ ]] || {
    MANAGED_COMPONENT_LAST_ERROR=component_transaction_begin_failed
    return 1
  }
  if [[ -f "${SINGBOX_SERVICE_FILE}" ]] && systemctl is-active sing-box >/dev/null 2>&1; then
    before_active=true
  fi
  case "${operation}" in
    create|replace)
      record=$(managed_component_normalize_input_file "${input}") || { MANAGED_COMPONENT_LAST_ERROR=record_invalid; return 1; }
      result_record="${record}"
      if managed_component_requires_public_confirmation "${record}" && [[ "${allow_public}" != y ]]; then
        MANAGED_COMPONENT_LAST_ERROR=public_confirmation_required
        return 1
      fi
      candidate=$(managed_component_state_candidate "${state}" "${operation}" "${record}") || {
        MANAGED_COMPONENT_LAST_ERROR=component_conflict; return 1;
      }
      ;;
    delete)
      managed_component_state_id_valid "${target_id}" || { MANAGED_COMPONENT_LAST_ERROR=invalid_id; return 1; }
      candidate=$(managed_component_state_candidate "${state}" delete "" "${target_id}") || {
        MANAGED_COMPONENT_LAST_ERROR=component_referenced_or_missing; return 1;
      }
      ;;
    rebuild)
      [[ -z "${input}${target_id}" && "${allow_public}" == n ]] || {
        MANAGED_COMPONENT_LAST_ERROR=invalid_operation; return 1;
      }
      candidate="${state}"
      state_changed=false
      ;;
    takeover)
      [[ -z "${input}${target_id}" ]] || {
        MANAGED_COMPONENT_LAST_ERROR=invalid_operation; return 1;
      }
      takeover_records=$(managed_component_live_takeover_records_json "${state}") || {
        takeover_status=$?
        case "${takeover_status}" in
          2) MANAGED_COMPONENT_LAST_ERROR=component_live_missing ;;
          3) MANAGED_COMPONENT_LAST_ERROR=component_live_missing ;;
          4) MANAGED_COMPONENT_LAST_ERROR=component_live_untrusted ;;
          *) MANAGED_COMPONENT_LAST_ERROR=component_takeover_failed ;;
        esac
        return 1
      }
      if jq -e 'any(.[];
          (.role == "inbound" and
           (.type == "tun" or .type == "cloudflared" or
            ((.config.listen // "127.0.0.1") as $listen |
             ($listen != "127.0.0.1" and $listen != "::1" and $listen != "localhost")))) or
          (.role == "endpoint" and .type == "openvpn-server"))' <<< "${takeover_records}" >/dev/null 2>&1 &&
         [[ "${allow_public}" != y ]]; then
        MANAGED_COMPONENT_LAST_ERROR=public_confirmation_required
        return 1
      fi
      candidate=$(managed_component_state_takeover_candidate "${state}" "${takeover_records}") || {
        MANAGED_COMPONENT_LAST_ERROR=component_takeover_conflict; return 1;
      }
      if [[ "${candidate}" == "${state}" ]]; then
        state_changed=false
      fi
      result_record='{}'
      ;;
    *) MANAGED_COMPONENT_LAST_ERROR=invalid_operation; return 1 ;;
  esac

  if ! managed_component_transaction_begin "${lock_dir}" "${operation}" "${expected}" \
    "${before_active}" "${owner_pid}" "${owner_start}"; then
    MANAGED_COMPONENT_LAST_ERROR=component_transaction_begin_failed
    return 1
  fi
  snapshot="${lock_dir}/snapshot"
  if ! create_managed_state_snapshot "${snapshot}" >/dev/null; then
    if ! rm -rf -- "${lock_dir}"; then
      MANAGED_COMPONENT_LAST_ERROR=component_cleanup_failed
    else
      MANAGED_COMPONENT_LAST_ERROR=snapshot_failed
    fi
    return 1
  fi
  candidate_revision=$(jq -r '.revision' <<< "${candidate}") || {
    managed_component_abort_component_transaction "${lock_dir}" "${snapshot}" "高级组件事务 revision 读取失败" || :
    MANAGED_COMPONENT_LAST_ERROR=component_transaction_write_failed
    return 1
  }
  if ! managed_component_transaction_checkpoint "${lock_dir}" snapshot ||
     ! managed_component_transaction_set_revision "${lock_dir}" "${candidate_revision}" ||
     ! managed_component_transaction_checkpoint "${lock_dir}" publish; then
    managed_component_abort_component_transaction "${lock_dir}" "${snapshot}" "高级组件事务日志写入失败" || :
    MANAGED_COMPONENT_LAST_ERROR=component_transaction_write_failed
    return 1
  fi
  old_config="${snapshot}/project/config.json"
  [[ -f "${old_config}" && ! -L "${old_config}" ]] || old_config=""
  if [[ "${state_changed}" == true ]]; then
    if ! managed_component_write_state "${candidate}"; then
      managed_component_abort_component_transaction "${lock_dir}" "${snapshot}" "高级组件状态写入失败" || :
      MANAGED_COMPONENT_LAST_ERROR=state_write_failed
      return 1
    fi
  fi
  if [[ "${operation}" != takeover ]]; then
    inventory_state_file="${snapshot}/project/components.json"
  fi

  # Agent component writes can start in a fresh shell that has not gone
  # through the interactive config-state loader. Preserve route toggles from
  # the live config before regeneration; otherwise a component-only change
  # would silently re-enable the default private-address reject rule or drop
  # an existing Warp endpoint.
  load_config_generation_settings "${SINGBOX_CONFIG_FILE}"

  if ! generate_config "${inventory_state_file}" ||
     [[ ! -f "${SINGBOX_CONFIG_FILE}" || -L "${SINGBOX_CONFIG_FILE}" ]]; then
    managed_component_abort_component_transaction "${lock_dir}" "${snapshot}" "高级组件配置生成或校验失败" || :
    MANAGED_COMPONENT_LAST_ERROR=config_check_failed
    return 1
  fi
  if [[ "${operation}" == takeover ]] &&
     ! managed_component_takeover_preserves_live_config "${old_config}" "${SINGBOX_CONFIG_FILE}"; then
    managed_component_abort_component_transaction "${lock_dir}" "${snapshot}" "高级组件接管会丢失现有配置对象或路由规则" || :
    MANAGED_COMPONENT_LAST_ERROR=config_check_failed
    return 1
  fi

  # Fixed listeners owned by advanced components use the same firewall
  # ownership ledger as structured protocol instances.  Keep the journal in
  # the state snapshot so a file/config rollback and external resource
  # compensation share one bounded recovery material set.
  new_listener_plan=$(managed_listener_plan "${SINGBOX_CONFIG_FILE}") || {
    managed_component_abort_component_transaction "${lock_dir}" "${snapshot}" "高级组件监听资源预检失败" || :
    MANAGED_COMPONENT_LAST_ERROR=config_check_failed
    return 1
  }
  if [[ -n "${old_config}" ]]; then
    old_listener_plan=$(managed_listener_plan "${old_config}") || {
      managed_component_abort_component_transaction "${lock_dir}" "${snapshot}" "高级组件旧监听资源预检失败" || :
      MANAGED_COMPONENT_LAST_ERROR=config_check_failed
      return 1
    }
  else
    old_listener_plan='[]'
  fi
  if [[ "${old_listener_plan}" != "${new_listener_plan}" ]]; then
    if ! managed_component_transaction_set_firewall_expected "${lock_dir}" true ||
       ! managed_component_transaction_checkpoint "${lock_dir}" resources; then
      managed_component_abort_component_transaction "${lock_dir}" "${snapshot}" "高级组件事务资源阶段记录失败" || :
      MANAGED_COMPONENT_LAST_ERROR=component_transaction_write_failed
      return 1
    fi
  elif ! managed_component_transaction_set_firewall_expected "${lock_dir}" false ||
       ! managed_component_transaction_checkpoint "${lock_dir}" resources; then
    managed_component_abort_component_transaction "${lock_dir}" "${snapshot}" "高级组件事务资源阶段记录失败" || :
    MANAGED_COMPONENT_LAST_ERROR=component_transaction_write_failed
    return 1
  fi
  if [[ "${old_listener_plan}" != "${new_listener_plan}" ]]; then
    firewall_journal="${snapshot}/component-firewall.json"
    if ! instance_firewall_prepare "${old_config}" "${SINGBOX_CONFIG_FILE}" "${firewall_journal}"; then
      firewall_summary=$(instance_transaction_firewall_summary "${firewall_journal}")
      managed_component_abort_component_transaction "${lock_dir}" "${snapshot}" "高级组件防火墙资源预检失败" || :
      MANAGED_COMPONENT_LAST_ERROR=firewall_prepare_failed
      return 1
    fi
    firewall_summary=$(instance_transaction_firewall_summary "${firewall_journal}")
    if ! instance_firewall_apply "${firewall_journal}"; then
      firewall_summary=$(instance_transaction_firewall_summary "${firewall_journal}")
      if ! instance_firewall_rollback "${firewall_journal}"; then
        MANAGED_COMPONENT_LAST_ERROR=firewall_rollback_failed
        if restore_managed_state_snapshot "${snapshot}"; then
          printf '[ERROR] 高级组件防火墙应用失败且外部资源回滚不确定；文件状态已恢复，事务快照保留在 %s。\n' \
            "${snapshot}" >&2
        else
          printf '[ERROR] 高级组件防火墙应用失败且自动回滚失败；事务快照保留在 %s。\n' \
            "${snapshot}" >&2
        fi
        return 1
      fi
      firewall_summary=$(instance_transaction_firewall_summary "${firewall_journal}")
      managed_component_abort_component_transaction "${lock_dir}" "${snapshot}" "高级组件防火墙资源应用失败" || :
      MANAGED_COMPONENT_LAST_ERROR=firewall_apply_failed
      return 1
    fi
    firewall_summary=$(instance_transaction_firewall_summary "${firewall_journal}")
  fi
  if ! managed_component_transaction_checkpoint "${lock_dir}" service; then
    if [[ -n "${firewall_journal}" ]] && ! instance_firewall_rollback "${firewall_journal}"; then
      MANAGED_COMPONENT_LAST_ERROR=firewall_rollback_failed
      if restore_managed_state_snapshot "${snapshot}"; then
        printf '[ERROR] 高级组件事务服务阶段记录失败且防火墙回滚不确定；文件状态已恢复，事务目录保留在 %s。\n' \
          "${lock_dir}" >&2
      else
        printf '[ERROR] 高级组件事务服务阶段记录失败且自动回滚失败；事务目录保留在 %s。\n' \
          "${lock_dir}" >&2
      fi
      return 1
    fi
    managed_component_abort_component_transaction "${lock_dir}" "${snapshot}" "高级组件事务服务阶段记录失败" || :
    MANAGED_COMPONENT_LAST_ERROR=component_transaction_write_failed
    return 1
  fi
  if [[ "${before_active}" == true ]]; then
    if ! systemctl restart sing-box >/dev/null 2>&1 ||
       [[ "$(systemctl is-active sing-box 2>/dev/null || true)" != active ]]; then
      if [[ -n "${firewall_journal}" ]]; then
        if ! instance_firewall_rollback "${firewall_journal}"; then
          MANAGED_COMPONENT_LAST_ERROR=firewall_rollback_failed
          if restore_managed_state_snapshot "${snapshot}"; then
            printf '[ERROR] 高级组件服务重启失败且防火墙回滚不确定；文件状态已恢复，事务快照保留在 %s。\n' \
              "${snapshot}" >&2
          else
            printf '[ERROR] 高级组件服务重启失败且自动回滚失败；事务快照保留在 %s。\n' \
              "${snapshot}" >&2
          fi
          return 1
        fi
        firewall_summary=$(instance_transaction_firewall_summary "${firewall_journal}")
      fi
      managed_component_abort_component_transaction "${lock_dir}" "${snapshot}" "高级组件服务重启失败" y || :
      MANAGED_COMPONENT_LAST_ERROR=service_restart_failed
      return 1
    fi
    service_restarted=true
  fi
  if [[ "${service_restarted}" == true ]] &&
     jq -e 'any(.inbounds[]?; .type == "tun") or
       any(.outbounds[]?; .type == "bridge") or
       any(.endpoints[]?;
         (
           ((.type == "wireguard" or .type == "openconnect" or
             .type == "openvpn-client" or .type == "openvpn-server") and
            .system == true and ((.name // "") | length > 0)) or
           (.type == "tailscale" and .system_interface == true and
            ((.system_interface_name // "") | length > 0))
         ))' \
       "${SINGBOX_CONFIG_FILE}" >/dev/null 2>&1; then
    if ! managed_component_transparent_runtime_healthy_with_retry "${SINGBOX_CONFIG_FILE}"; then
      if [[ -n "${firewall_journal}" ]]; then
        if ! instance_firewall_rollback "${firewall_journal}"; then
          MANAGED_COMPONENT_LAST_ERROR=firewall_rollback_failed
          if restore_managed_state_snapshot "${snapshot}"; then
            printf '[ERROR] 高级组件透明运行资源检查失败且防火墙回滚不确定；文件状态已恢复，事务快照保留在 %s。\n' \
              "${snapshot}" >&2
          else
            printf '[ERROR] 高级组件透明运行资源检查失败且自动回滚失败；事务快照保留在 %s。\n' \
              "${snapshot}" >&2
          fi
          return 1
        fi
        firewall_summary=$(instance_transaction_firewall_summary "${firewall_journal}")
      fi
      managed_component_abort_component_transaction "${lock_dir}" "${snapshot}" \
        "高级组件透明运行资源检查失败" y || :
      MANAGED_COMPONENT_LAST_ERROR=transparent_resource_check_failed
      return 1
    fi
  fi
  if [[ -n "${firewall_journal}" ]]; then
    if ! instance_firewall_commit "${firewall_journal}"; then
      firewall_summary=$(instance_transaction_firewall_summary "${firewall_journal}")
      if ! instance_firewall_rollback "${firewall_journal}"; then
        MANAGED_COMPONENT_LAST_ERROR=firewall_rollback_failed
        if restore_managed_state_snapshot "${snapshot}"; then
          printf '[ERROR] 高级组件防火墙提交失败且外部资源回滚不确定；文件状态已恢复，事务快照保留在 %s。\n' \
            "${snapshot}" >&2
        else
          printf '[ERROR] 高级组件防火墙提交失败且自动回滚失败；事务快照保留在 %s。\n' \
            "${snapshot}" >&2
        fi
        return 1
      fi
      firewall_summary=$(instance_transaction_firewall_summary "${firewall_journal}")
      managed_component_abort_component_transaction "${lock_dir}" "${snapshot}" "高级组件防火墙资源提交失败" y || :
      MANAGED_COMPONENT_LAST_ERROR=firewall_commit_failed
      return 1
    fi
    firewall_summary=$(instance_transaction_firewall_summary "${firewall_journal}")
  fi
  if ! managed_component_transaction_checkpoint "${lock_dir}" committed; then
    if [[ -n "${firewall_journal}" ]] && ! instance_firewall_rollback "${firewall_journal}"; then
      MANAGED_COMPONENT_LAST_ERROR=firewall_rollback_failed
      if restore_managed_state_snapshot "${snapshot}"; then
        printf '[ERROR] 高级组件事务提交记录失败且防火墙回滚不确定；文件状态已恢复，事务目录保留在 %s。\n' \
          "${lock_dir}" >&2
      else
        printf '[ERROR] 高级组件事务提交记录失败且自动回滚失败；事务目录保留在 %s。\n' \
          "${lock_dir}" >&2
      fi
      return 1
    fi
    managed_component_abort_component_transaction "${lock_dir}" "${snapshot}" "高级组件事务提交记录失败" y || :
    MANAGED_COMPONENT_LAST_ERROR=component_transaction_write_failed
    return 1
  fi
  if ! rm -rf -- "${lock_dir}"; then
    MANAGED_COMPONENT_LAST_ERROR=component_cleanup_failed
    return 1
  fi
  role=$(jq -r '.role // empty' <<< "${result_record}")
  type=$(jq -r '.type // empty' <<< "${result_record}")
  tag=$(jq -r '.tag // empty' <<< "${result_record}")
  if [[ "${operation}" == delete ]]; then
    role=$(jq -r --arg id "${target_id}" '.components[] | select(.id == $id) | .role' <<< "${state}")
    type=$(jq -r --arg id "${target_id}" '.components[] | select(.id == $id) | .type' <<< "${state}")
    tag=$(jq -r --arg id "${target_id}" '.components[] | select(.id == $id) | .tag' <<< "${state}")
  fi
  result_id="${target_id}"
  if [[ -z "${result_id}" ]]; then
    result_id=$(jq -r '.id // empty' <<< "${result_record}")
  fi
  result_count=$(jq -r '.components | length' <<< "${candidate}") || result_count=0
  MANAGED_COMPONENT_LAST_RESULT=$(jq -cn --arg operation "${operation}" --arg revision "$(jq -r '.revision' <<< "${candidate}")" \
    --arg id "${result_id}" --arg role "${role}" --arg type "${type}" --arg tag "${tag}" \
    --argjson count "${result_count}" \
    --argjson service_restarted "${service_restarted}" \
    --argjson firewall "${firewall_summary}" \
    '{action:"component-apply",operation:$operation,revision:($revision|tonumber),
      id:(if $id == "" then null else $id end),
      role:(if $role == "" then null else $role end),
      type:(if $type == "" then null else $type end),
      tag:(if $tag == "" then null else $tag end),
      config_check:"passed",service_restarted:$service_restarted,firewall:$firewall} +
      (if $operation == "takeover" then {count:$count} else {} end)')
  return 0
}

managed_state_snapshot_is_valid() {
  local snapshot_dir=$1

  [[ "${snapshot_dir}" == /tmp/sing-box-vps-state.* ||
     "${snapshot_dir}" == "${SB_PROJECT_DIR}.instance-write.lock/snapshot" ||
     "${snapshot_dir}" == "${SB_COMPONENT_TRANSACTION_DIR}/snapshot" ]] || return 1
  [[ ! -L "${snapshot_dir}" ]] || return 1
  [[ -d "${snapshot_dir}" && -f "${snapshot_dir}/snapshot.meta" ]] || return 1
  grep -Fqx 'SNAPSHOT_VERSION=1' "${snapshot_dir}/snapshot.meta" || return 1
  grep -Fqx "PROJECT_DIR=${SB_PROJECT_DIR}" "${snapshot_dir}/snapshot.meta" || return 1
}

persist_file_backup() {
  local source_file=$1
  local backup_file=$2
  local backup_dir backup_name backup_candidate

  [[ -f "${source_file}" ]] || return 1
  backup_dir=$(dirname "${backup_file}")
  backup_name=$(basename "${backup_file}")
  mkdir -p "${backup_dir}" || return 1
  backup_candidate=$(mktemp "${backup_dir}/.${backup_name}.candidate.XXXXXX") || return 1
  if ! cp -p "${source_file}" "${backup_candidate}" ||
     ! chmod 600 "${backup_candidate}" ||
     ! mv -f "${backup_candidate}" "${backup_file}"; then
    rm -f "${backup_candidate}"
    return 1
  fi
}

create_managed_state_snapshot() {
  local snapshot_dir

  if [[ $# -gt 0 ]]; then
    [[ ("$1" == "${SB_PROJECT_DIR}.instance-write.lock/snapshot" &&
        -d "${SB_PROJECT_DIR}.instance-write.lock" && ! -L "${SB_PROJECT_DIR}.instance-write.lock") ||
       ("$1" == "${SB_COMPONENT_TRANSACTION_DIR}/snapshot" &&
        -d "${SB_COMPONENT_TRANSACTION_DIR}" && ! -L "${SB_COMPONENT_TRANSACTION_DIR}") ]] || return 1
    snapshot_dir=$1
    mkdir -m 700 "${snapshot_dir}" || return 1
  else
    if [[ -e "${SB_PROJECT_DIR}.instance-write.lock" ]]; then
      printf '[ERROR] 存在未完成的实例事务；先执行 instance recover，未开始其他写操作。\n' >&2
      return 1
    fi
    snapshot_dir=$(mktemp -d /tmp/sing-box-vps-state.XXXXXX) || return 1
  fi
  chmod 700 "${snapshot_dir}" || {
    rm -rf "${snapshot_dir}"
    return 1
  }
  if ! mkdir -p "${snapshot_dir}/project"; then
    rm -rf "${snapshot_dir}"
    return 1
  fi
  if [[ -d "${SB_PROJECT_DIR}" ]]; then
    if ! cp -a "${SB_PROJECT_DIR}/." "${snapshot_dir}/project/"; then
      rm -rf "${snapshot_dir}"
      return 1
    fi
    : > "${snapshot_dir}/project.existed"
  fi
  if ! {
    printf 'SNAPSHOT_VERSION=1\n'
    printf 'PROJECT_DIR=%s\n' "${SB_PROJECT_DIR}"
  } > "${snapshot_dir}/snapshot.meta"; then
    rm -rf "${snapshot_dir}"
    return 1
  fi
  chmod 600 "${snapshot_dir}/snapshot.meta" || {
    rm -rf "${snapshot_dir}"
    return 1
  }

  printf '%s' "${snapshot_dir}"
}

discard_managed_state_snapshot() {
  local snapshot_dir=$1

  managed_state_snapshot_is_valid "${snapshot_dir}" || return 1
  rm -rf "${snapshot_dir}"
}

restore_managed_state_snapshot() {
  local snapshot_dir=$1
  local project_parent project_base restore_candidate restore_previous
  local current_existed="n"

  managed_state_snapshot_is_valid "${snapshot_dir}" || return 1
  [[ -n "${SB_PROJECT_DIR}" && "${SB_PROJECT_DIR}" != "/" ]] || return 1
  project_parent=$(dirname "${SB_PROJECT_DIR}")
  project_base=$(basename "${SB_PROJECT_DIR}")
  mkdir -p "${project_parent}" || return 1

  restore_candidate=$(mktemp -d "${project_parent}/.${project_base}.restore.XXXXXX") || return 1
  if [[ -f "${snapshot_dir}/project.existed" ]]; then
    if ! cp -a "${snapshot_dir}/project/." "${restore_candidate}/"; then
      rm -rf "${restore_candidate}"
      return 1
    fi
  fi

  restore_previous=$(mktemp -d "${project_parent}/.${project_base}.previous.XXXXXX") || {
    rm -rf "${restore_candidate}"
    return 1
  }
  rmdir "${restore_previous}" || {
    rm -rf "${restore_candidate}" "${restore_previous}"
    return 1
  }

  if [[ -e "${SB_PROJECT_DIR}" || -L "${SB_PROJECT_DIR}" ]]; then
    if ! mv "${SB_PROJECT_DIR}" "${restore_previous}"; then
      rm -rf "${restore_candidate}"
      return 1
    fi
    current_existed="y"
  fi

  if [[ -f "${snapshot_dir}/project.existed" ]]; then
    if ! mv "${restore_candidate}" "${SB_PROJECT_DIR}"; then
      if [[ "${current_existed}" == "y" ]] && ! mv "${restore_previous}" "${SB_PROJECT_DIR}"; then
        printf '[ERROR] state_restore: previous_directory_restore_failed; recovery=%s\n' "${restore_previous}" >&2
        return 1
      fi
      rm -rf "${restore_candidate}" || return 1
      return 1
    fi
  elif ! rmdir "${restore_candidate}"; then
    if [[ "${current_existed}" == "y" ]] && ! mv "${restore_previous}" "${SB_PROJECT_DIR}"; then
      printf '[ERROR] state_restore: previous_directory_restore_failed; recovery=%s\n' "${restore_previous}" >&2
    fi
    return 1
  fi

  if [[ "${current_existed}" == "y" ]] && ! rm -rf "${restore_previous}"; then
    return 1
  fi
}

rollback_managed_state_snapshot() {
  local snapshot_dir=$1

  if ! restore_managed_state_snapshot "${snapshot_dir}"; then
    log_warn "配置状态回滚失败；事务快照保留在 ${snapshot_dir}。"
    return 1
  fi
  if ! discard_managed_state_snapshot "${snapshot_dir}"; then
    log_warn "配置状态已恢复，但临时事务快照未能删除: ${snapshot_dir}。"
    return 1
  fi
}

abort_managed_state_transaction() {
  local snapshot_dir=$1
  local failure_message=$2

  if rollback_managed_state_snapshot "${snapshot_dir}"; then
    log_error "${failure_message}，已恢复变更前的配置状态。"
    return 1
  fi
  log_error "${failure_message}，且自动回滚失败；事务快照保留在 ${snapshot_dir}。"
  return 1
}

# Agent component writes must return a machine-readable error envelope.  The
# legacy abort helper intentionally calls log_error (which exits) for menu
# entrypoints, so keep a non-exiting equivalent for this API boundary.
managed_component_abort_state_transaction() {
  local snapshot_dir=$1
  local failure_message=$2

  if rollback_managed_state_snapshot "${snapshot_dir}" >/dev/null; then
    printf '[ERROR] %s，已恢复变更前的配置状态。\n' "${failure_message}" >&2
  else
    printf '[ERROR] %s，且自动回滚失败；事务快照保留在 %s。\n' \
      "${failure_message}" "${snapshot_dir}" >&2
  fi
  return 1
}

# Advanced component mutations use a durable journal.  The management flock
# serializes live writers, while this directory survives an abrupt process or
# host interruption and gives the next operator a bounded recovery path.
MANAGED_COMPONENT_TRANSACTION_RESTORE_ERROR=""
MANAGED_COMPONENT_RECOVERY_LAST_ERROR=""

managed_component_transaction_path_is_trusted() {
  local lock_dir=${1:-}

  [[ "${lock_dir}" == "${SB_COMPONENT_TRANSACTION_DIR}" &&
     -d "${lock_dir}" && ! -L "${lock_dir}" ]]
}

managed_component_transaction_begin() {
  local lock_dir=${1:-} operation=${2:-} expected_revision=${3:-}
  local before_active=${4:-false} owner_pid=${5:-} owner_start=${6:-}
  local transaction_next

  [[ "${lock_dir}" == "${SB_COMPONENT_TRANSACTION_DIR}" &&
     ! -e "${lock_dir}" && ! -L "${lock_dir}" ]] || return 1
  [[ "${operation}" =~ ^(create|replace|delete|rebuild|takeover)$ ]] || return 1
  [[ "${expected_revision}" =~ ^(0|[1-9][0-9]{0,15})$ ]] || return 1
  [[ "${before_active}" == true || "${before_active}" == false ]] || return 1
  [[ "${owner_pid}" =~ ^[1-9][0-9]*$ && "${owner_start}" =~ ^[0-9]+$ ]] || return 1

  umask 077
  mkdir -m 700 "${lock_dir}" || return 1
  transaction_next="${lock_dir}/transaction.next"
  if ! jq -n \
    --arg operation "${operation}" \
    --arg expected "${expected_revision}" \
    --argjson pid "${owner_pid}" \
    --arg start "${owner_start}" \
    --argjson before "${before_active}" \
    '{schema_version:1,operation:$operation,expected_revision:$expected,
      owner_pid:$pid,owner_start:$start,before_active:$before,phase:"prepare",
      new_revision:null,firewall_expected:false}' > "${transaction_next}"; then
    rm -rf -- "${lock_dir}"
    return 1
  fi
  if ! chmod 600 "${transaction_next}"; then
    rm -rf -- "${lock_dir}"
    return 1
  fi
  if ! mv -f -- "${transaction_next}" "${lock_dir}/transaction.json"; then
    rm -rf -- "${lock_dir}"
    return 1
  fi
}

managed_component_transaction_checkpoint() {
  local lock_dir=${1:-} phase=${2:-} transaction_next

  managed_component_transaction_path_is_trusted "${lock_dir}" || return 1
  [[ -f "${lock_dir}/transaction.json" && ! -L "${lock_dir}/transaction.json" ]] || return 1
  [[ "${phase}" =~ ^(prepare|snapshot|publish|resources|service|committed)$ ]] || return 1
  transaction_next="${lock_dir}/transaction.next"
  if ! jq --arg phase "${phase}" '.phase=$phase' \
    "${lock_dir}/transaction.json" > "${transaction_next}"; then
    rm -f -- "${transaction_next}"
    return 1
  fi
  chmod 600 "${transaction_next}" || return 1
  mv -f -- "${transaction_next}" "${lock_dir}/transaction.json"
}

managed_component_transaction_set_revision() {
  local lock_dir=${1:-} revision=${2:-} transaction_next

  managed_component_transaction_path_is_trusted "${lock_dir}" || return 1
  [[ -f "${lock_dir}/transaction.json" && ! -L "${lock_dir}/transaction.json" &&
     "${revision}" =~ ^(0|[1-9][0-9]{0,15})$ ]] || return 1
  transaction_next="${lock_dir}/transaction.next"
  if ! jq --argjson revision "${revision}" '.new_revision=$revision' \
    "${lock_dir}/transaction.json" > "${transaction_next}"; then
    rm -f -- "${transaction_next}"
    return 1
  fi
  chmod 600 "${transaction_next}" || return 1
  mv -f -- "${transaction_next}" "${lock_dir}/transaction.json"
}

managed_component_transaction_set_firewall_expected() {
  local lock_dir=${1:-} expected=${2:-false} transaction_next

  managed_component_transaction_path_is_trusted "${lock_dir}" || return 1
  [[ -f "${lock_dir}/transaction.json" && ! -L "${lock_dir}/transaction.json" &&
     ("${expected}" == true || "${expected}" == false) ]] || return 1
  transaction_next="${lock_dir}/transaction.next"
  if ! jq --argjson expected "${expected}" '.firewall_expected=$expected' \
    "${lock_dir}/transaction.json" > "${transaction_next}"; then
    rm -f -- "${transaction_next}"
    return 1
  fi
  chmod 600 "${transaction_next}" || return 1
  mv -f -- "${transaction_next}" "${lock_dir}/transaction.json"
}

managed_component_transaction_restore() {
  local lock_dir=${1:-} before_active firewall_expected firewall_journal
  local status=0 service_state
  MANAGED_COMPONENT_TRANSACTION_RESTORE_ERROR=""

  managed_component_transaction_path_is_trusted "${lock_dir}" || {
    MANAGED_COMPONENT_TRANSACTION_RESTORE_ERROR=component_rollback_failed
    return 1
  }
  [[ -f "${lock_dir}/transaction.json" && ! -L "${lock_dir}/transaction.json" ]] || {
    MANAGED_COMPONENT_TRANSACTION_RESTORE_ERROR=component_rollback_failed
    return 1
  }
  before_active=$(jq -r '.before_active' "${lock_dir}/transaction.json") || {
    MANAGED_COMPONENT_TRANSACTION_RESTORE_ERROR=component_rollback_failed
    return 1
  }
  firewall_expected=$(jq -r '.firewall_expected' "${lock_dir}/transaction.json") || {
    MANAGED_COMPONENT_TRANSACTION_RESTORE_ERROR=component_rollback_failed
    return 1
  }
  firewall_journal="${lock_dir}/snapshot/component-firewall.json"
  if [[ -e "${firewall_journal}" || -L "${firewall_journal}" ]]; then
    if [[ ! -f "${firewall_journal}" || -L "${firewall_journal}" ]]; then
      MANAGED_COMPONENT_TRANSACTION_RESTORE_ERROR=firewall_rollback_failed
      return 1
    fi
    if ! instance_firewall_rollback "${firewall_journal}"; then
      MANAGED_COMPONENT_TRANSACTION_RESTORE_ERROR=firewall_rollback_failed
      status=1
    fi
  elif [[ "${firewall_expected}" == true ]]; then
    printf '[ERROR] 高级组件事务防火墙日志缺失；无法证明外部状态已恢复。\n' >&2
    MANAGED_COMPONENT_TRANSACTION_RESTORE_ERROR=firewall_rollback_failed
    status=1
  fi

  if ! managed_state_snapshot_is_valid "${lock_dir}/snapshot" ||
     ! restore_managed_state_snapshot "${lock_dir}/snapshot"; then
    printf '[ERROR] 高级组件事务状态快照恢复失败；事务目录已保留供人工处理。\n' >&2
    MANAGED_COMPONENT_TRANSACTION_RESTORE_ERROR=${MANAGED_COMPONENT_TRANSACTION_RESTORE_ERROR:-component_rollback_failed}
    return 1
  fi

  if [[ "${before_active}" == true ]]; then
    if [[ ! -f "${SINGBOX_SERVICE_FILE}" ]] ||
       ! systemctl restart sing-box >/dev/null 2>&1 ||
       ! systemctl is-active --quiet sing-box; then
      MANAGED_COMPONENT_TRANSACTION_RESTORE_ERROR=${MANAGED_COMPONENT_TRANSACTION_RESTORE_ERROR:-component_rollback_failed}
      status=1
    fi
  elif [[ -f "${SINGBOX_SERVICE_FILE}" ]]; then
    service_state=$(systemctl is-active sing-box 2>/dev/null || printf 'unknown')
    case "${service_state}" in
      active)
        if ! systemctl stop sing-box >/dev/null 2>&1 || ! singbox_service_confirmed_stopped; then
          MANAGED_COMPONENT_TRANSACTION_RESTORE_ERROR=${MANAGED_COMPONENT_TRANSACTION_RESTORE_ERROR:-component_rollback_failed}
          status=1
        fi
        ;;
      inactive|failed) ;;
      *)
        MANAGED_COMPONENT_TRANSACTION_RESTORE_ERROR=${MANAGED_COMPONENT_TRANSACTION_RESTORE_ERROR:-component_rollback_failed}
        status=1
        ;;
    esac
  fi
  return "${status}"
}

managed_component_restore_service_activity() {
  local lock_dir=${1:-} before_active service_state

  managed_component_transaction_path_is_trusted "${lock_dir}" || return 1
  [[ -f "${lock_dir}/transaction.json" && ! -L "${lock_dir}/transaction.json" ]] || return 1
  before_active=$(jq -r '.before_active' "${lock_dir}/transaction.json") || return 1
  if [[ "${before_active}" == true ]]; then
    [[ -f "${SINGBOX_SERVICE_FILE}" ]] || return 1
    systemctl restart sing-box >/dev/null 2>&1 || return 1
    systemctl is-active --quiet sing-box
    return $?
  fi
  [[ -f "${SINGBOX_SERVICE_FILE}" ]] || return 0
  service_state=$(systemctl is-active sing-box 2>/dev/null || printf 'unknown')
  case "${service_state}" in
    inactive|failed) return 0 ;;
    active)
      systemctl stop sing-box >/dev/null 2>&1 || return 1
      singbox_service_confirmed_stopped
      ;;
    *) return 1 ;;
  esac
}

managed_component_abort_component_transaction() {
  local lock_dir=${1:-} snapshot_dir=${2:-} failure_message=${3:-} restore_service=${4:-n}

  if [[ -n "${snapshot_dir}" ]] && managed_state_snapshot_is_valid "${snapshot_dir}" &&
     restore_managed_state_snapshot "${snapshot_dir}"; then
    if [[ "${restore_service}" == y ]] && ! managed_component_restore_service_activity "${lock_dir}"; then
      printf '[ERROR] %s，配置状态已恢复但服务活动状态恢复失败；事务目录保留在 %s。\n' \
        "${failure_message}" "${lock_dir}" >&2
    elif rm -rf -- "${lock_dir}"; then
      printf '[ERROR] %s，已恢复变更前的配置状态。\n' "${failure_message}" >&2
    else
      printf '[ERROR] %s，配置状态已恢复但事务目录未能删除：%s。\n' \
        "${failure_message}" "${lock_dir}" >&2
    fi
  else
    printf '[ERROR] %s，且自动回滚失败；事务目录保留在 %s。\n' \
      "${failure_message}" "${lock_dir}" >&2
  fi
  return 1
}

managed_component_recovery_result_json() {
  local operation=${1:-unknown} revision=${2:-0} phase=${3:-prepare} status=${4:-unchanged}

  jq -cn --arg operation "${operation}" --arg revision "${revision}" --arg phase "${phase}" \
    --arg status "${status}" \
    '{ok:true,action:"component-recover",operation:$operation,revision:($revision|tonumber),
      status:$status,transaction:{phase:$phase,manual_intervention_required:false}}'
}

managed_component_recover_transaction() {
  local expected_revision=${1:-} lock_dir="${SB_COMPONENT_TRANSACTION_DIR}"
  local recovery_entries transaction_expected owner_pid owner_start current_start=""
  local phase operation revision snapshot recovery_fd state current_revision
  local recovery_error
  MANAGED_COMPONENT_RECOVERY_LAST_ERROR=""
  MANAGED_COMPONENT_RECOVERY_LAST_RESULT=""

  [[ ${EUID} -eq 0 ]] || {
    MANAGED_COMPONENT_RECOVERY_LAST_ERROR=root_required
    agent_json_error root_required "恢复必须以 root 执行。"
    return 1
  }
  [[ "${expected_revision}" =~ ^(0|[1-9][0-9]{0,15})$ ]] || {
    MANAGED_COMPONENT_RECOVERY_LAST_ERROR=invalid_arguments
    agent_json_error invalid_arguments "组件恢复需要有效的 --expected-revision。"
    return 1
  }
  acquire_managed_write_lock || {
    MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_write_busy
    agent_json_error component_write_busy "另一个管理进程正在执行；未开始组件恢复。"
    return 1
  }
  if [[ ! -e "${lock_dir}" ]]; then
    MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_recovery_unavailable
    agent_json_error component_recovery_unavailable "未找到可验证的待恢复高级组件事务。"
    return 1
  fi
  managed_component_transaction_path_is_trusted "${lock_dir}" || {
    MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_recovery_untrusted
    agent_json_error component_recovery_untrusted "高级组件事务目录不可信；未修改。"
    return 1
  }
  if [[ ! -e "${lock_dir}/transaction.json" ]]; then
    recovery_entries=$(find "${lock_dir}" -mindepth 1 -maxdepth 1 -printf '%f\n') || {
      MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_recovery_untrusted
      agent_json_error component_recovery_untrusted "高级组件事务目录无法安全读取；未修改。"
      return 1
    }
    if [[ -n "${recovery_entries}" && "${recovery_entries}" != transaction.next ]] ||
       [[ -e "${lock_dir}/transaction.next" &&
          ( ! -f "${lock_dir}/transaction.next" || -L "${lock_dir}/transaction.next" ) ]]; then
      MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_recovery_untrusted
      agent_json_error component_recovery_untrusted "主日志缺失且发现已准备材料；无法证明未发生变更。"
      return 1
    fi
    if ! rm -rf -- "${lock_dir}"; then
      MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_cleanup_failed
      agent_json_error component_cleanup_failed "组件事务未发生发布，但事务目录清理失败。"
      return 1
    fi
    MANAGED_COMPONENT_RECOVERY_LAST_RESULT=$(managed_component_recovery_result_json unknown "${expected_revision}" prepare unchanged) || return 1
    printf '%s\n' "${MANAGED_COMPONENT_RECOVERY_LAST_RESULT}"
    return 0
  fi
  [[ -f "${lock_dir}/transaction.json" && ! -L "${lock_dir}/transaction.json" ]] || {
    MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_recovery_untrusted
    agent_json_error component_recovery_untrusted "高级组件事务主日志不是可信普通文件；未修改。"
    return 1
  }
  if ! jq -e '
    .schema_version == 1 and
    (.operation | IN("create","replace","delete","rebuild","takeover")) and
    (.owner_pid | type == "number" and . == floor and . > 0) and
    (.owner_start | type == "string" and test("^[0-9]+$")) and
    (.before_active | type == "boolean") and
    (.phase | IN("prepare","snapshot","publish","resources","service","committed")) and
    (.new_revision == null or (.new_revision | type == "number" and . == floor and . >= 0 and . <= 9007199254740991)) and
    (.firewall_expected | type == "boolean")
  ' "${lock_dir}/transaction.json" >/dev/null 2>&1; then
    MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_recovery_untrusted
    agent_json_error component_recovery_untrusted "高级组件事务日志无法验证；请保留目录人工检查。"
    return 1
  fi
  transaction_expected=$(jq -r '.expected_revision' "${lock_dir}/transaction.json") || return 1
  if [[ "${transaction_expected}" != "${expected_revision}" ]]; then
    MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_revision_mismatch
    agent_json_error component_revision_mismatch "组件事务原 revision 与请求不匹配；未恢复。"
    return 1
  fi
  operation=$(jq -r '.operation' "${lock_dir}/transaction.json") || return 1
  owner_pid=$(jq -r '.owner_pid' "${lock_dir}/transaction.json") || return 1
  owner_start=$(jq -r '.owner_start' "${lock_dir}/transaction.json") || return 1
  if [[ -r "/proc/${owner_pid}/stat" ]]; then
    current_start=$(awk '{print $22}' "/proc/${owner_pid}/stat") || {
      MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_recovery_untrusted
      agent_json_error component_recovery_untrusted "无法验证原组件写进程；未恢复。"
      return 1
    }
    if [[ "${current_start}" == "${owner_start}" ]]; then
      MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_transaction_active
      agent_json_error component_transaction_active "原组件写进程仍在运行；禁止并发恢复。"
      return 1
    fi
  fi
  command -v flock >/dev/null 2>&1 && [[ ! -L "${lock_dir}/recovery.flock" ]] || {
    MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_recovery_unavailable
    agent_json_error component_recovery_unavailable "组件恢复需要可用且可信的 flock。"
    return 1
  }
  exec {recovery_fd}>"${lock_dir}/recovery.flock" || {
    MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_recovery_unavailable
    agent_json_error component_recovery_unavailable "无法打开组件恢复锁；未修改。"
    return 1
  }
  flock -n "${recovery_fd}" || {
    MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_recovery_active
    agent_json_error component_recovery_active "另一个恢复进程已取得组件恢复锁。"
    return 1
  }
  phase=$(jq -r '.phase' "${lock_dir}/transaction.json") || return 1
  revision=$(jq -r '.new_revision // .expected_revision' "${lock_dir}/transaction.json") || return 1
  snapshot="${lock_dir}/snapshot"
  if [[ "${phase}" == committed ]]; then
    state=$(managed_component_state_json) || {
      MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_recovery_untrusted
      agent_json_error component_recovery_untrusted "已提交组件事务的当前 state 无法安全读取；事务目录保留。"
      return 1
    }
    current_revision=$(jq -r '.revision | tostring' <<< "${state}") || return 1
    if [[ "${current_revision}" != "${revision}" ]]; then
      MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_recovery_untrusted
      agent_json_error component_recovery_untrusted "已提交组件事务 revision 与当前 state 不一致；事务目录保留。"
      return 1
    fi
    if ! rm -rf -- "${lock_dir}"; then
      MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_cleanup_failed
      agent_json_error component_cleanup_failed "组件事务已提交，但事务目录清理失败。"
      return 1
    fi
    MANAGED_COMPONENT_RECOVERY_LAST_RESULT=$(managed_component_recovery_result_json "${operation}" "${revision}" "${phase}" committed) || return 1
    printf '%s\n' "${MANAGED_COMPONENT_RECOVERY_LAST_RESULT}"
    return 0
  fi
  if [[ "${phase}" == prepare && ! -e "${snapshot}" ]]; then
    if ! rm -rf -- "${lock_dir}"; then
      MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_cleanup_failed
      agent_json_error component_cleanup_failed "组件事务尚未发布，但事务目录清理失败。"
      return 1
    fi
    MANAGED_COMPONENT_RECOVERY_LAST_RESULT=$(managed_component_recovery_result_json "${operation}" "${expected_revision}" "${phase}" unchanged) || return 1
    printf '%s\n' "${MANAGED_COMPONENT_RECOVERY_LAST_RESULT}"
    return 0
  fi
  if ! managed_state_snapshot_is_valid "${snapshot}"; then
    MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_recovery_untrusted
    agent_json_error component_recovery_untrusted "组件事务快照缺失或不可信；未自动恢复。"
    return 1
  fi
  if ! managed_component_transaction_restore "${lock_dir}"; then
    recovery_error=${MANAGED_COMPONENT_TRANSACTION_RESTORE_ERROR:-component_rollback_failed}
    MANAGED_COMPONENT_RECOVERY_LAST_ERROR=${recovery_error}
    case "${recovery_error}" in
      firewall_rollback_failed)
        agent_json_error firewall_rollback_failed "组件事务状态已尝试恢复，但防火墙外部资源仍不确定；事务目录已保留。" ;;
      *)
        agent_json_error component_rollback_failed "组件事务自动回滚失败；事务目录已保留供人工恢复。" ;;
    esac
    return 1
  fi
  if ! rm -rf -- "${lock_dir}"; then
    MANAGED_COMPONENT_RECOVERY_LAST_ERROR=component_cleanup_failed
    agent_json_error component_cleanup_failed "组件事务已回滚，但事务目录清理失败。"
    return 1
  fi
  MANAGED_COMPONENT_RECOVERY_LAST_RESULT=$(managed_component_recovery_result_json "${operation}" "${expected_revision}" "${phase}" rolled_back) || return 1
  printf '%s\n' "${MANAGED_COMPONENT_RECOVERY_LAST_RESULT}"
}

# Validate only managed candidates, not arbitrary existing configurations on
# read/upgrade. Explicit component identities are required; DNS, certificates,
# HTTP clients and rule sets have separate upstream tag namespaces. This is a
# reference preflight, never a substitute for the target core's `check`.
validate_managed_component_graph() {
  local config_file=${1:-} graph_status
  if [[ $# -ne 1 || ! -f "${config_file}" || ! -r "${config_file}" ]]; then
    printf '[ERROR] component_graph: invalid input\n' >&2
    return 1
  fi
  # Read the candidate once. Errors are fixed classifications: neither jq
  # diagnostics nor user-controlled tags, paths or credentials reach stderr.
  if ! graph_status=$(jq -sr '
    def bad: error("invalid field type");
    def object: if type == "object" then . else bad end;
    def array: if type == "array" then . else bad end;
    def text: if type == "string" then . else bad end;
    def name: text | if length > 0 then . else bad end;
    def list: if type == "array" then map(name) else [name] end;
    def field($key; $default): if has($key) then .[$key] else $default end;
    def records($items; $space; $role; $typed; $explicit):
      $items | array | to_entries[] | .key as $index | .value | object |
      (if $typed then .type | name else (.type // "") end) as $type |
      (if $explicit then .tag | name
       else (field("tag"; "") | text) as $tag |
         if $tag == "" then ($index | tostring) else $tag end end) as $tag |
      {id: ($space + ":" + $tag), space: $space, role: $role, tag: $tag,
       kind: $type, value: .};
    def ref($owner; $space; $value; $dependency):
      $value | text | select(length > 0) |
      {from: $owner, space: $space, tag: ., dependency: $dependency};
    def optional_ref($owner; $space; $key; $dependency):
      if has($key) then ref($owner; $space; .[$key]; $dependency) else empty end;
    def list_refs($owner; $space; $key):
      if has($key) then .[$key] | list[] | ref($owner; $space; .; false)
      else empty end;
    def resolver_tag:
      if type == "string" then text
      elif type == "object" then .server | name else bad end;
    def domain_host:
      type == "string" and length > 0 and
      (test("^[0-9.]+$") | not) and (contains(":") | not);
    def dial_refs($owner; $dependency; $default_resolver):
      object |
      optional_ref($owner; "outbound"; "detour"; true),
      optional_ref($owner; "netns"; "netns"; true),
      (if has("domain_resolver") then
         ref($owner; "dns"; (.domain_resolver | resolver_tag); $dependency)
       elif $dependency and (.detour // "") == "" then
         ref($owner; "dns"; $default_resolver; true)
       else empty end);
    def http_refs($owner; $default_resolver):
      if type == "string" then ref($owner; "http"; .; true)
      elif type == "object" then dial_refs($owner; true; $default_resolver)
      else bad end;
    def provider_refs($owner; $default_resolver):
      object | (.type | name) as $type |
      if $type == "acme" or $type == "cloudflare-origin-ca" then
        if has("http_client") then .http_client | http_refs($owner; $default_resolver)
        else empty end
      elif $type == "tailscale" then
        optional_ref($owner; "tailscale"; "endpoint"; true)
      else empty end;
    def tls_refs($owner; $default_resolver):
      object |
      (if has("certificate_provider") then
         .certificate_provider |
         if type == "string" then name | ref($owner; "cert"; .; true)
         else provider_refs($owner; $default_resolver) end
       else empty end),
      (if has("acme") then .acme | object |
         if has("http_client") then .http_client | http_refs($owner; $default_resolver)
         else empty end
       else empty end),
      (if has("reality") then .reality | object |
         if has("handshake") then .handshake |
           dial_refs($owner; (.server | domain_host); $default_resolver)
         else empty end
       else empty end);
    def rule_refs($owner; $dns):
      array[] | object | . as $rule |
      list_refs($owner; "inbound"; "inbound"),
      list_refs($owner; "ruleset"; "rule_set"),
      (if $dns then
         (list_refs($owner; "outbound"; "outbound") | select(.tag != "any")),
         optional_ref($owner; "dns"; "server"; false)
       else
         optional_ref($owner; "outbound"; "outbound"; false),
         (if .action == "resolve" then optional_ref($owner; "dns"; "server"; false)
          else empty end)
       end),
      (if $rule | has("rules") then $rule.rules | rule_refs($owner; $dns)
       else empty end);
    # Build adjacency once. Kahn elimination does not revisit all paths in a
    # shared selector DAG and cannot recurse forever on a cycle.
    def acyclic($edges):
      (reduce $edges[] as $edge ({degree: {}, next: {}};
        .degree[$edge.from] = (.degree[$edge.from] // 0) |
        .degree[$edge.to] = ((.degree[$edge.to] // 0) + 1) |
        .next[$edge.from] += [$edge.to])) as $graph |
      ($graph + {queue: [$graph.degree | to_entries[] | select(.value == 0) | .key],
                 cursor: 0}) |
      until(.cursor == (.queue | length);
        .queue[.cursor] as $node | .cursor += 1 |
        reduce (.next[$node] // [])[] as $target (.;
          .degree[$target] -= 1 |
          if .degree[$target] == 0 then .queue += [$target] else . end)) |
      .cursor == (.degree | length);
    try (
      if length == 1 and (.[0] | type == "object") then .[0]
      else error("invalid config shape") end |
      . as $root |
      (field("route"; {}) | object) as $route |
      (field("dns"; {}) | object) as $dns |
      ($route | if has("default_domain_resolver") then
         .default_domain_resolver | resolver_tag else "" end) as $default_resolver |
      [records(field("inbounds"; []); "component"; "inbound"; true; true),
       records(field("outbounds"; []); "component"; "outbound"; true; true),
       records(field("endpoints"; []); "component"; "endpoint"; true; true),
       records(field("certificate_providers"; []); "cert"; "cert"; true; false),
       records(field("http_clients"; []); "http"; "http"; false; true),
       records(field("services"; []); "service"; "service"; true; false),
       records(field("network_namespaces"; []); "netns"; "netns"; false; true),
       records(($dns | field("servers"; [])); "dns"; "dns"; false; false),
       ($route | field("rule_set"; []) | array[] | object | . as $set |
         (.tag | list | if length > 0 then .[] else bad end) |
         {id: ("ruleset:" + .), space: "ruleset", role: "ruleset", tag: .,
          kind: ($set.type // "inline"), value: $set})] as $nodes |
      if ($nodes | group_by(.id) | any(.[]; length > 1)) then
        error("duplicate tag") else . end |
      # Aliases resolve to the same component node, not different graph nodes.
      (reduce $nodes[] as $node ({};
        .[$node.space][$node.tag] = $node.id |
        if $node.role == "inbound" or $node.role == "endpoint" then
          .inbound[$node.tag] = $node.id else . end |
        if $node.role == "outbound" or $node.role == "endpoint" then
          .outbound[$node.tag] = $node.id else . end |
        if $node.role == "endpoint" and $node.kind == "tailscale" then
          .tailscale[$node.tag] = $node.id else . end)) as $spaces |
      [($nodes[] | . as $node | .value |
        if $node.role == "inbound" or
           ($node.role == "endpoint" and $node.kind == "openvpn-server") then
          optional_ref($node.id; "inbound"; "detour"; true),
          optional_ref($node.id; "netns"; "netns"; true)
        elif $node.role == "outbound" or $node.role == "endpoint" or
             $node.role == "http" or $node.role == "dns" then
          dial_refs($node.id; (($node.role == "http") or (.server | domain_host)); $default_resolver)
        else empty end),
       ($nodes[] | select(.role == "outbound" and
          (.kind == "selector" or .kind == "urltest")) | . as $node | .value |
          (.outbounds | array | if length > 0 then map(name) else bad end) as $members |
          (if has("default") then (.default | text) as $default |
            if $default != "" and ($members | index($default)) == null then bad
            else empty end else empty end),
          ($members[] | ref($node.id; "outbound"; .; true))),
       ($nodes[] | select(.role == "inbound" or .role == "service" or
          (.role == "endpoint" and .kind == "openvpn-server")) |
          . as $node | .value |
          if has("tls") then .tls | tls_refs($node.id; $default_resolver) else empty end),
       ($nodes[] | select(.role == "inbound" and .kind == "cloudflared") |
          . as $node | .value |
          (if has("control_dialer") then .control_dialer | dial_refs($node.id; true; $default_resolver) else empty end),
          (if has("tunnel_dialer") then .tunnel_dialer | dial_refs($node.id; true; $default_resolver) else empty end)),
       ($nodes[] | select(.role == "inbound" and .kind == "tun") |
          . as $node | .value |
          list_refs($node.id; "ruleset"; "route_address_set"),
          list_refs($node.id; "ruleset"; "route_exclude_address_set")),
       ($nodes[] | select(.role == "cert") | . as $node | .value |
          provider_refs($node.id; $default_resolver)),
       ($nodes[] | select((.role == "inbound" or .role == "outbound") and
          .kind == "hysteria2") | . as $node | .value |
          if has("realm") then .realm | object |
            (if has("http_client") then .http_client | http_refs($node.id; $default_resolver)
             else empty end),
            (if $node.role == "inbound" and has("stun_domain_resolver") then
               ref($node.id; "dns"; (.stun_domain_resolver | resolver_tag); true)
             else empty end)
          else empty end),
       ($nodes[] | select(.role == "dns") | . as $node | .value |
          # DNS transport managers register explicit resolver dependencies
          # even for IP servers; unlike ordinary outbound dialers these must
          # be checked for startup cycles independently of the target address.
          (if has("domain_resolver") then
             ref($node.id; "dns"; (.domain_resolver | resolver_tag); true)
           else empty end),
          optional_ref($node.id; "dns"; "address_resolver"; true),
          (if $node.kind == "tailscale" then
             optional_ref($node.id; "tailscale"; "endpoint"; true) else empty end)),
       ($nodes[] | select(.role == "ruleset") | . as $node | .value |
          optional_ref($node.id; "outbound"; "download_detour"; true),
          (if has("http_client") then .http_client | http_refs($node.id; $default_resolver)
           else empty end)),
       ($nodes[] | select(.role == "service") | . as $node | .value |
          optional_ref($node.id; (if $node.kind == "ocm" or $node.kind == "ccm"
            then "outbound" else "inbound" end); "detour"; true),
          optional_ref($node.id; "netns"; "netns"; true),
          (if $node.kind == "api" and has("dashboard") then .dashboard | object |
            if has("http_client") then .http_client | http_refs($node.id; $default_resolver)
            else empty end else empty end),
          (if $node.kind == "derp" then
            (list_refs($node.id; "tailscale"; "verify_client_endpoint") | .dependency = true),
            (field("verify_client_url"; []) |
              if type == "array" then .[] else . end |
              if type == "string" then empty else http_refs($node.id; $default_resolver) end),
            (field("mesh_with"; []) | array[] | dial_refs($node.id; (.server | domain_host); $default_resolver))
           else empty end)),
       ($route | optional_ref("root:route"; "outbound"; "final"; false),
          optional_ref("root:route"; "http"; "default_http_client"; false),
          ref("root:route"; "dns"; $default_resolver; false),
          (field("rules"; []) | rule_refs("root:route"; false)),
          ((.geoip // {}), (.geosite // {}) | object |
            optional_ref("root:route"; "outbound"; "download_detour"; false))),
       ($dns | optional_ref("root:dns"; "dns"; "final"; false),
          (field("rules"; []) | rule_refs("root:dns"; true))),
       ($root | field("experimental"; {}) | object | field("clash_api"; {}) | object |
          optional_ref("root:experimental"; "outbound"; "external_ui_download_detour"; false))
      ] as $refs |
      if any($refs[]; $spaces[.space][.tag] == null) then
        error("unknown reference") else . end |
      [$refs[] | select(.dependency) |
        {from: .from, to: $spaces[.space][.tag]}] | unique as $edges |
      if acyclic($edges) then "ok" else error("dependency cycle") end
    ) catch (
      if . == "invalid config shape" or . == "invalid field type" or
         . == "duplicate tag" or . == "unknown reference" or . == "dependency cycle"
      then . else "invalid field type" end
    )
  ' -- "${config_file}" 2>/dev/null); then
    graph_status="invalid config shape"
  fi
  if [[ "${graph_status}" != "ok" ]]; then
    printf '[ERROR] component_graph: %s; 配置未发布。\n' "${graph_status}" >&2
    return 1
  fi
}

# --- Config Generator ---
publish_managed_config_candidate() (
  local source_file=${1:-} candidate="" backup_candidate=""
  umask 077
  [[ -f "${source_file}" && ! -L "${source_file}" && -x "${SINGBOX_BIN_PATH}" ]] || return 1
  candidate=$(mktemp "${SINGBOX_CONFIG_DIR}/.config.json.candidate.XXXXXX") || return $?
  trap 'rm -f -- "${candidate}" "${backup_candidate}"' EXIT
  head -c 4194305 -- "${source_file}" > "${candidate}" || return $?
  [[ "$(wc -c < "${candidate}")" -le 4194304 ]] || return 1
  jq -es 'length == 1 and (.[0] | type == "object")' "${candidate}" >/dev/null 2>&1 || return 1
  validate_managed_component_graph "${candidate}" || return $?
  validate_managed_listener_resources "${candidate}" || return $?
  "${SINGBOX_BIN_PATH}" check -c "${candidate}" >&2 || return $?
  chmod 600 "${candidate}" || return $?
  if [[ -f "${SINGBOX_CONFIG_FILE}" ]]; then
    backup_candidate=$(mktemp "${SINGBOX_CONFIG_DIR}/.config.json.backup.XXXXXX") || return $?
    cp -p "${SINGBOX_CONFIG_FILE}" "${backup_candidate}" || return $?
    chmod 600 "${backup_candidate}" || return $?
    mv -f "${backup_candidate}" "${SINGBOX_CONFIG_FILE}.bak" || return $?
  fi
  mv -f "${candidate}" "${SINGBOX_CONFIG_FILE}" || return $?
)

generate_config_candidate() {
  local inventory_state_file=${1:-}
  local inbound_file="" provider_file="" protocol_rule_file="" instance_outbound_rule_file=""
  local config_candidate="" backup_candidate="" protocol
  local exit_cleanup_command effective_protocols
  local inbounds_json certificate_providers_json protocol_rules_json instance_outbound_rules_json
  local managed_components_json managed_route_options_json

  # Force ensure jq is installed
  if ! command -v jq &>/dev/null; then
    log_warn "未检测到 jq，正在尝试自动安装以确保配置生成安全..."
    get_os_info && install_dependencies
  fi

  if [[ ! -x "${SINGBOX_BIN_PATH}" ]]; then
    log_warn "无法生成配置：缺少可执行的 sing-box 二进制 ${SINGBOX_BIN_PATH}。"
    return 1
  fi

  # Inspect the complete live inventory before discovery or resource creation.
  # A supported first inbound is not evidence that the rest can be rebuilt.
  validate_live_inbound_inventory "${SINGBOX_CONFIG_FILE}" "${inventory_state_file}" || return 1

  # Capture discovery before resource preparation; process substitution hides
  # its failure status and could otherwise publish an empty/partial config.
  effective_protocols=$(list_effective_protocols "${inventory_state_file}") || return 1
  [[ -n "${effective_protocols}" ]] || return 1
  managed_components_json=$(managed_component_render_json) || {
    log_warn "高级组件状态无效，禁止生成可能丢失组件的配置。"
    return 1
  }
  managed_route_options_json=$(managed_component_tun_route_options_json "${managed_components_json}") || return 1

  log_info "正在生成配置 (目标 sing-box $(resolve_config_target_singbox_version)，Endpoint 架构 & 安全注入)..."
  mkdir -p "${SINGBOX_CONFIG_DIR}" || return 1
  ensure_warp_routing_assets || return 1
  load_warp_route_settings || return 1

  # Endpoints Logic
  local w_key="" w_v4="" w_v6="" w_client_id="" w_reserved='[]' enable_warp_endpoint
  enable_warp_endpoint="${SB_ENABLE_WARP}"
  if [[ "${enable_warp_endpoint}" != "y" ]] && instance_outbound_requires_warp; then
    enable_warp_endpoint="y"
  fi

  if [[ "${enable_warp_endpoint}" == "y" ]]; then
    register_warp || return 1
    w_key=$(grep "WARP_PRIV_KEY" "${SB_WARP_KEY_FILE}" | cut -d'=' -f2- | tr -d '\r\n ')
    w_v4=$(grep "WARP_V4" "${SB_WARP_KEY_FILE}" | cut -d'=' -f2- | tr -d '\r\n ')
    w_v6=$(grep "WARP_V6" "${SB_WARP_KEY_FILE}" | cut -d'=' -f2- | tr -d '\r\n ')
    w_client_id=$(grep "WARP_CLIENT_ID" "${SB_WARP_KEY_FILE}" | cut -d'=' -f2- | tr -d '\r\n ')
    w_reserved=$(warp_client_id_to_reserved_json "${w_client_id}")
  fi

  refresh_warp_route_assets || return 1
  ensure_stack_mode_state_loaded || return 1

  inbound_file=$(mktemp) || return 1
  if ! provider_file=$(mktemp); then
    rm -f "${inbound_file}"
    return 1
  fi
  if ! protocol_rule_file=$(mktemp); then
    rm -f "${inbound_file}" "${provider_file}"
    return 1
  fi
  if ! instance_outbound_rule_file=$(mktemp); then
    rm -f "${inbound_file}" "${provider_file}" "${protocol_rule_file}"
    return 1
  fi
  if ! config_candidate=$(mktemp "${SINGBOX_CONFIG_DIR}/.config.json.candidate.XXXXXX"); then
    rm -f "${inbound_file}" "${provider_file}" "${protocol_rule_file}" "${instance_outbound_rule_file}"
    return 1
  fi
  printf -v exit_cleanup_command 'rm -f -- %q %q %q %q %q' \
    "${inbound_file}" "${provider_file}" "${protocol_rule_file}" \
    "${instance_outbound_rule_file}" "${config_candidate}"
  trap "${exit_cleanup_command}" EXIT

  while IFS= read -r protocol; do
    [[ -z "${protocol}" ]] && continue
    if ! load_protocol_state "${protocol}"; then
      rm -f "${inbound_file}" "${provider_file}" "${protocol_rule_file}" "${instance_outbound_rule_file}" "${config_candidate}"
      return 1
    fi
    if ! append_protocol_fragment "${protocol}" inbound "${inbound_file}"; then
      rm -f "${inbound_file}" "${provider_file}" "${protocol_rule_file}" "${instance_outbound_rule_file}" "${config_candidate}"
      return 1
    fi
    if ! append_protocol_fragment "${protocol}" certificate "${provider_file}"; then
      rm -f "${inbound_file}" "${provider_file}" "${protocol_rule_file}" "${instance_outbound_rule_file}" "${config_candidate}"
      return 1
    fi
    if ! append_protocol_fragment "${protocol}" route "${protocol_rule_file}"; then
      rm -f "${inbound_file}" "${provider_file}" "${protocol_rule_file}" "${instance_outbound_rule_file}" "${config_candidate}"
      return 1
    fi
    if [[ "${protocol}" == "vless-reality" ]]; then
      if ! build_vless_reality_instance_outbound_rules_json >> "${instance_outbound_rule_file}"; then
        rm -f "${inbound_file}" "${provider_file}" "${protocol_rule_file}" "${instance_outbound_rule_file}" "${config_candidate}"
        return 1
      fi
    fi
  done <<< "${effective_protocols}"

  if ! inbounds_json=$(jq -s . "${inbound_file}"); then
    rm -f "${inbound_file}" "${provider_file}" "${protocol_rule_file}" "${instance_outbound_rule_file}" "${config_candidate}"
    return 1
  fi
  if ! certificate_providers_json=$(jq -s . "${provider_file}"); then
    rm -f "${inbound_file}" "${provider_file}" "${protocol_rule_file}" "${instance_outbound_rule_file}" "${config_candidate}"
    return 1
  fi
  if ! protocol_rules_json=$(jq -s 'add // []' "${protocol_rule_file}"); then
    rm -f "${inbound_file}" "${provider_file}" "${protocol_rule_file}" "${instance_outbound_rule_file}" "${config_candidate}"
    return 1
  fi
  if ! instance_outbound_rules_json=$(jq -s 'add // []' "${instance_outbound_rule_file}"); then
    rm -f "${inbound_file}" "${provider_file}" "${protocol_rule_file}" "${instance_outbound_rule_file}" "${config_candidate}"
    return 1
  fi

  if ! jq -n \
    --arg adv_route "${SB_ADVANCED_ROUTE}" \
    --arg enable_warp "${SB_ENABLE_WARP}" \
    --arg enable_warp_endpoint "${enable_warp_endpoint}" \
    --arg warp_mode "${SB_WARP_ROUTE_MODE}" \
    --arg w_key "${w_key}" \
    --arg w_v4 "${w_v4}/32" \
    --arg w_v6 "${w_v6}/128" \
    --argjson w_reserved "${w_reserved}" \
    --arg outbound_stack_mode "${SB_OUTBOUND_STACK_MODE}" \
    --argjson inbounds "${inbounds_json}" \
    --argjson managed_components "${managed_components_json}" \
    --argjson certificate_providers "${certificate_providers_json}" \
    --argjson protocol_rules "${protocol_rules_json}" \
    --argjson instance_outbound_rules "${instance_outbound_rules_json}" \
    --argjson managed_route_options "${managed_route_options_json}" \
    --argjson ai_domains "${WARP_AI_ROUTE_DOMAINS_JSON}" \
    --argjson ai_domain_suffixes "${WARP_AI_ROUTE_DOMAIN_SUFFIXES_JSON}" \
    --argjson stream_domains "${WARP_STREAM_ROUTE_DOMAINS_JSON}" \
    --argjson stream_domain_suffixes "${WARP_STREAM_ROUTE_DOMAIN_SUFFIXES_JSON}" \
    --argjson custom_domains "${SB_WARP_CUSTOM_DOMAINS_JSON}" \
    --argjson custom_domain_suffixes "${SB_WARP_CUSTOM_DOMAIN_SUFFIXES_JSON}" \
    --argjson local_rule_sets "${SB_WARP_LOCAL_RULE_SETS_JSON}" \
    --argjson remote_rule_sets "${SB_WARP_REMOTE_RULE_SETS_JSON}" \
    --argjson warp_rule_set_tags "${SB_WARP_RULE_SET_TAGS_JSON}" \
    '{
      "log": { "level": "info", "timestamp": true },
      "dns": {
        "servers": [
          {
            "type": "local",
            "tag": "local-dns"
          }
        ],
        "strategy": $outbound_stack_mode
      },
      "endpoints": ((if $enable_warp_endpoint == "y" then [
        {
          "type": "wireguard",
          "tag": "warp-ep",
          "address": [ $w_v4, $w_v6 ],
          "private_key": $w_key,
          "peers": [
            {
              "address": "engage.cloudflareclient.com",
              "port": 2408,
              "public_key": "bmXOC+F1FxEMF9dyiK2H5/1SUtzH0JuVo51h2wPfgyo=",
              "reserved": $w_reserved,
              "allowed_ips": [ "0.0.0.0/0", "::/0" ]
            }
          ],
          "mtu": 1280
        }
      ] else [] end) + ($managed_components.endpoints // [])),
      "inbounds": ($inbounds + ($managed_components.inbounds // [])),
      "outbounds": ([
        {
          "type": "direct",
          "tag": "direct",
          "domain_resolver": {
            "server": "local-dns",
            "strategy": $outbound_stack_mode
          }
        },
        { "type": "block", "tag": "block" }
      ] + ($managed_components.outbounds // [])),
      "route": ({
        "rule_set": (
          if $enable_warp == "y" and $warp_mode == "selective" then
            $local_rule_sets + $remote_rule_sets
          else
            []
          end
        ),
        "rules": (
          ($managed_components.route_rules // []) +
          $instance_outbound_rules +
          $protocol_rules +
          (if $adv_route == "y" then [ { "ip_is_private": true, "action": "reject" } ] else [] end) +
          (
            if $enable_warp == "y" and $warp_mode == "selective" then
              [
                {
                  "domain": $ai_domains,
                  "domain_suffix": $ai_domain_suffixes,
                  "action": "route",
                  "outbound": "warp-ep"
                },
                {
                  "domain": $stream_domains,
                  "domain_suffix": $stream_domain_suffixes,
                  "action": "route",
                  "outbound": "warp-ep"
                }
              ] +
              (
                if ($custom_domains | length) > 0 or ($custom_domain_suffixes | length) > 0 then
                  [
                    {
                      "domain": $custom_domains,
                      "domain_suffix": $custom_domain_suffixes,
                      "action": "route",
                      "outbound": "warp-ep"
                    }
                  ]
                else
                  []
                end
              ) +
              (
                if ($warp_rule_set_tags | length) > 0 then
                  [
                    {
                      "rule_set": $warp_rule_set_tags,
                      "action": "route",
                      "outbound": "warp-ep"
                    }
                  ]
                else
                  []
                end
              )
            else
              []
            end
          )
        ),
        "final": (if $enable_warp == "y" and $warp_mode == "all" then "warp-ep" else "direct" end)
      } + $managed_route_options)
    } + (
      if ($certificate_providers | length) > 0 then
        { "certificate_providers": $certificate_providers }
      else
        {}
      end
    )' > "${config_candidate}"; then
    rm -f "${inbound_file}" "${provider_file}" "${protocol_rule_file}" "${instance_outbound_rule_file}" "${config_candidate}"
    return 1
  fi

  if ! publish_managed_config_candidate "${config_candidate}"; then
    rm -f "${inbound_file}" "${provider_file}" "${protocol_rule_file}" "${instance_outbound_rule_file}" "${config_candidate}"
    return 1
  fi

  rm -f "${inbound_file}" "${provider_file}" "${protocol_rule_file}" "${instance_outbound_rule_file}" "${config_candidate}"
  trap - EXIT
}

generate_config() {
  local inventory_state_file=${1:-} snapshot_dir

  validate_live_inbound_inventory "${SINGBOX_CONFIG_FILE}" "${inventory_state_file}" || return 1
  snapshot_dir=$(create_managed_state_snapshot) || return 1
  if ! (generate_config_candidate "${inventory_state_file}"); then
    rollback_managed_state_snapshot "${snapshot_dir}" || true
    return 1
  fi
  if ! discard_managed_state_snapshot "${snapshot_dir}"; then
    log_warn "配置已发布，但临时事务快照未能删除: ${snapshot_dir}。"
  fi
}

# --- Uninstaller ---
perform_singbox_runtime_uninstall() {
  local lib_path expected_hash actual_hash

  log_info "正在彻底卸载 sing-box 环境..."
  if command -v tc >/dev/null 2>&1; then
    clear_vless_reality_qos_rules
  fi
  systemctl stop sing-box &>/dev/null || true
  systemctl disable sing-box &>/dev/null || true
  rm -f "${SINGBOX_SERVICE_FILE}"
  systemctl daemon-reload
  rm -f "${SINGBOX_BIN_PATH}"
  lib_path=$(singbox_library_path || printf '')
  if [[ -n "${lib_path}" && -f "${SB_NAIVE_LIBRARY_MARKER}" ]]; then
    expected_hash=$(tr -d '[:space:]' < "${SB_NAIVE_LIBRARY_MARKER}")
    actual_hash=''
    if [[ -f "${lib_path}" && ! -L "${lib_path}" ]]; then
      actual_hash=$(sha256sum "${lib_path}" | awk '{print $1}')
    fi
    if [[ -n "${expected_hash}" && "${expected_hash}" == "${actual_hash}" ]]; then
      rm -f "${lib_path}"
      if [[ "$(dirname "${lib_path}")" == "/usr/local/lib" ]] &&
         command -v ldconfig >/dev/null 2>&1; then
        ldconfig || log_warn "libcronet.so 已删除，但 ldconfig 缓存刷新失败。"
      fi
    else
      log_warn "检测到 libcronet.so 已被外部修改，保留 ${lib_path} 以避免误删。"
    fi
  fi
  rm -rf "${SINGBOX_CONFIG_DIR}"
  print_success "sing-box 服务、二进制和配置目录已彻底删除。"
}

perform_full_uninstall() {
  perform_singbox_runtime_uninstall
  rm -f "${SBV_BIN_PATH}"
  print_success "全局命令 sbv 已删除。"
}

uninstall_singbox() {
  echo ""
  print_warn "该操作会彻底删除 sing-box 服务、配置目录和密钥，但会保留全局命令 sbv。"
  read -rp "确认继续吗？[y/N]: " confirm
  if [[ ! "${confirm}" =~ ^[Yy]$ ]]; then
    log_info "已取消卸载。"
    return 0
  fi

  perform_singbox_runtime_uninstall
  exit 0
}

# Uninstall script itself
uninstall_script() {
  local deleted_cfg="n"
  read -rp "是否同时删除项目配置文件目录 (/root/sing-box-vps)? [y/N]: " del_cfg
  if [[ "${del_cfg}" =~ ^[Yy]$ ]]; then
    rm -rf "${SB_PROJECT_DIR}"
    deleted_cfg="y"
    print_info "配置文件目录已删除。"
  fi
  
  if [[ "${deleted_cfg}" == "y" ]]; then
    print_info "正在删除全局命令 sbv..."
  else
    log_info "正在删除全局命令 sbv..."
  fi
  rm -f "${SBV_BIN_PATH}"
  if [[ "${deleted_cfg}" == "y" ]]; then
    print_success "管理脚本已卸载。"
  else
    log_success "管理脚本已卸载。"
  fi
  exit 0
}

# --- UI & Main ---
term_columns() {
  local cols=${COLUMNS:-}

  if [[ "${cols}" =~ ^[0-9]+$ ]] && (( cols > 0 )); then
    printf '%s' "${cols}"
    return 0
  fi

  if command -v tput >/dev/null 2>&1; then
    cols=$(tput cols 2>/dev/null || true)
    if [[ "${cols}" =~ ^[0-9]+$ ]] && (( cols > 0 )); then
      printf '%s' "${cols}"
      return 0
    fi
  fi

  cols=$(stty size 2>/dev/null | awk '{print $2}' || true)
  if [[ "${cols}" =~ ^[0-9]+$ ]] && (( cols > 0 )); then
    printf '%s' "${cols}"
    return 0
  fi

  printf '80'
}

compact_ui_width() {
  local width

  width=$(term_columns)
  if (( width < 1 )); then
    width=1
  elif (( width > UI_COMPACT_MAX_WIDTH )); then
    width=${UI_COMPACT_MAX_WIDTH}
  fi

  printf '%s' "${width}"
}

repeat_char() {
  local char=$1
  local count=$2
  local output=""
  local i

  for ((i = 0; i < count; i++)); do
    output+="${char}"
  done

  printf '%s' "${output}"
}

safe_clear_screen() {
  if [[ -z "${TERM:-}" ]] || [[ "${TERM}" == "dumb" ]]; then
    return 0
  fi

  if [[ ! -t 1 ]]; then
    return 0
  fi

  if command -v clear >/dev/null 2>&1; then
    clear 2>/dev/null || true
  fi
}

is_ascii_text() {
  LC_ALL=C grep -q '^[ -~]*$' <<< "${1}"
}

estimate_text_width() {
  local text=$1
  local char_count byte_count extra_bytes

  if is_ascii_text "${text}"; then
    printf '%s' "${#text}"
    return 0
  fi

  char_count=$(printf '%s' "${text}" | wc -m | tr -d '[:space:]')
  byte_count=$(printf '%s' "${text}" | wc -c | tr -d '[:space:]')

  if [[ ! "${char_count}" =~ ^[0-9]+$ ]] || [[ ! "${byte_count}" =~ ^[0-9]+$ ]]; then
    printf '%s' "${#text}"
    return 0
  fi

  extra_bytes=$((byte_count - char_count))
  printf '%s' "$((char_count + (extra_bytes / 2)))"
}

print_centered_text() {
  local text=$1
  local color=${2:-}
  local width text_length padding

  width=$(term_columns)
  padding=0
  text_length=$(estimate_text_width "${text}")

  if (( width > text_length )); then
    padding=$(((width - text_length) / 2))
  fi

  printf '%*s' "${padding}" ''
  if [[ -n "${color}" ]]; then
    printf '%b%s%b\n' "${color}" "${text}" "${NC}"
  else
    printf '%s\n' "${text}"
  fi
}

render_page_header() {
  local title=$1
  local subtitle=${2:-}
  local width divider

  width=$(compact_ui_width)
  divider=$(repeat_char "═" "${width}")

  echo -e "${BLUE}${divider}${NC}"
  echo -e "${GREEN}${title}${NC}"
  if [[ -n "${subtitle}" ]]; then
    echo -e "${BLUE}${subtitle}${NC}"
  fi
  echo -e "${BLUE}${divider}${NC}"
}

render_section_title() {
  local title=$1
  local width divider

  width=$(term_columns)
  if (( width < 56 )); then
    echo -e "\n${BLUE}${title}${NC}"
    return 0
  fi

  divider=$(repeat_char "·" 8)
  echo -e "\n${BLUE}${divider} ${title} ${divider}${NC}"
}

render_menu_item() {
  local number=$1
  local label=$2
  local hint=${3:-}
  local status=${4:-}
  local width line

  width=$(term_columns)
  line="${number}. ${label}"

  if [[ -n "${status}" ]]; then
    if (( width >= 72 )); then
      echo -e "${line} ${GREEN}${status}${NC}"
    else
      echo "${line}"
      echo -e "   ${GREEN}${status}${NC}"
    fi
    return 0
  fi

  if [[ -n "${hint}" ]]; then
    if (( width >= 72 )); then
      echo -e "${line} ${BLUE}${hint}${NC}"
    else
      echo "${line}"
      echo -e "   ${BLUE}${hint}${NC}"
    fi
    return 0
  fi

  echo "${line}"
}

render_summary_item() {
  local label=$1
  local value=${2:-}
  printf '%s: %b\n' "${label}" "${value}"
}

render_main_menu_brand_block() {
  local width divider brand_info brand_meta brand_info_width brand_meta_width
  local project_url_without_scheme project_url_base project_url_path
  local current_path_line path_segment candidate
  local -a project_path_segments

  width=$(compact_ui_width)
  divider=$(repeat_char "═" "${width}")
  brand_info="作者: ${PROJECT_AUTHOR} · 项目: ${PROJECT_URL}"
  brand_meta="专为 VPS 稳定部署与安全运维设计 · 版本: ${SCRIPT_VERSION}"
  brand_info_width=$(estimate_text_width "${brand_info}")
  brand_meta_width=$(estimate_text_width "${brand_meta}")

  echo -e "${BLUE}${divider}${NC}"
  echo -e "${GREEN}sing-box-vps 一键安装管理脚本${NC}"

  if (( brand_info_width <= width && brand_meta_width <= width )); then
    echo -e "${YELLOW}${brand_info}${NC}"
    echo -e "${BLUE}${brand_meta}${NC}"
  else
    echo -e "${YELLOW}作者: ${PROJECT_AUTHOR}${NC}"
    echo -e "${YELLOW}项目:${NC}"
    project_url_without_scheme=${PROJECT_URL#*://}
    project_url_base="${PROJECT_URL%%://*}://${project_url_without_scheme%%/*}/"
    if [[ "${project_url_without_scheme}" == */* ]]; then
      project_url_path=${project_url_without_scheme#*/}
    else
      project_url_path=""
    fi

    echo -e "${YELLOW}${project_url_base}${NC}"

    if [[ -n "${project_url_path}" ]]; then
      IFS='/' read -r -a project_path_segments <<< "${project_url_path}"
      current_path_line=""

      for path_segment in "${project_path_segments[@]}"; do
        if [[ -z "${current_path_line}" ]]; then
          candidate="${path_segment}"
        else
          candidate="${current_path_line}/${path_segment}"
        fi

        if (( $(estimate_text_width "${candidate}") <= width )); then
          current_path_line="${candidate}"
        else
          [[ -n "${current_path_line}" ]] && echo -e "${YELLOW}${current_path_line}${NC}"
          current_path_line="${path_segment}"
        fi
      done

      [[ -n "${current_path_line}" ]] && echo -e "${YELLOW}${current_path_line}${NC}"
    fi

    echo -e "${BLUE}专为 VPS 稳定部署与安全运维设计${NC}"
    echo -e "${BLUE}版本: ${SCRIPT_VERSION}${NC}"
  fi

  echo -e "${BLUE}${divider}${NC}"
}

render_left_aligned_page_header() {
  local title=$1
  local subtitle=${2:-}
  local width divider

  width=$(compact_ui_width)
  divider=$(repeat_char "═" "${width}")

  echo -e "${BLUE}${divider}${NC}"
  echo -e "${GREEN}${title}${NC}"
  if [[ -n "${subtitle}" ]]; then
    echo -e "${BLUE}${subtitle}${NC}"
  fi
  echo -e "${BLUE}${divider}${NC}"
}

render_menu_group_start() {
  local title=${1:-}

  if [[ -n "${title}" ]]; then
    render_section_title "${title}"
  else
    echo
  fi
}

show_banner() {
  safe_clear_screen
  render_main_menu_brand_block
  echo
}

render_main_menu_footer() {
  :
}

# Helper: Check BBR Status
check_bbr_status() {
  local cc
  cc=$(sysctl net.ipv4.tcp_congestion_control 2>/dev/null | awk '{print $3}' || true)

  if [[ -z "${cc}" ]]; then
    BBR_STATUS="${YELLOW}(状态未知)${NC}"
  elif [[ "${cc}" == "bbr" ]]; then
    BBR_STATUS="${GREEN}(已开启 BBR)${NC}"
  else
    BBR_STATUS="${YELLOW}(未开启 BBR)${NC}"
  fi
}

apply_stack_mode_changes() {
  local selected_inbound selected_outbound snapshot_dir
  selected_inbound="${SB_INBOUND_STACK_MODE}"
  selected_outbound="${SB_OUTBOUND_STACK_MODE}"

  if [[ -f "${SINGBOX_CONFIG_FILE}" || -f "${SB_PROTOCOL_INDEX_FILE}" ]]; then
    load_current_config_state
    SB_INBOUND_STACK_MODE="${selected_inbound}"
    SB_OUTBOUND_STACK_MODE="${selected_outbound}"
  fi

  if [[ ! -f "${SINGBOX_CONFIG_FILE}" && ! -f "${SB_PROTOCOL_INDEX_FILE}" ]]; then
    save_stack_mode_state
    log_success "协议栈设置已保存，将在首次安装或下次生成配置时生效。"
    return 0
  fi

  snapshot_dir=$(create_managed_state_snapshot) || log_error "无法创建配置状态事务快照。"
  if ! save_stack_mode_state || ! generate_config; then
    abort_managed_state_transaction "${snapshot_dir}" "协议栈配置生成或校验失败"
  fi
  if ! discard_managed_state_snapshot "${snapshot_dir}"; then
    log_warn "协议栈配置已提交，但临时事务快照未能删除: ${snapshot_dir}。"
  fi
  refresh_vless_reality_qos_rules
  setup_service
  open_committed_protocol_ports || return $?
  systemctl restart sing-box
  log_success "协议栈设置已保存并重启服务。"
}

configure_inbound_stack_mode() {
  local host_stack choice selected_mode
  local available_modes=()
  local index

  ensure_stack_mode_state_loaded
  host_stack=$(detect_host_ip_stack)

  case "${host_stack}" in
    dual) available_modes=(ipv4_only ipv6_only dual_stack) ;;
    ipv6) available_modes=(ipv6_only) ;;
    *) available_modes=(ipv4_only) ;;
  esac

  while true; do
    echo
    render_left_aligned_page_header "入站协议栈" "按主机能力选择监听栈"
    render_section_title "当前设置"
    render_summary_item "系统网络能力" "$(host_ip_stack_display_name "${host_stack}")"
    render_summary_item "当前入站协议栈" "$(inbound_stack_mode_display_name "${SB_INBOUND_STACK_MODE}")"
    render_section_title "可选模式"

    for index in "${!available_modes[@]}"; do
      render_menu_item "$((index + 1))" "$(inbound_stack_mode_display_name "${available_modes[$index]}")"
    done
    echo "0. 返回"
    choice=$(prompt_choice "请选择 [0-${#available_modes[@]}]: " 0 "${#available_modes[@]}" "")

    if [[ "${choice}" == "0" ]]; then
      return 0
    fi

    if [[ "${choice}" =~ ^[1-9][0-9]*$ ]] && (( choice >= 1 && choice <= ${#available_modes[@]} )); then
      selected_mode="${available_modes[$((choice - 1))]}"
      [[ "${selected_mode}" == "${SB_INBOUND_STACK_MODE}" ]] && return 0
      SB_INBOUND_STACK_MODE="${selected_mode}"
      apply_stack_mode_changes
      return 0
    fi

    log_warn "无效选项，请重新选择。"
  done
}

configure_outbound_stack_mode() {
  local choice selected_mode
  local available_modes=(ipv4_only ipv6_only prefer_ipv4 prefer_ipv6)
  local index

  ensure_stack_mode_state_loaded

  if [[ "${SB_ENABLE_WARP}" == "y" ]]; then
    log_warn "当前已开启 Warp，出站协议栈设置不生效，已禁止修改。"
    return 0
  fi

  while true; do
    echo
    render_left_aligned_page_header "出站协议栈" "调整 sing-box 的 DNS 与直连出站策略"
    render_section_title "当前设置"
    render_summary_item "当前出站协议栈" "$(outbound_stack_mode_display_name "${SB_OUTBOUND_STACK_MODE}")"
    render_section_title "可选模式"

    for index in "${!available_modes[@]}"; do
      render_menu_item "$((index + 1))" "$(outbound_stack_mode_display_name "${available_modes[$index]}")"
    done
    echo "0. 返回"
    choice=$(prompt_choice "请选择 [0-${#available_modes[@]}]: " 0 "${#available_modes[@]}" "")

    if [[ "${choice}" == "0" ]]; then
      return 0
    fi

    if [[ "${choice}" =~ ^[1-9][0-9]*$ ]] && (( choice >= 1 && choice <= ${#available_modes[@]} )); then
      selected_mode="${available_modes[$((choice - 1))]}"
      [[ "${selected_mode}" == "${SB_OUTBOUND_STACK_MODE}" ]] && return 0
      SB_OUTBOUND_STACK_MODE="${selected_mode}"
      apply_stack_mode_changes
      return 0
    fi

    log_warn "无效选项，请重新选择。"
  done
}

stack_management_menu() {
  local host_stack
  local warp_status

  while true; do
    if [[ -f "${SINGBOX_CONFIG_FILE}" || -f "${SB_PROTOCOL_INDEX_FILE}" ]]; then
      load_current_config_state
    else
      ensure_stack_mode_state_loaded
      SB_ENABLE_WARP="n"
    fi

    host_stack=$(detect_host_ip_stack)
    if [[ "${SB_ENABLE_WARP}" == "y" ]]; then
      warp_status="已开启 (出站协议栈当前不生效)"
    else
      warp_status="未开启"
    fi

    echo
    render_left_aligned_page_header "协议栈管理" "统一调整入站 / 出站网络栈策略"
    render_section_title "协议栈摘要"
    render_summary_item "系统网络能力" "$(host_ip_stack_display_name "${host_stack}")"
    render_summary_item "当前入站协议栈" "$(inbound_stack_mode_display_name "${SB_INBOUND_STACK_MODE}")"
    render_summary_item "当前出站协议栈" "$(outbound_stack_mode_display_name "${SB_OUTBOUND_STACK_MODE}")"
    render_summary_item "Warp 状态" "${warp_status}"
    render_section_title "操作选项"
    render_menu_item "1" "修改入站协议栈"
    render_menu_item "2" "修改出站协议栈"
    echo "0. 返回上一级"
    stack_choice=$(prompt_choice "请选择 [0-2]: " 0 2 "")

    case "${stack_choice}" in
      1) configure_inbound_stack_mode || true ;;
      2) configure_outbound_stack_mode || true ;;
      0) return ;;
      *) log_warn "无效选项，请重新选择。" ;;
    esac
  done
}

system_management_menu() {
  while true; do
    check_bbr_status
    echo
    render_left_aligned_page_header "系统管理" "维护内核优化与网络协议栈设置"
    render_section_title "系统摘要"
    render_summary_item "BBR 状态" "${BBR_STATUS}"
    render_section_title "操作选项"
    render_menu_item "1" "开启 BBR"
    render_menu_item "2" "协议栈管理"
    echo "0. 返回主菜单"
    system_choice=$(prompt_choice "请选择 [0-2]: " 0 2 "")

    case "${system_choice}" in
      1) enable_bbr ;;
      2) stack_management_menu ;;
      0) return ;;
      *) log_warn "无效选项，请重新选择。" ;;
    esac
  done
}

# Detect whether the current config enables Warp.
# Prefer the current endpoint-based schema, but keep compatibility with older configs.
config_has_warp_enabled() {
  local config_file=$1

  jq -e '
    (
      any(.endpoints[]?; .tag == "warp-ep") and
      (
        (.route.final // "") == "warp-ep" or
        any(.route.rules[]?; (.outbound // "") == "warp-ep" and (has("inbound") | not))
      )
    ) or any(.outbounds[]?; .tag == "warp")
  ' "${config_file}" &>/dev/null
}

config_detect_warp_route_mode() {
  local config_file=$1

  if jq -e '(.route.final // "") == "warp-ep"' "${config_file}" &>/dev/null; then
    printf 'all'
    return 0
  fi

  if jq -e 'any(.route.rules[]?; (.outbound // "") == "warp-ep")' "${config_file}" &>/dev/null; then
    printf 'selective'
    return 0
  fi

  printf 'selective'
}

# Detect whether advanced route rules are enabled in either the current or legacy schema.
config_has_advanced_route() {
  local config_file=$1

  jq -e '
    any(
      .route.rules[]?;
      (.ip_is_private == true and .action == "reject") or
      (.geosite == "category-ads-all")
    )
  ' "${config_file}" &>/dev/null
}

load_config_generation_settings() {
  local config_file=${1:-}

  [[ -f "${config_file}" && ! -L "${config_file}" ]] || return 0
  jq -e 'type == "object"' "${config_file}" >/dev/null 2>&1 || return 0

  if config_has_advanced_route "${config_file}"; then
    SB_ADVANCED_ROUTE="y"
  else
    SB_ADVANCED_ROUTE="n"
  fi
  if config_has_warp_enabled "${config_file}"; then
    SB_ENABLE_WARP="y"
  else
    SB_ENABLE_WARP="n"
  fi
  load_warp_route_settings
}

normalize_acme_extra_json() {
  local acme_json=$1

  if ! jq -n -e --argjson acme "${acme_json}" '$acme | type == "object"' >/dev/null 2>&1; then
    return 1
  fi
  if jq -n -e --argjson acme "${acme_json}" '$acme.http_client? | type == "string"' >/dev/null 2>&1; then
    return 1
  fi

  jq -cnS \
    --argjson acme "${acme_json}" \
    --arg default_data_directory "${SB_ACME_DATA_DIR}" \
    '$acme
    | if .domain == null then
        del(.domain)
      elif (.domain | type) != "array" or (.domain | length) == 0 then
        error("invalid ACME domain")
      elif (.domain | length) == 1 then
        del(.domain)
      else
        .
      end
    | del(.type, .tag, .email)
    | if .data_directory == $default_data_directory then del(.data_directory) else . end
    | if .dns01_challenge == null then
        del(.dns01_challenge)
      elif (.dns01_challenge | type) == "object" then
        .dns01_challenge |= del(.provider, .api_token)
        | if .dns01_challenge == {} then del(.dns01_challenge) else . end
      else
        .
      end'
}

inline_acme_extra_json_from_config() {
  local config_file=$1
  local inbound_index=$2
  local acme_json

  acme_json=$(jq -c --argjson idx "${inbound_index}" '.inbounds[$idx].tls.acme' "${config_file}") || return 1
  normalize_acme_extra_json "${acme_json}"
}

# Resolve an inbound certificate provider into the state fields consumed by all
# protocol readers.  A certificate_provider may be either a shared tag or an
# inline object, but only an ACME provider can be represented by the script's
# state model.  Returning an error for anything else prevents a later rewrite
# from silently changing the certificate configuration.
load_certificate_provider_from_config() {
  local config_file=$1
  local inbound_index=$2
  local provider_kind provider_tag provider_count provider_json provider_type server_name

  CERT_PROVIDER_MODE="none"
  CERT_PROVIDER_TAG=""
  CERT_PROVIDER_EMAIL=""
  CERT_PROVIDER_DOMAIN=""
  CERT_PROVIDER_EXTRA_JSON='{}'
  CERT_PROVIDER_ACME_MODE="http"
  CERT_PROVIDER_DNS_PROVIDER="cloudflare"
  CERT_PROVIDER_CF_API_TOKEN=""
  CERT_PROVIDER_ERROR=""

  if ! provider_kind=$(jq -r --argjson idx "${inbound_index}" '
    .inbounds[$idx].tls.certificate_provider? |
    if . == null then "none"
    elif type == "string" then "shared"
    elif type == "object" then "inline"
    else "invalid"
    end
  ' "${config_file}"); then
    CERT_PROVIDER_ERROR="无法读取 certificate_provider"
    return 1
  fi

  case "${provider_kind}" in
    none)
      return 0
      ;;
    shared)
      provider_tag=$(jq -r --argjson idx "${inbound_index}" '.inbounds[$idx].tls.certificate_provider' "${config_file}") || {
        CERT_PROVIDER_ERROR="无法读取 shared certificate_provider tag"
        return 1
      }
      provider_count=$(jq -r --arg tag "${provider_tag}" '[.certificate_providers[]? | select(type == "object" and .tag == $tag)] | length' "${config_file}") || {
        CERT_PROVIDER_ERROR="无法读取 shared certificate_provider 映射"
        return 1
      }
      if [[ "${provider_count}" != "1" ]]; then
        CERT_PROVIDER_ERROR="shared certificate_provider 未唯一映射"
        return 1
      fi
      provider_json=$(jq -c --arg tag "${provider_tag}" 'first(.certificate_providers[]? | select(type == "object" and .tag == $tag)) // null' "${config_file}") || {
        CERT_PROVIDER_ERROR="无法读取 shared certificate_provider"
        return 1
      }
      CERT_PROVIDER_TAG="${provider_tag}"
      ;;
    inline)
      provider_json=$(jq -c --argjson idx "${inbound_index}" '.inbounds[$idx].tls.certificate_provider' "${config_file}") || {
        CERT_PROVIDER_ERROR="无法读取 inline certificate_provider"
        return 1
      }
      ;;
    *)
      CERT_PROVIDER_ERROR="certificate_provider 类型不受支持"
      return 1
      ;;
  esac

  provider_type=$(jq -n -r --argjson provider "${provider_json}" '$provider.type // ""' 2>/dev/null) || {
    CERT_PROVIDER_ERROR="无法读取 certificate_provider type"
    return 1
  }
  if [[ "${provider_type}" != "acme" ]]; then
    CERT_PROVIDER_ERROR="certificate_provider 不是 ACME provider"
    return 1
  fi

  if ! CERT_PROVIDER_EXTRA_JSON=$(normalize_acme_extra_json "${provider_json}"); then
    if jq -n -e --argjson provider "${provider_json}" '$provider.http_client? | type == "string"' >/dev/null 2>&1; then
      CERT_PROVIDER_ERROR="暂不支持引用 shared http_client 的 ACME provider"
    else
      CERT_PROVIDER_ERROR="无法保留 ACME provider 的扩展字段"
    fi
    return 1
  fi

  server_name=$(jq -r --argjson idx "${inbound_index}" '.inbounds[$idx].tls.server_name // ""' "${config_file}") || {
    CERT_PROVIDER_ERROR="无法读取 certificate_provider fallback domain"
    return 1
  }
  CERT_PROVIDER_MODE="acme"
  if ! CERT_PROVIDER_EMAIL=$(jq -n -r --argjson provider "${provider_json}" '$provider.email // ""' 2>/dev/null); then
    CERT_PROVIDER_ERROR="无法读取 ACME provider email"
    return 1
  fi
  if ! CERT_PROVIDER_DOMAIN=$(jq -n -r --argjson provider "${provider_json}" --arg fallback "${server_name}" '$provider.domain[0] // $fallback' 2>/dev/null); then
    CERT_PROVIDER_ERROR="无法读取 ACME provider domain"
    return 1
  fi
  if jq -n -e --argjson provider "${provider_json}" '$provider.dns01_challenge? != null' &>/dev/null; then
    CERT_PROVIDER_ACME_MODE="dns"
    if ! CERT_PROVIDER_DNS_PROVIDER=$(jq -n -r --argjson provider "${provider_json}" '$provider.dns01_challenge.provider // "cloudflare"' 2>/dev/null); then
      CERT_PROVIDER_ERROR="无法读取 ACME DNS provider"
      return 1
    fi
    if ! CERT_PROVIDER_CF_API_TOKEN=$(jq -n -r --argjson provider "${provider_json}" '$provider.dns01_challenge.api_token // ""' 2>/dev/null); then
      CERT_PROVIDER_ERROR="无法读取 ACME DNS API token"
      return 1
    fi
  fi
}

load_current_config_state() {
  local first_protocol
  local installed_protocols=()

  migrate_legacy_single_protocol_state_if_needed

  if [[ ! -f "${SINGBOX_CONFIG_FILE}" && ! -f "${SB_PROTOCOL_INDEX_FILE}" ]]; then
    log_error "未找到配置文件，请先安装。"
  fi

  if [[ -f "${SINGBOX_CONFIG_FILE}" ]]; then
    if config_has_advanced_route "${SINGBOX_CONFIG_FILE}"; then
      SB_ADVANCED_ROUTE="y"
    else
      SB_ADVANCED_ROUTE="n"
    fi

    if config_has_warp_enabled "${SINGBOX_CONFIG_FILE}"; then
      SB_ENABLE_WARP="y"
    else
      SB_ENABLE_WARP="n"
    fi

    load_warp_route_settings
  fi

  load_stack_mode_state

  if [[ -f "${SB_PROTOCOL_INDEX_FILE}" ]]; then
    mapfile -t installed_protocols < <(list_installed_protocols)
    first_protocol="${installed_protocols[0]:-}"
    if [[ -n "${first_protocol}" ]]; then
      load_protocol_state "${first_protocol}"
      return 0
    fi
  fi

  if [[ ! -f "${SINGBOX_CONFIG_FILE}" ]]; then
    log_error "未找到配置文件，请先安装。"
  fi

  SB_PROTOCOL=$(jq -r '.inbounds[0].type' "${SINGBOX_CONFIG_FILE}")
  case "${SB_PROTOCOL}" in
    vless) SB_PROTOCOL="vless+reality" ;;
    mixed) SB_PROTOCOL="mixed" ;;
    hysteria2) SB_PROTOCOL="hy2" ;;
    anytls) SB_PROTOCOL="anytls" ;;
    *) log_error "当前配置中的协议类型不受脚本支持: ${SB_PROTOCOL}" ;;
  esac

  SB_PORT=$(jq -r '.inbounds[0].listen_port' "${SINGBOX_CONFIG_FILE}")

  if [[ "${SB_PROTOCOL}" == "vless+reality" ]]; then
    SB_NODE_NAME="$(default_node_name_for_protocol "vless+reality")"
    SB_UUID=$(jq -r '.inbounds[0].users[0].uuid' "${SINGBOX_CONFIG_FILE}")
    SB_SNI=$(jq -r '.inbounds[0].tls.server_name' "${SINGBOX_CONFIG_FILE}")
    SB_PRIVATE_KEY=$(jq -r '.inbounds[0].tls.reality.private_key' "${SINGBOX_CONFIG_FILE}")
    SB_SHORT_ID_1=$(jq -r '.inbounds[0].tls.reality.short_id[0]' "${SINGBOX_CONFIG_FILE}")
    SB_SHORT_ID_2=$(jq -r '.inbounds[0].tls.reality.short_id[1]' "${SINGBOX_CONFIG_FILE}")
    SB_MIXED_AUTH_ENABLED="y"
    SB_MIXED_USERNAME=""
    SB_MIXED_PASSWORD=""
  elif [[ "${SB_PROTOCOL}" == "mixed" ]]; then
    SB_NODE_NAME="$(default_node_name_for_protocol "mixed")"
    SB_UUID=""
    SB_SNI=""
    SB_PRIVATE_KEY=""
    SB_SHORT_ID_1=""
    SB_SHORT_ID_2=""
    if jq -e '(.inbounds[0].users // []) | length > 0' "${SINGBOX_CONFIG_FILE}" &>/dev/null; then
      SB_MIXED_AUTH_ENABLED="y"
      SB_MIXED_USERNAME=$(jq -r '.inbounds[0].users[0].username // ""' "${SINGBOX_CONFIG_FILE}")
      SB_MIXED_PASSWORD=$(jq -r '.inbounds[0].users[0].password // ""' "${SINGBOX_CONFIG_FILE}")
    else
      SB_MIXED_AUTH_ENABLED="n"
      SB_MIXED_USERNAME=""
      SB_MIXED_PASSWORD=""
    fi
  elif [[ "${SB_PROTOCOL}" == "hy2" ]]; then
    SB_NODE_NAME="$(default_node_name_for_protocol "hy2")"
    SB_HY2_DOMAIN=$(jq -r '.inbounds[0].tls.server_name // ""' "${SINGBOX_CONFIG_FILE}")
    SB_HY2_PASSWORD=$(jq -r '.inbounds[0].users[0].password // ""' "${SINGBOX_CONFIG_FILE}")
    SB_HY2_USER_NAME=$(jq -r '.inbounds[0].users[0].name // ""' "${SINGBOX_CONFIG_FILE}")
    SB_HY2_UP_MBPS=$(jq -r '.inbounds[0].up_mbps // ""' "${SINGBOX_CONFIG_FILE}")
    SB_HY2_DOWN_MBPS=$(jq -r '.inbounds[0].down_mbps // ""' "${SINGBOX_CONFIG_FILE}")
    if jq -e '.inbounds[0].obfs.type == "salamander"' "${SINGBOX_CONFIG_FILE}" &>/dev/null; then
      SB_HY2_OBFS_ENABLED="y"
      SB_HY2_OBFS_TYPE="salamander"
      SB_HY2_OBFS_PASSWORD=$(jq -r '.inbounds[0].obfs.password // ""' "${SINGBOX_CONFIG_FILE}")
    else
      SB_HY2_OBFS_ENABLED="n"
      SB_HY2_OBFS_TYPE=""
      SB_HY2_OBFS_PASSWORD=""
    fi
    if jq -e '.inbounds[0].tls.acme? != null' "${SINGBOX_CONFIG_FILE}" &>/dev/null; then
      SB_HY2_TLS_MODE="acme"
      SB_HY2_ACME_EMAIL=$(jq -r '.inbounds[0].tls.acme.email // ""' "${SINGBOX_CONFIG_FILE}")
      SB_HY2_ACME_DOMAIN=$(jq -r '.inbounds[0].tls.acme.domain[0] // .inbounds[0].tls.server_name // ""' "${SINGBOX_CONFIG_FILE}")
      if jq -e '.inbounds[0].tls.acme.dns01_challenge? != null' "${SINGBOX_CONFIG_FILE}" &>/dev/null; then
        SB_HY2_ACME_MODE="dns"
        SB_HY2_DNS_PROVIDER=$(jq -r '.inbounds[0].tls.acme.dns01_challenge.provider // "cloudflare"' "${SINGBOX_CONFIG_FILE}")
        SB_HY2_CF_API_TOKEN=$(jq -r '.inbounds[0].tls.acme.dns01_challenge.api_token // ""' "${SINGBOX_CONFIG_FILE}")
      else
        SB_HY2_ACME_MODE="http"
        SB_HY2_DNS_PROVIDER="cloudflare"
        SB_HY2_CF_API_TOKEN=""
      fi
      if ! SB_HY2_ACME_EXTRA_JSON=$(inline_acme_extra_json_from_config "${SINGBOX_CONFIG_FILE}" 0); then
        log_error "当前 Hysteria2 tls.acme 扩展字段无法安全保留。"
      fi
      SB_HY2_CERT_PATH=""
      SB_HY2_KEY_PATH=""
    elif jq -e '.inbounds[0].tls.certificate_provider? != null' "${SINGBOX_CONFIG_FILE}" &>/dev/null; then
      if ! load_certificate_provider_from_config "${SINGBOX_CONFIG_FILE}" 0; then
        log_error "当前 Hysteria2 certificate_provider 无法安全解析: ${CERT_PROVIDER_ERROR}"
      fi
      SB_HY2_TLS_MODE="acme"
      SB_HY2_ACME_MODE="${CERT_PROVIDER_ACME_MODE}"
      SB_HY2_ACME_EMAIL="${CERT_PROVIDER_EMAIL}"
      SB_HY2_ACME_DOMAIN="${CERT_PROVIDER_DOMAIN}"
      SB_HY2_ACME_EXTRA_JSON="${CERT_PROVIDER_EXTRA_JSON}"
      SB_HY2_DNS_PROVIDER="${CERT_PROVIDER_DNS_PROVIDER}"
      SB_HY2_CF_API_TOKEN="${CERT_PROVIDER_CF_API_TOKEN}"
      SB_HY2_CERT_PATH=""
      SB_HY2_KEY_PATH=""
    else
      SB_HY2_TLS_MODE="manual"
      SB_HY2_ACME_MODE="http"
      SB_HY2_ACME_EMAIL=""
      SB_HY2_ACME_DOMAIN="${SB_HY2_DOMAIN}"
      SB_HY2_ACME_EXTRA_JSON='{}'
      SB_HY2_DNS_PROVIDER="cloudflare"
      SB_HY2_CF_API_TOKEN=""
      SB_HY2_CERT_PATH=$(jq -r '.inbounds[0].tls.certificate_path // ""' "${SINGBOX_CONFIG_FILE}")
      SB_HY2_KEY_PATH=$(jq -r '.inbounds[0].tls.key_path // ""' "${SINGBOX_CONFIG_FILE}")
    fi
    SB_HY2_MASQUERADE=$(jq -r '.inbounds[0].masquerade // ""' "${SINGBOX_CONFIG_FILE}")
    SB_ANYTLS_DOMAIN=""
    SB_ANYTLS_PASSWORD=""
    SB_ANYTLS_USER_NAME=""
  else
    SB_NODE_NAME="$(default_node_name_for_protocol "anytls")"
    SB_ANYTLS_DOMAIN=$(jq -r '.inbounds[0].tls.server_name // ""' "${SINGBOX_CONFIG_FILE}")
    SB_ANYTLS_PASSWORD=$(jq -r '.inbounds[0].users[0].password // ""' "${SINGBOX_CONFIG_FILE}")
    SB_ANYTLS_USER_NAME=$(jq -r '.inbounds[0].users[0].name // ""' "${SINGBOX_CONFIG_FILE}")
    if jq -e '.inbounds[0].tls.acme? != null' "${SINGBOX_CONFIG_FILE}" &>/dev/null; then
      SB_ANYTLS_TLS_MODE="acme"
      SB_ANYTLS_ACME_EMAIL=$(jq -r '.inbounds[0].tls.acme.email // ""' "${SINGBOX_CONFIG_FILE}")
      SB_ANYTLS_ACME_DOMAIN=$(jq -r '.inbounds[0].tls.acme.domain[0] // .inbounds[0].tls.server_name // ""' "${SINGBOX_CONFIG_FILE}")
      if jq -e '.inbounds[0].tls.acme.dns01_challenge? != null' "${SINGBOX_CONFIG_FILE}" &>/dev/null; then
        SB_ANYTLS_ACME_MODE="dns"
        SB_ANYTLS_DNS_PROVIDER=$(jq -r '.inbounds[0].tls.acme.dns01_challenge.provider // "cloudflare"' "${SINGBOX_CONFIG_FILE}")
        SB_ANYTLS_CF_API_TOKEN=$(jq -r '.inbounds[0].tls.acme.dns01_challenge.api_token // ""' "${SINGBOX_CONFIG_FILE}")
      else
        SB_ANYTLS_ACME_MODE="http"
        SB_ANYTLS_DNS_PROVIDER="cloudflare"
        SB_ANYTLS_CF_API_TOKEN=""
      fi
      if ! SB_ANYTLS_ACME_EXTRA_JSON=$(inline_acme_extra_json_from_config "${SINGBOX_CONFIG_FILE}" 0); then
        log_error "当前 AnyTLS tls.acme 扩展字段无法安全保留。"
      fi
      SB_ANYTLS_CERT_PATH=""
      SB_ANYTLS_KEY_PATH=""
    elif jq -e '.inbounds[0].tls.certificate_provider? != null' "${SINGBOX_CONFIG_FILE}" &>/dev/null; then
      if ! load_certificate_provider_from_config "${SINGBOX_CONFIG_FILE}" 0; then
        log_error "当前 AnyTLS certificate_provider 无法安全解析: ${CERT_PROVIDER_ERROR}"
      fi
      SB_ANYTLS_TLS_MODE="acme"
      SB_ANYTLS_ACME_MODE="${CERT_PROVIDER_ACME_MODE}"
      SB_ANYTLS_ACME_EMAIL="${CERT_PROVIDER_EMAIL}"
      SB_ANYTLS_ACME_DOMAIN="${CERT_PROVIDER_DOMAIN}"
      SB_ANYTLS_ACME_EXTRA_JSON="${CERT_PROVIDER_EXTRA_JSON}"
      SB_ANYTLS_DNS_PROVIDER="${CERT_PROVIDER_DNS_PROVIDER}"
      SB_ANYTLS_CF_API_TOKEN="${CERT_PROVIDER_CF_API_TOKEN}"
      SB_ANYTLS_CERT_PATH=""
      SB_ANYTLS_KEY_PATH=""
    else
      SB_ANYTLS_TLS_MODE="manual"
      SB_ANYTLS_ACME_MODE="http"
      SB_ANYTLS_ACME_EMAIL=""
      SB_ANYTLS_ACME_DOMAIN="${SB_ANYTLS_DOMAIN}"
      SB_ANYTLS_ACME_EXTRA_JSON='{}'
      SB_ANYTLS_DNS_PROVIDER="cloudflare"
      SB_ANYTLS_CF_API_TOKEN=""
      SB_ANYTLS_CERT_PATH=$(jq -r '.inbounds[0].tls.certificate_path // ""' "${SINGBOX_CONFIG_FILE}")
      SB_ANYTLS_KEY_PATH=$(jq -r '.inbounds[0].tls.key_path // ""' "${SINGBOX_CONFIG_FILE}")
    fi
  fi

  if [[ "${SB_PROTOCOL}" == "vless+reality" && -f "${SB_KEY_FILE}" ]]; then
    SB_PUBLIC_KEY=$(grep "PUBLIC_KEY" "${SB_KEY_FILE}" | cut -d'=' -f2- | tr -d '\r\n ')
  elif [[ "${SB_PROTOCOL}" == "vless+reality" ]]; then
    SB_PUBLIC_KEY="[密钥丢失，请更新配置]"
  else
    SB_PUBLIC_KEY=""
  fi
}

# Cloudflare Warp Management
warp_management() {
  local apply_change should_reload status warp_was_enabled snapshot_dir

  while true; do
    apply_change="n"
    should_reload="n"

    load_current_config_state
    ensure_warp_routing_assets
    warp_was_enabled="${SB_ENABLE_WARP}"

    if [[ "${SB_ENABLE_WARP}" == "y" ]]; then
      status="${GREEN}已开启${NC}"
    else
      status="${YELLOW}未开启${NC}"
    fi

    echo
    render_left_aligned_page_header "Cloudflare Warp 管理" "调整 Warp 出口与分流资产"
    render_section_title "Warp 摘要"
    render_summary_item "当前状态" "${status}"
    render_summary_item "当前路由模式" "${SB_WARP_ROUTE_MODE}"
    render_summary_item "域名列表文件" "${SB_WARP_DOMAINS_FILE}"
    render_section_title "操作选项"
    render_menu_item "1" "开启 Warp"
    render_menu_item "2" "关闭 Warp"
    render_menu_item "3" "重新注册 Warp 账户" "(获取新密钥和 IP)"
    render_menu_item "4" "切换 Warp 路由模式"
    render_menu_item "5" "添加自定义 Warp 域名"
    render_menu_item "6" "添加远程 Warp 规则集"
    render_menu_item "7" "查看 Warp 分流文件路径"
    render_menu_item "8" "查看当前生效的 Warp 分流来源"
    render_menu_item "9" "导入推荐 Warp 规则源"
    echo "0. 返回主菜单"
    w_choice=$(prompt_choice "请选择 [0-9]: " 0 9 "")

    case "${w_choice}" in
      7)
        show_warp_route_assets
        continue
        ;;
      8)
        show_effective_warp_route_sources
        continue
        ;;
      0) return ;;
    esac

    snapshot_dir=$(create_managed_state_snapshot) || log_error "无法创建配置状态事务快照。"

    case "${w_choice}" in
      1)
        SB_ENABLE_WARP="y"
        log_info "正在开启 Warp..."
        apply_change="y"
        should_reload="y"
        ;;
      2)
        SB_ENABLE_WARP="n"
        log_info "正在关闭 Warp..."
        apply_change="y"
        should_reload="y"
        ;;
      3)
        rm -f "${SB_WARP_KEY_FILE}"
        SB_ENABLE_WARP="y"
        log_info "正在重新注册 Warp..."
        apply_change="y"
        should_reload="y"
        ;;
      4)
        if set_warp_route_mode_interactive; then
          log_success "Warp 路由模式已更新为: ${SB_WARP_ROUTE_MODE}"
          apply_change="y"
          [[ "${warp_was_enabled}" == "y" || "${SB_ENABLE_WARP}" == "y" ]] && should_reload="y"
        fi
        ;;
      5)
        if add_warp_domain_entry; then
          apply_change="y"
          [[ "${warp_was_enabled}" == "y" || "${SB_ENABLE_WARP}" == "y" ]] && should_reload="y"
        fi
        ;;
      6)
        if add_remote_warp_rule_set; then
          apply_change="y"
          [[ "${warp_was_enabled}" == "y" || "${SB_ENABLE_WARP}" == "y" ]] && should_reload="y"
        fi
        ;;
      9)
        if import_recommended_warp_rule_sets; then
          apply_change="y"
          [[ "${warp_was_enabled}" == "y" || "${SB_ENABLE_WARP}" == "y" ]] && should_reload="y"
        fi
        ;;
      *) log_warn "无效选项，请重新选择。" ;;
    esac

    if [[ "${apply_change}" == "n" ]]; then
      if ! rollback_managed_state_snapshot "${snapshot_dir}"; then
        log_error "取消 Warp 变更时无法恢复配置状态；事务快照保留在 ${snapshot_dir}。"
      fi
      continue
    fi

    if ! save_warp_route_settings; then
      abort_managed_state_transaction "${snapshot_dir}" "Warp 设置写入失败"
    fi

    if [[ "${should_reload}" != "y" ]]; then
      if ! discard_managed_state_snapshot "${snapshot_dir}"; then
        log_warn "Warp 分流资产已保存，但临时事务快照未能删除: ${snapshot_dir}。"
      fi
      log_success "Warp 分流资产已更新，待下次开启 Warp 或重载配置时生效。"
      continue
    fi

    if ! generate_config; then
      abort_managed_state_transaction "${snapshot_dir}" "Warp 配置生成或校验失败"
    fi
    if ! discard_managed_state_snapshot "${snapshot_dir}"; then
      log_warn "Warp 配置已提交，但临时事务快照未能删除: ${snapshot_dir}。"
    fi
    setup_service
    systemctl restart sing-box
    log_success "Warp 配置已更新并重启服务。"

    load_current_config_state
    display_status_summary
    log_info "连接信息未自动展示，如需查看请进入菜单 11。"
  done
}

# Helper to extract config values and display info
view_status() {
  load_current_config_state
  display_status_summary
}

# New function: Update config only
update_config_only() {
  local selected_protocol selected_instance snapshot_dir

  if [[ ! -f "${SINGBOX_CONFIG_FILE}" && ! -f "${SB_PROTOCOL_INDEX_FILE}" ]]; then
    log_error "未找到配置文件或协议状态，请先执行安装流程。"
  fi

  migrate_legacy_single_protocol_state_if_needed

  log_info "正在读取当前配置..."
  load_current_config_state

  echo -e "\n${BLUE}--- 进入配置修改模式 ---${NC}"
  SELECTED_PROTOCOL=""
  if ! prompt_installed_protocol_selection; then
    return 0
  fi
  selected_protocol="${SELECTED_PROTOCOL}"

  # Mixed schema 2 (and an explicitly managed legacy singleton) uses the
  # instance CAS lifecycle.  Return before the legacy save/generate path: that
  # path writes mixed.env and would otherwise flatten the JSON inventory.
  if [[ "${selected_protocol}" == mixed ]]; then
    mixed_instance_replace_interactive
    return $?
  fi
  if [[ "${selected_protocol}" == socks ]]; then
    socks_instance_management_menu replace
    return $?
  fi
  if [[ "${selected_protocol}" == http ]]; then
    http_instance_management_menu replace
    return $?
  fi
  if [[ "${selected_protocol}" == shadowsocks ]]; then
    shadowsocks_instance_management_menu replace
    return $?
  fi
  if [[ "${selected_protocol}" == trojan ]]; then
    trojan_instance_management_menu replace
    return $?
  fi
  if [[ "${selected_protocol}" == vmess ]]; then
    vmess_instance_management_menu replace
    return $?
  fi
  if [[ "${selected_protocol}" == anytls ]] && plain_proxy_structured_state_active anytls; then
    anytls_instance_management_menu replace
    return $?
  fi
  if [[ "${selected_protocol}" == hy2 ]] && plain_proxy_structured_state_active hy2; then
    hy2_instance_management_menu replace
    return $?
  fi
  if [[ "${selected_protocol}" == snell ]] && plain_proxy_structured_state_active snell; then
    snell_instance_management_menu replace
    return $?
  fi
  if [[ "${selected_protocol}" == tuic ]] && plain_proxy_structured_state_active tuic; then
    tuic_instance_management_menu replace
    return $?
  fi
  if [[ "${selected_protocol}" == hysteria ]] && plain_proxy_structured_state_active hysteria; then
    hysteria_instance_management_menu replace
    return $?
  fi

  load_protocol_state "${selected_protocol}"
  if [[ "${selected_protocol}" == "vless-reality" ]]; then
    SELECTED_VLESS_INSTANCE_ID=""
    if ! prompt_vless_reality_instance_selection; then
      return 0
    fi
    selected_instance="${SELECTED_VLESS_INSTANCE_ID}"
    load_vless_reality_protocol_state
    load_vless_reality_instance_state "${selected_instance}" || log_error "加载 REALITY 实例失败: ${selected_instance}"
    echo -e "当前正在修改: $(protocol_display_name "${SB_PROTOCOL}") / ${SB_NODE_NAME} (${SB_VLESS_INSTANCE_ID})"
  else
    echo -e "当前正在修改: $(protocol_display_name "${SB_PROTOCOL}")"
  fi
  snapshot_dir=$(create_managed_state_snapshot) || log_error "无法创建配置状态事务快照。"
  prompt_protocol_update_fields "${selected_protocol}"
  if ! save_protocol_state "${selected_protocol}" || ! generate_config; then
    abort_managed_state_transaction "${snapshot_dir}" "协议配置生成或校验失败"
  fi
  if ! discard_managed_state_snapshot "${snapshot_dir}"; then
    log_warn "协议配置已提交，但临时事务快照未能删除: ${snapshot_dir}。"
  fi
  if [[ "${selected_protocol}" == "vless-reality" ]]; then
    refresh_vless_reality_qos_rules
  fi
  setup_service
  open_committed_protocol_ports || return $?
  load_protocol_state "${selected_protocol}"
  systemctl restart sing-box
  log_success "配置及服务文件已更新并重启服务。"
  log_info "连接信息未自动展示，如需查看请进入菜单 11。"
}

remove_protocol_menu() {
  local protocols=() selected_protocols=() remaining_protocols=()
  local selected_protocol display_str confirm
  local state_file backup_state_file transaction_dir
  local joined_protocols first_remaining protocol
  local reality_instances=() instance_state_file backup_instance_state_file
  local selected_instance first_remaining_instance removed_instance_port
  local reality_remove_mode="instance" choice removed_port
  local removed_ports=() idx raw_choice raw_choices chosen_protocol display_list

  if [[ ! -f "${SINGBOX_CONFIG_FILE}" && ! -f "${SB_PROTOCOL_INDEX_FILE}" ]]; then
    log_error "未找到配置文件或协议状态，请先执行安装流程。"
  fi

  migrate_legacy_single_protocol_state_if_needed
  load_current_config_state
  mapfile -t protocols < <(list_installed_protocols)

  if [[ ${#protocols[@]} -eq 0 ]]; then
    log_error "当前未检测到已安装协议。"
  fi

  echo -e "\n${BLUE}--- 移除已安装协议 ---${NC}"
  echo "可用协议:"
  for idx in "${!protocols[@]}"; do
    echo "$((idx + 1)). $(protocol_display_name "${protocols[$idx]}")"
  done
  echo "0. 返回"
  echo "留空则移除所有已安装协议。"
  read -rp "请选择一个或多个协议 [0-${#protocols[@]}]，逗号分隔: " choice

  if [[ -z "$(trim_whitespace "${choice}")" ]]; then
    selected_protocols=("${protocols[@]}")
  elif [[ "$(trim_whitespace "${choice}")" == "0" ]]; then
    return 0
  else
    IFS="," read -r -a raw_choices <<< "${choice}"
    for raw_choice in "${raw_choices[@]}"; do
      raw_choice=$(trim_whitespace "${raw_choice}")
      [[ -z "${raw_choice}" ]] && continue
      if [[ "${raw_choice}" =~ ^[1-9][0-9]*$ ]] && (( raw_choice >= 1 && raw_choice <= ${#protocols[@]} )); then
        chosen_protocol="${protocols[$((raw_choice - 1))]}"
        if ! protocol_array_contains "${chosen_protocol}" ${selected_protocols[@]+"${selected_protocols[@]}"}; then
          selected_protocols+=("${chosen_protocol}")
        fi
      else
        log_warn "跳过无效选项: ${raw_choice}"
      fi
    done
  fi

  if [[ ${#selected_protocols[@]} -eq 0 ]]; then
    log_info "未选择任何协议。"
    return 0
  fi

  if mixed_structured_state_active && protocol_array_contains mixed "${selected_protocols[@]}"; then
    if [[ ${#selected_protocols[@]} -eq 1 ]]; then
      mixed_instance_management_menu delete
      return $?
    fi
    log_warn "结构化 Mixed 实例需通过实例事务逐个移除；请先进入 Mixed 实例管理，再移除其他协议。本次未修改。"
    return 1
  fi
  if plain_proxy_structured_state_active socks && protocol_array_contains socks "${selected_protocols[@]}"; then
    if [[ ${#selected_protocols[@]} -eq 1 ]]; then
      socks_instance_management_menu delete
      return $?
    fi
    log_warn "结构化 SOCKS 实例需通过实例事务逐个移除；请先进入 SOCKS 实例管理，再移除其他协议。本次未修改。"
    return 1
  fi
  if plain_proxy_structured_state_active http && protocol_array_contains http "${selected_protocols[@]}"; then
    if [[ ${#selected_protocols[@]} -eq 1 ]]; then
      http_instance_management_menu delete
      return $?
    fi
    log_warn "结构化 HTTP 实例需通过实例事务逐个移除；请先进入 HTTP 实例管理，再移除其他协议。本次未修改。"
    return 1
  fi
  if plain_proxy_structured_state_active shadowsocks && protocol_array_contains shadowsocks "${selected_protocols[@]}"; then
    if [[ ${#selected_protocols[@]} -eq 1 ]]; then
      shadowsocks_instance_management_menu delete
      return $?
    fi
    log_warn "结构化 Shadowsocks 实例需通过实例事务逐个移除；请先进入 Shadowsocks 实例管理，再移除其他协议。本次未修改。"
    return 1
  fi

  if plain_proxy_structured_state_active trojan && protocol_array_contains trojan "${selected_protocols[@]}"; then
    if [[ ${#selected_protocols[@]} -eq 1 ]]; then
      trojan_instance_management_menu delete
      return $?
    fi
    log_warn "结构化 Trojan 实例需通过实例事务逐个移除；请先进入 Trojan 实例管理，再移除其他协议。本次未修改。"
    return 1
  fi
  if plain_proxy_structured_state_active vmess && protocol_array_contains vmess "${selected_protocols[@]}"; then
    if [[ ${#selected_protocols[@]} -eq 1 ]]; then
      vmess_instance_management_menu delete
      return $?
    fi
    log_warn "结构化 VMess 实例需通过实例事务逐个移除；请先进入 VMess 实例管理，再移除其他协议。本次未修改。"
    return 1
  fi
  if plain_proxy_structured_state_active vless-plain && protocol_array_contains vless-plain "${selected_protocols[@]}"; then
    if [[ ${#selected_protocols[@]} -eq 1 ]]; then
      vless_plain_instance_management_menu delete
      return $?
    fi
    log_warn "结构化 VLESS 实例需通过实例事务逐个移除；请先进入 VLESS 实例管理，再移除其他协议。本次未修改。"
    return 1
  fi
  if plain_proxy_structured_state_active anytls && protocol_array_contains anytls "${selected_protocols[@]}"; then
    if [[ ${#selected_protocols[@]} -eq 1 ]]; then
      anytls_instance_management_menu delete
      return $?
    fi
    log_warn "结构化 AnyTLS 实例需通过实例事务逐个移除；请先进入 AnyTLS 实例管理，再移除其他协议。本次未修改。"
    return 1
  fi
  if plain_proxy_structured_state_active hy2 && protocol_array_contains hy2 "${selected_protocols[@]}"; then
    if [[ ${#selected_protocols[@]} -eq 1 ]]; then
      hy2_instance_management_menu delete
      return $?
    fi
    log_warn "结构化 Hysteria2 实例需通过实例事务逐个移除；请先进入 Hysteria2 实例管理，再移除其他协议。本次未修改。"
    return 1
  fi
  if plain_proxy_structured_state_active snell && protocol_array_contains snell "${selected_protocols[@]}"; then
    if [[ ${#selected_protocols[@]} -eq 1 ]]; then
      snell_instance_management_menu delete
      return $?
    fi
    log_warn "结构化 Snell 实例需通过实例事务逐个移除；请先进入 Snell 实例管理，再移除其他协议。本次未修改。"
    return 1
  fi
  if plain_proxy_structured_state_active tuic && protocol_array_contains tuic "${selected_protocols[@]}"; then
    if [[ ${#selected_protocols[@]} -eq 1 ]]; then
      tuic_instance_management_menu delete
      return $?
    fi
    log_warn "结构化 TUIC 实例需通过实例事务逐个移除；请先进入 TUIC 实例管理，再移除其他协议。本次未修改。"
    return 1
  fi
  if plain_proxy_structured_state_active hysteria && protocol_array_contains hysteria "${selected_protocols[@]}"; then
    if [[ ${#selected_protocols[@]} -eq 1 ]]; then
      hysteria_instance_management_menu delete
      return $?
    fi
    log_warn "结构化 Hysteria 实例需通过实例事务逐个移除；请先进入 Hysteria 实例管理，再移除其他协议。本次未修改。"
    return 1
  fi

  # Selecting only VLESS + REALITY keeps the historical per-instance removal
  # flow when more than one managed instance exists, while still exposing an
  # explicit whole-protocol option. Multi-select and blank keep their newer
  # whole-protocol semantics.
  if [[ ${#selected_protocols[@]} -eq 1 && "${selected_protocols[0]}" == "vless-reality" ]]; then
    migrate_vless_reality_state_to_instances_if_needed
    mapfile -t reality_instances < <(list_vless_reality_instance_ids)
    if [[ ${#reality_instances[@]} -gt 1 ]]; then
      echo "检测到多个 REALITY 实例:"
      echo "1. 移除单个 REALITY 实例 (默认)"
      echo "2. 移除整个 VLESS + REALITY 协议"
      echo "0. 返回"
      read -rp "请选择移除范围 [1]: " reality_remove_mode
      reality_remove_mode=$(trim_whitespace "${reality_remove_mode}")
      case "${reality_remove_mode}" in
        ""|1) reality_remove_mode="instance" ;;
        2) reality_remove_mode="protocol" ;;
        0) return 0 ;;
        *)
          log_warn "无效选项，已取消移除。"
          return 0
          ;;
      esac
    fi
    if [[ ${#reality_instances[@]} -gt 1 && "${reality_remove_mode}" == "instance" ]]; then
      SELECTED_VLESS_INSTANCE_ID=""
      if ! prompt_vless_reality_instance_selection; then
        return 0
      fi
      selected_instance="${SELECTED_VLESS_INSTANCE_ID}"
      load_vless_reality_instance_state "${selected_instance}" || \
        log_error "未找到 REALITY 实例状态: ${selected_instance}"
      removed_instance_port="${SB_PORT}"
      read -rp "确认移除 REALITY 实例 ${SB_NODE_NAME} (${selected_instance})? [y/N]: " confirm
      if [[ "${confirm}" != "y" && "${confirm}" != "Y" ]]; then
        log_info "已取消移除 REALITY 实例。"
        return 0
      fi

      instance_state_file=$(vless_reality_instance_state_file "${selected_instance}") || \
        log_error "REALITY 实例 ID 非法: ${selected_instance}"
      state_file=$(protocol_state_file "vless-reality")
      [[ -f "${instance_state_file}" ]] || log_error "未找到 REALITY 实例状态文件: ${instance_state_file}"
      [[ -f "${state_file}" ]] || log_error "未找到协议状态文件: ${state_file}"

      transaction_dir=$(create_managed_state_snapshot) || log_error "无法创建配置状态事务快照。"
      backup_instance_state_file="${instance_state_file}.bak.$(date +%Y%m%d%H%M%S)"
      if ! mv "${instance_state_file}" "${backup_instance_state_file}"; then
        abort_managed_state_transaction "${transaction_dir}" "REALITY 实例状态备份失败"
      fi

      load_vless_reality_protocol_state
      remove_vless_reality_instance_id_from_list "${selected_instance}"
      first_remaining_instance="${VLESS_REALITY_INSTANCE_IDS%%,*}"
      if [[ "${VLESS_REALITY_DEFAULT_INSTANCE_ID:-main}" == "${selected_instance}" ]]; then
        VLESS_REALITY_DEFAULT_INSTANCE_ID="${first_remaining_instance}"
      fi
      if ! save_vless_reality_protocol_state; then
        abort_managed_state_transaction "${transaction_dir}" "REALITY 协议状态写入失败"
      fi

      if ! generate_config; then
        abort_managed_state_transaction "${transaction_dir}" "移除 REALITY 实例后配置生成或校验失败"
      fi

      if ! discard_managed_state_snapshot "${transaction_dir}"; then
        log_warn "REALITY 实例移除已提交，但临时事务快照未能删除: ${transaction_dir}。"
      fi
      setup_service
      load_protocol_state "vless-reality"
      open_committed_protocol_ports || return $?
      refresh_vless_reality_qos_rules
      systemctl restart sing-box
      close_firewall_port "${removed_instance_port}" || return $?
      log_success "已移除 REALITY 实例: ${selected_instance}。原状态已备份到: ${backup_instance_state_file}"
      return 0
    fi
  fi

  display_list=()
  for selected_protocol in "${selected_protocols[@]}"; do
    display_list+=("$(protocol_display_name "${selected_protocol}")")
  done
  display_str=$(IFS=", "; printf "%s" "${display_list[*]}")
  read -rp "确认移除下列协议: ${display_str}? [y/N]: " confirm
  if [[ "${confirm}" != "y" && "${confirm}" != "Y" ]]; then
    log_info "已取消移除协议。"
    return 0
  fi

  transaction_dir=$(create_managed_state_snapshot) || log_error "无法创建配置状态事务快照。"
  if [[ ${#selected_protocols[@]} -eq ${#protocols[@]} ]]; then
    if ! persist_file_backup "${SINGBOX_CONFIG_FILE}" "${SINGBOX_CONFIG_FILE}.bak" ||
       ! persist_file_backup "${SB_PROTOCOL_INDEX_FILE}" "${SB_PROTOCOL_INDEX_FILE}.bak"; then
      abort_managed_state_transaction "${transaction_dir}" "无法为当前配置和协议索引创建持久备份"
    fi
  fi

  for selected_protocol in "${selected_protocols[@]}"; do
    if [[ "${selected_protocol}" == "vless-reality" ]]; then
      migrate_vless_reality_state_to_instances_if_needed
      mapfile -t reality_instances < <(list_vless_reality_instance_ids)
      if [[ ${#reality_instances[@]} -gt 0 ]]; then
        for instance_id in "${reality_instances[@]}"; do
          if ! instance_state_file=$(vless_reality_instance_state_file "${instance_id}"); then
            abort_managed_state_transaction "${transaction_dir}" "REALITY 实例 ID 非法: ${instance_id}"
          fi
          if [[ ! -f "${instance_state_file}" ]]; then
            abort_managed_state_transaction "${transaction_dir}" "未找到 REALITY 实例状态: ${instance_id}"
          fi
          backup_instance_state_file="${instance_state_file}.bak.$(date +%Y%m%d%H%M%S)"
          if ! mv "${instance_state_file}" "${backup_instance_state_file}"; then
            abort_managed_state_transaction "${transaction_dir}" "REALITY 实例状态备份失败: ${instance_id}"
          fi
          # Capture removed instance port for firewall cleanup
          removed_ports+=("$(sed -n 's/^PORT=//p' "${backup_instance_state_file}" 2>/dev/null || true)")
        done
        state_file=$(protocol_state_file "vless-reality")
        if [[ -f "${state_file}" ]]; then
          backup_state_file="${state_file}.bak.$(date +%Y%m%d%H%M%S)"
          if ! mv "${state_file}" "${backup_state_file}"; then
            abort_managed_state_transaction "${transaction_dir}" "VLESS + REALITY 协议状态备份失败"
          fi
          VLESS_REALITY_INSTANCE_IDS=""
          VLESS_REALITY_DEFAULT_INSTANCE_ID=""
        else
          abort_managed_state_transaction "${transaction_dir}" "未找到 VLESS + REALITY 协议状态"
        fi
      else
        abort_managed_state_transaction "${transaction_dir}" "未找到可移除的 REALITY 实例状态"
      fi
    else
      state_file=$(protocol_state_file "${selected_protocol}")
      if [[ -f "${state_file}" ]]; then
        backup_state_file="${state_file}.bak.$(date +%Y%m%d%H%M%S)"
        if ! mv "${state_file}" "${backup_state_file}"; then
          abort_managed_state_transaction "${transaction_dir}" "协议状态备份失败: ${selected_protocol}"
        fi
        # Capture removed protocol port for firewall cleanup
        removed_ports+=("$(sed -n 's/^PORT=//p' "${backup_state_file}" 2>/dev/null || true)")
      else
        abort_managed_state_transaction "${transaction_dir}" "未找到协议状态: ${selected_protocol}"
      fi
    fi
  done

  for protocol in "${protocols[@]}"; do
    if protocol_array_contains "${protocol}" "${selected_protocols[@]}"; then
      continue
    fi
    remaining_protocols+=("${protocol}")
  done

  if [[ ${#remaining_protocols[@]} -gt 0 ]]; then
    joined_protocols=$(IFS=,; printf "%s" "${remaining_protocols[*]}")
    if ! write_protocol_index "${joined_protocols}"; then
      abort_managed_state_transaction "${transaction_dir}" "协议索引写入失败"
    fi
  else
    # Stop before treating the new inventory as empty. A stop failure must not
    # turn a still-running listener into an apparently unreferenced resource.
    local stop_status
    if systemctl stop sing-box >/dev/null 2>&1; then :; else
      stop_status=$?
      rollback_managed_state_snapshot "${transaction_dir}" || \
        log_warn "服务停止失败且文件回滚失败；请检查事务快照。"
      printf '[ERROR] protocol_remove: stop_failed; firewall_unchanged\n' >&2
      return "${stop_status}"
    fi
    if ! singbox_service_confirmed_stopped; then
      rollback_managed_state_snapshot "${transaction_dir}" || \
        log_warn "服务状态无法确认且文件回滚失败；请检查事务快照。"
      printf '[ERROR] protocol_remove: service_state_unconfirmed; inspect_service_manually\n' >&2
      return 1
    fi
    rm -f "${SB_PROTOCOL_INDEX_FILE}"
    rm -f "${SINGBOX_CONFIG_FILE}"
    if command -v tc >/dev/null 2>&1; then
      clear_vless_reality_qos_rules
    fi
    if systemctl disable sing-box >/dev/null 2>&1; then :; else
      stop_status=$?
      printf '[ERROR] protocol_remove: disable_failed; service_stopped; firewall_unchanged; snapshot=%s\n' "${transaction_dir}" >&2
      return "${stop_status}"
    fi
    for removed_port in "${removed_ports[@]}"; do
      if [[ -n "${removed_port}" ]]; then
        close_firewall_port "${removed_port}" all_removed || return $?
      fi
    done
    if ! discard_managed_state_snapshot "${transaction_dir}"; then
      log_warn "协议移除已提交，但临时事务快照未能删除: ${transaction_dir}。"
    fi
    log_info "所有协议已移除，sing-box 服务已停止。"
    return 0
  fi

  if ! generate_config; then
    abort_managed_state_transaction "${transaction_dir}" "移除协议后配置生成或校验失败"
  fi

  if ! discard_managed_state_snapshot "${transaction_dir}"; then
    log_warn "协议移除已提交，但临时事务快照未能删除: ${transaction_dir}。"
  fi
  setup_service
  first_remaining="${remaining_protocols[0]}"
  load_protocol_state "${first_remaining}"
  open_committed_protocol_ports || return $?
  refresh_vless_reality_qos_rules
  systemctl restart sing-box
  for removed_port in "${removed_ports[@]}"; do
    if [[ -n "${removed_port}" ]]; then
      close_firewall_port "${removed_port}" || return $?
    fi
  done
  log_success "已移除协议: ${display_str}。"
}

get_public_ip() {
  get_public_ipv4 || get_public_ipv6
}

get_public_ipv4() {
  curl -4 -s https://api.ip.sb/ip 2>/dev/null || curl -4 -s https://ifconfig.me 2>/dev/null || true
}

get_public_ipv6() {
  curl -6 -s https://api.ip.sb/ip 2>/dev/null || curl -6 -s https://ifconfig.me 2>/dev/null || true
}

normalize_ip_list() {
  sed -E 's/^[[:space:]]+//; s/[[:space:]]+$//' | sed '/^$/d' | sort -u
}

get_public_ip_candidates() {
  local ipv4_address ipv6_address

  ipv4_address=$(get_public_ipv4 || true)
  ipv6_address=$(get_public_ipv6 || true)

  {
    printf '%s\n' "${ipv4_address}"
    printf '%s\n' "${ipv6_address}"
  } | normalize_ip_list
}

resolve_domain_ip_candidates() {
  local domain=$1
  local resolved_any="n"

  if command -v getent >/dev/null 2>&1; then
    getent ahosts "${domain}" 2>/dev/null | awk '{print $1}' | normalize_ip_list || true
    resolved_any="y"
  fi

  if command -v dig >/dev/null 2>&1; then
    {
      dig +short A "${domain}" 2>/dev/null || true
      dig +short AAAA "${domain}" 2>/dev/null || true
    } | normalize_ip_list
    resolved_any="y"
  fi

  if [[ "${resolved_any}" == "n" ]] && command -v nslookup >/dev/null 2>&1; then
    nslookup "${domain}" 2>/dev/null | awk '/^Address: / {print $2}' | normalize_ip_list || true
  fi
}

ip_lists_have_match() {
  local public_ips=$1
  local domain_ips=$2
  local public_ip domain_ip

  while IFS= read -r public_ip; do
    [[ -z "${public_ip}" ]] && continue
    while IFS= read -r domain_ip; do
      [[ -z "${domain_ip}" ]] && continue
      [[ "${public_ip}" == "${domain_ip}" ]] && return 0
    done <<< "${domain_ips}"
  done <<< "${public_ips}"

  return 1
}

confirm_domain_ip_mismatch() {
  local protocol_name=$1
  local domain=$2
  local public_ips=$3
  local domain_ips=$4
  local answer

  log_warn "${protocol_name} 域名解析结果与本机公网出口 IP 不匹配。"
  echo "域名: ${domain}"
  echo "本机公网出口 IP:"
  if [[ -n "${public_ips}" ]]; then
    printf '  - %s\n' ${public_ips}
  else
    echo "  - 未获取到"
  fi
  echo "域名解析 IP:"
  if [[ -n "${domain_ips}" ]]; then
    printf '  - %s\n' ${domain_ips}
  else
    echo "  - 未解析到"
  fi
  log_warn "如果继续，ACME HTTP-01 签发或客户端连接可能失败。CDN、反代、DNS-01 或手动证书场景可确认继续。"
  read -rp "仍要继续使用该域名吗？[y/N]: " answer
  [[ "${answer}" == "y" || "${answer}" == "Y" ]]
}

validate_tls_domain_points_to_server() {
  local protocol_name=$1
  local domain=$2
  local public_ips domain_ips

  public_ips=$(get_public_ip_candidates | normalize_ip_list || true)
  domain_ips=$(resolve_domain_ip_candidates "${domain}" | normalize_ip_list || true)

  if [[ -n "${public_ips}" && -n "${domain_ips}" ]] && ip_lists_have_match "${public_ips}" "${domain_ips}"; then
    return 0
  fi

  confirm_domain_ip_mismatch "${protocol_name}" "${domain}" "${public_ips}" "${domain_ips}"
}

format_share_host() {
  local host=$1

  if [[ "${host}" == *:* && "${host}" != \[*\] ]]; then
    printf '[%s]' "${host}"
  else
    printf '%s' "${host}"
  fi
}

build_vless_link() {
  local public_ip=$1
  local address_label=${2:-}
  local share_host node_name advanced_query alpn_value
  share_host=$(format_share_host "${public_ip}")
  node_name=$(vless_reality_display_node_name "${SB_NODE_NAME}" "${address_label}")
  advanced_query=""
  alpn_value=$(vless_reality_alpn_link_value_for_mode "${SB_VLESS_ALPN_MODE:-off}")
  [[ -n "${alpn_value}" ]] && advanced_query="${advanced_query}&alpn=${alpn_value}"
  [[ "${SB_VLESS_TCP_FAST_OPEN:-n}" == "y" ]] && advanced_query="${advanced_query}&tfo=1"

  printf 'vless://%s@%s:%s?security=reality&sni=%s&fp=chrome&pbk=%s&sid=%s%s&flow=xtls-rprx-vision#%s' \
    "${SB_UUID}" "${share_host}" "${SB_PORT}" "${SB_SNI}" "${SB_PUBLIC_KEY:-[密钥丢失，请更新配置]}" "${SB_SHORT_ID_1}" "${advanced_query}" "${node_name}"
}

vless_reality_rate_limit_summary() {
  local up_mbps=${1:-}
  local down_mbps=${2:-}
  local up_text down_text

  if [[ -n "${up_mbps}" ]]; then
    up_text="上行 ${up_mbps} Mbps"
  else
    up_text="上行不限"
  fi

  if [[ -n "${down_mbps}" ]]; then
    down_text="下行 ${down_mbps} Mbps"
  else
    down_text="下行不限"
  fi

  printf '%s / %s' "${up_text}" "${down_text}"
}

build_vless_link_for_instance() {
  local instance_id=$1
  local public_ip=$2
  local address_label=${3:-}
  local link_output status=0

  load_vless_reality_protocol_state
  load_vless_reality_instance_state "${instance_id}" || return 1
  link_output=$(build_vless_link "${public_ip}" "${address_label}") || status=$?
  load_vless_reality_instance_state "${VLESS_REALITY_DEFAULT_INSTANCE_ID:-main}" >/dev/null 2>&1 || true

  if (( status != 0 )); then
    return "${status}"
  fi
  printf '%s' "${link_output}"
}

encode_uri_userinfo_component() {
  local LC_ALL=C value=${1:-} result="" character encoded index
  for ((index=0; index<${#value}; index++)); do
    character=${value:index:1}
    case "${character}" in
      [a-zA-Z0-9.~_-]) result+="${character}" ;;
      *) printf -v encoded '%%%02X' "'${character}" || return 1; result+="${encoded}" ;;
    esac
  done
  printf '%s' "${result}"
}

plain_proxy_http_auth_representable() {
  local LC_ALL=C
  [[ "${SB_MIXED_AUTH_ENABLED:-}" == n ]] && return 0
  [[ "${SB_MIXED_AUTH_ENABLED:-}" == y ]] || return 1
  # RFC 7617: the first colon separates user/password; neither admits CTL.
  [[ "${SB_MIXED_USERNAME:-}" != *:* &&
     ! "${SB_MIXED_USERNAME:-}${SB_MIXED_PASSWORD:-}" =~ [[:cntrl:]] ]]
}

validate_http_client_connection() {
  local port=${1:-} auth_enabled=${2:-} username=${3:-} password=${4:-}
  local username_bytes password_bytes
  [[ "${port}" =~ ^[0-9]{1,5}$ ]] || return 1
  jq -en --arg port "${port}" '$port | tonumber | . >= 1 and . <= 65535' >/dev/null || return 1
  case "${auth_enabled}" in
    y)
      [[ -n "${username}" && -n "${password}" ]] || return 1
      username_bytes=$(printf '%s' "${username}" | wc -c) || return 1
      password_bytes=$(printf '%s' "${password}" | wc -c) || return 1
      [[ "${username_bytes}" =~ ^[0-9]+$ && "${password_bytes}" =~ ^[0-9]+$ &&
        "${username_bytes}" -le 4096 && "${password_bytes}" -le 4096 ]]
      ;;
    n) return 0 ;;
    *) return 1 ;;
  esac
}

# Shared typed transport contract for the VMess/Trojan/plain-VLESS adapters.
# This does not register a deployable protocol. Native TCP is represented in
# managed data by {type:"none"}; it must be omitted from sing-box configuration.
# No state, certificate, account, credential or public-network access occurs here.
validate_v2ray_transport_state_json() {
  local transport_json=${1:-} LC_ALL=C
  [[ $# -eq 1 && -n "${transport_json}" && ${#transport_json} -le 65536 ]] || return 1
  jq -es '
    def bounded($n): type == "string" and utf8bytelength <= $n and
      (test("[\u0000-\u001f\u007f]") | not);
    def token: bounded(256) and length > 0 and
      test("^[!#$%&\u0027*+.^_`|~0-9A-Za-z-]+$");
    def allowed($keys): (keys_unsorted - $keys | length) == 0;
    def optional($key; filter): if has($key) then .[$key] | filter else true end;
    # A shared server/client path is decoded text, not a URI. Query, fragment
    # and percent-encoded paths have different server/client interpretations.
    def path: bounded(4096) and (length == 0 or startswith("/")) and
      (test("[%?#]") | not);
    def host: bounded(1024) and length > 0 and (test("[ /@?#%\\\\]") | not);
    def host_list: if type == "string" then host
      elif type == "array" then length <= 32 and all(.[]; host)
      else false end;
    # Managed timeouts use bounded, non-negative ASCII Go duration units.
    # Reject overflow before a core check; do not silently clamp or normalize.
    def duration:
      bounded(64) and
      (if . == "0" then true
       elif test("^([0-9]+(\\.[0-9]+)?(ns|us|ms|s|m|h))+$") then
         ([scan("([0-9]+(?:\\.[0-9]+)?)(ns|us|ms|s|m|h)") |
           (.[0] | tonumber) *
           ({ns:0.000000001,us:0.000001,ms:0.001,s:1,m:60,h:3600}[.[1]])] |
          add <= 86400)
       else false end);
    def header_values:
      if type == "string" then bounded(4096)
      elif type == "array" then length > 0 and length <= 32 and all(.[]; bounded(4096))
      else false end;
    def headers($ws):
      type == "object" and length <= 64 and
      ([keys_unsorted[] | ascii_downcase] | unique | length) == length and
      all(to_entries[];
        (.key | token) and (.value | header_values) and
        (.key | ascii_downcase) as $key |
        (["connection","proxy-connection","upgrade","content-length","content-encoding","expect","transfer-encoding","keep-alive",
          "te","trailer","sec-websocket-key","sec-websocket-accept",
          "sec-websocket-version","sec-websocket-extensions"] |
          index($key) | not) and
        (if $key == "host" then $ws and
           (.value | if type == "array" then length == 1 and (.[0] | host) else host end)
         elif $key == "sec-websocket-protocol" then $ws and
           (.value | if type == "array" then length == 1 and (.[0] | token) else token end)
         else true end));
    def record:
      type == "object" and (.type | type == "string") and
      (if .type == "none" or .type == "quic" then allowed(["type"])
       elif .type == "http" then
         allowed(["type","host","path","method","headers","idle_timeout","ping_timeout"]) and
         optional("host"; host_list) and optional("path"; path) and
         optional("method"; (. == "" or token) and . != "HEAD" and . != "CONNECT") and
         optional("headers"; headers(false)) and
         optional("idle_timeout"; duration) and optional("ping_timeout"; duration)
       elif .type == "ws" then
         allowed(["type","path","headers","max_early_data","early_data_header_name"]) and
         optional("path"; path) and optional("headers"; headers(true)) and
         # The core compares RequestURI against the unescaped base path when
         # early data uses the path, even with max_early_data=0. Only header-
         # based early data can safely use characters that Go URL-escapes.
         (if (.early_data_header_name // "") == "" then
            optional("path"; test("^[A-Za-z0-9/._~$&+,;=:@-]*$"))
          else true end) and
         optional("max_early_data"; type == "number" and floor == . and . >= 0 and . <= 65536) and
         optional("early_data_header_name"; . == "" or token) and
         (if (.early_data_header_name // "") != "" then
           (.max_early_data // 0) > 0 and
           (.early_data_header_name | ascii_downcase) as $key |
           (["host","connection","proxy-connection","upgrade","content-length","content-encoding","expect","transfer-encoding","keep-alive",
             "te","trailer","sec-websocket-key","sec-websocket-accept",
             "sec-websocket-version","sec-websocket-extensions"] | index($key) | not) and
           ([((.headers // {}) | keys_unsorted[]) | ascii_downcase] | index($key) | not)
          else true end)
       elif .type == "grpc" then
         allowed(["type","service_name","idle_timeout","ping_timeout","permit_without_stream"]) and
         optional("service_name"; bounded(256) and test("^[A-Za-z0-9_.-]*$")) and
         optional("idle_timeout"; duration) and optional("ping_timeout"; duration) and
         # The default lite gRPC build does not implement this standard-gRPC option.
         optional("permit_without_stream"; . == false)
       elif .type == "httpupgrade" then
         allowed(["type","host","path","headers"]) and
         optional("host"; . == "" or host) and optional("path"; path) and
         optional("headers"; headers(false))
       else false end);
    length == 1 and (.[0] | record)
  ' <<< "${transport_json}" >/dev/null 2>&1
}

inspect_v2ray_transport_profile_json() {
  local family=${1:-} transport_json=${2:-} tls_mode=${3:-} flow=${4-} core_version=${5:-}
  local transport_type listen_network=tcp alpn='[]' required_build_tags='[]'
  [[ $# -eq 5 ]] || {
    printf '[ERROR] v2ray_transport: invalid arguments\n' >&2
    return 1
  }
  # Explicit family, not normalize_protocol_id: the historical vless alias
  # remains vless-reality, while this API describes the upstream family.
  case "${family}" in vmess|trojan|vless) ;; *)
    printf '[ERROR] v2ray_transport: unsupported family\n' >&2; return 1 ;;
  esac
  case "${tls_mode}" in disabled|tls|reality) ;; *)
    printf '[ERROR] v2ray_transport: invalid security mode\n' >&2; return 1 ;;
  esac
  core_version=${core_version#v}
  if [[ ! "${core_version}" =~ ^[0-9]{1,6}\.[0-9]{1,6}\.[0-9]{1,6}$ ]] ||
      ! singbox_version_at_least "${core_version}" 1.13.0 ||
      ! singbox_version_at_least "${SB_SUPPORT_MAX_VERSION}" "${core_version}"; then
    printf '[ERROR] v2ray_transport: unsupported core version\n' >&2
    return 1
  fi
  if ! validate_v2ray_transport_state_json "${transport_json}"; then
    printf '[ERROR] v2ray_transport: invalid typed transport\n' >&2
    return 1
  fi
  transport_type=$(jq -er '.type' <<< "${transport_json}") || return 1
  # Managed REALITY remains the native VLESS preset, not a generic switch
  # offered for arbitrary protocols/transports accepted by a loose TLS schema.
  if [[ "${tls_mode}" == reality && ( "${family}" != vless || "${transport_type}" != none ) ]] ||
      [[ -n "${flow}" && ( "${flow}" != xtls-rprx-vision || "${family}" != vless ||
        "${transport_type}" != none || "${tls_mode}" == disabled ) ]] ||
      [[ "${transport_type}" == quic && "${tls_mode}" != tls ]]; then
    printf '[ERROR] v2ray_transport: incompatible security or flow\n' >&2
    return 1
  fi
  if [[ "${transport_type}" == quic ]]; then
    listen_network=udp
    required_build_tags='["with_quic"]'
  fi
  if [[ "${tls_mode}" == tls ]]; then
    case "${transport_type}" in
      http|grpc) alpn='["h2"]' ;;
      ws|httpupgrade) alpn='["http/1.1"]' ;;
      quic) alpn='["h3"]' ;;
    esac
  fi
  jq -cn --argjson transport "${transport_json}" --arg network "${listen_network}" \
    --argjson alpn "${alpn}" --argjson required_build_tags "${required_build_tags}" '
    {transport:(if $transport.type == "none" then null else $transport end),
     listen_networks:[$network],tls_alpn:$alpn,required_build_tags:$required_build_tags,
     runtime_guard:(if $transport.type == "httpupgrade" then
       {status:"blocked",code:"httpupgrade_runtime_unreliable"}
       elif $transport.type == "ws" and ($transport.max_early_data // 0) > 0 then
       {status:"blocked",code:"ws_early_data_runtime_unreliable"}
       else {status:"requires_validation",code:null} end)}'
}

build_v2ray_transport_profile_json() {
  local profile guard_code
  profile=$(inspect_v2ray_transport_profile_json "$@") || return 1
  # Fixed 1.13.18/1.14.0 HTTPUpgrade client/server pairs intermittently lose
  # their protocol handshake despite passing check (both TLS and plaintext).
  # Keep inspection/reproduction available, but never publish this known
  # unreliable transport through the normal adapter contract. A newer core
  # must be independently revalidated before this guard is removed. WebSocket
  # early data also exposed response corruption; block it for all families and
  # security modes because the client upgrade buffering path is shared.
  if ! jq -e '.runtime_guard.status == "requires_validation"' <<< "${profile}" >/dev/null; then
    guard_code=$(jq -er '.runtime_guard.code' <<< "${profile}") || return 1
    printf '[ERROR] v2ray_transport: %s; use diagnostic inspection, not deployment\n' "${guard_code}" >&2
    return 1
  fi
  printf '%s\n' "${profile}"
}

validate_http_tls_state_json() {
  local tls_json=${1:-}
  [[ -n "${tls_json}" ]] || return 1
  jq -e 'type == "object" and (.enabled | type == "boolean") and
    (if .enabled then
       (keys_unsorted | sort) == ["certificate_path", "enabled", "key_path", "server_name"] and
       (.server_name | type == "string" and length > 0 and (test("[\u0000-\u001F\u007F]") | not)) and
       (.certificate_path | type == "string" and startswith("/") and (test("[\u0000-\u001F\u007F]") | not)) and
       (.key_path | type == "string" and startswith("/") and (test("[\u0000-\u001F\u007F]") | not))
     else
       (keys_unsorted | sort) == ["enabled"]
     end)' <<< "${tls_json}" >/dev/null
}

read_public_certificate_pem() {
  local certificate_path=${1:-} staged certificate_size certificate_pem
  [[ -n "${certificate_path}" && -f "${certificate_path}" && -r "${certificate_path}" ]] || return 1
  staged=$(mktemp) || return 1
  if ! head -c 1048577 -- "${certificate_path}" > "${staged}"; then
    rm -f -- "${staged}"
    return 1
  fi
  certificate_size=$(wc -c < "${staged}") || {
    rm -f -- "${staged}"
    return 1
  }
  if [[ ! "${certificate_size}" =~ ^[0-9]+$ || "${certificate_size}" -gt 1048576 ]]; then
    rm -f -- "${staged}"
    return 1
  fi
  certificate_pem=$(<"${staged}") || {
    rm -f -- "${staged}"
    return 1
  }
  rm -f -- "${staged}" || return 1
  LC_ALL=C awk '
    BEGIN { state = 0; certificates = 0; invalid = 0; payload = 0 }
    {
      line = $0
      sub(/\r$/, "", line)
      if (line ~ /^[[:space:]]*$/) next
      if (state == 0) {
        if (line == "-----BEGIN CERTIFICATE-----") { state = 1; payload = 0 }
        else { invalid = 1; next }
      } else if (line == "-----END CERTIFICATE-----") {
        if (payload == 0) invalid = 1
        else { state = 0; certificates++ }
      } else if (line !~ /^[A-Za-z0-9+\/=]+$/) {
        invalid = 1
      } else payload = 1
    }
    END { exit !(invalid == 0 && state == 0 && certificates > 0) }
  ' <<< "${certificate_pem}" >/dev/null || return 1
  printf '%s' "${certificate_pem}"
}

build_plain_proxy_link() {
  local scheme=${1:-} public_ip=${2:-} share_host username password
  [[ "${scheme}" == http || "${scheme}" == socks5 ]] || return 1
  [[ -n "${public_ip}" && "${public_ip}" != *[[:space:]@/?#%]* ]] || return 1
  if [[ "${scheme}" == http ]]; then
    validate_http_client_connection "${SB_PORT:-}" "${SB_MIXED_AUTH_ENABLED:-}" \
      "${SB_MIXED_USERNAME:-}" "${SB_MIXED_PASSWORD:-}" || return 1
  else
    validate_mixed_client_connection "${SB_PORT:-}" "${SB_MIXED_AUTH_ENABLED:-}" \
      "${SB_MIXED_USERNAME:-}" "${SB_MIXED_PASSWORD:-}" || return 1
  fi
  if [[ "${scheme}" == http ]] && ! plain_proxy_http_auth_representable; then
    printf '[WARN] mixed_http_auth_unrepresentable: HTTP Basic 无法表达当前认证；请使用 SOCKS5 或客户端 JSON，原凭据未修改。\n' >&2
    return 1
  fi
  share_host=$(format_share_host "${public_ip}") || return 1
  if [[ "${SB_MIXED_AUTH_ENABLED}" == y ]]; then
    username=$(encode_uri_userinfo_component "${SB_MIXED_USERNAME}") || return 1
    password=$(encode_uri_userinfo_component "${SB_MIXED_PASSWORD}") || return 1
    printf '%s://%s:%s@%s:%s' "${scheme}" "${username}" "${password}" "${share_host}" "${SB_PORT}"
  else
    printf '%s://%s:%s' "${scheme}" "${share_host}" "${SB_PORT}"
  fi
}

build_mixed_http_link() { build_plain_proxy_link http "$@"; }
build_mixed_socks5_link() { build_plain_proxy_link socks5 "$@"; }

build_plain_proxy_links_json() {
  local protocol=${1:-} address=${2:-} socks_link="" http_link="" tls_json
  case "${protocol}" in
    mixed)
      socks_link=$(build_mixed_socks5_link "${address}") || return 1
      if plain_proxy_http_auth_representable; then
        http_link=$(build_mixed_http_link "${address}") || return 1
      fi
      jq -cn --arg socks5 "${socks_link}" --arg http "${http_link}" \
        '{socks5:$socks5} + (if $http == "" then {} else {http:$http} end)'
      ;;
    socks)
      socks_link=$(build_mixed_socks5_link "${address}") || return 1
      jq -cn --arg socks5 "${socks_link}" '{socks5:$socks5}'
      ;;
    http)
      tls_json=${SB_HTTP_TLS_JSON:-}
      validate_http_tls_state_json "${tls_json}" || return 1
      validate_http_client_connection "${SB_PORT:-}" "${SB_MIXED_AUTH_ENABLED:-}" \
        "${SB_MIXED_USERNAME:-}" "${SB_MIXED_PASSWORD:-}" || return 1
      plain_proxy_http_auth_representable || return 1
      [[ -n "${address}" && "${address}" != *[[:space:]@/?#%]* ]] || return 1
      if jq -e '.enabled == true' <<< "${tls_json}" >/dev/null 2>&1; then
        jq -cn '{}'
      else
        http_link=$(build_mixed_http_link "${address}") || return 1
        jq -cn --arg http "${http_link}" '{http:$http}'
      fi
      ;;
    *) return 1 ;;
  esac
}

plain_proxy_share_warnings_json() {
  local protocol=${1:-} unavailable=false tls_uri_unavailable=false tls_json
  case "${protocol}" in
    mixed|socks) ;;
    http)
      tls_json=${SB_HTTP_TLS_JSON:-}
      validate_http_tls_state_json "${tls_json}" || return 1
      validate_http_client_connection "${SB_PORT:-}" "${SB_MIXED_AUTH_ENABLED:-}" \
        "${SB_MIXED_USERNAME:-}" "${SB_MIXED_PASSWORD:-}" || return 1
      plain_proxy_http_auth_representable || return 1
      if jq -e '.enabled == true' <<< "${tls_json}" >/dev/null 2>&1; then
        tls_uri_unavailable=true
      fi
      ;;
    *) return 1 ;;
  esac
  if [[ "${protocol}" == mixed ]] && ! plain_proxy_http_auth_representable; then unavailable=true; fi
  jq -cn --argjson unavailable "${unavailable}" --argjson tls_uri_unavailable "${tls_uri_unavailable}" \
    --arg protocol "${protocol}" '
    (if $protocol == "http" then [] else [{code:"socks5_uri_transport_options_omitted",message:"SOCKS5 URI 只携带代理地址和认证，不携带 UoT v2 等客户端选项；完整连接配置请使用 export-client JSON。"}] end)
    + (if $protocol == "http" and ($tls_uri_unavailable | not) then [{code:"http_plaintext_transport",message:"HTTP 代理入口未启用 TLS，认证信息与非加密业务可能被读取；访问 HTTPS 目标不等于代理入口已加密。仅用于可信网络或受保护隧道。"}] else [] end)
    + (if $protocol == "http" then [] else (if $unavailable then [{code:"mixed_http_auth_unrepresentable",message:"当前认证不符合 HTTP Basic 字段约束，未提供 HTTP 链接；SOCKS5 和客户端 JSON 仍可使用，原凭据未修改。"}] else [] end) end)
    + (if $tls_uri_unavailable then [{code:"http_tls_uri_unrepresentable",message:"HTTP TLS 客户端配置包含证书信任或 SNI，分享 URI 无法安全表达；未提供 HTTP 链接，请使用客户端 JSON 导出。"}] else [] end)'
}

hy2_manual_certificate_algorithm() {
  local algorithm

  [[ "${SB_HY2_TLS_MODE:-}" == "manual" ]] || return 1
  [[ -n "${SB_HY2_CERT_PATH:-}" && -r "${SB_HY2_CERT_PATH}" ]] || return 1
  command -v openssl >/dev/null 2>&1 || return 1

  algorithm=$(LC_ALL=C openssl x509 -in "${SB_HY2_CERT_PATH}" -noout -text 2>/dev/null \
    | awk -F': ' '/Public Key Algorithm:/ {print $2; exit}' || true)
  algorithm=$(trim_whitespace "${algorithm}")
  [[ -n "${algorithm}" ]] || return 1

  printf '%s' "${algorithm}"
}

hy2_manual_certificate_uses_ed25519() {
  local algorithm

  algorithm=$(hy2_manual_certificate_algorithm) || return 1
  [[ "${algorithm^^}" == "ED25519" ]]
}

hy2_certificate_path_uses_ed25519() {
  local certificate_path=${1:-} algorithm

  [[ -n "${certificate_path}" && -r "${certificate_path}" ]] || return 1
  command -v openssl >/dev/null 2>&1 || return 1
  algorithm=$(LC_ALL=C openssl x509 -in "${certificate_path}" -noout -text 2>/dev/null \
    | awk -F': ' '/Public Key Algorithm:/ {print $2; exit}' || true)
  algorithm=$(trim_whitespace "${algorithm}")
  [[ "${algorithm^^}" == "ED25519" ]]
}

hy2_ed25519_share_warning_json() {
  local certificate_path=${1:-}

  if ! hy2_certificate_path_uses_ed25519 "${certificate_path}"; then
    printf '[]'
    return 0
  fi
  jq -cn '[{
    code:"hy2_ed25519_share_link_requires_client_override",
    message:"检测到 Hysteria2 手动 Ed25519 证书；分享链接无法携带 disable_chrome_parrot，1.14+ 客户端必须手动启用该选项。"
  }]'
}

hy2_client_needs_chrome_parrot_disabled() {
  singbox_config_supports_1_14 && hy2_manual_certificate_uses_ed25519
}

build_hy2_compatibility_warnings_json() {
  local context=${1:-share}
  local algorithm code message

  if [[ "${SB_HY2_TLS_MODE:-}" != "manual" ]]; then
    printf '[]'
    return 0
  fi

  if ! algorithm=$(hy2_manual_certificate_algorithm); then
    jq -n '[{
      code: "hy2_certificate_algorithm_unknown",
      message: "无法识别 Hysteria2 手动证书的公钥算法；请确认 1.14+ 客户端与证书算法兼容。"
    }]'
    return 0
  fi

  if [[ "${algorithm^^}" != "ED25519" ]]; then
    printf '[]'
    return 0
  fi

  if [[ "${context}" == "export" ]]; then
    if ! singbox_config_supports_1_14; then
      printf '[]'
      return 0
    fi
    code="hy2_ed25519_chrome_parrot_disabled"
    message="检测到 Hysteria2 手动 Ed25519 证书；导出的 1.14+ 客户端配置已设置 disable_chrome_parrot=true。"
  else
    code="hy2_ed25519_share_link_requires_client_override"
    message="检测到 Hysteria2 手动 Ed25519 证书；分享链接无法携带 disable_chrome_parrot，1.14+ 客户端必须手动启用该选项。"
  fi

  jq -n \
    --arg code "${code}" \
    --arg message "${message}" \
    '[{code: $code, message: $message}]'
}

collect_hy2_compatibility_warnings_json() (
  local context=${1:-share}

  if ! protocol_state_exists "hy2" || ! load_protocol_state "hy2" "read-only"; then
    printf '[]'
    return 0
  fi

  build_hy2_compatibility_warnings_json "${context}"
)

print_hy2_compatibility_warnings() {
  local context=${1:-share}
  local warnings_json warning_message

  warnings_json=$(collect_hy2_compatibility_warnings_json "${context}")
  while IFS= read -r warning_message; do
    [[ -n "${warning_message}" ]] && log_warn "${warning_message}"
  done < <(jq -r '.[]?.message' <<< "${warnings_json}")
}

client_export_mixed_tags_json() (
  local schema store_file instance_id

  if ! protocol_state_exists "mixed"; then
    printf '[]'
    return 0
  fi
  schema=$(protocol_instance_state_schema "mixed" 2>/dev/null || true)
  case "${schema}" in
    2)
      store_file=$(mixed_structured_store_file 2>/dev/null || true)
      if [[ -f "${store_file}" && ! -L "${store_file}" ]]; then
        jq -c '[.instances[]?.id | "mixed-" + .]' "${store_file}" 2>/dev/null || printf '[]'
      else
        printf '[]'
      fi
      ;;
    1)
      instance_id=$(protocol_default_instance_id "mixed" 2>/dev/null || true)
      if [[ -n "${instance_id}" ]] && load_protocol_instance_state mixed "${instance_id}" >/dev/null 2>&1; then
        jq -cn --arg tag "$(client_outbound_tag_for_protocol mixed)" '[ $tag ]'
      else
        printf '[]'
      fi
      ;;
    *)
      printf '[]'
      ;;
  esac
)

collect_client_export_warnings_json() {
  local config_json=$1 hy2_warnings mixed_tags_json
  hy2_warnings=$(collect_hy2_compatibility_warnings_json "export") || return 1
  if ! mixed_tags_json=$(client_export_mixed_tags_json); then
    mixed_tags_json='[]'
  fi
  jq --argjson warnings "${hy2_warnings}" --argjson mixed_tags "${mixed_tags_json}" '
    def mixed_origin:
      (.tag // "") as $tag |
      (any($mixed_tags[]; . == $tag) or
       (($tag | type) == "string" and ($tag | startswith("mixed-"))));
    $warnings
    + (if any(.outbounds[]?;
        .type == "socks" and mixed_origin) then [{
      code: "mixed_plaintext_transport",
      message: "Mixed 导出使用明文 SOCKS5，代理链路未启用 TLS，认证信息与非加密业务可能被读取；仅用于可信网络或受保护隧道。UDP 经 UoT v2 承载，UoT 不提供加密。"
    }] else [] end)
    + (if any(.outbounds[]?;
        .type == "socks" and (mixed_origin | not)) then [{
      code: "socks_plaintext_transport",
      message: "SOCKS5 导出使用明文代理链路，认证信息与非加密业务可能被读取；仅用于可信网络或受保护隧道。UoT 即使启用也不提供加密。"
    }] else [] end)
    + (if any(.outbounds[]?; .type == "http" and .tls.enabled != true) then [{
      code: "http_plaintext_transport",
      message: "HTTP 代理入口未启用 TLS，认证信息与非加密业务可能被读取；访问 HTTPS 目标不等于代理入口已加密。仅用于可信网络或受保护隧道。"
    }] else [] end)
    + (if any(.outbounds[]?; .type == "http" and .tls.enabled == true) then [{
      code: "http_tls_certificate_embedded",
      message: "HTTP TLS 导出仅嵌入公开证书信任与 server_name；服务端私钥未读取或写入客户端配置。"
    }] else [] end)
    + (if any(.outbounds[]?; .type == "shadowsocks" and .method == "none") then [{
      code: "shadowsocks_plaintext_transport",
      message: "Shadowsocks none 不提供加密或认证，只能用于可信网络或受保护隧道。"
    }] else [] end)
  ' <<< "${config_json}"
}

build_hy2_link() {
  local public_ip=$1
  local address_label=${2:-}
  local server_host query node_name
  server_host=${SB_HY2_DOMAIN:-${public_ip}}
  node_name=$(display_node_name_for_protocol "hy2" "${SB_NODE_NAME}" "${address_label}")
  query="sni=${SB_HY2_DOMAIN:-${server_host}}"

  if [[ "${SB_HY2_OBFS_ENABLED}" == "y" ]]; then
    query="${query}&obfs=${SB_HY2_OBFS_TYPE:-salamander}&obfs-password=${SB_HY2_OBFS_PASSWORD}"
  fi

  printf 'hy2://%s@%s:%s?%s#%s' \
    "${SB_HY2_PASSWORD}" \
    "$(format_share_host "${server_host}")" \
    "${SB_PORT}" \
    "${query}" \
    "${node_name}"
}

subman_node_prefix() {
  local prefix
  prefix=$(trim_whitespace "${SUBMAN_NODE_PREFIX:-}")
  [[ -z "${prefix}" ]] && prefix=$(hostname)
  printf '%s' "${prefix}"
}

subman_type_for_protocol() {
  local type
  type=$(protocol_registry_field "$1" subman_type) || return 1
  [[ -n "${type}" ]] || return 1
  printf '%s' "${type}"
}

subman_external_key_for_protocol() {
  local protocol prefix instance_id address_label stack_suffix key
  protocol=$(normalize_protocol_id "$1")
  instance_id=${2:-}
  address_label=${3:-}
  prefix=$(subman_node_prefix)

  if [[ "${protocol}" == "vless-reality" && -n "${instance_id}" && "${instance_id}" != "${VLESS_REALITY_DEFAULT_INSTANCE_ID:-main}" ]]; then
    key=$(printf 'sing-box-vps:%s:%s:%s' "${prefix}" "${protocol}" "${instance_id}")
  else
    key=$(printf 'sing-box-vps:%s:%s' "${prefix}" "${protocol}")
  fi

  stack_suffix=$(network_stack_suffix_from_label "${address_label}")
  if [[ -n "${stack_suffix}" ]]; then
    key="${key}:${stack_suffix}"
  fi

  printf '%s' "${key}"
}

subman_external_key_for_shadowsocks_user() {
  local instance_id=${1:-} user_name=${2:-} address_label=${3:-}
  local prefix digest key stack_suffix key_bytes

  structured_instance_store_validate_id "${instance_id}" || return 1
  prefix=$(subman_node_prefix)
  digest=$(printf '%s' "${user_name}" | sha256sum) || return 1
  digest=${digest%% *}
  key="sing-box-vps:${prefix}:shadowsocks:${instance_id}:user-${digest}"
  stack_suffix=$(network_stack_suffix_from_label "${address_label}")
  if [[ -n "${stack_suffix}" ]]; then
    key="${key}:${stack_suffix}"
  fi
  key_bytes=$(printf '%s' "${key}" | wc -c | tr -d '[:space:]') || return 1
  [[ "${key_bytes}" =~ ^[0-9]+$ && "${key_bytes}" -gt 0 && "${key_bytes}" -le 256 ]] || return 1
  printf '%s' "${key}"
}

subman_shadowsocks_node_name() {
  local instance_id=${1:-} user_name=${2:-} prefix digest suffix name name_bytes

  prefix=$(subman_node_prefix)
  digest=$(printf '%s' "${user_name}" | sha256sum) || return 1
  digest=${digest%% *}
  if [[ -n "${user_name}" ]]; then
    suffix="user-${digest:0:12}"
  else
    suffix="single-${digest:0:12}"
  fi
  name="${prefix} Shadowsocks ${instance_id} ${suffix}"
  name_bytes=$(printf '%s' "${name}" | wc -c | tr -d '[:space:]') || return 1
  if [[ ! "${name_bytes}" =~ ^[0-9]+$ || "${name_bytes}" -gt 256 ]]; then
    name="Shadowsocks ${instance_id} ${suffix}"
  fi
  printf '%s' "${name}"
}

build_subman_shadowsocks_node_payload() {
  local outbound=${1:-} name=${2:-} node_type prefix raw_link

  [[ -n "${outbound}" && -n "${name}" ]] || return 1
  node_type=$(subman_type_for_protocol shadowsocks) || return 1
  raw_link=$(build_shadowsocks_uri "${outbound}" "${name}") || return 1
  prefix=$(subman_node_prefix)
  jq -n \
    --arg name "${name}" \
    --arg type "${node_type}" \
    --arg raw "${raw_link}" \
    --arg prefix "${prefix}" \
    '{name:$name,type:$type,raw:$raw,enabled:true,tags:["sing-box-vps",$prefix],source:"single"}'
}

trojan_share_skip() {
  TROJAN_SHARE_SKIP_CODE=${1:-trojan_uri_unrepresentable}
  TROJAN_SHARE_SKIP_MESSAGE=${2:-Trojan 当前配置无法无损转换为 SubMan raw URI。}
  return 2
}

trojan_share_query_value_safe() {
  local value=${1-}
  # SubMan's query parser trims Unicode whitespace. Reject values whose
  # leading/trailing bytes would therefore be changed by a raw URI roundtrip.
  jq -en --arg value "${value}" \
    '$value | (test("^[\u0009-\u000d\u0020\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000\ufeff]") or test("[\u0009-\u000d\u0020\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000\ufeff]$")) | not' \
    >/dev/null
}

trojan_share_uri_query() {
  local transport_json=${1:-} tls_json=${2:-} profile transport_type path host service_name
  local encoded value query=""

  [[ -n "${transport_json}" && -n "${tls_json}" ]] || return 1
  transport_type=$(jq -er '.type' <<< "${transport_json}") || return 1
  case "${transport_type}" in
    none)
      jq -e 'keys_unsorted == ["type"]' <<< "${transport_json}" >/dev/null || return 1
      ;;
    ws)
      jq -e '
        (keys_unsorted - ["type","path","headers","max_early_data","early_data_header_name"] | length) == 0 and
        ((.max_early_data // 0) == 0) and
        ((.early_data_header_name // "") == "") and
        ((.headers // {}) | keys_unsorted | map(ascii_downcase) | unique) ==
          ((.headers // {}) | keys_unsorted | map(ascii_downcase) | unique) and
        (((.headers // {}) | keys_unsorted | length) == 0 or
          ((.headers | keys_unsorted) == ["Host"] and (.headers.Host | type == "string")))
      ' <<< "${transport_json}" >/dev/null || return 1
      path=$(jq -r '.path // ""' <<< "${transport_json}") || return 1
      host=$(jq -r '.headers.Host // empty' <<< "${transport_json}") || return 1
      trojan_share_query_value_safe "${path}" || return 1
      [[ -z "${host}" ]] || trojan_share_query_value_safe "${host}" || return 1
      encoded=$(jq -rn --arg value "${path}" '$value|@uri') || return 1
      query="type=ws&path=${encoded}"
      if [[ -n "${host}" ]]; then
        encoded=$(jq -rn --arg value "${host}" '$value|@uri') || return 1
        query="${query}&host=${encoded}"
      fi
      ;;
    http)
      jq -e '
        (keys_unsorted - ["type","path","host"] | length) == 0 and
        (if has("host") then
          (.host | if type == "array" then length == 1 and (.[0] | type == "string")
                   elif type == "string" then true else false end)
         else true end)
      ' <<< "${transport_json}" >/dev/null || return 1
      path=$(jq -r '.path // ""' <<< "${transport_json}") || return 1
      host=$(jq -r 'if (.host | type) == "array" then .host[0] // empty else .host // empty end' <<< "${transport_json}") || return 1
      trojan_share_query_value_safe "${path}" || return 1
      [[ -z "${host}" ]] || trojan_share_query_value_safe "${host}" || return 1
      encoded=$(jq -rn --arg value "${path}" '$value|@uri') || return 1
      query="type=http&path=${encoded}"
      if [[ -n "${host}" ]]; then
        encoded=$(jq -rn --arg value "${host}" '$value|@uri') || return 1
        query="${query}&host=${encoded}"
      fi
      ;;
    grpc)
      jq -e 'keys_unsorted - ["type","service_name"] | length == 0' <<< "${transport_json}" >/dev/null || return 1
      service_name=$(jq -r '.service_name // empty' <<< "${transport_json}") || return 1
      [[ -z "${service_name}" ]] || trojan_share_query_value_safe "${service_name}" || return 1
      query='type=grpc'
      if [[ -n "${service_name}" ]]; then
        encoded=$(jq -rn --arg value "${service_name}" '$value|@uri') || return 1
        query="${query}&service_name=${encoded}"
      fi
      ;;
    quic)
      jq -e 'keys_unsorted == ["type"]' <<< "${transport_json}" >/dev/null || return 1
      query='type=quic'
      ;;
    *) return 1 ;;
  esac

  profile=$(build_v2ray_transport_profile_json trojan "${transport_json}" tls '' "$(resolve_config_target_singbox_version)") || return 1
  if jq -e '.tls_alpn | length > 0' <<< "${profile}" >/dev/null; then
    value=$(jq -r '.tls_alpn | join(",")' <<< "${profile}") || return 1
    encoded=$(jq -rn --arg value "${value}" '$value|@uri') || return 1
    query="${query}&alpn=${encoded}"
  fi
  value=$(jq -er '.server_name' <<< "${tls_json}") || return 1
  trojan_share_query_value_safe "${value}" || return 1
  encoded=$(jq -rn --arg value "${value}" '$value|@uri') || return 1
  printf 'sni=%s&%s' "${encoded}" "${query}"
}

build_trojan_subman_uri_from_store() (
  local store_file=${1:-} server=${2:-} instance_id=${3:-} user_name=${4-} node_name=${5:-Trojan}
  local snapshot instance tls_json transport_json client_trust password_encoded name_encoded query share_host port uri uri_bytes

  [[ $# -eq 5 && -n "${store_file}" && -f "${store_file}" && ! -L "${store_file}" ]] || return 1
  [[ -n "${server}" && "${server}" != *[[:space:]@/?#%]* ]] || return 1
  structured_instance_store_validate_id "${instance_id}" || return 1
  validate_structured_instance_store trojan "${store_file}" || return 1
  snapshot=$(structured_instance_store_snapshot_json trojan "${store_file}") || return 1
  instance=$(jq -ce --arg id "${instance_id}" --arg user "${user_name}" \
    '.instances[] | select(.id == $id) | . as $instance |
     ($instance.authentication.users[] | select(.name == $user)) |
     {instance:$instance,user:.}' <<< "${snapshot}") || return 1
  tls_json=$(jq -ce '.instance.tls' <<< "${instance}") || return 1
  client_trust=$(jq -er '.instance.client_trust' <<< "${instance}") || return 1
  if ! jq -e '.enabled == true' <<< "${tls_json}" >/dev/null; then
    trojan_share_skip trojan_tls_disabled_uri_unrepresentable 'Trojan 明文入口无法转换为 SubMan 默认 TLS raw URI；该用户已跳过。'
    return 20
  fi
  if [[ "${client_trust}" != system ]]; then
    trojan_share_skip trojan_tls_certificate_uri_unrepresentable 'Trojan 自定义证书信任无法由 SubMan raw URI 无损表达；该用户已跳过。'
    return 21
  fi
  transport_json=$(jq -ce '.instance.transport' <<< "${instance}") || return 1
  if ! query=$(trojan_share_uri_query "${transport_json}" "${tls_json}"); then
    trojan_share_skip trojan_transport_uri_unrepresentable 'Trojan transport 包含 SubMan raw URI 无法无损表达的字段；该用户已跳过。'
    return 22
  fi
  password_encoded=$(jq -er '.user.password | @uri' <<< "${instance}") || return 1
  name_encoded=$(jq -rn --arg value "${node_name}" '$value|@uri') || return 1
  port=$(jq -er '.instance.listen.port' <<< "${instance}") || return 1
  share_host=$(format_share_host "${server}") || return 1
  uri="trojan://${password_encoded}@${share_host}:${port}?${query}#${name_encoded}"
  uri_bytes=$(printf '%s' "${uri}" | wc -c) || return 1
  [[ "${uri_bytes}" =~ ^[0-9]+$ && "${uri_bytes}" -le 16384 ]] || \
    { trojan_share_skip trojan_uri_too_large 'Trojan raw URI 超过 SubMan 16384 字节上限；该用户已跳过。'; return 23; }
  printf '%s' "${uri}"
)

trojan_share_warning_for_status() {
  local status=${1:-1}
  case "${status}" in
    20) build_trojan_share_warnings_json trojan_tls_disabled_uri_unrepresentable \
      'Trojan 明文入口无法转换为 SubMan 默认 TLS raw URI；该用户已跳过。' ;;
    21) build_trojan_share_warnings_json trojan_tls_certificate_uri_unrepresentable \
      'Trojan 自定义证书信任无法由 SubMan raw URI 无损表达；该用户已跳过。' ;;
    22) build_trojan_share_warnings_json trojan_transport_uri_unrepresentable \
      'Trojan transport 包含 SubMan raw URI 无法无损表达的字段；该用户已跳过。' ;;
    23) build_trojan_share_warnings_json trojan_uri_too_large \
      'Trojan raw URI 超过 SubMan 16384 字节上限；该用户已跳过。' ;;
    *) return 1 ;;
  esac
}

build_trojan_subman_links_and_warnings_json() (
  local server=${1:-} instance_id=${2:-} store_file snapshot snapshot_file instance node_name user_name tag uri status
  local links='{}' warnings='[]' warning users_text
  [[ $# -ge 1 && $# -le 2 ]] || return 1
  store_file=$(plain_proxy_structured_store_file trojan) || return 1
  snapshot=$(structured_instance_store_snapshot_json trojan "${store_file}") || return 1
  snapshot_file=$(mktemp) || return 1
  trap 'rm -f -- "${snapshot_file}"' EXIT
  printf '%s\n' "${snapshot}" > "${snapshot_file}" || return 1
  instance_id=${2:-$(jq -er '.default_instance_id' <<< "${snapshot}")}
  instance=$(jq -ce --arg id "${instance_id}" '.instances[] | select(.id == $id)' <<< "${snapshot}") || return 1
  node_name=$(jq -r '.name' <<< "${instance}") || return 1
  users_text=$(jq -r '.authentication.users[].name' <<< "${instance}") || return 1
  while IFS= read -r user_name; do
    [[ -n "${user_name}" ]] || continue
    tag=$(jq -r --arg user "${user_name}" '"trojan-" + .id + "-user-" + ($user | @base64)' <<< "${instance}") || return 1
    if uri=$(build_trojan_subman_uri_from_store "${snapshot_file}" "${server}" "${instance_id}" "${user_name}" "${node_name} ${tag}"); then
      links=$(jq -cn --argjson links "${links}" --arg tag "${tag}" --arg uri "${uri}" '$links + {($tag):$uri}') || return 1
    else
      status=$?
      if [[ "${status}" =~ ^2[0-3]$ ]]; then
        warning=$(trojan_share_warning_for_status "${status}") || return 1
        warnings=$(jq -cn --argjson warnings "${warnings}" --argjson warning "${warning}" \
          --arg instance_id "${instance_id}" --arg tag "${tag}" \
          '$warnings + ($warning | map(. + {instance_id:$instance_id,outbound_tag:$tag}))') || return 1
      else
        return "${status}"
      fi
    fi
  done <<< "${users_text}"
  jq -cn --argjson links "${links}" --argjson warnings "${warnings}" '{links:$links,warnings:$warnings}'
)

build_trojan_subman_links_json() (
  local result
  result=$(build_trojan_subman_links_and_warnings_json "$@") || return $?
  jq -e '.links | length > 0' <<< "${result}" >/dev/null || return 1
  jq -c '.links' <<< "${result}"
)

build_trojan_share_warnings_json() {
  local code=${1:-trojan_uri_unrepresentable} message=${2:-Trojan 当前配置无法无损转换为 SubMan raw URI。}
  jq -cn --arg code "${code}" --arg message "${message}" '[{code:$code,message:$message}]'
}

subman_external_key_for_trojan_user() {
  local instance_id=${1:-} user_name=${2-} address_label=${3:-}
  local prefix digest key stack_suffix key_bytes
  structured_instance_store_validate_id "${instance_id}" || return 1
  prefix=$(subman_node_prefix) || return 1
  digest=$(printf '%s' "${user_name}" | sha256sum) || return 1
  digest=${digest%% *}
  key="sing-box-vps:${prefix}:trojan:${instance_id}:user-${digest}"
  stack_suffix=$(network_stack_suffix_from_label "${address_label}") || return 1
  [[ -z "${stack_suffix}" ]] || key="${key}:${stack_suffix}"
  key_bytes=$(printf '%s' "${key}" | wc -c) || return 1
  [[ "${key_bytes}" =~ ^[0-9]+$ && "${key_bytes}" -le 256 ]] || return 1
  printf '%s' "${key}"
}

subman_trojan_node_name() {
  local instance_id=${1:-} user_name=${2-} prefix digest suffix name name_bytes
  prefix=$(subman_node_prefix) || return 1
  digest=$(printf '%s' "${user_name}" | sha256sum) || return 1
  digest=${digest%% *}
  suffix="user-${digest:0:12}"
  name="${prefix} Trojan ${instance_id} ${suffix}"
  name_bytes=$(printf '%s' "${name}" | wc -c) || return 1
  if [[ ! "${name_bytes}" =~ ^[0-9]+$ || "${name_bytes}" -gt 256 ]]; then
    name="Trojan ${instance_id} ${suffix}"
  fi
  printf '%s' "${name}"
}

build_subman_trojan_node_payload() {
  local raw_link=${1:-} name=${2:-} node_type prefix
  [[ -n "${raw_link}" && -n "${name}" ]] || return 1
  node_type=$(subman_type_for_protocol trojan) || return 1
  prefix=$(subman_node_prefix) || return 1
  jq -n --arg name "${name}" --arg type "${node_type}" --arg raw "${raw_link}" \
    --arg prefix "${prefix}" \
    '{name:$name,type:$type,raw:$raw,enabled:true,tags:["sing-box-vps",$prefix],source:"single"}'
}

push_subman_trojan_instance() {
  local instance_id=${1:-} server=${2:-} quiet=${3:-n} address_label=${4:-}
  local store_file snapshot snapshot_file producer_file instance user_name node_name raw_link external_key payload_json status producer_count
  local users_text
  local synced=0 skipped=0 failed=0 warnings='[]' warning

  SUBMAN_TROJAN_SYNCED=0
  SUBMAN_TROJAN_SKIPPED=0
  SUBMAN_TROJAN_FAILED=0
  SUBMAN_TROJAN_WARNINGS_JSON='[]'
  structured_instance_store_validate_id "${instance_id}" || { SUBMAN_TROJAN_FAILED=1; return 1; }
  store_file=$(plain_proxy_structured_store_file trojan) || { SUBMAN_TROJAN_FAILED=1; return 1; }
  snapshot=$(structured_instance_store_snapshot_json trojan "${store_file}") || { SUBMAN_TROJAN_FAILED=1; return 1; }
  instance=$(jq -ce --arg id "${instance_id}" '.instances[] | select(.id == $id)' <<< "${snapshot}") || { SUBMAN_TROJAN_FAILED=1; return 1; }
  case "$(jq -r '.listen.address' <<< "${instance}")" in
    0.0.0.0|::) ;;
    *) server=$(jq -r '.listen.address' <<< "${instance}") ;;
  esac
  # Run the same complete outbound producer used by export-client before any
  # SubMan mutation. Certificate-trust users are intentionally excluded here:
  # their URI is skipped because SubMan cannot carry the custom trust, while
  # their certificate file must not become a sync prerequisite.
  producer_file=$(mktemp) || { SUBMAN_TROJAN_FAILED=1; return 1; }
  jq --arg id "${instance_id}" \
    '. as $root | ($root.instances | map(select(.id == $id and .client_trust == "system"))) as $instances |
     $root | .default_instance_id=$id | .instances=$instances' <<< "${snapshot}" > "${producer_file}" || {
    rm -f -- "${producer_file}"
    SUBMAN_TROJAN_FAILED=1
    return 1
  }
  producer_count=$(jq -r '.instances | length' "${producer_file}") || {
    rm -f -- "${producer_file}"
    SUBMAN_TROJAN_FAILED=1
    return 1
  }
  if [[ "${producer_count}" != 0 ]]; then
    if ! build_trojan_client_outbounds_from_store "${producer_file}" "${server}" >/dev/null; then
      rm -f -- "${producer_file}"
      SUBMAN_TROJAN_FAILED=1
      return 1
    fi
  fi
  rm -f -- "${producer_file}" || { SUBMAN_TROJAN_FAILED=1; return 1; }
  snapshot_file=$(mktemp) || { SUBMAN_TROJAN_FAILED=1; return 1; }
  printf '%s\n' "${snapshot}" > "${snapshot_file}" || { rm -f -- "${snapshot_file}"; SUBMAN_TROJAN_FAILED=1; return 1; }
  users_text=$(jq -r '.authentication.users[].name' <<< "${instance}") || { rm -f -- "${snapshot_file}"; SUBMAN_TROJAN_FAILED=1; return 1; }
  while IFS= read -r user_name; do
    [[ -n "${user_name}" ]] || continue
    node_name=$(subman_trojan_node_name "${instance_id}" "${user_name}") || { failed=$((failed + 1)); continue; }
    if raw_link=$(build_trojan_subman_uri_from_store "${snapshot_file}" "${server}" "${instance_id}" "${user_name}" "${node_name}"); then
      :
    else
      status=$?
      if [[ "${status}" =~ ^2[0-3]$ ]]; then
        skipped=$((skipped + 1))
        warning=$(trojan_share_warning_for_status "${status}") || { failed=$((failed + 1)); continue; }
        warnings=$(jq -cn --argjson existing "${warnings}" --argjson addition "${warning}" \
          --arg instance_id "${instance_id}" --arg user "${user_name}" \
          '$existing + ($addition | map(. + {instance_id:$instance_id,
            outbound_tag:("trojan-" + $instance_id + "-user-" + ($user | @base64))}))') || {
          failed=$((failed + 1))
          continue
        }
        [[ "${quiet}" == y ]] || print_warn "Trojan 实例 ${instance_id} 用户 ${user_name} 无法无损转换为 SubMan raw URI，已跳过。"
      else
        failed=$((failed + 1))
      fi
      continue
    fi
    external_key=$(subman_external_key_for_trojan_user "${instance_id}" "${user_name}" "${address_label}") || { failed=$((failed + 1)); continue; }
    payload_json=$(build_subman_trojan_node_payload "${raw_link}" "${node_name}") || { failed=$((failed + 1)); continue; }
    if [[ "${quiet}" == y ]]; then
      if push_subman_node "${external_key}" "${payload_json}" >/dev/null; then synced=$((synced + 1)); else failed=$((failed + 1)); fi
    elif push_subman_node "${external_key}" "${payload_json}"; then
      synced=$((synced + 1))
    else
      failed=$((failed + 1))
    fi
  done <<< "${users_text}"
  rm -f -- "${snapshot_file}" || failed=$((failed + 1))
  SUBMAN_TROJAN_SYNCED=${synced}
  SUBMAN_TROJAN_SKIPPED=${skipped}
  SUBMAN_TROJAN_FAILED=${failed}
  SUBMAN_TROJAN_WARNINGS_JSON=${warnings}
  (( failed == 0 && (synced > 0 || skipped > 0) ))
}

push_subman_trojan_protocol() {
  local quiet=${1:-n} instance_ids instance_id address_entries address_entry address_label public_ip
  local total_synced=0 total_skipped=0 total_failed=0 warnings='[]' push_status=0
  SUBMAN_TROJAN_SYNCED=0
  SUBMAN_TROJAN_SKIPPED=0
  SUBMAN_TROJAN_FAILED=0
  SUBMAN_TROJAN_WARNINGS_JSON='[]'
  instance_ids=$(list_protocol_instance_ids trojan) || { SUBMAN_TROJAN_FAILED=1; return 1; }
  while IFS= read -r instance_id; do
    [[ -n "${instance_id}" ]] || continue
    load_protocol_instance_state trojan "${instance_id}" || { total_failed=$((total_failed + 1)); continue; }
    address_entries=$(list_subman_addresses_for_current_protocol) || { total_failed=$((total_failed + 1)); continue; }
    while IFS= read -r address_entry; do
      [[ -n "${address_entry}" ]] || continue
      address_label=${address_entry%%|*}
      public_ip=${address_entry#*|}
      if push_subman_trojan_instance "${instance_id}" "${public_ip}" "${quiet}" "${address_label}"; then
        push_status=0
      else
        push_status=$?
      fi
      total_synced=$((total_synced + ${SUBMAN_TROJAN_SYNCED:-0}))
      total_skipped=$((total_skipped + ${SUBMAN_TROJAN_SKIPPED:-0}))
      total_failed=$((total_failed + ${SUBMAN_TROJAN_FAILED:-0}))
      if [[ "${push_status}" != 0 && "${SUBMAN_TROJAN_FAILED:-0}" == 0 ]]; then
        total_failed=$((total_failed + 1))
      fi
      if [[ -n "${SUBMAN_TROJAN_WARNINGS_JSON:-}" ]]; then
        if ! warnings=$(jq -cn --argjson existing "${warnings}" --argjson additions "${SUBMAN_TROJAN_WARNINGS_JSON}" '$existing + $additions'); then
          SUBMAN_TROJAN_SYNCED=${total_synced}
          SUBMAN_TROJAN_SKIPPED=${total_skipped}
          SUBMAN_TROJAN_FAILED=$((total_failed + 1))
          SUBMAN_TROJAN_WARNINGS_JSON='[]'
          return 1
        fi
      fi
    done <<< "${address_entries}"
  done <<< "${instance_ids}"
  SUBMAN_TROJAN_SYNCED=${total_synced}
  SUBMAN_TROJAN_SKIPPED=${total_skipped}
  SUBMAN_TROJAN_FAILED=${total_failed}
  SUBMAN_TROJAN_WARNINGS_JSON=${warnings}
  (( total_failed == 0 && (total_synced > 0 || total_skipped > 0) ))
}

vmess_share_skip() {
  VMESS_SHARE_SKIP_CODE=${1:-vmess_uri_unrepresentable}
  VMESS_SHARE_SKIP_MESSAGE=${2:-VMess 当前配置无法无损转换为 SubMan raw URI。}
  return 2
}

build_vmess_subman_uri_from_store() (
  local store_file=${1:-} server=${2:-} instance_id=${3:-} user_name=${4-} node_name=${5:-VMess}
  local snapshot instance client_trust tag outbound uri uri_bytes filtered_file
  [[ $# -eq 5 && -n "${store_file}" && -f "${store_file}" && ! -L "${store_file}" ]] || return 1
  [[ -n "${server}" && "${server}" != *[[:space:]@/?#%]* ]] || return 1
  structured_instance_store_validate_id "${instance_id}" || return 1
  validate_structured_instance_store vmess "${store_file}" || return 1
  snapshot=$(structured_instance_store_snapshot_json vmess "${store_file}") || return 1
  instance=$(jq -ce --arg id "${instance_id}" --arg user "${user_name}" '.instances[] | select(.id == $id) | select(any(.authentication.users[]; .name == $user))' <<< "${snapshot}") || return 1
  client_trust=$(jq -er '.client_trust' <<< "${instance}") || return 1
  if [[ "${client_trust}" != system ]]; then
    vmess_share_skip vmess_tls_certificate_uri_unrepresentable 'VMess 自定义证书信任无法由 SubMan raw URI 无损表达；该用户已跳过。'
    return 31
  fi
  tag=$(jq -r --arg user "${user_name}" '"vmess-" + .id + "-user-" + ($user | @base64)' <<< "${instance}") || return 1
  filtered_file=$(mktemp) || return 1
  trap 'rm -f -- "${filtered_file}"' EXIT
  jq -e --arg id "${instance_id}" '.instances |= map(select(.id == $id)) | .default_instance_id=$id' \
    <<< "${snapshot}" > "${filtered_file}" || return 1
  outbound=$(build_vmess_client_outbounds_from_store "${filtered_file}" "${server}" | jq -ce --arg tag "${tag}" 'select(.tag == $tag)') || return 1
  uri=$(build_vmess_uri_from_outbound "${outbound}" "${node_name}") || return 1
  uri_bytes=$(printf '%s' "${uri}" | wc -c) || return 1
  [[ "${uri_bytes}" =~ ^[0-9]+$ && "${uri_bytes}" -le 16384 ]] || {
    vmess_share_skip vmess_uri_too_large 'VMess raw URI 超过 SubMan 16384 字节上限；该用户已跳过。'; return 32;
  }
  printf '%s' "${uri}"
)

vmess_share_warning_for_status() {
  case "${1:-1}" in
    31) jq -cn '[{code:"vmess_tls_certificate_uri_unrepresentable",message:"VMess 自定义证书信任无法由 SubMan raw URI 无损表达；该用户已跳过。"}]' ;;
    32) jq -cn '[{code:"vmess_uri_too_large",message:"VMess raw URI 超过 SubMan 16384 字节上限；该用户已跳过。"}]' ;;
    *) return 1 ;;
  esac
}

build_vmess_subman_links_and_warnings_json() (
  local server=${1:-} instance_id=${2:-} store_file snapshot snapshot_file instance user_name node_name tag uri status warning
  local links='{}' warnings='[]' users_text
  store_file=$(plain_proxy_structured_store_file vmess) || return 1
  snapshot=$(structured_instance_store_snapshot_json vmess "${store_file}") || return 1
  snapshot_file=$(mktemp) || return 1; trap 'rm -f -- "${snapshot_file}"' EXIT
  printf '%s\n' "${snapshot}" > "${snapshot_file}" || return 1
  instance_id=${2:-$(jq -er '.default_instance_id' <<< "${snapshot}")}
  instance=$(jq -ce --arg id "${instance_id}" '.instances[] | select(.id == $id)' <<< "${snapshot}") || return 1
  node_name=$(jq -r '.name' <<< "${instance}") || return 1
  users_text=$(jq -r '.authentication.users[].name' <<< "${instance}") || return 1
  while IFS= read -r user_name; do
    [[ -n "${user_name}" ]] || continue
    tag=$(jq -r --arg user "${user_name}" '"vmess-" + .id + "-user-" + ($user | @base64)' <<< "${instance}") || return 1
    if uri=$(build_vmess_subman_uri_from_store "${snapshot_file}" "${server}" "${instance_id}" "${user_name}" "${node_name} ${tag}"); then
      links=$(jq -cn --argjson links "${links}" --arg tag "${tag}" --arg uri "${uri}" '$links + {($tag):$uri}') || return 1
    else
      status=$?
      if [[ "${status}" == 31 || "${status}" == 32 ]]; then
        warning=$(vmess_share_warning_for_status "${status}") || return 1
        warnings=$(jq -cn --argjson warnings "${warnings}" --argjson warning "${warning}" --arg instance_id "${instance_id}" --arg tag "${tag}" '$warnings + ($warning | map(. + {instance_id:$instance_id,outbound_tag:$tag}))') || return 1
      else return "${status}"; fi
    fi
  done <<< "${users_text}"
  jq -cn --argjson links "${links}" --argjson warnings "${warnings}" '{links:$links,warnings:$warnings}'
)

subman_external_key_for_vmess_user() {
  local instance_id=${1:-} user_name=${2-} address_label=${3:-} prefix digest key stack_suffix key_bytes
  structured_instance_store_validate_id "${instance_id}" || return 1
  prefix=$(subman_node_prefix) || return 1; digest=$(printf '%s' "${user_name}" | sha256sum); digest=${digest%% *}
  key="sing-box-vps:${prefix}:vmess:${instance_id}:user-${digest}"
  stack_suffix=$(network_stack_suffix_from_label "${address_label}") || return 1
  [[ -z "${stack_suffix}" ]] || key="${key}:${stack_suffix}"
  key_bytes=$(printf '%s' "${key}" | wc -c) || return 1
  [[ "${key_bytes}" =~ ^[0-9]+$ && "${key_bytes}" -le 256 ]] || return 1
  printf '%s' "${key}"
}

subman_vmess_node_name() {
  local instance_id=${1:-} user_name=${2-} prefix digest suffix
  prefix=$(subman_node_prefix) || return 1; digest=$(printf '%s' "${user_name}" | sha256sum); digest=${digest%% *}; suffix="user-${digest:0:12}"
  printf '%s VMess %s %s' "${prefix}" "${instance_id}" "${suffix}"
}

build_subman_vmess_node_payload() {
  local raw_link=${1:-} name=${2:-} node_type prefix
  [[ -n "${raw_link}" && -n "${name}" ]] || return 1
  node_type=$(subman_type_for_protocol vmess) || return 1; prefix=$(subman_node_prefix) || return 1
  jq -n --arg name "${name}" --arg type "${node_type}" --arg raw "${raw_link}" --arg prefix "${prefix}" '{name:$name,type:$type,raw:$raw,enabled:true,tags:["sing-box-vps",$prefix],source:"single"}'
}

push_subman_vmess_instance() {
  local instance_id=${1:-} server=${2:-} quiet=${3:-n} address_label=${4:-}
  local store_file snapshot snapshot_file instance user_name node_name raw_link external_key payload_json status warning users_text
  local synced=0 skipped=0 failed=0 warnings='[]'
  SUBMAN_VMESS_SYNCED=0; SUBMAN_VMESS_SKIPPED=0; SUBMAN_VMESS_FAILED=0; SUBMAN_VMESS_WARNINGS_JSON='[]'
  structured_instance_store_validate_id "${instance_id}" || { SUBMAN_VMESS_FAILED=1; return 1; }
  store_file=$(plain_proxy_structured_store_file vmess) || { SUBMAN_VMESS_FAILED=1; return 1; }
  snapshot=$(structured_instance_store_snapshot_json vmess "${store_file}") || { SUBMAN_VMESS_FAILED=1; return 1; }
  instance=$(jq -ce --arg id "${instance_id}" '.instances[] | select(.id == $id)' <<< "${snapshot}") || { SUBMAN_VMESS_FAILED=1; return 1; }
  case "$(jq -r '.listen.address' <<< "${instance}")" in 0.0.0.0|::) ;; *) server=$(jq -r '.listen.address' <<< "${instance}") ;; esac
  snapshot_file=$(mktemp) || { SUBMAN_VMESS_FAILED=1; return 1; }; printf '%s\n' "${snapshot}" > "${snapshot_file}" || { rm -f -- "${snapshot_file}"; SUBMAN_VMESS_FAILED=1; return 1; }
  users_text=$(jq -r '.authentication.users[].name' <<< "${instance}") || { rm -f -- "${snapshot_file}"; SUBMAN_VMESS_FAILED=1; return 1; }
  while IFS= read -r user_name; do
    [[ -n "${user_name}" ]] || continue
    node_name=$(subman_vmess_node_name "${instance_id}" "${user_name}") || { failed=$((failed + 1)); continue; }
    if raw_link=$(build_vmess_subman_uri_from_store "${snapshot_file}" "${server}" "${instance_id}" "${user_name}" "${node_name}"); then
      external_key=$(subman_external_key_for_vmess_user "${instance_id}" "${user_name}" "${address_label}") || { failed=$((failed + 1)); continue; }
      payload_json=$(build_subman_vmess_node_payload "${raw_link}" "${node_name}") || { failed=$((failed + 1)); continue; }
      if [[ "${quiet}" == y ]]; then push_subman_node "${external_key}" "${payload_json}" >/dev/null && synced=$((synced + 1)) || failed=$((failed + 1)); else push_subman_node "${external_key}" "${payload_json}" && synced=$((synced + 1)) || failed=$((failed + 1)); fi
    else
      status=$?
      if [[ "${status}" == 31 || "${status}" == 32 ]]; then
        skipped=$((skipped + 1)); warning=$(vmess_share_warning_for_status "${status}") || { failed=$((failed + 1)); continue; }
        warnings=$(jq -cn --argjson existing "${warnings}" --argjson addition "${warning}" --arg instance_id "${instance_id}" --arg user "${user_name}" '$existing + ($addition | map(. + {instance_id:$instance_id,outbound_tag:("vmess-" + $instance_id + "-user-" + ($user | @base64))}))') || { failed=$((failed + 1)); continue; }
        [[ "${quiet}" == y ]] || print_warn "VMess 实例 ${instance_id} 用户 ${user_name} 无法无损转换为 SubMan raw URI，已跳过。"
      else failed=$((failed + 1)); fi
    fi
  done <<< "${users_text}"
  rm -f -- "${snapshot_file}" || failed=$((failed + 1))
  SUBMAN_VMESS_SYNCED=${synced}; SUBMAN_VMESS_SKIPPED=${skipped}; SUBMAN_VMESS_FAILED=${failed}; SUBMAN_VMESS_WARNINGS_JSON=${warnings}
  (( failed == 0 && (synced > 0 || skipped > 0) ))
}

push_subman_vmess_protocol() {
  local quiet=${1:-n} instance_ids instance_id address_entries address_entry address_label public_ip
  local total_synced=0 total_skipped=0 total_failed=0 warnings='[]'
  SUBMAN_VMESS_SYNCED=0; SUBMAN_VMESS_SKIPPED=0; SUBMAN_VMESS_FAILED=0; SUBMAN_VMESS_WARNINGS_JSON='[]'
  instance_ids=$(list_protocol_instance_ids vmess) || { SUBMAN_VMESS_FAILED=1; return 1; }
  while IFS= read -r instance_id; do
    [[ -n "${instance_id}" ]] || continue
    load_protocol_instance_state vmess "${instance_id}" || { total_failed=$((total_failed + 1)); continue; }
    address_entries=$(list_subman_addresses_for_current_protocol) || { total_failed=$((total_failed + 1)); continue; }
    while IFS= read -r address_entry; do
      [[ -n "${address_entry}" ]] || continue; address_label=${address_entry%%|*}; public_ip=${address_entry#*|}
      push_subman_vmess_instance "${instance_id}" "${public_ip}" "${quiet}" "${address_label}" || :
      total_synced=$((total_synced + ${SUBMAN_VMESS_SYNCED:-0})); total_skipped=$((total_skipped + ${SUBMAN_VMESS_SKIPPED:-0})); total_failed=$((total_failed + ${SUBMAN_VMESS_FAILED:-0}))
      if [[ -n "${SUBMAN_VMESS_WARNINGS_JSON:-}" ]]; then warnings=$(jq -cn --argjson a "${warnings}" --argjson b "${SUBMAN_VMESS_WARNINGS_JSON}" '$a+$b') || return 1; fi
    done <<< "${address_entries}"
  done <<< "${instance_ids}"
  SUBMAN_VMESS_SYNCED=${total_synced}; SUBMAN_VMESS_SKIPPED=${total_skipped}; SUBMAN_VMESS_FAILED=${total_failed}; SUBMAN_VMESS_WARNINGS_JSON=${warnings}
  (( total_failed == 0 && (total_synced > 0 || total_skipped > 0) ))
}

vless_plain_share_skip() {
  VLESS_PLAIN_SHARE_SKIP_CODE=${1:-vless_plain_uri_unrepresentable}
  VLESS_PLAIN_SHARE_SKIP_MESSAGE=${2:-VLESS 当前配置无法无损转换为 raw URI。}
  return 2
}

vless_plain_share_warning_for_status() {
  case "${1:-1}" in
    31) jq -cn '[{code:"vless_plain_tls_certificate_uri_unrepresentable",message:"VLESS 自定义证书信任无法由 raw URI 无损表达；该用户已跳过。"}]' ;;
    32) jq -cn '[{code:"vless_plain_transport_uri_unrepresentable",message:"VLESS transport 包含 raw URI 无法无损表达的字段；该用户已跳过。"}]' ;;
    33) jq -cn '[{code:"vless_plain_uri_too_large",message:"VLESS raw URI 超过 SubMan 16384 字节上限；该用户已跳过。"}]' ;;
    *) return 1 ;;
  esac
}

vless_plain_share_transport_supported() {
  local transport_json=${1:-} transport_type
  transport_type=$(jq -er '.type' <<< "${transport_json}") || return 1
  case "${transport_type}" in
    none|quic) jq -e 'keys_unsorted == ["type"]' <<< "${transport_json}" >/dev/null ;;
    http)
      jq -e '((keys_unsorted - ["type","host","path","headers"] | length) == 0) and
        ((.method // "GET") == "GET") and
        (((.headers // {}) | keys_unsorted | map(ascii_downcase) | unique) == [] or
          ((.headers | keys_unsorted | map(ascii_downcase) | unique) == ["host"] and
           ((.headers.Host // .headers.host) | type == "string"))) and
        ((.host // []) | if type == "array" then length <= 1 else true end)' <<< "${transport_json}" >/dev/null ;;
    ws)
      jq -e '((keys_unsorted - ["type","path","headers"] | length) == 0) and
        ((.headers // {}) | keys_unsorted | map(ascii_downcase) | unique) as $keys |
        ($keys == [] or $keys == ["host"])' <<< "${transport_json}" >/dev/null ;;
    grpc) jq -e '(keys_unsorted - ["type","service_name"] | length) == 0' <<< "${transport_json}" >/dev/null ;;
    *) return 1 ;;
  esac
}

build_vless_plain_subman_uri_from_store() (
  local store_file=${1:-} server=${2:-} instance_id=${3:-} user_name=${4-} node_name=${5:-VLESS}
  local snapshot instance client_trust tag filtered_file outbound uri uri_bytes transport_json
  [[ $# -eq 5 && -n "${store_file}" && -f "${store_file}" && ! -L "${store_file}" ]] || return 1
  [[ -n "${server}" && "${server}" != *[[:space:]@/?#%]* ]] || return 1
  structured_instance_store_validate_id "${instance_id}" || return 1
  validate_structured_instance_store vless-plain "${store_file}" || return 1
  snapshot=$(structured_instance_store_snapshot_json vless-plain "${store_file}") || return 1
  instance=$(jq -ce --arg id "${instance_id}" --arg user "${user_name}" '.instances[] | select(.id == $id) | select(any(.authentication.users[]; .name == $user))' <<< "${snapshot}") || return 1
  client_trust=$(jq -er '.client_trust' <<< "${instance}") || return 1
  if [[ "${client_trust}" != system ]]; then
    vless_plain_share_skip vless_plain_tls_certificate_uri_unrepresentable 'VLESS 自定义证书信任无法由 raw URI 无损表达；该用户已跳过。'
    return 31
  fi
  transport_json=$(jq -ce '.transport' <<< "${instance}") || return 1
  if ! vless_plain_share_transport_supported "${transport_json}"; then
    vless_plain_share_skip vless_plain_transport_uri_unrepresentable 'VLESS transport 包含 raw URI 无法无损表达的字段；该用户已跳过。'
    return 32
  fi
  tag=$(jq -r --arg user "${user_name}" '"vless-plain-" + .id + "-user-" + ($user | @base64)' <<< "${instance}") || return 1
  filtered_file=$(mktemp) || return 1
  trap 'rm -f -- "${filtered_file}"' EXIT
  jq -e --arg id "${instance_id}" '.instances |= map(select(.id == $id)) | .default_instance_id=$id' <<< "${snapshot}" > "${filtered_file}" || return 1
  outbound=$(build_vless_plain_client_outbounds_from_store "${filtered_file}" "${server}" | jq -ce --arg tag "${tag}" 'select(.tag == $tag)') || return 1
  uri=$(build_vless_plain_uri_from_outbound "${outbound}" "${node_name}") || return 1
  uri_bytes=$(printf '%s' "${uri}" | wc -c) || return 1
  [[ "${uri_bytes}" =~ ^[0-9]+$ && "${uri_bytes}" -le 16384 ]] || {
    vless_plain_share_skip vless_plain_uri_too_large 'VLESS raw URI 超过 SubMan 16384 字节上限；该用户已跳过。'; return 33;
  }
  printf '%s' "${uri}"
)

build_vless_plain_subman_links_and_warnings_json() (
  local server=${1:-} instance_id=${2:-} store_file snapshot snapshot_file instance node_name user_name tag uri status warning
  local links='{}' warnings='[]' users_text
  [[ $# -ge 1 && $# -le 2 ]] || return 1
  store_file=$(plain_proxy_structured_store_file vless-plain) || return 1
  snapshot=$(structured_instance_store_snapshot_json vless-plain "${store_file}") || return 1
  snapshot_file=$(mktemp) || return 1; trap 'rm -f -- "${snapshot_file}"' EXIT
  printf '%s\n' "${snapshot}" > "${snapshot_file}" || return 1
  instance_id=${2:-$(jq -er '.default_instance_id' <<< "${snapshot}")}
  instance=$(jq -ce --arg id "${instance_id}" '.instances[] | select(.id == $id)' <<< "${snapshot}") || return 1
  node_name=$(jq -r '.name' <<< "${instance}") || return 1
  users_text=$(jq -r '.authentication.users[].name' <<< "${instance}") || return 1
  while IFS= read -r user_name; do
    [[ -n "${user_name}" ]] || continue
    tag=$(jq -r --arg user "${user_name}" '"vless-plain-" + .id + "-user-" + ($user | @base64)' <<< "${instance}") || return 1
    if uri=$(build_vless_plain_subman_uri_from_store "${snapshot_file}" "${server}" "${instance_id}" "${user_name}" "${node_name} ${tag}"); then
      links=$(jq -cn --argjson links "${links}" --arg tag "${tag}" --arg uri "${uri}" '$links + {($tag):$uri}') || return 1
    else
      status=$?
      if [[ "${status}" == 31 || "${status}" == 32 || "${status}" == 33 ]]; then
        warning=$(vless_plain_share_warning_for_status "${status}") || return 1
        warnings=$(jq -cn --argjson warnings "${warnings}" --argjson warning "${warning}" --arg instance_id "${instance_id}" --arg tag "${tag}" '$warnings + ($warning | map(. + {instance_id:$instance_id,outbound_tag:$tag}))') || return 1
      else return "${status}"; fi
    fi
  done <<< "${users_text}"
  jq -cn --argjson links "${links}" --argjson warnings "${warnings}" '{links:$links,warnings:$warnings}'
)

build_vless_plain_links_json_for_instance() {
  local result
  result=$(build_vless_plain_subman_links_and_warnings_json "$@") || return $?
  jq -e '.links | length > 0' <<< "${result}" >/dev/null || return 1
  jq -c '.links' <<< "${result}"
}

