  local instance_id=${1:-} user_name=${2-} prefix digest suffix
  prefix=$(subman_node_prefix) || return 1; digest=$(printf '%s' "${user_name}" | sha256sum); digest=${digest%% *}; suffix="user-${digest:0:12}"
