  case "${SB_MIXED_LISTEN_ADDRESS:-}" in 0.0.0.0|::) server=${public_ip} ;; *) server=${SB_MIXED_LISTEN_ADDRESS:-} ;; esac
  [[ -n "${server}" ]] || return 1
  jq -n --arg name "${SB_NODE_NAME:-ShadowTLS}" --arg id "${SB_INSTANCE_ID:-}" --arg tag "${SB_MIXED_INBOUND_TAG:-}" --arg address "${SB_MIXED_LISTEN_ADDRESS:-}" --arg port "${SB_PORT:-}" --arg revision "${SB_MIXED_STORE_REVISION:-0}" --arg server "${server}" --arg handshake_server "${handshake}" --arg trust "${trust}" --arg wildcard "${wildcard}" --arg policy "${SB_OUTBOUND_POLICY:-default}" --arg detour "${SB_SHADOWTLS_DETOUR_TAG:-shadowtls-inner-${SB_INSTANCE_ID:-}}" --argjson version "${version}" --argjson user_count "${user_count}" --argjson strict "${strict}" '{protocol:"shadowtls",name:$name,port:($port|tonumber),instance_id:$id,tag:$tag,instance_revision:($revision|tonumber),listen:{address:$address,port:($port|tonumber)},server:$server,version:$version,handshake_server:$handshake_server,user_count:(if $version == 3 then $user_count else 1 end),auth_enabled:($version != 1),wildcard_sni:$wildcard,strict_mode:$strict,detour_tag:$detour,client_trust:$trust,outbound_policy:$policy,shareable:false,client_exportable:true}'
}

agent_shadowtls_link_json() (
  umask 077
  local public_ip=${1:-$(get_public_ip)} store_file snapshot end_snapshot instance_id server isolated_store summary bundle_json outbounds primary_tags warnings
  [[ "${CONFIG_SCHEMA_VERSION:-1}" == "2" ]] || return 1
  store_file=$(plain_proxy_structured_store_file shadowtls) || return 1
  snapshot=$(structured_instance_store_snapshot_json shadowtls "${store_file}") || return 1
  instance_id=${SB_INSTANCE_ID:-}; [[ -n "${instance_id}" ]] || instance_id=$(jq -er '.default_instance_id' <<< "${snapshot}") || return 1
  jq -e --arg id "${instance_id}" 'any(.instances[]; .id == $id)' <<< "${snapshot}" >/dev/null || return 1
  [[ "$(jq -r '.revision|tostring' <<< "${snapshot}")" == "${SB_MIXED_STORE_REVISION:-}" ]] || return 1
  case "${SB_MIXED_LISTEN_ADDRESS:-}" in 0.0.0.0|::) server=${public_ip} ;; "") return 1 ;; *) server=${SB_MIXED_LISTEN_ADDRESS} ;; esac
  [[ -n "${server}" && "${server}" != *[[:space:]@/?#%]* ]] || return 1
  summary=$(agent_shadowtls_node_json "${public_ip}") || return 1
  isolated_store=$(mktemp) || return 1
  trap 'rm -f -- "${isolated_store}"' EXIT
  jq --arg id "${instance_id}" '. as $root | ($root.instances|map(select(.id==$id))) as $instances | $root|.default_instance_id=$id|.instances=$instances' <<< "${snapshot}" > "${isolated_store}" || return 1
  bundle_json=$(build_client_shadowtls_bundle_json "${server}" "${isolated_store}") || return 1
  end_snapshot=$(structured_instance_store_snapshot_json shadowtls "${store_file}") || return 1
  [[ "${snapshot}" == "${end_snapshot}" ]] || return 1
  outbounds=$(jq -c '.outbounds' <<< "${bundle_json}") || return 1
  primary_tags=$(jq -c '.primary_tags' <<< "${bundle_json}") || return 1
  warnings=$(jq -cn '[{code:"shadowtls_standard_uri_unavailable",message:"ShadowTLS 是 TLS 包装层组合协议，当前没有可安全表达握手映射、detour 与版本参数的标准分享 URI；请使用完整客户端 outbound JSON。"}]') || return 1
  if [[ "${SB_SHADOWTLS_CLIENT_TRUST:-system}" == certificate ]]; then
    warnings=$(jq -cn --argjson warnings "${warnings}" '$warnings + [{code:"shadowtls_uri_certificate_trust_unavailable",message:"ShadowTLS certificate trust 无法由标准 URI 表达；请使用完整客户端 outbound JSON。"}]') || return 1
  fi
  jq -cn --argjson summary "${summary}" --argjson outbounds "${outbounds}" --argjson primary_tags "${primary_tags}" --argjson warnings "${warnings}" '$summary + {links:{},outbounds:$outbounds,primary_outbound_tags:$primary_tags,warnings:$warnings}'
)

agent_node_summary_json_for_current_protocol() {
  local protocol api_protocol public_ip shareable="true" client_exportable="false"
  local auth_enabled="false" server_name="" tls_enabled="false" http_tls_json
  local node_name instance_id="" inbound_tag="" listen_address="" instance_revision="0" rate_up="" rate_down="" outbound_policy=""
  local tls_mode="" acme_mode="" obfs_enabled="false"

  protocol=$(runtime_protocol_to_state "${SB_PROTOCOL}" 2>/dev/null || true)
  api_protocol=$(agent_protocol_id "${protocol}" 2>/dev/null || printf '%s' "${protocol}")
  public_ip=${1:-$(get_public_ip)}
  node_name=$(display_node_name_for_protocol "${protocol}" "${SB_NODE_NAME}" "")
  if [[ "${protocol}" == shadowsocks ]]; then agent_shadowsocks_node_json; return $?; fi
  if [[ "${protocol}" == trojan ]]; then agent_trojan_node_json "${public_ip}"; return $?; fi
  if [[ "${protocol}" == vmess ]]; then agent_vmess_node_json "${public_ip}"; return $?; fi
  if [[ "${protocol}" == vless-plain ]]; then agent_vless_plain_node_json "${public_ip}"; return $?; fi
  if [[ "${protocol}" == anytls && "${CONFIG_SCHEMA_VERSION:-1}" == 2 ]] && plain_proxy_structured_state_active anytls; then
    agent_anytls_node_json "${public_ip}"; return $?
  fi
  if [[ "${protocol}" == hy2 && "${CONFIG_SCHEMA_VERSION:-1}" == 2 ]] && plain_proxy_structured_state_active hy2; then
    agent_hy2_node_json "${public_ip}"; return $?
  fi
  if [[ "${protocol}" == snell && "${CONFIG_SCHEMA_VERSION:-1}" == 2 ]] && plain_proxy_structured_state_active snell; then
    agent_snell_node_json "${public_ip}"; return $?
  fi
  if [[ "${protocol}" == tuic && "${CONFIG_SCHEMA_VERSION:-1}" == 2 ]] && plain_proxy_structured_state_active tuic; then
    agent_tuic_node_json "${public_ip}"; return $?
  fi
  if [[ "${protocol}" == hysteria && "${CONFIG_SCHEMA_VERSION:-1}" == 2 ]] && plain_proxy_structured_state_active hysteria; then
    agent_hysteria_node_json "${public_ip}"; return $?
  fi
  if [[ "${protocol}" == naive && "${CONFIG_SCHEMA_VERSION:-1}" == 2 ]] && plain_proxy_structured_state_active naive; then
    agent_naive_node_json "${public_ip}"; return $?
  fi
  if [[ "${protocol}" == shadowtls && "${CONFIG_SCHEMA_VERSION:-1}" == 2 ]] && plain_proxy_structured_state_active shadowtls; then
    agent_shadowtls_node_json "${public_ip}"; return $?
  fi

  case "${protocol}" in
    vless-reality)
      client_exportable="true"
      server_name="${SB_SNI}"
      instance_id="${SB_VLESS_INSTANCE_ID:-main}"
      rate_up="${SB_VLESS_RATE_LIMIT_UP_MBPS:-}"
      rate_down="${SB_VLESS_RATE_LIMIT_DOWN_MBPS:-}"
      outbound_policy="${SB_OUTBOUND_POLICY:-default}"
      ;;
    mixed|socks)
      client_exportable="true"
      [[ "${SB_MIXED_AUTH_ENABLED}" == "y" ]] && auth_enabled="true"
      instance_id="${SB_MIXED_INSTANCE_ID:-}"
      inbound_tag="${SB_MIXED_INBOUND_TAG:-}"
      listen_address="${SB_MIXED_LISTEN_ADDRESS:-}"
      instance_revision="${SB_MIXED_STORE_REVISION:-0}"
      ;;
    http)
      client_exportable="true"
      [[ "${SB_MIXED_AUTH_ENABLED}" == "y" ]] && auth_enabled="true"
      instance_id="${SB_MIXED_INSTANCE_ID:-}"
      inbound_tag="${SB_MIXED_INBOUND_TAG:-}"
      listen_address="${SB_MIXED_LISTEN_ADDRESS:-}"
      instance_revision="${SB_MIXED_STORE_REVISION:-0}"
      http_tls_json=${SB_HTTP_TLS_JSON:-}
      [[ -n "${http_tls_json}" ]] || return 1
      tls_enabled=$(jq -er 'if .enabled == true then "true" elif .enabled == false then "false" else empty end' <<< "${http_tls_json}") || return 1
      [[ "${tls_enabled}" == true ]] && shareable="false"
      ;;
    hy2)
      client_exportable="true"
      server_name="${SB_HY2_DOMAIN:-${public_ip}}"
      rate_up="${SB_HY2_UP_MBPS:-}"
      rate_down="${SB_HY2_DOWN_MBPS:-}"
      tls_mode="${SB_HY2_TLS_MODE:-}"
      acme_mode="${SB_HY2_ACME_MODE:-}"
      [[ "${SB_HY2_OBFS_ENABLED:-n}" == "y" ]] && obfs_enabled="true"
      ;;
    anytls)
      client_exportable="true"
      server_name="${SB_ANYTLS_DOMAIN:-${public_ip}}"
      tls_mode="${SB_ANYTLS_TLS_MODE:-}"
      acme_mode="${SB_ANYTLS_ACME_MODE:-}"
      ;;
    *)
      shareable="false"
      ;;
  esac

  jq -n \
    --arg protocol "${api_protocol}" \
    --arg name "${node_name}" \
    --arg port "${SB_PORT}" \
    --arg server_name "${server_name}" \
    --arg instance_id "${instance_id}" \
    --arg inbound_tag "${inbound_tag}" \
    --arg listen_address "${listen_address}" \
    --arg instance_revision "${instance_revision}" \
    --arg rate_up "${rate_up}" \
    --arg rate_down "${rate_down}" \
    --arg outbound_policy "${outbound_policy}" \
    --arg tls_mode "${tls_mode}" \
    --arg acme_mode "${acme_mode}" \
    --argjson obfs_enabled "${obfs_enabled}" \
    --argjson shareable "${shareable}" \
    --argjson client_exportable "${client_exportable}" \
    --argjson auth_enabled "${auth_enabled}" \
    --argjson tls_enabled "${tls_enabled}" \
    '{
      "protocol": $protocol,
      "name": $name,
      "port": ($port | tonumber),
      "shareable": $shareable,
      "client_exportable": $client_exportable
    }
    + (if $server_name != "" then {"server_name": $server_name} else {} end)
    + (if ($protocol == "mixed" or $protocol == "socks" or $protocol == "http") then {"auth_enabled": $auth_enabled} else {} end)
    + (if ($protocol == "mixed" or $protocol == "socks" or $protocol == "http") then {"instance_revision": ($instance_revision | tonumber)} else {} end)
    + (if ($protocol == "http") then {"tls_enabled": $tls_enabled} else {} end)
    + (if ($protocol == "mixed" or $protocol == "socks" or $protocol == "http") and $instance_id != "" then {
        "instance_id": $instance_id,
        "tag": $inbound_tag,
        "listen": {"address": $listen_address, "port": ($port | tonumber)}
      } else {} end)
    + (if $protocol == "vless-reality" then {
        "instance_id": $instance_id,
        "rate_limit": {
          "up_mbps": (if $rate_up == "" then null else (try ($rate_up | tonumber) catch null) end),
          "down_mbps": (if $rate_down == "" then null else (try ($rate_down | tonumber) catch null) end)
        },
        "outbound_policy": $outbound_policy
      } else {} end)
    + (if $protocol == "hysteria2" then {
        "rate_limit": {
          "up_mbps": (if $rate_up == "" then null else (try ($rate_up | tonumber) catch null) end),
          "down_mbps": (if $rate_down == "" then null else (try ($rate_down | tonumber) catch null) end)
        },
        "tls_mode": $tls_mode,
        "acme_mode": (if $tls_mode == "acme" then $acme_mode else null end),
        "obfs_enabled": $obfs_enabled
      } else {} end)
    + (if $protocol == "anytls" then {
        "tls_mode": $tls_mode,
        "acme_mode": (if $tls_mode == "acme" then $acme_mode else null end)
      } else {} end)'
}

agent_link_json_for_current_protocol() {
  local protocol api_protocol public_ip link_json outbound_json
  local address_label
  local node_name instance_id="" inbound_tag="" listen_address="" mixed_link_address="" instance_revision="0" rate_up="" rate_down="" outbound_policy="" http_tls_json http_tls_enabled
  local compatibility_warnings_json='[]' share_warnings

  protocol=$(runtime_protocol_to_state "${SB_PROTOCOL}" 2>/dev/null || true)
  api_protocol=$(agent_protocol_id "${protocol}" 2>/dev/null || printf '%s' "${protocol}")
  public_ip=${1:-$(get_public_ip)}
  if [[ "${protocol}" == shadowsocks ]]; then agent_shadowsocks_link_json "${public_ip}"; return $?; fi
  if [[ "${protocol}" == trojan ]]; then agent_trojan_link_json "${public_ip}"; return $?; fi
  if [[ "${protocol}" == vmess ]]; then agent_vmess_link_json "${public_ip}"; return $?; fi
  if [[ "${protocol}" == vless-plain ]]; then agent_vless_plain_link_json "${public_ip}"; return $?; fi
  if [[ "${protocol}" == anytls && "${CONFIG_SCHEMA_VERSION:-1}" == 2 ]] && plain_proxy_structured_state_active anytls; then
    agent_anytls_link_json "${public_ip}"; return $?
  fi
  if [[ "${protocol}" == hy2 && "${CONFIG_SCHEMA_VERSION:-1}" == 2 ]] && plain_proxy_structured_state_active hy2; then
    agent_hy2_link_json "${public_ip}"; return $?
  fi
  if [[ "${protocol}" == snell && "${CONFIG_SCHEMA_VERSION:-1}" == 2 ]] && plain_proxy_structured_state_active snell; then
    agent_snell_link_json "${public_ip}"; return $?
  fi
  if [[ "${protocol}" == tuic && "${CONFIG_SCHEMA_VERSION:-1}" == 2 ]] && plain_proxy_structured_state_active tuic; then
    agent_tuic_link_json "${public_ip}"; return $?
  fi
  if [[ "${protocol}" == hysteria && "${CONFIG_SCHEMA_VERSION:-1}" == 2 ]] && plain_proxy_structured_state_active hysteria; then
    agent_hysteria_link_json "${public_ip}"; return $?
  fi
  if [[ "${protocol}" == naive && "${CONFIG_SCHEMA_VERSION:-1}" == 2 ]] && plain_proxy_structured_state_active naive; then
    agent_naive_link_json "${public_ip}"; return $?
  fi
  if [[ "${protocol}" == shadowtls && "${CONFIG_SCHEMA_VERSION:-1}" == 2 ]] && plain_proxy_structured_state_active shadowtls; then
    agent_shadowtls_link_json "${public_ip}"; return $?
  fi
  if [[ "${public_ip}" == *:* ]]; then
    address_label="IPv6"
  elif [[ "${public_ip}" == *.* ]]; then
    address_label="IPv4"
  else
    address_label=""
  fi
  node_name=$(display_node_name_for_protocol "${protocol}" "${SB_NODE_NAME}" "${address_label}")

  case "${protocol}" in
    vless-reality)
      instance_id="${SB_VLESS_INSTANCE_ID:-main}"
      rate_up="${SB_VLESS_RATE_LIMIT_UP_MBPS:-}"
      rate_down="${SB_VLESS_RATE_LIMIT_DOWN_MBPS:-}"
      outbound_policy="${SB_OUTBOUND_POLICY:-default}"
      link_json=$(jq -n --arg vless "$(build_vless_link "${public_ip}" "${address_label}")" '{"vless": $vless}')
      ;;
    mixed)
      instance_id="${SB_MIXED_INSTANCE_ID:-}"
      inbound_tag="${SB_MIXED_INBOUND_TAG:-}"
      listen_address="${SB_MIXED_LISTEN_ADDRESS:-}"
      instance_revision="${SB_MIXED_STORE_REVISION:-0}"
      mixed_link_address="${public_ip}"
      case "${listen_address}" in
        0.0.0.0|::) mixed_link_address="${public_ip}" ;;
        "") ;;
        *) mixed_link_address="${listen_address}" ;;
      esac
      link_json=$(build_plain_proxy_links_json mixed "${mixed_link_address}") || return 1
      ;;
    socks)
      instance_id="${SB_MIXED_INSTANCE_ID:-}"
      inbound_tag="${SB_MIXED_INBOUND_TAG:-}"
      listen_address="${SB_MIXED_LISTEN_ADDRESS:-}"
      instance_revision="${SB_MIXED_STORE_REVISION:-0}"
      mixed_link_address="${public_ip}"
      case "${listen_address}" in
        0.0.0.0|::) mixed_link_address="${public_ip}" ;;
        "") ;;
        *) mixed_link_address="${listen_address}" ;;
      esac
      link_json=$(build_plain_proxy_links_json socks "${mixed_link_address}") || return 1
      compatibility_warnings_json=$(jq -n '[{
        code: "socks_plaintext_transport",
        message: "SOCKS5 导出使用明文代理链路，认证信息与非加密业务可能被读取；仅用于可信网络或受保护隧道。UoT 即使启用也不提供加密。"
      }]')
      ;;
    http)
      instance_id="${SB_MIXED_INSTANCE_ID:-}"
      inbound_tag="${SB_MIXED_INBOUND_TAG:-}"
      listen_address="${SB_MIXED_LISTEN_ADDRESS:-}"
      instance_revision="${SB_MIXED_STORE_REVISION:-0}"
      mixed_link_address="${public_ip}"
      case "${listen_address}" in
        0.0.0.0|::) mixed_link_address="${public_ip}" ;;
        "") ;;
        *) mixed_link_address="${listen_address}" ;;
      esac
      http_tls_json=${SB_HTTP_TLS_JSON:-}
      [[ -n "${http_tls_json}" ]] || return 1
      http_tls_enabled=$(jq -er 'if .enabled == true then "true" elif .enabled == false then "false" else empty end' <<< "${http_tls_json}") || return 1
      [[ "${http_tls_enabled}" == true || "${http_tls_enabled}" == false ]] || return 1
      plain_proxy_http_auth_representable || return 1
      link_json=$(build_plain_proxy_links_json http "${mixed_link_address}") || return 1
      ;;
    hy2)
      link_json=$(jq -n --arg hy2 "$(build_hy2_link "${public_ip}" "${address_label}")" '{"hy2": $hy2}')
      compatibility_warnings_json=$(build_hy2_compatibility_warnings_json "share")
      ;;
    anytls)
      outbound_json=$(build_anytls_outbound_example "${public_ip}")
      link_json='{}'
      ;;
    *)
      link_json='{}'
      ;;
  esac

  if [[ "${protocol}" == mixed || "${protocol}" == socks || "${protocol}" == http ]]; then
    share_warnings=$(plain_proxy_share_warnings_json "${protocol}") || return 1
    compatibility_warnings_json=$(jq -cn --argjson existing "${compatibility_warnings_json}" \
      --argjson share "${share_warnings}" '$existing + $share') || return 1
  fi

  jq -n \
    --arg protocol "${api_protocol}" \
    --arg name "${node_name}" \
    --arg port "${SB_PORT}" \
    --arg instance_id "${instance_id}" \
    --arg inbound_tag "${inbound_tag}" \
    --arg listen_address "${listen_address}" \
    --arg instance_revision "${instance_revision}" \
    --arg rate_up "${rate_up}" \
    --arg rate_down "${rate_down}" \
    --arg outbound_policy "${outbound_policy}" \
    --argjson links "${link_json}" \
    --argjson outbound "${outbound_json:-null}" \
    --argjson warnings "${compatibility_warnings_json}" \
    '{
      "protocol": $protocol,
      "name": $name,
      "port": ($port | tonumber),
      "links": $links
    }
    + (if $protocol == "vless-reality" then {
        "instance_id": $instance_id,
        "rate_limit": {
          "up_mbps": (if $rate_up == "" then null else (try ($rate_up | tonumber) catch null) end),
          "down_mbps": (if $rate_down == "" then null else (try ($rate_down | tonumber) catch null) end)
        },
        "outbound_policy": $outbound_policy
      } else {} end)
    + (if ($protocol == "mixed" or $protocol == "socks" or $protocol == "http") and $instance_id != "" then {
        "instance_id": $instance_id,
        "tag": $inbound_tag,
        "listen": {"address": $listen_address, "port": ($port | tonumber)}
      } else {} end)
    + (if ($protocol == "mixed" or $protocol == "socks" or $protocol == "http") then {"instance_revision": ($instance_revision | tonumber)} else {} end)
    + (if $outbound != null then {"outbound": $outbound} else {} end)
    + (if ($warnings | length) > 0 then {"warnings": $warnings} else {} end)'
}

agent_collect_nodes_json() {
  local mode=$1
  local public_ip original_protocol_state original_state_file original_instance_id
  local protocol node_json instance_id indexed_protocols instance_ids instance_record
  local nodes_json='[]'
  local installed_protocols=()
  local protocol_instance_records=()
  local tmpdir status=0

  if ! validate_live_inbound_inventory "${SINGBOX_CONFIG_FILE}"; then
    agent_json_error "live_inbound_inventory_untrusted" "现有配置包含无法完整识别的入站；未返回部分节点。"
    return 1
  fi
  if ! indexed_protocols=$(agent_trusted_indexed_protocols_raw); then
    agent_json_error "protocol_index_untrusted" "协议索引与现有配置无法完整对应；未返回部分节点。"
    return 1
  fi
  if ! agent_validate_indexed_protocol_states "${indexed_protocols}"; then
    agent_json_error "protocol_state_untrusted" "协议状态无法完整读取；未返回部分节点。"
    return 1
  fi
  while IFS= read -r protocol; do
    [[ -n "${protocol}" ]] || continue
    installed_protocols+=("${protocol}")
  done <<< "${indexed_protocols}"

  # Enumerate every managed instance before doing public-IP or other resource
  # work.  The records are the single input to the rendering loop below.
  for protocol in ${installed_protocols[@]+"${installed_protocols[@]}"}; do
    if ! instance_ids=$(list_protocol_instance_ids "${protocol}"); then
      agent_json_error "protocol_state_untrusted" "协议实例清单无法完整读取；未返回部分节点。"
      return 1
    fi
    while IFS= read -r instance_id; do
      [[ -n "${instance_id}" ]] || continue
      protocol_instance_records+=("${protocol}"$'\t'"${instance_id}")
    done <<< "${instance_ids}"
  done

  original_protocol_state=$(runtime_protocol_to_state "${SB_PROTOCOL}" 2>/dev/null || true)
  original_state_file=""
  if [[ -n "${original_protocol_state}" ]]; then
    original_state_file=$(protocol_state_file "${original_protocol_state}" 2>/dev/null || true)
  fi
  original_instance_id=""
  if [[ -n "${original_state_file}" && -f "${original_state_file}" ]]; then
    if ! original_instance_id=$(protocol_default_instance_id "${original_protocol_state}"); then
      agent_json_error "protocol_state_untrusted" "当前协议默认实例无法完整读取；未返回节点。"
      return 1
    fi
  fi
  public_ip=$(get_public_ip)
  tmpdir=$(mktemp -d)

  trap 'rm -rf "${tmpdir:-}"' RETURN

  for instance_record in ${protocol_instance_records[@]+"${protocol_instance_records[@]}"}; do
    IFS=$'\t' read -r protocol instance_id <<< "${instance_record}"
    if ! load_protocol_instance_state "${protocol}" "${instance_id}"; then
      status=1
      continue
    fi
    case "${mode}" in
      summary) node_json=$(agent_node_summary_json_for_current_protocol "${public_ip}") || status=1 ;;
      links) node_json=$(agent_link_json_for_current_protocol "${public_ip}") || status=1 ;;
      *) status=1; continue ;;
    esac

    if [[ -n "${node_json:-}" ]]; then
      if ! printf '%s\n' "${node_json}" >> "${tmpdir}/nodes.jsonl"; then
        status=1
      fi
    else
      status=1
    fi
  done

  if [[ -s "${tmpdir}/nodes.jsonl" ]]; then
    nodes_json=$(jq -s '.' "${tmpdir}/nodes.jsonl") || status=1
  fi
  if [[ -n "${original_state_file}" && -f "${original_state_file}" ]]; then
    load_protocol_instance_state "${original_protocol_state}" "${original_instance_id}" >/dev/null 2>&1 || status=1
  fi
  if rm -rf "${tmpdir}"; then
    tmpdir=""
  else
    status=1
  fi

  if [[ "${status}" != "0" ]]; then
    agent_json_error "protocol_state_untrusted" "协议状态无法完整读取；未返回部分节点。"
    return 1
  fi
  trap - RETURN

  jq -n \
    --arg schema "${AGENT_OUTPUT_SCHEMA_VERSION}" \
    --arg action "$([[ "${mode}" == "summary" ]] && printf 'nodes' || printf 'links')" \
    --argjson sensitive "$([[ "${mode}" == "links" ]] && printf 'true' || printf 'false')" \
    --arg public_address "${public_ip}" \
    --argjson nodes "${nodes_json}" \
    '{
      "schema": $schema,
      "action": $action,
      "sensitive": $sensitive,
      "public_address": $public_address,
      "nodes": $nodes
    }'

  return 0
}

agent_export_client_json() {
  local config_json export_path compatibility_warnings_json

  if ! config_json=$(build_singbox_client_config); then
    agent_json_error "client_config_generation_failed" "客户端配置生成失败；请检查已安装协议的状态、端口与认证字段，原导出文件和备份未改变。"
    return 1
  fi

  if ! validate_client_config_json "${config_json}"; then
    agent_json_error "client_config_validation_failed" "客户端配置未通过引用或核心 check 校验，未发布导出文件。"
    return 1
  fi

  compatibility_warnings_json=$(collect_client_export_warnings_json "${config_json}") || return 1

  export_path=$(client_export_file_path)
  if ! write_client_config_export "${config_json}"; then
    log_warn "agent export-client 写入失败: ${export_path}" >&2
    return 1
  fi

  jq -n \
    --arg path "${export_path}" \
    --argjson config "${config_json}" \
    --argjson warnings "${compatibility_warnings_json}" \
    '{
      "path": $path,
      "config": $config
    }
    + (if ($warnings | length) > 0 then {"warnings": $warnings} else {} end)'
}

agent_service_cli() {
  local command=${1:-}
  local json_flag=${2:-}
  local yes_flag=${3:-}
  local before_state after_state check_json restart_status

  if [[ "${command}" != "restart" ]]; then
    agent_json_error "unknown_service_command" "未知 service 子命令: ${command}"
    return 1
  fi

  agent_require_json_flag "${json_flag}" || return 1

  if [[ "${yes_flag}" != "--yes" ]]; then
    agent_json_error "confirmation_required" "service restart 需要 --yes 确认。"
    return 1
  fi

  before_state=$(systemctl is-active sing-box 2>/dev/null || true)
  if ! check_json=$(agent_singbox_check_json); then
    after_state=$(systemctl is-active sing-box 2>/dev/null || true)
    jq -n \
      --arg before "${before_state:-unknown}" \
      --arg after "${after_state:-unknown}" \
      --argjson check "${check_json}" \
      '{
        ok: false,
        action: "service_restart",
        skipped: true,
        reason: "config_check_failed",
        service: {
          before: $before,
          after: $after
        },
        check: $check
      }'
    return 1
  fi

  if systemctl restart sing-box; then
    restart_status=0
  else
    restart_status=$?
  fi
  after_state=$(systemctl is-active sing-box 2>/dev/null || true)

  if [[ "${restart_status}" != "0" || "${after_state}" != "active" ]]; then
    jq -n \
      --arg before "${before_state:-unknown}" \
      --arg after "${after_state:-unknown}" \
      --argjson exit_code "${restart_status}" \
      --argjson check "${check_json}" \
      '{
        ok: false,
        action: "service_restart",
        error: "service_restart_failed",
        skipped: false,
        service: {
          before: $before,
          after: $after,
          restart_exit_code: $exit_code
        },
        check: $check
      }'
    return 1
  fi

  jq -n \
    --arg before "${before_state:-unknown}" \
    --arg after "${after_state:-unknown}" \
    --argjson check "${check_json}" \
    '{
      ok: true,
      action: "service_restart",
      service: {
        before: $before,
        after: $after
      },
      check: $check
    }'
}

agent_push_nodes_to_subman_json() {
  local original_protocol_state protocol instance_id
  local address_entry address_label public_ip
  local instance_attempted instance_synced instance_stacked_synced
  local synced_count skipped_count failed_count shadowsocks_skipped_count trojan_skipped_count vmess_skipped_count vless_plain_skipped_count hy2_skipped_count ok_json
  local last_error_code last_error_disposition last_http_status last_retry_after
  local compatibility_warnings_json
  local installed_protocols=()

  original_protocol_state=$(runtime_protocol_to_state "${SB_PROTOCOL}" 2>/dev/null || true)
  synced_count=0
  skipped_count=0
  failed_count=0
  shadowsocks_skipped_count=0
  trojan_skipped_count=0
  vmess_skipped_count=0
  vless_plain_skipped_count=0
  hy2_skipped_count=0
  last_error_code=""
  last_error_disposition=""
  last_http_status=""
  last_retry_after=""
  compatibility_warnings_json=$(collect_hy2_compatibility_warnings_json "share")

  mapfile -t installed_protocols < <(list_installed_protocols)
  if [[ ${#installed_protocols[@]} -eq 0 ]]; then
    jq -n '{ok: false, synced: 0, skipped: 0, failed: 0, error: "no_installed_protocols"}'
    return 1
  fi

  for protocol in "${installed_protocols[@]}"; do
    protocol=$(normalize_protocol_id "${protocol}" 2>/dev/null || true)
    if [[ -z "${protocol}" ]]; then
      skipped_count=$((skipped_count + 1))
      continue
    fi

    if ! subman_type_for_protocol "${protocol}" >/dev/null; then
      skipped_count=$((skipped_count + 1))
      continue
    fi

    if ! protocol_state_exists "${protocol}"; then
      skipped_count=$((skipped_count + 1))
      continue
    fi

    if ! load_protocol_state "${protocol}"; then
      failed_count=$((failed_count + 1))
      continue
    fi

    if [[ "${protocol}" == "vless-reality" ]]; then
      while IFS= read -r instance_id; do
        [[ -z "${instance_id}" ]] && continue
        instance_attempted=0
        instance_synced=0
        instance_stacked_synced=0
        while IFS= read -r address_entry; do
          [[ -z "${address_entry}" ]] && continue
          address_label=${address_entry%%|*}
          public_ip=${address_entry#*|}
          instance_attempted=$((instance_attempted + 1))
          if push_subman_protocol_instance "${protocol}" "${public_ip}" "${instance_id}" "y" "${address_label}"; then
            synced_count=$((synced_count + 1))
            instance_synced=$((instance_synced + 1))
            if [[ -n "$(network_stack_suffix_from_label "${address_label}")" ]]; then
              instance_stacked_synced=$((instance_stacked_synced + 1))
            fi
          else
            failed_count=$((failed_count + 1))
            last_error_code=${SUBMAN_LAST_ERROR_CODE:-unknown_error}
            last_error_disposition=${SUBMAN_LAST_ERROR_DISPOSITION:-operator-repair}
            last_http_status=${SUBMAN_LAST_HTTP_STATUS:-}
            last_retry_after=${SUBMAN_LAST_RETRY_AFTER:-}
          fi
        done < <(list_subman_addresses_for_current_protocol)
        if subman_instance_ready_for_legacy_cleanup "${instance_attempted}" "${instance_synced}" "${instance_stacked_synced}" && \
          push_subman_legacy_protocol_key_cleanup "${protocol}" "${instance_id}" "y"; then
          :
        elif subman_instance_ready_for_legacy_cleanup "${instance_attempted}" "${instance_synced}" "${instance_stacked_synced}"; then
          failed_count=$((failed_count + 1))
          last_error_code=${SUBMAN_LAST_ERROR_CODE:-unknown_error}
          last_error_disposition=${SUBMAN_LAST_ERROR_DISPOSITION:-operator-repair}
          last_http_status=${SUBMAN_LAST_HTTP_STATUS:-}
          last_retry_after=${SUBMAN_LAST_RETRY_AFTER:-}
        fi
      done < <(list_vless_reality_instance_ids)
      continue
    fi

    if [[ "${protocol}" == "shadowsocks" ]]; then
      push_subman_shadowsocks_protocol y || true
      synced_count=$((synced_count + ${SUBMAN_SHADOWSOCKS_SYNCED:-0}))
      skipped_count=$((skipped_count + ${SUBMAN_SHADOWSOCKS_SKIPPED:-0}))
      shadowsocks_skipped_count=$((shadowsocks_skipped_count + ${SUBMAN_SHADOWSOCKS_SKIPPED:-0}))
      failed_count=$((failed_count + ${SUBMAN_SHADOWSOCKS_FAILED:-0}))
      if [[ -n "${SUBMAN_SHADOWSOCKS_WARNINGS_JSON:-}" ]]; then
        compatibility_warnings_json=$(jq -cn \
          --argjson existing "${compatibility_warnings_json}" \
          --argjson additions "${SUBMAN_SHADOWSOCKS_WARNINGS_JSON}" '$existing + $additions') || return 1
      fi
      if [[ "${SUBMAN_SHADOWSOCKS_FAILED:-0}" -gt 0 ]]; then
        last_error_code=${SUBMAN_LAST_ERROR_CODE:-shadowsocks_sync_failed}
        last_error_disposition=${SUBMAN_LAST_ERROR_DISPOSITION:-operator-repair}
        last_http_status=${SUBMAN_LAST_HTTP_STATUS:-}
        last_retry_after=${SUBMAN_LAST_RETRY_AFTER:-}
      fi
      continue
    fi

    if [[ "${protocol}" == "trojan" ]]; then
      if push_subman_trojan_protocol y; then
        :
      else
        # The protocol worker records per-instance failures in its counters;
        # retain those counters while keeping the aggregate operation running.
        last_error_code=${SUBMAN_LAST_ERROR_CODE:-trojan_sync_failed}
        last_error_disposition=${SUBMAN_LAST_ERROR_DISPOSITION:-operator-repair}
        last_http_status=${SUBMAN_LAST_HTTP_STATUS:-}
        last_retry_after=${SUBMAN_LAST_RETRY_AFTER:-}
      fi
      synced_count=$((synced_count + ${SUBMAN_TROJAN_SYNCED:-0}))
      skipped_count=$((skipped_count + ${SUBMAN_TROJAN_SKIPPED:-0}))
      trojan_skipped_count=$((trojan_skipped_count + ${SUBMAN_TROJAN_SKIPPED:-0}))
      failed_count=$((failed_count + ${SUBMAN_TROJAN_FAILED:-0}))
      if [[ -n "${SUBMAN_TROJAN_WARNINGS_JSON:-}" ]]; then
        compatibility_warnings_json=$(jq -cn \
          --argjson existing "${compatibility_warnings_json}" \
          --argjson additions "${SUBMAN_TROJAN_WARNINGS_JSON}" '$existing + $additions') || return 1
      fi
      if [[ "${SUBMAN_TROJAN_FAILED:-0}" -gt 0 ]]; then
        last_error_code=${SUBMAN_LAST_ERROR_CODE:-trojan_sync_failed}
        last_error_disposition=${SUBMAN_LAST_ERROR_DISPOSITION:-operator-repair}
        last_http_status=${SUBMAN_LAST_HTTP_STATUS:-}
        last_retry_after=${SUBMAN_LAST_RETRY_AFTER:-}
      fi
      continue
    fi

    if [[ "${protocol}" == "vmess" ]]; then
      if push_subman_vmess_protocol y; then :; else
        last_error_code=${SUBMAN_LAST_ERROR_CODE:-vmess_sync_failed}
        last_error_disposition=${SUBMAN_LAST_ERROR_DISPOSITION:-operator-repair}
        last_http_status=${SUBMAN_LAST_HTTP_STATUS:-}
        last_retry_after=${SUBMAN_LAST_RETRY_AFTER:-}
      fi
      synced_count=$((synced_count + ${SUBMAN_VMESS_SYNCED:-0}))
      skipped_count=$((skipped_count + ${SUBMAN_VMESS_SKIPPED:-0}))
      vmess_skipped_count=$((vmess_skipped_count + ${SUBMAN_VMESS_SKIPPED:-0}))
      failed_count=$((failed_count + ${SUBMAN_VMESS_FAILED:-0}))
      if [[ -n "${SUBMAN_VMESS_WARNINGS_JSON:-}" ]]; then
        compatibility_warnings_json=$(jq -cn --argjson existing "${compatibility_warnings_json}" --argjson additions "${SUBMAN_VMESS_WARNINGS_JSON}" '$existing + $additions') || return 1
      fi
      if [[ "${SUBMAN_VMESS_FAILED:-0}" -gt 0 ]]; then
        last_error_code=${SUBMAN_LAST_ERROR_CODE:-vmess_sync_failed}
        last_error_disposition=${SUBMAN_LAST_ERROR_DISPOSITION:-operator-repair}
        last_http_status=${SUBMAN_LAST_HTTP_STATUS:-}
        last_retry_after=${SUBMAN_LAST_RETRY_AFTER:-}
      fi
      continue
    fi

    if [[ "${protocol}" == "vless-plain" ]]; then
      if push_subman_vless_plain_protocol y; then :; else
        last_error_code=${SUBMAN_LAST_ERROR_CODE:-vless_plain_sync_failed}
        last_error_disposition=${SUBMAN_LAST_ERROR_DISPOSITION:-operator-repair}
        last_http_status=${SUBMAN_LAST_HTTP_STATUS:-}
        last_retry_after=${SUBMAN_LAST_RETRY_AFTER:-}
      fi
      synced_count=$((synced_count + ${SUBMAN_VLESS_PLAIN_SYNCED:-0}))
      skipped_count=$((skipped_count + ${SUBMAN_VLESS_PLAIN_SKIPPED:-0}))
      vless_plain_skipped_count=$((vless_plain_skipped_count + ${SUBMAN_VLESS_PLAIN_SKIPPED:-0}))
      failed_count=$((failed_count + ${SUBMAN_VLESS_PLAIN_FAILED:-0}))
      if [[ -n "${SUBMAN_VLESS_PLAIN_WARNINGS_JSON:-}" ]]; then
        compatibility_warnings_json=$(jq -cn --argjson existing "${compatibility_warnings_json}" --argjson additions "${SUBMAN_VLESS_PLAIN_WARNINGS_JSON}" '$existing + $additions') || return 1
      fi
      if [[ "${SUBMAN_VLESS_PLAIN_FAILED:-0}" -gt 0 ]]; then
        last_error_code=${SUBMAN_LAST_ERROR_CODE:-vless_plain_sync_failed}
        last_error_disposition=${SUBMAN_LAST_ERROR_DISPOSITION:-operator-repair}
        last_http_status=${SUBMAN_LAST_HTTP_STATUS:-}
        last_retry_after=${SUBMAN_LAST_RETRY_AFTER:-}
      fi
      continue
    fi

    if [[ "${protocol}" == "hy2" ]] && [[ "${CONFIG_SCHEMA_VERSION:-1}" == 2 ]] && plain_proxy_structured_state_active hy2; then
      if push_subman_hy2_protocol y; then :; else
        last_error_code=${SUBMAN_LAST_ERROR_CODE:-hy2_sync_failed}
        last_error_disposition=${SUBMAN_LAST_ERROR_DISPOSITION:-operator-repair}
        last_http_status=${SUBMAN_LAST_HTTP_STATUS:-}
        last_retry_after=${SUBMAN_LAST_RETRY_AFTER:-}
      fi
      synced_count=$((synced_count + ${SUBMAN_HY2_SYNCED:-0}))
      skipped_count=$((skipped_count + ${SUBMAN_HY2_SKIPPED:-0}))
      hy2_skipped_count=$((hy2_skipped_count + ${SUBMAN_HY2_SKIPPED:-0}))
      failed_count=$((failed_count + ${SUBMAN_HY2_FAILED:-0}))
      if [[ -n "${SUBMAN_HY2_WARNINGS_JSON:-}" ]]; then
        compatibility_warnings_json=$(jq -cn --argjson existing "${compatibility_warnings_json}" --argjson additions "${SUBMAN_HY2_WARNINGS_JSON}" '$existing + $additions') || return 1
      fi
      if [[ "${SUBMAN_HY2_FAILED:-0}" -gt 0 ]]; then
        last_error_code=${SUBMAN_LAST_ERROR_CODE:-hy2_sync_failed}
        last_error_disposition=${SUBMAN_LAST_ERROR_DISPOSITION:-operator-repair}
        last_http_status=${SUBMAN_LAST_HTTP_STATUS:-}
        last_retry_after=${SUBMAN_LAST_RETRY_AFTER:-}
      fi
      continue
    fi

    while IFS= read -r address_entry; do
      [[ -z "${address_entry}" ]] && continue
      address_label=${address_entry%%|*}
      public_ip=${address_entry#*|}
      if push_subman_protocol_instance "${protocol}" "${public_ip}" "" "y" "${address_label}"; then
        synced_count=$((synced_count + 1))
      else
        failed_count=$((failed_count + 1))
        last_error_code=${SUBMAN_LAST_ERROR_CODE:-unknown_error}
        last_error_disposition=${SUBMAN_LAST_ERROR_DISPOSITION:-operator-repair}
        last_http_status=${SUBMAN_LAST_HTTP_STATUS:-}
        last_retry_after=${SUBMAN_LAST_RETRY_AFTER:-}
      fi
    done < <(list_subman_addresses_for_current_protocol)
  done

  if [[ -n "${original_protocol_state}" ]] && protocol_state_exists "${original_protocol_state}"; then
    load_protocol_state "${original_protocol_state}"
  fi

  if (( synced_count == 0 && shadowsocks_skipped_count == 0 && trojan_skipped_count == 0 && vmess_skipped_count == 0 && vless_plain_skipped_count == 0 && hy2_skipped_count == 0 && failed_count == 0 )); then
    agent_json_error "public_ip_unavailable" "未获取到公网 IP，无法生成 SubMan 节点链接。"
    return 1
  fi

  ok_json=false
  if (( synced_count > 0 && failed_count == 0 )); then
    ok_json=true
  fi

  jq -n \
    --argjson ok "${ok_json}" \
    --argjson synced "${synced_count}" \
    --argjson skipped "${skipped_count}" \
    --argjson failed "${failed_count}" \
    --arg error_code "${last_error_code}" \
    --arg error_disposition "${last_error_disposition}" \
    --arg http_status "${last_http_status}" \
    --arg retry_after "${last_retry_after}" \
    --argjson warnings "${compatibility_warnings_json}" \
    '{
      ok: $ok,
      synced: $synced,
      skipped: $skipped,
      failed: $failed
    }
    + (if ($warnings | length) > 0 then {
        warnings: $warnings
      } else {} end)
    + (if $failed > 0 and $error_code != "" then {
        last_error: {
          code: $error_code,
          disposition: $error_disposition,
          http_status: (if $http_status == "" then null else $http_status end),
          retry_after: (if $retry_after == "" then null else $retry_after end)
        }
      } else {} end)'

  if [[ "${ok_json}" != "true" ]]; then
    return 1
  fi
}

agent_subman_sync_json() {
  local config_file

  config_file=$(subman_config_file_path)
  if [[ ! -f "${config_file}" ]]; then
    agent_json_error "subman_config_missing" "未找到 SubMan 配置，请先在交互菜单中配置 SubMan。"
    return 1
  fi

  load_subman_config
  if [[ -z "${SUBMAN_API_URL}" || -z "${SUBMAN_API_TOKEN}" ]]; then
    agent_json_error "subman_config_missing" "SubMan API URL 或 Token 为空。"
    return 1
  fi

  agent_push_nodes_to_subman_json
}

mixed_inactive_store_snapshot() {
  plain_proxy_inactive_store_snapshot mixed "$@"
}

plain_proxy_inactive_store_snapshot() {
  local protocol=$1
  local snapshot
  [[ ! -e "$(protocol_state_file "${protocol}")" ]] || return 1
  snapshot=$(structured_instance_store_snapshot_json "${protocol}" "$(plain_proxy_structured_store_file "${protocol}")") || return $?
  jq -e '.instances==[] and .default_instance_id=="" and .revision>0' <<< "${snapshot}" >/dev/null || return 1
  printf '%s\n' "${snapshot}"
}

mixed_instance_config_candidate() {
  plain_proxy_instance_config_candidate mixed "$@"
}

plain_proxy_instance_config_candidate() {
  local protocol=$1 old_config=$2 old_store=$3 new_store=$4 inbounds rules
  inbounds=$(render_structured_instance_inbounds "${protocol}" "${new_store}" | jq -s '.') || return $?
  rules=$(render_structured_instance_route_rules "${protocol}" "${new_store}") || return $?
  jq --arg protocol "${protocol}" --slurpfile old "${old_store}" --argjson added "${inbounds}" --argjson rules "${rules}" '
    def protocol_id:
      if $protocol == "shadowtls" and .type == "mixed" and ((.tag // "") | startswith("shadowtls-inner-")) then
        "shadowtls"
      elif .type == "vless" then
        (if .tls.reality? != null then "vless-reality" else "vless-plain" end)
      else .type end;
    ($old[0].instances | map(.tag) + (if $protocol == "shadowtls" then map(.detour.tag) else [] end)) as $old_tags |
    def owned_rule:
      (.inbound | type) == "string" and (.inbound as $tag | $old_tags | index($tag) != null) and
      ((.action == "sniff" and (keys | sort) == ["action","inbound"]) or
       (.action == "route" and (.outbound == "direct" or .outbound == "warp-ep") and
        (keys | sort) == ["action","inbound","outbound"]));
    (.inbounds // []) as $previous |
    ([$previous | to_entries[] | select((.value | protocol_id) == $protocol) | .key][0] // ($previous|length)) as $at |
    .inbounds = ($previous[:$at] + $added + [$previous[$at:][] | select((. | protocol_id) != $protocol)]) |
    (.route.rules // []) as $prior_rules |
    ([$prior_rules[] | select(owned_rule) | [.inbound,.action]] | unique) as $positioned |
    # Keep existing managed rules in place: moving a direct/Warp rule ahead
    # of a custom reject or routing condition would change existing traffic.
    (reduce $prior_rules[] as $rule ({seen:[],rules:[]};
      if ($rule | owned_rule) then
        if (.seen | index([[$rule.inbound,$rule.action]])) != null then .
        else .seen += [[$rule.inbound,$rule.action]] |
          .rules += [$rules[] | select(.inbound == $rule.inbound and .action == $rule.action)] end
      else .rules += [$rule] end)) as $retained |
    # A missing sniff rule is observational and must run before retained
    # custom rules. A missing route rule is a fallback; append it after the
    # retained rules so a conditional/reject rule keeps its precedence.
    .route.rules = (
      [$rules[] | select(.action == "sniff") |
        select([.inbound,.action] as $key | $positioned | index([$key]) == null)]
      + $retained.rules
      + [$rules[] | select(.action == "route") |
        select([.inbound,.action] as $key | $positioned | index([$key]) == null)]
    )
  ' "${old_config}"
}

# Public mutation entrypoints share a kernel lock. The persistent instance
# journal is a separate crash-recovery barrier, not a substitute for this lock.
acquire_managed_write_lock() {
  local lock_file="${SB_PROJECT_DIR}.management.flock" descriptor_target lock_mode=${1:-exclusive}
  local lock_option=-x
  case "${lock_mode}" in exclusive) ;; shared) lock_option=-s ;; *) return 1 ;; esac
  command -v flock >/dev/null 2>&1 || {
    printf '[ERROR] 写操作需要系统 flock 工具。\n' >&2; return 1;
  }
  [[ ! -L "${lock_file}" ]] || return 1
  if [[ "${SB_MANAGEMENT_LOCK_FD:-}" =~ ^[0-9]+$ ]]; then
    descriptor_target=$(readlink "/proc/${BASHPID:-$$}/fd/${SB_MANAGEMENT_LOCK_FD}") || return 1
    [[ "${descriptor_target}" == "${lock_file}" ]] || return 1
    if [[ "${lock_mode}" == shared && "${SB_MANAGEMENT_LOCK_MODE:-}" == exclusive ]]; then
      return 0
    fi
  else
    (umask 077; touch -- "${lock_file}") || return $?
    exec {SB_MANAGEMENT_LOCK_FD}>"${lock_file}" || return $?
  fi
  flock -n "${lock_option}" "${SB_MANAGEMENT_LOCK_FD}" || {
    printf '[ERROR] 另一个管理进程正在执行；本次未修改。\n' >&2; return 1;
  }
  SB_MANAGEMENT_LOCK_MODE=${lock_mode}
}

instance_transaction_checkpoint() {
  local lock_dir=$1 phase=$2
  jq --arg phase "${phase}" '.phase=$phase' "${lock_dir}/transaction.json" > "${lock_dir}/transaction.next" || return $?
  mv -f "${lock_dir}/transaction.next" "${lock_dir}/transaction.json"
}

instance_transaction_restore() {
  local lock_dir=$1 before_active status=0
  before_active=$(jq -r '.before_active' "${lock_dir}/transaction.json") || return $?
  # Restore only owned external effects; never infer firewall recovery from a
  # directory restore. Keep the persistent journal if either half fails.
  if [[ -f "${lock_dir}/firewall.json" ]]; then
    instance_firewall_rollback "${lock_dir}/firewall.json" || status=1
  else
    printf '[ERROR] 防火墙事务日志缺失；无法证明外部状态已恢复。\n' >&2
    status=1
  fi
  if [[ -f "${lock_dir}/snapshot/snapshot.meta" ]]; then
    if ! restore_managed_state_snapshot "${lock_dir}/snapshot"; then
      printf '[ERROR] 状态快照恢复失败；未启动可能不一致的配置，请保留事务目录人工恢复。\n' >&2
      return 1
    fi
    if [[ "${before_active}" == true ]]; then
      if systemctl restart sing-box >/dev/null 2>&1 && systemctl is-active --quiet sing-box; then :; else status=1; fi
    else
      if systemctl stop sing-box >/dev/null 2>&1 && singbox_service_confirmed_stopped; then :; else status=1; fi
    fi
  else
    printf '[ERROR] 事务恢复快照缺失；未报告回滚成功。\n' >&2
    return 1
  fi
  return "${status}"
}

instance_transaction_firewall_summary() {
  local journal_file=$1 summary
  if [[ -f "${journal_file}" && ! -L "${journal_file}" ]] && summary=$(jq -ce '
    def backend: IN("ufw","firewalld","iptables","ip6tables");
    def code: IN("backend_unavailable","backend_external_managed","backend_conflict",
      "backend_inspection_failed","backend_mutation_failed","backend_mutation_unconfirmed","owned_backend_unavailable",
      "owned_rule_inspection_failed","rule_inspection_failed","firewalld_owned_unsupported",
      "firewalld_requires_manual_setup","invalid_old_plan","invalid_new_plan",
      "invalid_old_targets","invalid_new_targets","invalid_ledger","invalid_candidates",
      "ledger_persist_failed","ledger_restore_failed","compensation_failed","external_state_uncertain");
    select(type == "object") | . as $journal |
    {status:(if (.status | IN("prepared","applying","applied","committed","prepare_failed",
       "apply_failed","rolling_back","rolled_back","rollback_failed","rollback_uncertain"))
       then .status else "unavailable" end),
     backends:[.backend_statuses[]? | select(.backend | backend) |
       {backend, state:(if (.state | IN("available","unavailable","external-managed")) then .state else "unavailable" end)}],
     diagnostics:[.diagnostics[]? |
       {code:(if (.code | code) then .code else "firewall_diagnostic_unrecognized" end),
        severity:(if .severity == "error" then "error" else "warning" end),
        backend:(if (.backend | backend) then .backend else "unavailable" end)}]}
    + (if $journal.error_code == null then {} else
       {error_code:(if ($journal.error_code | code) then $journal.error_code else "firewall_diagnostic_unrecognized" end)} end)
  ' "${journal_file}" 2>/dev/null); then
    printf '%s\n' "${summary}"
  else
    printf '%s\n' '{"status":"unavailable","backends":[],"diagnostics":[]}'
  fi
}

instance_transaction_report() {
  local state=$1 phase=$2 code=$3 changed=$4 manual=$5 revision=${6:-0}
  local report_protocol=${SB_INSTANCE_TRANSACTION_PROTOCOL:-mixed}
  local firewall_summary='{"status":"not_attempted","backends":[],"diagnostics":[]}'
  [[ $# -le 6 ]] || firewall_summary=$7
  jq -n --arg protocol "${report_protocol}" --arg state "${state}" --arg phase "${phase}" --arg code "${code}" \
    --argjson changed "${changed}" --argjson manual "${manual}" --argjson revision "${revision}" \
    --argjson firewall "${firewall_summary}" '
    {ok:($code==""),action:"instance",protocol:$protocol,changed:$changed,revision:$revision,
     transaction:{status:$state,phase:$phase,manual_intervention_required:$manual,firewall:$firewall}}
    + (if $code=="" then {} else {error:$code,message:"实例操作未成功；检查 transaction 状态，必要时执行 instance recover。"} end)'
}

instance_transaction_persist_result() (
  local payload=$1 directory="${SB_PROJECT_DIR}.instance-transactions" result
  umask 077
  [[ ! -L "${directory}" ]] || return 1
  mkdir -p "${directory}" && chmod 700 "${directory}" || return $?
  result=$(mktemp "${directory}/result-$(date -u +%Y%m%dT%H%M%SZ).XXXXXX.json") || return $?
  if ! instance_transaction_update_result "${result}" "${payload}"; then
    rm -f -- "${result}" || return 1
    return 1
  fi
  printf '%s' "${result}"
)

instance_transaction_update_result() (
  local result=$1 payload=$2 stage
  [[ "${result}" == "${SB_PROJECT_DIR}.instance-transactions/"result-*.json &&
     -f "${result}" && ! -L "${result}" ]] || return 1
  umask 077
  stage=$(mktemp "${result}.candidate.XXXXXX") || return $?
  trap 'rm -f -- "${stage}"' EXIT
  jq --arg path "${result}" \
    '.transaction.result_path=$path | .transaction.result_persisted=true' \
    <<< "${payload}" > "${stage}" || return $?
  mv -f -- "${stage}" "${result}"
)

recover_mixed_instance_transaction() {
  recover_plain_proxy_instance_transaction mixed "$@"
}

recover_plain_proxy_instance_transaction() (
  local SB_INSTANCE_TRANSACTION_PROTOCOL=$1
  local expected_revision=$2 lock_dir="${SB_PROJECT_DIR}.instance-write.lock"
  local phase owner_pid owner_start current_start="" result revision recovery_fd recovery_entries result_path firewall_summary
  structured_instance_store_protocol "${SB_INSTANCE_TRANSACTION_PROTOCOL}" >/dev/null || return 1
  [[ ${EUID} -eq 0 ]] || { agent_json_error root_required "恢复必须以 root 执行。"; return 1; }
  acquire_managed_write_lock || {
    agent_json_error instance_write_busy "另一个管理进程正在执行；未开始恢复。"; return 1;
  }
  if [[ -e "${SB_COMPONENT_TRANSACTION_DIR}" || -L "${SB_COMPONENT_TRANSACTION_DIR}" ]]; then
    agent_json_error component_transaction_pending "存在未完成的高级组件事务；请先完成 component recover。未开始实例恢复。"
    return 1
  fi
  [[ -d "${lock_dir}" && ! -L "${lock_dir}" ]] || {
    agent_json_error instance_recovery_unavailable "未找到可验证的待恢复实例事务；未自动删除任何文件。"; return 1;
  }
  if [[ ! -e "${lock_dir}/transaction.json" ]]; then
    # The shared kernel lock proves that no writer is still preparing this
    # directory. Before atomic journal publication, only transaction.next can
    # exist and no state/resource mutation is permitted. Anything else is an
    # ambiguous damaged transaction and must remain for manual inspection.
    recovery_entries=$(find "${lock_dir}" -mindepth 1 -maxdepth 1 -printf '%f\n') || return $?
    if [[ -n "${recovery_entries}" && "${recovery_entries}" != transaction.next ]] ||
       [[ -e "${lock_dir}/transaction.next" && (! -f "${lock_dir}/transaction.next" || -L "${lock_dir}/transaction.next") ]]; then
      agent_json_error instance_recovery_untrusted "主日志缺失且发现已准备材料；无法证明未发生变更，已保留目录。"; return 1
    fi
    result=$(instance_transaction_report unchanged prepare '' false false "${expected_revision}") || return $?
    result_path=$(instance_transaction_persist_result "${result}") || return $?
    rm -rf -- "${lock_dir}" || return $?
    jq --arg path "${result_path}" '.transaction.result_path=$path | .transaction.result_persisted=true' <<< "${result}"
    return 0
  fi
  [[ -f "${lock_dir}/transaction.json" && ! -L "${lock_dir}/transaction.json" ]] || {
    agent_json_error instance_recovery_untrusted "事务主日志不是可信普通文件；未修改。"; return 1;
  }
  jq -e --arg revision "${expected_revision}" --arg protocol "${SB_INSTANCE_TRANSACTION_PROTOCOL}" '
    .schema_version==1 and (if has("protocol") then .protocol else "mixed" end)==$protocol and (.owner_pid|type=="number" and floor==. and .>0) and
    (.owner_start|type=="string" and test("^[0-9]+$")) and
    (.before_active|type=="boolean") and .expected_revision==$revision and
    (.phase=="prepare" or .phase=="snapshot" or .phase=="publish" or .phase=="resources" or .phase=="service" or .phase=="committed")
  ' "${lock_dir}/transaction.json" >/dev/null 2>&1 || {
    agent_json_error instance_recovery_untrusted "事务日志无法验证或 revision 不匹配；请保留文件并人工检查。"; return 1;
  }
  owner_pid=$(jq -r .owner_pid "${lock_dir}/transaction.json") || return $?
  owner_start=$(jq -r .owner_start "${lock_dir}/transaction.json") || return $?
  if [[ -r "/proc/${owner_pid}/stat" ]]; then
    current_start=$(awk '{print $22}' "/proc/${owner_pid}/stat") || return $?
    if [[ "${current_start}" == "${owner_start}" ]]; then
      agent_json_error instance_transaction_active "原实例写进程仍在运行；禁止并发恢复。"; return 1
    fi
  fi
  # A kernel lock is released on uncatchable interruption; the durable write
  # journal itself stays in place until recovery has actually succeeded.
  command -v flock >/dev/null 2>&1 && [[ ! -L "${lock_dir}/recovery.flock" ]] || {
    agent_json_error instance_recovery_unavailable "恢复需要 flock 且锁文件必须可信。"; return 1;
  }
  exec {recovery_fd}>"${lock_dir}/recovery.flock" || return $?
  flock -n "${recovery_fd}" || {
    agent_json_error instance_recovery_active "另一个恢复进程已取得恢复锁。"; return 1;
  }
  phase=$(jq -r .phase "${lock_dir}/transaction.json") || return $?
  revision=$(jq -r '.new_revision // .expected_revision | tonumber' "${lock_dir}/transaction.json") || return $?
  firewall_summary=$(instance_transaction_firewall_summary "${lock_dir}/firewall.json")
  case "${phase}" in
    publish|resources|service)
      if ! instance_transaction_restore "${lock_dir}"; then
        firewall_summary=$(instance_transaction_firewall_summary "${lock_dir}/firewall.json")
        result=$(instance_transaction_report rollback_failed "${phase}" instance_rollback_failed false true "${expected_revision}" "${firewall_summary}") || return $?
        if result_path=$(instance_transaction_persist_result "${result}"); then
          jq --arg path "${result_path}" '.transaction.result_path=$path | .transaction.result_persisted=true' <<< "${result}"
        else
          jq '.transaction.result_path="" | .transaction.result_persisted=false |
            .transaction.audit_error="instance_audit_failed"' <<< "${result}"
        fi
        return 1
      fi
      firewall_summary=$(instance_transaction_firewall_summary "${lock_dir}/firewall.json")
      result=$(instance_transaction_report rolled_back "${phase}" '' false false "${expected_revision}" "${firewall_summary}") || return $?
      ;;
    committed) result=$(instance_transaction_report committed "${phase}" '' true false "${revision}" "${firewall_summary}") || return $? ;;
    *) result=$(instance_transaction_report unchanged "${phase}" '' false false "${expected_revision}" "${firewall_summary}") || return $? ;;
  esac
  result_path=$(instance_transaction_persist_result "${result}") || return $?
  rm -rf -- "${lock_dir}" || return $?
  jq --arg path "${result_path}" '.transaction.result_path=$path | .transaction.result_persisted=true' <<< "${result}"
)

apply_mixed_instance_change() {
  apply_plain_proxy_instance_change mixed "$@"
}

apply_plain_proxy_instance_change() (
  local instance_protocol=$1 operation=$2 expected_revision=$3 input=$4 allow_public=${5:-n}
  local SB_INSTANCE_TRANSACTION_PROTOCOL=${instance_protocol}
  local lock_dir="${SB_PROJECT_DIR}.instance-write.lock" touched=n completed=n noop=n
  local phase=prepare revision=0 before_active=false current_revision=0 schema count indexed protocol
  local owner_pid=${BASHPID:-$$} owner_start snapshot_file result_status
  local protocols=() inbound_json
  umask 077
  structured_instance_store_protocol "${instance_protocol}" >/dev/null || return 1
  [[ "${operation}" != migrate || "${instance_protocol}" == mixed ]] || return 1
  [[ ${EUID} -eq 0 ]] || { agent_json_error root_required "实例写操作必须以 root 执行。"; return 1; }
  acquire_managed_write_lock || {
    agent_json_error instance_write_busy "另一个管理进程正在执行；未修改。"; return 1;
  }
  [[ ${EUID} -eq 0 && -x "${SINGBOX_BIN_PATH}" && -f "${SINGBOX_CONFIG_FILE}" &&
     ! -L "${SB_PROJECT_DIR}" && ! -L "${SB_PROTOCOL_STATE_DIR}" ]] || {
    agent_json_error instance_precheck_failed "需要现有受管配置、可执行核心和 root 权限。"; return 1;
  }
  validate_protocol_index_for_rebuild >&2 && validate_live_inbound_inventory "${SINGBOX_CONFIG_FILE}" >&2 || {
    agent_json_error protocol_state_untrusted "现有配置或协议索引无法完整读取；未修改。"; return 1;
  }
  if ! mkdir -m 700 "${lock_dir}" 2>/dev/null; then
    agent_json_error instance_transaction_pending "已有实例写事务或未完成恢复；请先检查并使用 instance recover。"
    return 1
  fi
  instance_transaction_finish() {
    local operation_status=$1 state=success code="" manual=false cleanup_status=0 result result_path="" firewall_summary
    trap - EXIT INT TERM HUP
    if [[ "${operation_status}" != 0 ]]; then
      code=instance_apply_failed
      if [[ "${touched}" == y ]]; then
        if instance_transaction_restore "${lock_dir}"; then state=rolled_back; revision=${current_revision}; else
          state=rollback_failed; code=instance_rollback_failed; manual=true
        fi
      else
        state=unchanged
      fi
    elif [[ "${noop}" == y ]]; then
      state=not_attempted
    fi
    if [[ "${noop}" == y ]]; then
      firewall_summary='{"status":"not_attempted","backends":[],"diagnostics":[]}'
    else
      firewall_summary=$(instance_transaction_firewall_summary "${lock_dir}/firewall.json")
    fi
    result=$(instance_transaction_report "${state}" "${phase}" "${code}" \
      "$([[ "${completed}" == y ]] && printf true || printf false)" "${manual}" "${revision}" "${firewall_summary}" |
      jq --argjson status "${operation_status}" '.transaction.operation_exit_code=$status')
    if [[ "${touched}" == y ]]; then
      if result_path=$(instance_transaction_persist_result "${result}"); then :; else
        cleanup_status=1; manual=true; code=instance_audit_failed
      fi
    fi
    if [[ "${manual}" == false ]]; then
      if ! rm -rf -- "${lock_dir}"; then
        cleanup_status=1
        state=cleanup_failed; code=instance_cleanup_failed; manual=true
      fi
    fi
    [[ "${operation_status}" == 0 && "${cleanup_status}" != 0 ]] && operation_status=1
    result=$(instance_transaction_report "${state}" "${phase}" "${code}" \
      "$([[ "${completed}" == y ]] && printf true || printf false)" "${manual}" "${revision}" "${firewall_summary}" |
      jq --arg path "${result_path}" --argjson exit_code "${operation_status}" \
      '.transaction.result_path=$path | .transaction.result_persisted=($path!="") | .transaction.operation_exit_code=$exit_code')
    if [[ -n "${result_path}" ]] && ! instance_transaction_update_result "${result_path}" "${result}"; then
      operation_status=1
      result=$(jq '.ok=false | .error="instance_audit_failed" |
        .transaction.result_persisted=false | .transaction.manual_intervention_required=true |
        .transaction.operation_exit_code=1' <<< "${result}")
    fi
    printf '%s\n' "${result}"
    exit "${operation_status}"
  }
  trap 'instance_transaction_finish "$?"' EXIT
  trap 'exit 130' INT
  trap 'exit 143' TERM
  trap 'exit 129' HUP
  owner_start=$(awk '{print $22}' "/proc/${owner_pid}/stat") || return $?
  case "$(systemctl show -p ActiveState --value sing-box)" in
    active) before_active=true ;;
    inactive|failed) before_active=false ;;
    *) return 1 ;;
  esac
  jq -n --arg protocol "${instance_protocol}" --arg operation "${operation}" --arg expected "${expected_revision}" --argjson pid "${owner_pid}" --arg start "${owner_start}" \
    --argjson before "${before_active}" \
    '{schema_version:1,protocol:$protocol,operation:$operation,expected_revision:$expected,owner_pid:$pid,owner_start:$start,before_active:$before,phase:"prepare"}' \
    > "${lock_dir}/transaction.next" || return $?
  mv -f -- "${lock_dir}/transaction.next" "${lock_dir}/transaction.json" || return $?
  if plain_proxy_structured_state_active "${instance_protocol}"; then
    plain_proxy_structured_state_matches_config "${instance_protocol}" || return 1
    structured_instance_store_snapshot_json "${instance_protocol}" "$(plain_proxy_structured_store_file "${instance_protocol}")" > "${lock_dir}/before.json" || return $?
    current_revision=$(jq -r .revision "${lock_dir}/before.json") || return $?
  elif protocol_state_exists "${instance_protocol}"; then
    if [[ "${instance_protocol}" == mixed ]]; then
      [[ ! -e "$(mixed_structured_store_file)" ]] || return 1
      mixed_config_store_candidate | jq '.revision=0' > "${lock_dir}/before.json" || return $?
    elif [[ "${instance_protocol}" == anytls ]]; then
      [[ ! -e "$(plain_proxy_structured_store_file anytls)" ]] || return 1
      plain_proxy_config_store_candidate anytls | jq '.revision=0' > "${lock_dir}/before.json" || return $?
    elif [[ "${instance_protocol}" == hy2 ]]; then
      [[ ! -e "$(plain_proxy_structured_store_file hy2)" ]] || return 1
      plain_proxy_config_store_candidate hy2 | jq '.revision=0' > "${lock_dir}/before.json" || return $?
    elif [[ "${instance_protocol}" == shadowtls ]]; then
      [[ ! -e "$(plain_proxy_structured_store_file shadowtls)" ]] || return 1
      plain_proxy_config_store_candidate shadowtls "${SINGBOX_CONFIG_FILE}" | jq '.revision=0' > "${lock_dir}/before.json" || return $?
    else
      return 1
    fi
  else
    [[ "${operation}" != migrate ]] || return 1
    if [[ "${instance_protocol}" == shadowtls ]] &&
       [[ "$(config_protocol_inbound_count shadowtls "${SINGBOX_CONFIG_FILE}" 2>/dev/null || printf 0)" -gt 0 ]]; then
      [[ ! -e "$(plain_proxy_structured_store_file shadowtls)" ]] || return 1
      plain_proxy_config_store_candidate shadowtls "${SINGBOX_CONFIG_FILE}" | jq '.revision=0' > "${lock_dir}/before.json" || return $?
      current_revision=0
    elif [[ "$(config_protocol_inbound_count "${instance_protocol}" "${SINGBOX_CONFIG_FILE}" 2>/dev/null || printf 0)" == "0" ]]; then
      if [[ -e "$(plain_proxy_structured_store_file "${instance_protocol}")" ]]; then
        plain_proxy_inactive_store_snapshot "${instance_protocol}" > "${lock_dir}/before.json" || return $?
        current_revision=$(jq -r .revision "${lock_dir}/before.json") || return $?
      else
        structured_instance_store_empty_json "${instance_protocol}" > "${lock_dir}/before.json" || return $?
      fi
    else
      return 1
    fi
  fi
  [[ "${expected_revision}" == "${current_revision}" ]] || return 1
  if [[ "${operation}" == migrate ]]; then
    if plain_proxy_structured_state_active "${instance_protocol}"; then
      revision=${current_revision}; noop=y; return 0
    fi
    jq '.revision=1' "${lock_dir}/before.json" > "${lock_dir}/after.json" || return $?
  else
    if [[ "${operation}" == create || "${operation}" == replace ]]; then
      [[ -f "${input}" && ! -L "${input}" ]] || return 1
      head -c 1048577 -- "${input}" > "${lock_dir}/record.json" || return $?
      [[ "$(wc -c < "${lock_dir}/record.json")" -le 1048576 ]] || return 1
      # New non-loopback exposure requires a distinct acknowledgement. Legacy
      # migration alone retains its existing listener without changing it.
      if [[ "${allow_public}" != y ]]; then
        jq -es 'length==1 and (.[0].listen.address | .=="::1" or test("^127\\."))' "${lock_dir}/record.json" >/dev/null 2>&1 || return 1
      fi
      input="${lock_dir}/record.json"
    fi
    structured_instance_store_candidate "${instance_protocol}" "${lock_dir}/before.json" "${operation}" "${input}" \
      "${current_revision}" > "${lock_dir}/after.json" || return $?
  fi
  validate_structured_instance_store "${instance_protocol}" "${lock_dir}/after.json" || return $?
  revision=$(jq -r .revision "${lock_dir}/after.json") || return $?
  if [[ "${revision}" == "${current_revision}" ]]; then noop=y; return 0; fi
  jq --argjson revision "${revision}" '.new_revision=$revision' "${lock_dir}/transaction.json" > "${lock_dir}/transaction.next" || return $?
  mv -f "${lock_dir}/transaction.next" "${lock_dir}/transaction.json" || return $?
  plain_proxy_instance_config_candidate "${instance_protocol}" "${SINGBOX_CONFIG_FILE}" "${lock_dir}/before.json" "${lock_dir}/after.json" \
    > "${lock_dir}/config.json" || return $?
  validate_managed_component_graph "${lock_dir}/config.json" || return $?
  validate_managed_listener_resources "${lock_dir}/config.json" || return $?
  "${SINGBOX_BIN_PATH}" check -c "${lock_dir}/config.json" >&2 || return $?
  instance_firewall_prepare "${SINGBOX_CONFIG_FILE}" "${lock_dir}/config.json" "${lock_dir}/firewall.json" || return $?
  phase=snapshot
  instance_transaction_checkpoint "${lock_dir}" "${phase}" || return $?
  snapshot_file=$(create_managed_state_snapshot "${lock_dir}/snapshot") || return $?
  phase=publish
  instance_transaction_checkpoint "${lock_dir}" "${phase}" || return $?
  touched=y
  count=$(jq -r '.instances|length' "${lock_dir}/after.json") || return $?
  if [[ "${count}" == 0 ]]; then
    # Preserve the empty, revisioned store as a tombstone. Recreating Mixed
    # must not reset CAS to zero and revive an older request (ABA).
    publish_structured_instance_store "${instance_protocol}" "${lock_dir}/after.json" "${current_revision}" legacy-empty-activation || return $?
    persist_file_backup "$(protocol_state_file "${instance_protocol}")" "$(protocol_state_file "${instance_protocol}").bak" || return $?
    rm -f -- "$(protocol_state_file "${instance_protocol}")" || return $?
  else
    publish_structured_instance_store "${instance_protocol}" "${lock_dir}/after.json" "${current_revision}" || return $?
    save_plain_proxy_structured_marker "${instance_protocol}" || return $?
  fi
  # Match the live config's protocol ordering, retaining every non-Mixed role.
  # `vless` is shared by REALITY and plain VLESS, so classify each inbound
  # through the config-aware adapter instead of normalizing the raw core type.
  protocols=()
  while IFS= read -r inbound_json; do
    [[ -n "${inbound_json}" ]] || continue
    if jq -e '.type | IN("direct","tun","redirect","tproxy","cloudflared")' \
      <<< "${inbound_json}" >/dev/null 2>&1; then
      # Advanced component inbounds have their own state and do not belong in
      # the share-link protocol index.
      continue
    fi
    protocol=$(config_inbound_protocol "${inbound_json}") || return 1
    if ! protocol_array_contains "${protocol}" ${protocols[@]+"${protocols[@]}"}; then
      protocols+=("${protocol}")
    fi
  done < <(jq -c '.inbounds[]?' "${lock_dir}/config.json")
  indexed=$(IFS=,; printf '%s' "${protocols[*]-}")
  write_protocol_index "${indexed}" || return $?
  publish_managed_config_candidate "${lock_dir}/config.json" || return $?
  cmp -s -- "${lock_dir}/config.json" "${SINGBOX_CONFIG_FILE}" || return 1
  if [[ "${count}" != 0 ]]; then
    plain_proxy_structured_state_matches_config "${instance_protocol}" || return 1
  fi
  phase=resources
  instance_transaction_checkpoint "${lock_dir}" "${phase}" || return $?
  instance_firewall_apply "${lock_dir}/firewall.json" || return $?
  phase=service
  instance_transaction_checkpoint "${lock_dir}" "${phase}" || return $?
  if [[ "${before_active}" == true ]]; then
    systemctl restart sing-box >/dev/null 2>&1 || return $?
    systemctl is-active --quiet sing-box || return $?
  fi
  phase=committed
  instance_transaction_checkpoint "${lock_dir}" "${phase}" || return $?
  completed=y
  return 0
)

agent_component_cli() {
  local operation=${1:-} expected="" input="" component_id="" json=n confirmed=n allow_public=n
  local export_json export_status
  shift || true
  while [[ $# -gt 0 ]]; do
    case "$1" in
      --json) [[ "${json}" == n ]] || break; json=y; shift ;;
      --yes) [[ "${confirmed}" == n ]] || break; confirmed=y; shift ;;
      --allow-public) [[ "${allow_public}" == n ]] || break; allow_public=y; shift ;;
      --expected-revision) [[ $# -ge 2 && -z "${expected}" ]] || break; expected=$2; shift 2 ;;
      --file) [[ $# -ge 2 && -z "${input}" ]] || break; input=$2; shift 2 ;;
      --id) [[ $# -ge 2 && -z "${component_id}" ]] || break; component_id=$2; shift 2 ;;
      *) break ;;
    esac
  done

  if [[ "${operation}" == list ]]; then
    if [[ $# -ne 0 || "${json}" != y || "${confirmed}" != n || "${allow_public}" != n || -n "${expected}" || -n "${input}" || -n "${component_id}" ]]; then
      agent_json_error invalid_arguments "用法: sbv agent component list --json"; return 1
    fi
    managed_component_inventory_json
    return $?
  fi

  if [[ "${operation}" == diagnose ]]; then
    if [[ $# -ne 0 || "${json}" != y || "${confirmed}" != n || "${allow_public}" != n || -n "${expected}" || -n "${input}" || -n "${component_id}" ]]; then
      agent_json_error invalid_arguments "用法: sbv agent component diagnose --json"; return 1
    fi
    if managed_component_diagnose_json; then
      return 0
    fi
    agent_json_error component_state_untrusted "高级组件状态无法完整读取；未返回部分诊断。"
    return 1
  fi

  if [[ "${operation}" == recover ]]; then
    if [[ $# -ne 0 || "${json}" != y || "${confirmed}" != y || "${allow_public}" != n ||
          -n "${input}" || -n "${component_id}" ||
          ! "${expected}" =~ ^(0|[1-9][0-9]{0,15})$ ]]; then
      agent_json_error invalid_arguments "用法: sbv agent component recover --json --yes --expected-revision N"; return 1
    fi
    if ! structured_instance_store_revision_arg "${expected}" >/dev/null; then
      agent_json_error invalid_arguments "revision 超出安全整数范围；未修改。"; return 1
    fi
    managed_component_recover_transaction "${expected}"
    return $?
  fi

  if [[ "${operation}" == export ]]; then
    if [[ $# -ne 0 || "${json}" != y || "${confirmed}" != n || "${allow_public}" != n ||
          -z "${component_id}" || -n "${input}" ||
          ( -n "${expected}" && ! "${expected}" =~ ^(0|[1-9][0-9]{0,15})$ ) ]]; then
      agent_json_error invalid_arguments "用法: sbv agent component export --json --id ID [--expected-revision N]"; return 1
    fi
    if [[ -n "${expected}" ]] && ! structured_instance_store_revision_arg "${expected}" >/dev/null; then
      agent_json_error invalid_arguments "revision 超出安全整数范围；未修改。"; return 1
    fi
    if export_json=$(managed_component_export_json "${component_id}" "${expected}"); then
      printf '%s\n' "${export_json}"
      return 0
    else
      export_status=$?
    fi
    case "${export_status}" in
      2) agent_json_error revision_mismatch "组件 state revision 不匹配；未返回导出。" ;;
      3) agent_json_error component_not_found "组件不存在；未返回导出。" ;;
      *) agent_json_error component_export_failed "组件状态无法安全读取；未返回导出。" ;;
    esac
    return 1
  fi

  if [[ "${operation}" == takeover ]]; then
    if [[ $# -ne 0 || "${json}" != y || "${confirmed}" != y ||
          -n "${input}" || -n "${component_id}" ||
          ! "${expected}" =~ ^(0|[1-9][0-9]{0,15})$ ]]; then
      agent_json_error invalid_arguments "用法: sbv agent component takeover --json --yes --expected-revision N [--allow-public]"; return 1
    fi
    if ! structured_instance_store_revision_arg "${expected}" >/dev/null; then
      agent_json_error invalid_arguments "revision 超出安全整数范围；未修改。"; return 1
    fi
    if managed_component_state_apply takeover "${expected}" "" "" "${allow_public}"; then
      printf '%s\n' "${MANAGED_COMPONENT_LAST_RESULT}"
      return 0
    fi
    case "${MANAGED_COMPONENT_LAST_ERROR:-component_takeover_failed}" in
      revision_mismatch) agent_json_error revision_mismatch "组件 state revision 不匹配；未修改。" ;;
      instance_transaction_pending) agent_json_error instance_transaction_pending "存在未完成的实例事务；请先完成 instance recover。" ;;
      component_write_busy) agent_json_error component_write_busy "另一个管理进程正在执行；组件未修改。" ;;
      component_transaction_pending) agent_json_error component_transaction_pending "存在未完成的高级组件事务；请先执行 component recover。" ;;
      component_transaction_begin_failed|component_transaction_write_failed) agent_json_error component_transaction_failed "高级组件持久事务日志写入失败；未报告成功。" ;;
      component_cleanup_failed) agent_json_error component_cleanup_failed "组件已提交，但持久事务目录清理失败；请执行 component recover。" ;;
      public_confirmation_required) agent_json_error confirmation_required "现有接管对象包含公开监听或 OpenVPN server；请明确传入 --allow-public。" ;;
      component_live_missing) agent_json_error component_live_missing "当前配置没有可接管的已注册高级入站或 Endpoint。" ;;
      component_live_untrusted) agent_json_error component_live_untrusted "当前配置对象或组件状态无法安全读取；未修改。" ;;
      component_takeover_conflict) agent_json_error component_takeover_conflict "接管对象与现有组件 ID/tag 冲突；未修改。" ;;
      config_check_failed) agent_json_error config_check_failed "组件接管已回滚；候选配置或无损保留校验失败。" ;;
      service_restart_failed) agent_json_error service_restart_failed "组件接管已回滚；服务重启失败。" ;;
      transparent_resource_check_failed) agent_json_error transparent_resource_check_failed "组件接管已回滚；core-owned 透明资源未就绪。" ;;
      firewall_prepare_failed) agent_json_error firewall_prepare_failed "组件接管已回滚；防火墙资源预检失败。" ;;
      firewall_apply_failed) agent_json_error firewall_apply_failed "组件接管已回滚；防火墙资源应用失败。" ;;
      firewall_commit_failed) agent_json_error firewall_commit_failed "组件接管已回滚；防火墙资源提交失败。" ;;
      firewall_rollback_failed) agent_json_error firewall_rollback_failed "防火墙外部资源回滚不确定；已保留事务快照供恢复。" ;;
      *) agent_json_error component_takeover_failed "组件接管失败，状态已回滚或保留快照待恢复。" ;;
    esac
    return 1
  fi

  if [[ "${operation}" == rebuild ]]; then
    if [[ $# -ne 0 || "${json}" != y || "${confirmed}" != y || "${allow_public}" != n ||
          -n "${input}" || -n "${component_id}" || ! "${expected}" =~ ^(0|[1-9][0-9]{0,15})$ ]]; then
      agent_json_error invalid_arguments "用法: sbv agent component rebuild --json --yes --expected-revision N"; return 1
    fi
    if ! structured_instance_store_revision_arg "${expected}" >/dev/null; then
      agent_json_error invalid_arguments "revision 超出安全整数范围；未修改。"; return 1
    fi
    if managed_component_state_apply rebuild "${expected}" "" "" n; then
      printf '%s\n' "${MANAGED_COMPONENT_LAST_RESULT}"
      return 0
    fi
    case "${MANAGED_COMPONENT_LAST_ERROR:-component_apply_failed}" in
      revision_mismatch) agent_json_error revision_mismatch "组件 state revision 不匹配；未修改。" ;;
      instance_transaction_pending) agent_json_error instance_transaction_pending "存在未完成的实例事务；请先完成 instance recover。" ;;
      component_write_busy) agent_json_error component_write_busy "另一个管理进程正在执行；组件未修改。" ;;
      component_transaction_pending) agent_json_error component_transaction_pending "存在未完成的高级组件事务；请先执行 component recover。" ;;
      component_transaction_begin_failed|component_transaction_write_failed) agent_json_error component_transaction_failed "高级组件持久事务日志写入失败；未报告成功。" ;;
      component_cleanup_failed) agent_json_error component_cleanup_failed "组件已提交，但持久事务目录清理失败；请执行 component recover。" ;;
      config_check_failed) agent_json_error config_check_failed "组件重建已回滚；生成的配置未通过图校验、监听校验或 sing-box check。" ;;
      service_restart_failed) agent_json_error service_restart_failed "组件重建已回滚；服务重启失败。" ;;
      transparent_resource_check_failed) agent_json_error transparent_resource_check_failed "组件重建已回滚；core-owned 透明资源未就绪。" ;;
      firewall_prepare_failed) agent_json_error firewall_prepare_failed "组件重建已回滚；防火墙资源预检失败。" ;;
      firewall_apply_failed) agent_json_error firewall_apply_failed "组件重建已回滚；防火墙资源应用失败。" ;;
      firewall_commit_failed) agent_json_error firewall_commit_failed "组件重建已回滚；防火墙资源提交失败。" ;;
      firewall_rollback_failed) agent_json_error firewall_rollback_failed "防火墙外部资源回滚不确定；已保留事务快照供恢复。" ;;
      *) agent_json_error component_apply_failed "组件重建失败，状态已回滚或保留快照待恢复。" ;;
    esac
    return 1
  fi

  if [[ "${operation}" != create && "${operation}" != replace && "${operation}" != delete ||
        $# -ne 0 || "${json}" != y || "${confirmed}" != y ||
        ! "${expected}" =~ ^(0|[1-9][0-9]{0,15})$ ]]; then
    agent_json_error invalid_arguments "组件参数无效；需要 create/replace/delete、--json、--yes 和 --expected-revision N。"
    return 1
  fi
  if ! structured_instance_store_revision_arg "${expected}" >/dev/null; then
    agent_json_error invalid_arguments "revision 超出安全整数范围；未修改。"
    return 1
  fi
  case "${operation}" in
    create|replace)
      if [[ -z "${input}" || -n "${component_id}" ]]; then
        agent_json_error invalid_arguments "create/replace 需要 --file，且不接受 --id。"; return 1
      fi
      ;;
    delete)
      if [[ -n "${input}" || -z "${component_id}" || "${allow_public}" != n ]]; then
        agent_json_error invalid_arguments "delete 需要 --id，且不接受 --file/--allow-public。"; return 1
      fi
      ;;
  esac
  if managed_component_state_apply "${operation}" "${expected}" "${input}" "${component_id}" "${allow_public}"; then
    printf '%s\n' "${MANAGED_COMPONENT_LAST_RESULT}"
    return 0
  fi
  case "${MANAGED_COMPONENT_LAST_ERROR:-component_apply_failed}" in
    revision_mismatch) agent_json_error revision_mismatch "组件 state revision 不匹配；未修改。" ;;
    instance_transaction_pending) agent_json_error instance_transaction_pending "存在未完成的实例事务；请先完成 instance recover。" ;;
    public_confirmation_required) agent_json_error confirmation_required "公开监听或隧道组件需要 --allow-public；未修改。" ;;
    component_referenced_or_missing) agent_json_error component_referenced "组件仍被 route/group/detour 引用，或目标不存在；未修改。" ;;
    record_invalid|component_conflict) agent_json_error invalid_component "组件记录无效、类型不受支持或 tag/id 冲突；未修改。" ;;
    service_restart_failed) agent_json_error service_restart_failed "组件已回滚；服务重启失败。" ;;
    transparent_resource_check_failed) agent_json_error transparent_resource_check_failed "组件已回滚；core-owned 透明资源未就绪。" ;;
    config_check_failed) agent_json_error config_check_failed "组件已回滚；生成的配置未通过图校验或 sing-box check。" ;;
    root_required) agent_json_error root_required "组件写操作必须以 root 执行；未修改。" ;;
    component_write_busy) agent_json_error component_write_busy "另一个管理进程正在执行；组件未修改。" ;;
    component_transaction_pending) agent_json_error component_transaction_pending "存在未完成的高级组件事务；请先执行 component recover。" ;;
    component_transaction_begin_failed|component_transaction_write_failed) agent_json_error component_transaction_failed "高级组件持久事务日志写入失败；未报告成功。" ;;
    component_cleanup_failed) agent_json_error component_cleanup_failed "组件已提交，但持久事务目录清理失败；请执行 component recover。" ;;
    firewall_prepare_failed) agent_json_error firewall_prepare_failed "组件已回滚；防火墙资源预检失败，未执行外部变更。" ;;
    firewall_apply_failed) agent_json_error firewall_apply_failed "组件已回滚；防火墙资源应用失败。" ;;
    firewall_commit_failed) agent_json_error firewall_commit_failed "组件已回滚；防火墙资源提交失败。" ;;
    firewall_rollback_failed) agent_json_error firewall_rollback_failed "防火墙外部资源回滚不确定；已保留事务快照供恢复。" ;;
    *) agent_json_error component_apply_failed "组件事务失败，状态已回滚或保留快照待恢复。" ;;
  esac
  return 1
}

agent_instance_cli() {
  local operation=${1:-} protocol=${2:-} expected="" input="" instance_id="" json=n confirmed=n allow_public=n
  [[ $# -ge 2 ]] || { agent_json_error invalid_arguments "用法: instance 操作 mixed|socks|http|shadowsocks|trojan|vmess|vless-plain|anytls|hy2|snell|tuic|hysteria|naive|shadowtls --json --yes --expected-revision N [--file 文件 | --id ID]"; return 1; }
  shift 2
  protocol=$(normalize_protocol_id "${protocol}") || {
    agent_json_error invalid_arguments "实例协议无效；未修改。"; return 1;
  }
  while [[ $# -gt 0 ]]; do
    case "$1" in
      --json) [[ "${json}" == n ]] || break; json=y; shift ;;
      --yes) [[ "${confirmed}" == n ]] || break; confirmed=y; shift ;;
      --allow-public) [[ "${allow_public}" == n ]] || break; allow_public=y; shift ;;
      --expected-revision) [[ $# -ge 2 && -z "${expected}" ]] || break; expected=$2; shift 2 ;;
      --file) [[ $# -ge 2 && -z "${input}" ]] || break; input=$2; shift 2 ;;
      --id) [[ $# -ge 2 && -z "${instance_id}" ]] || break; instance_id=$2; shift 2 ;;
      *) break ;;
    esac
  done
  if [[ $# -ne 0 || "${json}" != y || ("${protocol}" != mixed && "${protocol}" != socks && "${protocol}" != http && "${protocol}" != shadowsocks && "${protocol}" != trojan && "${protocol}" != vmess && "${protocol}" != vless-plain && "${protocol}" != anytls && "${protocol}" != hy2 && "${protocol}" != snell && "${protocol}" != tuic && "${protocol}" != hysteria && "${protocol}" != naive && "${protocol}" != shadowtls) || ! "${expected}" =~ ^(0|[1-9][0-9]{0,15})$ ]]; then
    agent_json_error invalid_arguments "实例参数、协议或 revision 无效；未修改。"; return 1
  fi
  if ! structured_instance_store_revision_arg "${expected}" >/dev/null; then
    agent_json_error invalid_arguments "revision 超出安全整数范围；未修改。"; return 1
  fi
  if [[ "${operation}" == migrate && "${protocol}" != mixed ]]; then
    agent_json_error invalid_arguments "只有 Mixed 提供 legacy schema 1 迁移；SOCKS/HTTP/Shadowsocks/Trojan/VMess/VLESS/AnyTLS/Hysteria2/Snell/TUIC/Hysteria/NaiveProxy/ShadowTLS 使用 schema 2，已有 live 配置请使用接管入口。"
    return 1
  fi
  [[ "${confirmed}" == y ]] || { agent_json_error confirmation_required "实例写操作需要 --yes；非回环入口另需 --allow-public。"; return 1; }
  case "${operation}" in
    create|replace) [[ -n "${input}" && -z "${instance_id}" ]] || { agent_json_error invalid_arguments "create/replace 需要 --file 类型化实例记录。"; return 1; } ;;
    delete|default) [[ -z "${input}" && -n "${instance_id}" && "${allow_public}" == n ]] || { agent_json_error invalid_arguments "delete/default 需要 --id。"; return 1; }; input=${instance_id} ;;
    migrate|recover) [[ -z "${input}${instance_id}" && "${allow_public}" == n ]] || { agent_json_error invalid_arguments "migrate/recover 不接收实例参数。"; return 1; } ;;
    *) agent_json_error invalid_arguments "未知实例操作。"; return 1 ;;
  esac
  if [[ "${operation}" == recover ]]; then
    recover_plain_proxy_instance_transaction "${protocol}" "${expected}"
  else
    apply_plain_proxy_instance_change "${protocol}" "${operation}" "${expected}" "${input}" "${allow_public}"
  fi
}

agent_cli() {
  local command=${1:-help}
  shift || true
  local service_command

  case "${command}" in
    help|-h|--help)
      if [[ $# -ne 0 ]]; then
        agent_cli_error "help" "invalid_arguments" "用法: sbv agent help"
        return $?
      fi
      agent_print_help
      ;;
    capabilities)
      if [[ $# -ne 1 || "${1:-}" != "--json" ]]; then
        agent_cli_error "capabilities" "invalid_arguments" "用法: sbv agent capabilities --json"
        return $?
      fi
      agent_cli_run "capabilities" agent_capabilities_json
      ;;
    instance)
      agent_cli_run "instance" agent_instance_cli "$@"
      ;;
    component)
      agent_cli_run "component" agent_component_cli "$@"
      ;;
    upgrade-check)
      if [[ $# -ne 2 || "${1:-}" != "--json" ]]; then
        agent_cli_error "upgrade-check" "invalid_arguments" "用法: sbv agent upgrade-check --json x.y.z"
        return $?
      fi
      agent_cli_run "upgrade-check" agent_upgrade_check_json "${2}"
      ;;
    upgrade)
      if [[ $# -lt 2 || $# -gt 3 || "${1:-}" != "--json" ]]; then
        agent_cli_error "upgrade" "invalid_arguments" "用法: sbv agent upgrade --json x.y.z --yes"
        return $?
      fi
      agent_cli_run "upgrade" agent_upgrade_cli "$@"
      ;;
    status)
      if [[ $# -ne 1 || "${1:-}" != "--json" ]]; then
        agent_cli_error "status" "invalid_arguments" "用法: sbv agent status --json"
        return $?
      fi
      agent_cli_run "status" agent_status_json
      ;;
    nodes)
      if [[ $# -ne 1 || "${1:-}" != "--json" ]]; then
        agent_cli_error "nodes" "invalid_arguments" "用法: sbv agent nodes --json"
        return $?
      fi
      agent_cli_run "nodes" agent_collect_nodes_json "summary"
      ;;
    links)
      if [[ $# -ne 1 || "${1:-}" != "--json" ]]; then
        agent_cli_error "links" "invalid_arguments" "用法: sbv agent links --json"
        return $?
      fi
      agent_cli_run "links" agent_collect_nodes_json "links"
      ;;
    export-client)
      if [[ $# -ne 1 || "${1:-}" != "--json" ]]; then
        agent_cli_error "export-client" "invalid_arguments" "用法: sbv agent export-client --json"
        return $?
      fi
      agent_cli_run "export-client" agent_export_client_json
      ;;
    warp)
      if [[ $# -ne 1 || "${1:-}" != "--json" ]]; then
        agent_cli_error "warp" "invalid_arguments" "用法: sbv agent warp --json"
        return $?
      fi
      agent_cli_run "warp" agent_warp_json
      ;;
    check)
      if [[ $# -ne 1 || "${1:-}" != "--json" ]]; then
        agent_cli_error "check" "invalid_arguments" "用法: sbv agent check --json"
        return $?
      fi
      agent_cli_run "check" agent_singbox_check_json
      ;;
    doctor)
      if [[ $# -ne 1 || "${1:-}" != "--json" ]]; then
        agent_cli_error "doctor" "invalid_arguments" "用法: sbv agent doctor --json"
        return $?
      fi
      agent_cli_run "doctor" agent_doctor_json
      ;;
    service)
      service_command=${1:-service}
      if [[ $# -lt 1 || $# -gt 3 ]]; then
        agent_cli_error "service ${service_command}" "invalid_arguments" "用法: sbv agent service restart --json --yes"
        return $?
      fi
      agent_cli_run "service ${service_command}" agent_service_cli "$@"
      ;;
    subman-sync)
      if [[ $# -ne 1 || "${1:-}" != "--json" ]]; then
        agent_cli_error "subman-sync" "invalid_arguments" "用法: sbv agent subman-sync --json"
        return $?
      fi
      agent_cli_run "subman-sync" agent_subman_sync_json
      ;;
    *)
      agent_cli_error "${command}" "unknown_command" "未知 agent 子命令: ${command}"
      return $?
      ;;
  esac
}

agent_command_name_from_args() {
  local command=${1:-help}

  if [[ "${command}" == "service" && -n "${2:-}" ]]; then
    printf 'service %s' "${2}"
  else
    printf '%s' "${command}"
  fi
}

agent_current_user_is_root() {
  [[ ${EUID} -eq 0 ]]
}

agent_dispatch() {
  local command

  case "${1:-help}" in
    help|-h|--help)
      agent_cli "$@"
      return $?
      ;;
  esac

  command=$(agent_command_name_from_args "$@")
  if ! agent_current_user_is_root; then
    agent_cli_error "${command}" "root_required" "Agent 命令必须以 root 用户执行。"
    return $?
  fi

  case "${1:-}" in
    instance) agent_cli "$@" ;;
    component)
      case "${2:-}" in
        diagnose) (
          if ! acquire_managed_write_lock shared; then
            agent_cli_error "component" instance_write_busy "配置正在被管理进程使用，未返回部分组件状态。"; return 1
          fi
          if [[ -e "${SB_PROJECT_DIR}.instance-write.lock" ]]; then
            agent_cli_error "component" instance_transaction_pending "存在未完成的实例事务；请先检查并恢复。"; return 1
          fi
          agent_cli "$@"
        ) ;;
        list|export) (
          if ! acquire_managed_write_lock shared; then
            agent_cli_error "component" instance_write_busy "配置正在被管理进程使用，未返回部分组件状态。"; return 1
          fi
          if [[ -e "${SB_PROJECT_DIR}.instance-write.lock" ]]; then
            agent_cli_error "component" instance_transaction_pending "存在未完成的实例事务；请先检查并恢复。"; return 1
          fi
          if [[ -e "${SB_COMPONENT_TRANSACTION_DIR}" ]]; then
            agent_cli_error "component" component_transaction_pending "存在未完成的高级组件事务；请先执行 component recover。"; return 1
          fi
          agent_cli "$@"
        ) ;;
        recover) (
          if ! acquire_managed_write_lock; then
            agent_cli_error "component" instance_write_busy "另一个管理进程正在执行；未开始组件恢复。"; return 1
          fi
          if [[ -e "${SB_PROJECT_DIR}.instance-write.lock" ]]; then
            agent_cli_error "component" instance_transaction_pending "请先完成 instance recover；未开始组件恢复。"; return 1
          fi
          agent_cli "$@"
        ) ;;
        *) (
          if ! acquire_managed_write_lock; then
            agent_cli_error "component" instance_write_busy "另一个管理进程正在执行。"; return 1
          fi
          if [[ -e "${SB_PROJECT_DIR}.instance-write.lock" ]]; then
            agent_cli_error "component" instance_transaction_pending "请先完成 instance recover；未开始其他写操作。"; return 1
          fi
          if [[ -e "${SB_COMPONENT_TRANSACTION_DIR}" ]]; then
            agent_cli_error "component" component_transaction_pending "请先完成 component recover；未开始其他写操作。"; return 1
          fi
          agent_cli "$@"
        ) ;;
      esac
      ;;
    status|nodes|links|check|doctor|warp|upgrade-check)
      (
        if ! acquire_managed_write_lock shared; then
          agent_cli_error "${command}" instance_write_busy "配置正在被管理进程使用，未返回部分状态。"; return 1
        fi
        if [[ -e "${SB_PROJECT_DIR}.instance-write.lock" ]]; then
          agent_cli_error "${command}" instance_transaction_pending "存在未完成的实例事务；请先检查并恢复。"; return 1
        fi
        agent_cli "$@"
      )
      ;;
    upgrade|service|export-client|subman-sync)
      (
        if ! acquire_managed_write_lock; then
          agent_cli_error "${command}" instance_write_busy "另一个管理进程正在执行。"; return 1
        fi
        if [[ -e "${SB_PROJECT_DIR}.instance-write.lock" ]]; then
          agent_cli_error "${command}" instance_transaction_pending "请先完成 instance recover；未开始其他写操作。"; return 1
        fi
        agent_cli "$@"
      )
      ;;
    *) agent_cli "$@" ;;
  esac
}

push_nodes_to_subman() {
  local original_protocol_state protocol instance_id
  local address_entry address_label public_ip
  local instance_attempted instance_synced instance_stacked_synced
  local synced_count skipped_count failed_count shadowsocks_skipped_count trojan_skipped_count vmess_skipped_count vless_plain_skipped_count hy2_skipped_count trojan_status
  local installed_protocols=()

  prompt_subman_config_if_needed
  original_protocol_state=$(runtime_protocol_to_state "${SB_PROTOCOL}" 2>/dev/null || true)
  synced_count=0
  skipped_count=0
  failed_count=0
  shadowsocks_skipped_count=0
  trojan_skipped_count=0
  vmess_skipped_count=0
  vless_plain_skipped_count=0
  hy2_skipped_count=0

  mapfile -t installed_protocols < <(list_installed_protocols)
  if [[ ${#installed_protocols[@]} -eq 0 ]]; then
    print_warn "未发现已安装协议，无法推送 SubMan 节点。"
    printf 'SubMan 推送完成：已同步: 0，已跳过: 0，失败: 0\n'
    return 1
  fi

  for protocol in "${installed_protocols[@]}"; do
    protocol=$(normalize_protocol_id "${protocol}" 2>/dev/null || true)
    if [[ -z "${protocol}" ]]; then
      skipped_count=$((skipped_count + 1))
      continue
    fi

    if ! subman_type_for_protocol "${protocol}" >/dev/null; then
      print_warn "SubMan 暂不支持协议，已跳过: ${protocol}"
      skipped_count=$((skipped_count + 1))
      continue
    fi

    if ! protocol_state_exists "${protocol}"; then
      print_warn "协议状态文件缺失，已跳过 SubMan 推送: ${protocol}"
      skipped_count=$((skipped_count + 1))
      continue
    fi

    if ! load_protocol_state "${protocol}"; then
      print_warn "加载协议状态失败，已跳过 SubMan 推送: ${protocol}"
      failed_count=$((failed_count + 1))
      continue
    fi

    if [[ "${protocol}" == "hy2" ]]; then
      print_hy2_compatibility_warnings "share"
    fi

    if [[ "${protocol}" == "vless-reality" ]]; then
      while IFS= read -r instance_id; do
        [[ -z "${instance_id}" ]] && continue
        instance_attempted=0
        instance_synced=0
        instance_stacked_synced=0
        while IFS= read -r address_entry; do
          [[ -z "${address_entry}" ]] && continue
          address_label=${address_entry%%|*}
          public_ip=${address_entry#*|}
          instance_attempted=$((instance_attempted + 1))
          if push_subman_protocol_instance "${protocol}" "${public_ip}" "${instance_id}" "n" "${address_label}"; then
            synced_count=$((synced_count + 1))
            instance_synced=$((instance_synced + 1))
            if [[ -n "$(network_stack_suffix_from_label "${address_label}")" ]]; then
              instance_stacked_synced=$((instance_stacked_synced + 1))
            fi
          else
            failed_count=$((failed_count + 1))
          fi
        done < <(list_subman_addresses_for_current_protocol)
        if subman_instance_ready_for_legacy_cleanup "${instance_attempted}" "${instance_synced}" "${instance_stacked_synced}" && \
          push_subman_legacy_protocol_key_cleanup "${protocol}" "${instance_id}" "n"; then
          :
        elif subman_instance_ready_for_legacy_cleanup "${instance_attempted}" "${instance_synced}" "${instance_stacked_synced}"; then
          failed_count=$((failed_count + 1))
        fi
      done < <(list_vless_reality_instance_ids)
      continue
    fi

    if [[ "${protocol}" == "trojan" ]]; then
      trojan_status=0
      push_subman_trojan_protocol n || trojan_status=$?
      synced_count=$((synced_count + ${SUBMAN_TROJAN_SYNCED:-0}))
      skipped_count=$((skipped_count + ${SUBMAN_TROJAN_SKIPPED:-0}))
      trojan_skipped_count=$((trojan_skipped_count + ${SUBMAN_TROJAN_SKIPPED:-0}))
      failed_count=$((failed_count + ${SUBMAN_TROJAN_FAILED:-0}))
      if (( trojan_status != 0 && ${SUBMAN_TROJAN_FAILED:-0} == 0 )); then
        failed_count=$((failed_count + 1))
      fi
      continue
    fi

    if [[ "${protocol}" == "vmess" ]]; then
      push_subman_vmess_protocol n || true
      synced_count=$((synced_count + ${SUBMAN_VMESS_SYNCED:-0}))
      skipped_count=$((skipped_count + ${SUBMAN_VMESS_SKIPPED:-0}))
      vmess_skipped_count=$((vmess_skipped_count + ${SUBMAN_VMESS_SKIPPED:-0}))
      failed_count=$((failed_count + ${SUBMAN_VMESS_FAILED:-0}))
      continue
    fi

    if [[ "${protocol}" == "vless-plain" ]]; then
      push_subman_vless_plain_protocol n || true
      synced_count=$((synced_count + ${SUBMAN_VLESS_PLAIN_SYNCED:-0}))
      skipped_count=$((skipped_count + ${SUBMAN_VLESS_PLAIN_SKIPPED:-0}))
      vless_plain_skipped_count=$((vless_plain_skipped_count + ${SUBMAN_VLESS_PLAIN_SKIPPED:-0}))
      failed_count=$((failed_count + ${SUBMAN_VLESS_PLAIN_FAILED:-0}))
      continue
    fi

    if [[ "${protocol}" == "hy2" ]] && [[ "${CONFIG_SCHEMA_VERSION:-1}" == 2 ]] && plain_proxy_structured_state_active hy2; then
      push_subman_hy2_protocol n || true
      synced_count=$((synced_count + ${SUBMAN_HY2_SYNCED:-0}))
      skipped_count=$((skipped_count + ${SUBMAN_HY2_SKIPPED:-0}))
      hy2_skipped_count=$((hy2_skipped_count + ${SUBMAN_HY2_SKIPPED:-0}))
      failed_count=$((failed_count + ${SUBMAN_HY2_FAILED:-0}))
      continue
    fi

    if [[ "${protocol}" == "shadowsocks" ]]; then
      push_subman_shadowsocks_protocol n || true
      synced_count=$((synced_count + ${SUBMAN_SHADOWSOCKS_SYNCED:-0}))
      skipped_count=$((skipped_count + ${SUBMAN_SHADOWSOCKS_SKIPPED:-0}))
      shadowsocks_skipped_count=$((shadowsocks_skipped_count + ${SUBMAN_SHADOWSOCKS_SKIPPED:-0}))
      failed_count=$((failed_count + ${SUBMAN_SHADOWSOCKS_FAILED:-0}))
      continue
    fi

    while IFS= read -r address_entry; do
      [[ -z "${address_entry}" ]] && continue
      address_label=${address_entry%%|*}
      public_ip=${address_entry#*|}
      if push_subman_protocol_instance "${protocol}" "${public_ip}" "" "n" "${address_label}"; then
        synced_count=$((synced_count + 1))
      else
        failed_count=$((failed_count + 1))
      fi
    done < <(list_subman_addresses_for_current_protocol)
  done

  if [[ -n "${original_protocol_state}" ]] && protocol_state_exists "${original_protocol_state}"; then
    load_protocol_state "${original_protocol_state}"
  fi

  if (( synced_count == 0 && shadowsocks_skipped_count == 0 && trojan_skipped_count == 0 && vmess_skipped_count == 0 && vless_plain_skipped_count == 0 && hy2_skipped_count == 0 && failed_count == 0 )); then
    log_warn "未获取到公网 IP，无法生成 SubMan 节点链接。"
    return 1
  fi

  printf 'SubMan 推送完成：已同步: %s，已跳过: %s，失败: %s\n' "${synced_count}" "${skipped_count}" "${failed_count}"

  if (( synced_count == 0 || failed_count > 0 )); then
    return 1
  fi
}

show_node_info_action_menu() {
  while true; do
    echo
    render_left_aligned_page_header "节点与订阅" "选择要执行的节点信息操作"
    render_menu_group_start "操作选项"
    render_menu_item "1" "查看连接链接 / 二维码"
    render_menu_item "2" "导出 sing-box 裸核客户端配置"
    render_menu_item "3" "推送节点到 SubMan"
    echo "0. 返回"
    node_info_choice=$(prompt_choice "请选择 [0-3]: " 0 3 "")

    case "${node_info_choice}" in
      1) show_connection_info_menu ;;
      2) export_singbox_client_config || true ;;
      3) push_nodes_to_subman || true ;;
      0) return ;;
      *) log_warn "无效选项，请重新选择。" ;;
    esac
  done
}

view_node_info() {
  log_info "正在从配置文件中读取节点信息..."
  load_current_config_state
  show_node_info_action_menu
}

prompt_singbox_version() {
  local input_version normalized_version

  while true; do
    read -rp "版本 (默认 ${SB_SUPPORT_MAX_VERSION}，可输入 latest 或 x.y.z): " input_version
    if normalized_version=$(normalize_singbox_version_input "${input_version}"); then
      SB_VERSION="${normalized_version}"
      return 0
    fi
    log_warn "无效版本号: ${input_version}。请输入 latest、${SB_SUPPORT_MAX_VERSION} 或完整版本号，例如 ${SB_SUPPORT_MAX_VERSION}。"
  done
}

validate_live_inbound_inventory() {
  local config_file=$1 state_file=${2:-} registry advanced_types component_state inventory_status allow_structured_hy2=false

  [[ -e "${config_file}" || -L "${config_file}" ]] || return 0
  registry=$(protocol_registry_json) || return 1
  advanced_types=$(component_registry_inbound_types_json) || return 1
  if plain_proxy_structured_state_active hy2 >/dev/null 2>&1; then
    allow_structured_hy2=true
  fi
  # This is an inventory gate, not a full field/route round-trip validator.
  # Accept only real core type names here; CLI aliases (especially vless)
  # cannot prove that a live inbound uses the corresponding managed preset.
  if ! inventory_status=$(jq -rs --argjson registry "${registry}" --argjson advanced_types "${advanced_types}" --argjson allow_structured_hy2 "${allow_structured_hy2}" '
    if length != 1 or (.[0] | type) != "object" then "invalid_document"
    else .[0] |
      if has("inbounds") and (.inbounds | type) != "array" then "invalid_inbounds"
      else (.inbounds // []) as $inbounds |
        if any($inbounds[]; type != "object" or (.type | type) != "string") then "invalid_inbounds"
        elif any($inbounds[]; has("tag") and (.tag | type) != "string") then "invalid_inbound_tag"
        else [
          $inbounds[] as $inbound |
          {inbound: $inbound, adapters:
            (if ($advanced_types | index($inbound.type)) != null then
               [{state_id:("advanced-" + $inbound.type), managed:true}]
             else
               [$registry[] |
                select(.role == "inbound" and .type == $inbound.type and
                  (if .type == "vless" then
                    ((.preset == "reality") == ($inbound.tls.reality? != null))
                  else true end))]
             end)}
        ] as $items |
          if any($items[]; (.adapters | length) == 0) then "unsupported_inbound_type"
          elif any($items[]; (.adapters | length) != 1) then "ambiguous_inbound_type"
          elif any($items[]; .adapters[0].preset == "reality" and
            ((.inbound.tls | type) != "object" or .inbound.tls.enabled != true or
             (.inbound.tls.reality | type) != "object" or .inbound.tls.reality.enabled != true))
            then "unsupported_inbound_preset"
          elif any($items | group_by(.adapters[0].state_id)[];
            length > 1 and .[0].adapters[0].managed != true and (
              (.[0].adapters[0].state_id == "hy2" and ($allow_structured_hy2 | not)) or
              (.[0].adapters[0].state_id != "hy2" and .[0].adapters[0].multi_instance != true)
            ))
            then "unsupported_inbound_multiplicity"
          elif ([$inbounds[].tag // empty | select(length > 0)] | length) !=
               ([$inbounds[].tag // empty | select(length > 0)] | unique | length)
            then "duplicate_inbound_tag"
          else "ok" end
        end
      end
    end
  ' "${config_file}" 2>/dev/null); then
    inventory_status="invalid_json_or_inventory"
  fi
  if [[ "${inventory_status}" != "ok" ]]; then
    printf '[ERROR] live_inbound_inventory: %s; 已保留配置和状态，禁止有损重建；请使用支持该入站的脚本或先备份并人工迁移。\n' "${inventory_status}" >&2
    return 1
  fi
  if ! managed_component_state_matches_live_config "${config_file}" "${state_file}"; then
    # Preserve the long-standing inventory error for an advanced inbound that
    # is present in the live config but has no owned component record. This
    # keeps takeover/rebuild fail-closed while distinguishing endpoint-only
    # ownership drift as a component-state error.
    if [[ -n "${state_file}" ]]; then
      if [[ -f "${state_file}" && ! -L "${state_file}" && -r "${state_file}" ]]; then
        component_state=$(jq -cS '.' "${state_file}" 2>/dev/null || printf '{}')
      elif [[ ! -e "${state_file}" ]]; then
        component_state=$(managed_component_state_default_json 2>/dev/null || printf '{}')
      else
        component_state='{}'
      fi
    else
      component_state=$(managed_component_state_json 2>/dev/null || printf '{}')
    fi
    if jq -e --argjson advanced_types "${advanced_types}" --argjson state "${component_state}" '
      any(.inbounds[]?; . as $inbound |
        ($advanced_types | index($inbound.type)) != null and
        (any($state.components[]?;
          .role == "inbound" and .type == $inbound.type and
          .tag == ($inbound.tag // "") and .enabled == true) | not))
    ' "${config_file}" >/dev/null 2>&1; then
      printf '[ERROR] live_inbound_inventory: unsupported_inbound_type; 已保留配置和状态，禁止有损重建；请使用支持该入站的脚本或先备份并人工迁移。\n' >&2
    else
      printf '[ERROR] live_component_inventory: advanced component state/config mismatch; 已保留配置和状态，禁止有损重建。\n' >&2
    fi
    return 1
  fi
  if ! jq -e '
    (.inbounds // []) as $inbounds |
    ([$inbounds[] | select(.type == "shadowtls")]) as $outers |
    ([$inbounds[] | select(.type == "mixed" and ((.tag // "") | startswith("shadowtls-inner-")))]) as $inners |
    (all($inners[]; . as $inner | ([ $outers[] | select(.detour == $inner.tag) ] | length) == 1)) and
    (all($outers[]; . as $outer | ($outer.detour | type == "string") and ([ $inners[] | select(.tag == $outer.detour) ] | length) == 1)) and
    (all($inbounds[]; (((.tag // "") | startswith("shadowtls-inner-")) | not) or (.type == "mixed")))
  ' "${config_file}" >/dev/null 2>&1; then
    printf '[ERROR] live_inbound_inventory: shadowtls_composite_invalid; 已保留配置和状态，禁止有损重建。\n' >&2
    return 1
  fi
}

list_config_protocols() {
  validate_live_inbound_inventory "${SINGBOX_CONFIG_FILE}" || return 1
  [[ -f "${SINGBOX_CONFIG_FILE}" ]] || return 0

  local protocols=()
  local inbound_count inbound_index inbound_json protocol

  inbound_count=$(jq -r '(.inbounds // []) | length' "${SINGBOX_CONFIG_FILE}") || return 1
  [[ "${inbound_count}" =~ ^[0-9]+$ ]] || return 1

  for ((inbound_index = 0; inbound_index < inbound_count; inbound_index++)); do
    inbound_json=$(jq -c --argjson idx "${inbound_index}" '.inbounds[$idx]' "${SINGBOX_CONFIG_FILE}") || return 1
    if jq -e '.type | IN("direct","tun","redirect","tproxy","cloudflared")' <<< "${inbound_json}" >/dev/null 2>&1; then
      # Advanced inbounds have their own typed component state and must not
      # pollute the share-link protocol index.
      continue
    fi
    protocol=$(config_inbound_protocol "${inbound_json}") || return 1

    if ! protocol_array_contains "${protocol}" ${protocols[@]+"${protocols[@]}"}; then
      protocols+=("${protocol}")
    fi
  done

  [[ ${#protocols[@]} -gt 0 ]] || return 0
  printf '%s\n' "${protocols[@]}"
}

find_config_inbound_index_by_protocol() {
  [[ -f "${SINGBOX_CONFIG_FILE}" ]] || return 1

  local target_protocol inbound_count inbound_index inbound_json protocol
  target_protocol=$(normalize_protocol_id "$1")

  inbound_count=$(jq -r '(.inbounds // []) | length' "${SINGBOX_CONFIG_FILE}")
  [[ "${inbound_count}" =~ ^[0-9]+$ ]] || return 1

  for ((inbound_index = 0; inbound_index < inbound_count; inbound_index++)); do
    inbound_json=$(jq -c --argjson idx "${inbound_index}" '.inbounds[$idx]' "${SINGBOX_CONFIG_FILE}")
    protocol=$(config_inbound_protocol "${inbound_json}" 2>/dev/null || true)
    if [[ "${protocol}" == "${target_protocol}" ]]; then
      printf '%s' "${inbound_index}"
      return 0
    fi
  done

  return 1
}

vless_reality_config_id_exists() {
  local target_id=$1
  local existing_id
  for existing_id in "${VLESS_CONFIG_INSTANCE_IDS[@]}"; do
    [[ "${existing_id}" == "${target_id}" ]] && return 0
  done
  return 1
}

reset_vless_reality_state_source_variables() {
  unset INSTALLED CONFIG_SCHEMA_VERSION DEFAULT_INSTANCE_ID INSTANCE_IDS
  unset REALITY_PRIVATE_KEY REALITY_PUBLIC_KEY PRIVATE_KEY PUBLIC_KEY
  unset INSTANCE_ID INBOUND_TAG ENABLED NODE_NAME PORT UUID SNI SHORT_ID_1 SHORT_ID_2
  unset RATE_LIMIT_UP_MBPS RATE_LIMIT_DOWN_MBPS ALPN_MODE TCP_FAST_OPEN OUTBOUND_POLICY
}

load_vless_reality_existing_metadata() {
  local state_file instance_dir normalized_ids instance_id state_index tag existing_tag
  local state_schema
  local state_ids=()

  VLESS_REBUILD_STATE_SCHEMA="none"
  VLESS_REBUILD_STATE_DEFAULT_ID=""
  VLESS_REBUILD_STATE_PRIVATE_KEY=""
  VLESS_REBUILD_STATE_PUBLIC_KEY=""
  VLESS_REBUILD_STATE_IDS=()
  VLESS_REBUILD_STATE_TAGS=()
  VLESS_REBUILD_STATE_NODE_NAMES=()
  VLESS_REBUILD_STATE_RATE_UP=()
  VLESS_REBUILD_STATE_RATE_DOWN=()

  state_file=$(protocol_state_file "vless-reality") || return 1
  [[ -f "${state_file}" ]] || return 0

  reset_vless_reality_state_source_variables
  # shellcheck disable=SC1090
  source "${state_file}" || return 1
  state_schema="${CONFIG_SCHEMA_VERSION:-1}"

  case "${state_schema}" in
    1) ;;
    2) ;;
    *) return 1 ;;
  esac

  if [[ "${state_schema}" == "1" ]]; then
    VLESS_REBUILD_STATE_SCHEMA="1"
    VLESS_REBUILD_STATE_DEFAULT_ID="main"
    VLESS_REBUILD_STATE_PRIVATE_KEY="${REALITY_PRIVATE_KEY:-${PRIVATE_KEY:-}}"
    VLESS_REBUILD_STATE_PUBLIC_KEY="${REALITY_PUBLIC_KEY:-${PUBLIC_KEY:-}}"
    VLESS_REBUILD_STATE_NODE_NAMES=("$(normalize_node_name "${NODE_NAME:-}")")
    return 0
  fi

  VLESS_REBUILD_STATE_SCHEMA="2"
  VLESS_REBUILD_STATE_DEFAULT_ID="${DEFAULT_INSTANCE_ID:-}"
  VLESS_REBUILD_STATE_PRIVATE_KEY="${REALITY_PRIVATE_KEY:-}"
  VLESS_REBUILD_STATE_PUBLIC_KEY="${REALITY_PUBLIC_KEY:-}"
  normalized_ids=$(normalize_csv_list "${INSTANCE_IDS:-}")
  [[ -n "${normalized_ids}" ]] || return 1
  IFS=',' read -r -a state_ids <<< "${normalized_ids}"
  [[ ${#state_ids[@]} -gt 0 ]] || return 1
  [[ -n "${VLESS_REBUILD_STATE_DEFAULT_ID}" ]] || return 1

  instance_dir=$(vless_reality_instance_dir) || return 1
  for instance_id in "${state_ids[@]}"; do
    instance_id=$(trim_whitespace "${instance_id}")
    validate_vless_reality_instance_id "${instance_id}" || return 1
    if [[ ${#VLESS_REBUILD_STATE_IDS[@]} -gt 0 ]]; then
      for existing_tag in "${VLESS_REBUILD_STATE_IDS[@]}"; do
        [[ "${existing_tag}" == "${instance_id}" ]] && return 1
      done
    fi
    state_file="${instance_dir}/${instance_id}.env"
    [[ -f "${state_file}" ]] || return 1

    reset_vless_reality_state_source_variables
    # shellcheck disable=SC1090
    source "${state_file}" || return 1
    [[ "${INSTANCE_ID:-}" == "${instance_id}" && "${ENABLED:-}" == "1" ]] || return 1
    validate_optional_positive_integer "${RATE_LIMIT_UP_MBPS:-}" || return 1
    validate_optional_positive_integer "${RATE_LIMIT_DOWN_MBPS:-}" || return 1
    tag="${INBOUND_TAG:-}"
    if [[ -z "${tag}" ]]; then
      if [[ "${instance_id}" == "${VLESS_REBUILD_STATE_DEFAULT_ID}" ]]; then
        tag="vless-in"
      else
        tag="vless-reality-${instance_id}"
      fi
    fi
    [[ -n "${tag}" && "${tag}" != *$'\n'* ]] || return 1
    if [[ ${#VLESS_REBUILD_STATE_TAGS[@]} -gt 0 ]]; then
      for existing_tag in "${VLESS_REBUILD_STATE_TAGS[@]}"; do
        [[ "${existing_tag}" == "${tag}" ]] && return 1
      done
    fi

    VLESS_REBUILD_STATE_IDS+=("${instance_id}")
    VLESS_REBUILD_STATE_TAGS+=("${tag}")
    VLESS_REBUILD_STATE_NODE_NAMES+=("$(normalize_node_name "${NODE_NAME:-}")")
    VLESS_REBUILD_STATE_RATE_UP+=("${RATE_LIMIT_UP_MBPS:-}")
    VLESS_REBUILD_STATE_RATE_DOWN+=("${RATE_LIMIT_DOWN_MBPS:-}")
  done

  for state_index in "${!VLESS_REBUILD_STATE_IDS[@]}"; do
    [[ "${VLESS_REBUILD_STATE_IDS[${state_index}]}" == "${VLESS_REBUILD_STATE_DEFAULT_ID}" ]] && return 0
  done
  return 1
}

vless_reality_existing_state_index_for_tag() {
  local target_tag=$1 state_index matched_index=""

  [[ "${VLESS_REBUILD_STATE_SCHEMA:-none}" == "2" ]] || return 1
  for state_index in "${!VLESS_REBUILD_STATE_TAGS[@]}"; do
    if [[ "${VLESS_REBUILD_STATE_TAGS[${state_index}]}" == "${target_tag}" ]]; then
      [[ -z "${matched_index}" ]] || return 1
      matched_index="${state_index}"
    fi
  done
  [[ -n "${matched_index}" ]] || return 1
  printf '%s' "${matched_index}"
}

vless_reality_existing_state_index_for_id() {
  local target_id=$1 state_index

  [[ "${VLESS_REBUILD_STATE_SCHEMA:-none}" == "2" ]] || return 1
  for state_index in "${!VLESS_REBUILD_STATE_IDS[@]}"; do
    [[ "${VLESS_REBUILD_STATE_IDS[${state_index}]}" == "${target_id}" ]] || continue
    printf '%s' "${state_index}"
    return 0
  done
  return 1
}

# --- Structured instance store (typed plain-proxy foundation) ---
#
# This store is deliberately separate from the legacy .env state.  It is a
# read/write file primitive for the next lifecycle layer; no caller here
# migrates legacy state or passes arbitrary JSON through to sing-box.
structured_instance_store_error() {
  local operation=${1:-operation} code=${2:-invalid}
  printf '[ERROR] structured instance store %s failed (%s).\n' "${operation}" "${code}" >&2
}

structured_instance_store_protocol() {
  local protocol
  protocol=$(normalize_protocol_id "${1:-}") || return 1
  [[ "${protocol}" == "mixed" || "${protocol}" == "vless-plain" || "${protocol}" == "socks" || "${protocol}" == "http" || "${protocol}" == "shadowsocks" || "${protocol}" == "trojan" || "${protocol}" == "vmess" || "${protocol}" == "anytls" || "${protocol}" == "hy2" || "${protocol}" == "snell" || "${protocol}" == "tuic" || "${protocol}" == "hysteria" || "${protocol}" == "naive" || "${protocol}" == "shadowtls" ]] || return 1
  printf '%s' "${protocol}"
}

structured_instance_store_validate_id() {
  [[ "${1:-}" =~ ^[a-zA-Z0-9][a-zA-Z0-9_-]{0,63}$ ]]
}

structured_instance_store_validate_address() {
  local address=${1:-} part octet count left right ipv4_tail ipv4_prefix converted
  local parts=() octets=()
  [[ -n "${address}" && "${address}" != *%* ]] || return 1
  # Validate an IPv4 tail embedded in any IPv6 spelling by converting the
  # final dotted quad to its two hexadecimal groups before applying the normal
  # IPv6 grammar. This covers compressed and full IPv4-mapped forms alike;
  # the stored listen value itself remains unchanged.
  if [[ "${address}" == *.* && "${address}" == *:* ]]; then
    ipv4_tail=${address##*:}
    ipv4_prefix=${address%:*}
    IFS=. read -r -a octets <<< "${ipv4_tail}"
    [[ ${#octets[@]} -eq 4 ]] || return 1
    for octet in "${octets[@]}"; do
      [[ "${octet}" =~ ^(0|[1-9][0-9]{0,2})$ ]] || return 1
      (( octet <= 255 )) || return 1
    done
    converted=$(printf '%x:%x' \
      "$((10#${octets[0]} * 256 + 10#${octets[1]}))" \
      "$((10#${octets[2]} * 256 + 10#${octets[3]}))") || return 1
    address="${ipv4_prefix}:${converted}"
  fi

  if [[ "${address}" =~ ^[0-9]+(\.[0-9]+){3}$ ]]; then
    IFS=. read -r -a octets <<< "${address}"
    [[ ${#octets[@]} -eq 4 ]] || return 1
    for octet in "${octets[@]}"; do
      [[ "${octet}" =~ ^(0|[1-9][0-9]{0,2})$ ]] || return 1
      (( octet <= 255 )) || return 1
    done
    return 0
  fi

  [[ "${address}" == *:* && "${address}" =~ ^[0-9A-Fa-f:]+$ ]] || return 1
  [[ "${address}" != *:::* ]] || return 1
  [[ "${address}" != :* || "${address}" == ::* ]] || return 1
  [[ "${address}" != *: || "${address}" == *:: ]] || return 1
  count=0
  if [[ "${address}" == *::* ]]; then
    left=${address%%::*}
    right=${address#*::}
    [[ "${right}" != *::* ]] || return 1
    if [[ -n "${left}" ]]; then
      IFS=: read -r -a parts <<< "${left}"
      for part in "${parts[@]}"; do
        [[ "${part}" =~ ^[0-9A-Fa-f]{1,4}$ ]] || return 1
        count=$((count + 1))
      done
    fi
    if [[ -n "${right}" ]]; then
      IFS=: read -r -a parts <<< "${right}"
      for part in "${parts[@]}"; do
        [[ "${part}" =~ ^[0-9A-Fa-f]{1,4}$ ]] || return 1
        count=$((count + 1))
      done
    fi
    (( count < 8 )) || return 1
    return 0
  fi

  IFS=: read -r -a parts <<< "${address}"
  [[ ${#parts[@]} -eq 8 ]] || return 1
  for part in "${parts[@]}"; do
    [[ "${part}" =~ ^[0-9A-Fa-f]{1,4}$ ]] || return 1
  done
}

structured_instance_record_jq_filter() {
  cat <<'JQ'
    def ss_key($method):
      type == "string" and utf8bytelength <= 4096 and
      test("^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/][AQgw]==|[A-Za-z0-9+/]{2}[AEIMQUYcgkosw048]=)?$") and
      # The pinned core derives longer PSKs, for both server and user keys.
      # Count decoded bytes without jq @base64d corrupting arbitrary binary.
      (((length / 4 * 3) - (if endswith("==") then 2 elif endswith("=") then 1 else 0 end)) >=
       (if $method == "2022-blake3-aes-128-gcm" then 16 else 32 end));
    def ss_auth:
      type == "object" and (keys | sort) == ["method","password","users"] and
      (.method | IN("none","aes-128-gcm","aes-192-gcm","aes-256-gcm",
        "chacha20-ietf-poly1305","xchacha20-ietf-poly1305",
        "2022-blake3-aes-128-gcm","2022-blake3-aes-256-gcm","2022-blake3-chacha20-poly1305")) and
      (.method as $method |
        (.password | type == "string" and index("\u0000") == null and utf8bytelength <= 4096) and
        (.users | type == "array" and length <= 128 and
          all(.[]; type == "object" and (keys | sort) == ["name","password"] and
            (.name | type == "string" and length > 0 and utf8bytelength <= 256 and
              (test("[\u0000-\u001F\u007F]") | not)) and
            (.password | type == "string" and length > 0 and utf8bytelength <= 4096 and index("\u0000") == null) and
            (if $method | startswith("2022-") then (.password | ss_key($method)) else true end)) and
          ((map(.name)|unique|length) == length) and ((map(.password)|unique|length) == length)) and
        (if $method == "none" then .password == "" and .users == []
         elif $method | startswith("2022-") then
           (.password | ss_key($method)) and
           (if $method == "2022-blake3-chacha20-poly1305" then .users == [] else true end)
         elif (.users|length) > 0 then .password == ""
         else (.password|length) > 0 end));
    def valid_snell_obfs_host:
      if . == "" then true
      else type == "string" and length > 0 and utf8bytelength <= 255 and
        (test("[\u0000-\u001F\u007F]") | not)
      end;
    def valid_plain_instance($protocol):
      type == "object" and
      ((keys | sort) == ((["authentication","dependencies","id","listen","name","outbound_policy","tag"] +
        (if $protocol == "snell" then ["mode","obfs_host","obfs_mode","version"] else [] end) +
        (if $protocol == "http" or $protocol == "trojan" or $protocol == "vmess" or $protocol == "vless-plain" or $protocol == "anytls" or $protocol == "hy2" or $protocol == "tuic" or $protocol == "hysteria" or $protocol == "naive" then ["tls"] else [] end) +
        (if $protocol == "trojan" or $protocol == "vmess" or $protocol == "vless-plain" then ["client_trust","transport"]
         elif $protocol == "anytls" then ["client_trust"]
         elif $protocol == "hy2" then ["bandwidth","client_trust","masquerade","obfs"]
         elif $protocol == "tuic" then ["client_trust","tuic"]
         elif $protocol == "hysteria" then ["bandwidth","client_trust","hysteria","obfs"]
         elif $protocol == "naive" then ["client_trust","naive"]
         else [] end)) | sort)) and
      (.id | type == "string" and test("^[a-zA-Z0-9][a-zA-Z0-9_-]{0,63}$")) and
      (.name | type == "string" and length > 0 and index("\u0000") == null) and
      (.tag | type == "string" and length > 0 and (test("[\u0000-\u001F\u007F]")|not)) and
      (.listen | type == "object" and
        ((keys|sort) == (if $protocol == "shadowsocks" or $protocol == "naive" then ["address","network","port"] else ["address","port"] end)) and
        (.address | type == "string" and length > 0 and (test("[\u0000-\u0020\u007F]")|not)) and
        (.port | type == "number" and floor == . and . >= 1 and . <= 65535) and
        (if $protocol == "shadowsocks" or $protocol == "naive" then
          (.network | type == "array" and length > 0 and length <= 2 and
            all(.[]; . == "tcp" or . == "udp") and . == (sort|unique))
         else true end)) and
      (if $protocol == "shadowsocks" then (.authentication | ss_auth)
      elif $protocol == "anytls" or $protocol == "hy2" then
         (.authentication | type == "object" and (keys|sort) == ["users"] and
           (.users | type == "array" and length >= 1 and length <= 128 and
             all(.[]; type == "object" and (keys|sort) == ["name","password"] and
               (.name | type == "string" and length > 0 and utf8bytelength <= 256 and
                 (test("[\u0000-\u001F\u007F]") | not)) and
               (.password | type == "string" and length > 0 and utf8bytelength <= 4096 and index("\u0000") == null)) and
             (map(.name)|unique|length) == length and
             (map(.password)|unique|length) == length))
      elif $protocol == "hysteria" then
         (.authentication | type == "object" and (keys|sort) == ["users"] and
           (.users | type == "array" and length >= 1 and length <= 128 and
             all(.[]; type == "object" and (keys|sort) == ["auth_str","name"] and
               (.name | type == "string" and length > 0 and utf8bytelength <= 256 and (test("[\u0000-\u001F\u007F]") | not)) and
               (.auth_str | type == "string" and length > 0 and utf8bytelength <= 4096 and (test("[\u0000-\u001F\u007F]") | not))) and
             (map(.name)|unique|length) == length and (map(.auth_str)|unique|length) == length))
       elif $protocol == "naive" then
         (.authentication | type == "object" and (keys|sort) == ["users"] and
           (.users | type == "array" and length >= 1 and length <= 128 and
             all(.[]; type == "object" and (keys|sort) == ["name","password","username"] and
               (.name | type == "string" and length > 0 and utf8bytelength <= 256 and (test("[\u0000-\u001F\u007F]") | not)) and
               (.username | type == "string" and length > 0 and utf8bytelength <= 4096 and index("\u0000") == null and (test("[\u0000-\u001F\u007F]") | not) and (contains(":") | not)) and
               (.password | type == "string" and length > 0 and utf8bytelength <= 4096 and index("\u0000") == null and (test("[\u0000-\u001F\u007F]") | not))) and
             (map(.name)|unique|length) == length and (map(.username)|unique|length) == length))
       elif $protocol == "tuic" then
         (.authentication | type == "object" and (keys|sort) == ["users"] and
           (.users | type == "array" and length >= 1 and length <= 128 and
             all(.[]; type == "object" and (keys|sort) == ["name","password","uuid"] and
               (.name | type == "string" and length > 0 and utf8bytelength <= 256 and
                 (test("[\u0000-\u001F\u007F]") | not)) and
               (.password | type == "string" and length > 0 and utf8bytelength <= 4096 and index("\u0000") == null) and
               (.uuid | type == "string" and test("^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$"))) and
             (map(.name)|unique|length) == length and
             (map(.uuid)|unique|length) == length and
             (map(.password)|unique|length) == length))
       elif $protocol == "trojan" or $protocol == "vmess" or $protocol == "vless-plain" then
         (.authentication | type == "object" and (keys|sort) == ["users"] and
           (.users | type == "array" and length >= 1 and length <= 128 and
             all(.[]; type == "object" and (keys|sort) == (if $protocol == "trojan" then ["name","password"] elif $protocol == "vmess" then ["alter_id","name","security","uuid"] else ["flow","name","uuid"] end) and
               (.name | type == "string" and length > 0 and utf8bytelength <= 256 and
                 (test("[\u0000-\u001F\u007F]") | not)) and
               (if $protocol == "trojan" then
                 (.password | type == "string" and length > 0 and utf8bytelength <= 4096 and index("\u0000") == null)
                elif $protocol == "vmess" then
                 (.uuid | type == "string" and test("^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$")) and
                 (.alter_id | type == "number" and floor == . and . >= 0 and . <= 65535) and
                 (.security | type == "string" and IN("auto","none","zero","aes-128-cfb","aes-128-gcm","chacha20-poly1305"))
                else
                  (.uuid | type == "string" and test("^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$")) and
                  (.flow | type == "string" and IN("","xtls-rprx-vision"))
                end)) and
             (map(.name)|unique|length) == length and
             (if $protocol == "trojan" then (map(.password)|unique|length) == length else (map(.uuid)|unique|length) == length end)))
       elif $protocol == "snell" then
         (.authentication | type == "object" and (keys|sort) == ["psk","users"] and
           (.psk | type == "string" and length > 0 and utf8bytelength <= 255 and index("\u0000") == null and
             (test("[\u0000-\u001F\u007F]") | not)) and
           (.users | type == "array" and length <= 128 and
             all(.[]; type == "object" and (keys|sort) == ["name","userkey"] and
               (.name | type == "string" and length > 0 and utf8bytelength <= 256 and
                 (test("[\u0000-\u001F\u007F]") | not)) and
               (.userkey | type == "string" and length > 0 and utf8bytelength <= 255 and
                 index("\u0000") == null and (test("[\u0000-\u001F\u007F]") | not))) and
             (map(.name)|unique|length) == length and
             (map(.userkey)|unique|length) == length))
       else (.authentication | type == "object" and (keys|sort) == ["enabled","password","username"] and
         (.enabled|type == "boolean") and
         (.username|type == "string" and index("\u0000") == null) and
         (.password|type == "string" and index("\u0000") == null) and
         (if $protocol == "http" then
            (.username|utf8bytelength <= 4096 and (test("[\u0000-\u001F\u007F]")|not) and (contains(":")|not)) and
            (.password|utf8bytelength <= 4096 and (test("[\u0000-\u001F\u007F]")|not))
          else (.username|utf8bytelength <= 255) and (.password|utf8bytelength <= 255) end) and
         (if .enabled then (.username|length)>0 and (.password|length)>0 else .username=="" and .password=="" end))
       end) and
      (if $protocol == "trojan" or $protocol == "vmess" or $protocol == "vless-plain" or $protocol == "anytls" or $protocol == "hy2" or $protocol == "tuic" or $protocol == "hysteria" or $protocol == "naive" then
         (.client_trust | type == "string" and IN("certificate","system")) and
         (if .tls.enabled == false then .client_trust == "system" else true end)
       else true end) and
      (if $protocol == "snell" then
         (.version | type == "number" and floor == . and IN(5,6)) and
         (.obfs_mode | type == "string") and (.obfs_host | type == "string") and
         (.mode | type == "string") and
         (if .version == 5 then
            (.mode == "" and (.obfs_mode | IN("none","http")) and
             (if .obfs_mode == "none" then .obfs_host == "" else
                (.obfs_host | length > 0 and utf8bytelength <= 255 and
                  (test("[\u0000-\u001F\u007F]") | not))
              end))
          else
            (.obfs_mode == "" and .obfs_host == "" and
             (.mode | IN("","default","unshaped","unsafe-raw")) and
             (.authentication.psk | utf8bytelength >= 12))
          end)
       else true end) and
      (.outbound_policy|IN("default","direct","warp")) and
      (.dependencies|type == "array" and length == 0) and
      (if $protocol == "http" or $protocol == "trojan" or $protocol == "vmess" or $protocol == "vless-plain" or $protocol == "anytls" or $protocol == "hy2" or $protocol == "tuic" or $protocol == "hysteria" or $protocol == "naive" then (.tls|type == "object" and
         (if .enabled == false then ($protocol != "anytls" and $protocol != "hy2" and $protocol != "tuic" and $protocol != "hysteria" and $protocol != "naive" and (keys|sort)==["enabled"])
          elif .enabled == true then
            (keys|sort)==["certificate_path","enabled","key_path","server_name"] and
            (.server_name|type=="string" and length>0 and (test("[\u0000-\u001F\u007F]")|not)) and
            (.certificate_path|type=="string" and startswith("/") and (test("[\u0000-\u001F\u007F]")|not)) and
            (.key_path|type=="string" and startswith("/") and (test("[\u0000-\u001F\u007F]")|not))
          else false end))
       else true end) and
      (if $protocol == "hysteria" then
         (.bandwidth | type == "object" and (keys|sort) == ["down_mbps","up_mbps"] and
           (.up_mbps | type == "number" and floor == . and . >= 1 and . <= 1000000) and
           (.down_mbps | type == "number" and floor == . and . >= 1 and . <= 1000000)) and
         (.obfs | type == "object" and (keys|sort) == ["enabled","password"] and
           (.enabled | type == "boolean") and
           (.password | type == "string" and utf8bytelength <= 4096 and (test("[\u0000-\u001F\u007F]") | not)) and
           (if .enabled then (.password|length)>0 else .password == "" end)) and
         (.hysteria | type == "object" and (keys|sort) == ["connection_receive_window","disable_path_mtu_discovery","initial_packet_size","max_concurrent_streams","stream_receive_window"] and
           (.initial_packet_size | type == "number" and floor == . and . >= 0 and . <= 65535) and
           (.max_concurrent_streams | type == "number" and floor == . and . >= 0 and . <= 65535) and
           (.disable_path_mtu_discovery | type == "boolean") and
           (.stream_receive_window | type == "string" and length <= 64 and test("^$|^[0-9]+( ?(B|KB|MB|GB))$")) and
           (.connection_receive_window | type == "string" and length <= 64 and test("^$|^[0-9]+( ?(B|KB|MB|GB))$")))
       elif $protocol == "hy2" then
         (.bandwidth | type == "object" and (keys|sort) == ["down_mbps","up_mbps"] and
           all(.[]; . == null or (type == "number" and floor == . and . >= 1 and . <= 1000000))) and
         (.obfs | type == "object" and (keys|sort) == ["enabled","password","type"] and
           (.enabled | type == "boolean") and
           (.type | type == "string" and (test("^[A-Za-z0-9_-]{0,32}$"))) and
           (.password | type == "string" and utf8bytelength <= 4096 and index("\u0000") == null and (test("[\u0000-\u001F\u007F]") | not)) and
           (if .enabled then .type == "salamander" and (.password|length)>0 else .type == "" and .password == "" end)) and
         (.masquerade | type == "string" and utf8bytelength <= 4096 and index("\u0000") == null and (test("[\u0000-\u001F\u007F]") | not))
       elif $protocol == "tuic" then
         (.tuic | type == "object" and (keys|sort) == ["auth_timeout_seconds","congestion_control","heartbeat_seconds","udp_over_stream","udp_relay_mode","zero_rtt_handshake"] and
           (.auth_timeout_seconds | type == "number" and floor == . and . >= 0 and . <= 86400) and
           (.heartbeat_seconds | type == "number" and floor == . and . >= 0 and . <= 86400) and
           (.congestion_control | type == "string" and IN("cubic","new_reno","bbr")) and
           (.udp_over_stream | type == "boolean") and
           (.zero_rtt_handshake | type == "boolean") and
           (.udp_relay_mode | type == "string" and IN("","native","quic")) and
           (if .udp_over_stream then .udp_relay_mode == "" else .udp_relay_mode != "" end))
       elif $protocol == "naive" then
         (.naive | type == "object" and (keys|sort) == ["extra_headers","insecure_concurrency","quic","quic_congestion_control","quic_session_receive_window","stream_receive_window"] and
           (.extra_headers | type == "object" and length <= 64 and all(to_entries[];
             (.key | type == "string" and length > 0 and length <= 128 and
               (test("^[!#$%&'*+.^_`|~0-9A-Za-z-]+$") )) and
             (.value | type == "string" and utf8bytelength <= 4096 and (test("[\u0000-\u001F\u007F]") | not)))) and
           (.insecure_concurrency | type == "number" and floor == . and . >= 0 and . <= 1024) and
           (.quic | type == "boolean") and
           (.quic_congestion_control | type == "string" and IN("bbr","cubic","reno")) and
           (.quic_session_receive_window | type == "string" and length <= 64 and test("^$|^[0-9]+( ?(B|KB|MB|GB))$")) and
           (.stream_receive_window | type == "string" and length <= 64 and test("^$|^[0-9]+( ?(B|KB|MB|GB))$")))
       else true end);
    def valid_shadowtls_instance:
      . as $instance |
      type == "object" and
      (keys|sort) == ["authentication","client_tls","client_trust","dependencies","detour","handshake","handshake_for_server_name","id","listen","name","outbound_policy","strict_mode","tag","version","wildcard_sni"] and
      (.id | type == "string" and test("^[a-zA-Z0-9][a-zA-Z0-9_-]{0,63}$")) and
      (.name | type == "string" and length > 0 and index("\u0000") == null) and
      (.tag | type == "string" and length > 0 and (test("[\u0000-\u001F\u007F]")|not)) and
      (.listen | type == "object" and (keys|sort) == ["address","port"] and
        (.address | type == "string" and length > 0 and (test("[\u0000-\u0020\u007F]")|not)) and
        (.port | type == "number" and floor == . and . >= 1 and . <= 65535)) and
      (.version | type == "number" and floor == . and IN(1,2,3)) and
      (.authentication | type == "object" and (keys|sort) == ["password","users"] and
        (.password | type == "string" and length <= 4096 and index("\u0000") == null and (test("[\u0000-\u001F\u007F]")|not)) and
        (.users | type == "array" and length <= 128 and
          all(.[]; type == "object" and (keys|sort) == ["name","password"] and
            (.name | type == "string" and length > 0 and utf8bytelength <= 256 and (test("[\u0000-\u001F\u007F]")|not)) and
            (.password | type == "string" and length > 0 and utf8bytelength <= 4096 and index("\u0000") == null and (test("[\u0000-\u001F\u007F]")|not))) and
          (map(.name)|unique|length) == length and (map(.password)|unique|length) == length) and
        (if $instance.version == 1 then .password == "" and .users == []
         elif $instance.version == 2 then (.password|length) > 0 and .users == []
         else .password == "" and (.users|length) >= 1 end)) and
      (.handshake | type == "object" and (keys|sort) == ["server","server_port"] and
        (.server | type == "string" and length > 0 and utf8bytelength <= 4096 and (test("[\u0000-\u001F\u007F]")|not)) and
        (.server_port | type == "number" and floor == . and . >= 1 and . <= 65535)) and
      (.handshake_for_server_name | type == "object" and
        all(to_entries[]; .key | type == "string" and length > 0 and utf8bytelength <= 255 and (test("[\u0000-\u001F\u007F]")|not)) and
        all(to_entries[]; .value | type == "object" and (keys|sort) == ["server","server_port"] and
          (.server | type == "string" and length > 0 and utf8bytelength <= 4096 and (test("[\u0000-\u001F\u007F]")|not)) and
          (.server_port | type == "number" and floor == . and . >= 1 and . <= 65535)) and
        (if $instance.version == 1 then length == 0 else true end)) and
      (.strict_mode | type == "boolean") and
      (.wildcard_sni | type == "string" and IN("off","authed","all")) and
      (if .version == 1 then (.strict_mode == false and .wildcard_sni == "off")
       elif .version == 2 then (.strict_mode == false and .wildcard_sni == "off")
       else true end) and
      (.detour | type == "object" and (keys|sort) == ["listen","tag"] and
        (.tag | type == "string" and . == ("shadowtls-inner-" + $instance.id)) and
        (.listen | type == "object" and (keys|sort) == ["address","port"] and
          .address == "127.0.0.1" and (.port | type == "number" and floor == . and . >= 1 and . <= 65535) and
          .port != $instance.listen.port)) and
      (.dependencies | type == "array") and (.dependencies == [$instance.detour.tag]) and
      (.client_trust | type == "string" and IN("system","certificate")) and
      (.client_tls | type == "object" and (keys|sort) == ["certificate_path","server_name"] and
        (.server_name | type == "string" and length > 0 and utf8bytelength <= 4096 and (test("[\u0000-\u001F\u007F]")|not)) and
        (.certificate_path | type == "string" and (test("[\u0000-\u001F\u007F]")|not)) and
        (if $instance.client_trust == "system" then .certificate_path == "" else (.certificate_path | startswith("/")) end)) and
      (.outbound_policy | IN("default","direct","warp"));
    def valid_instance($protocol):
      if $protocol == "shadowtls" then valid_shadowtls_instance else valid_plain_instance($protocol) end;
JQ
}

structured_instance_store_validate_common_json() {
  local protocol=${1:-mixed} file=${2:-} file_size filter transport_json tls_mode transport_list transport_record flow flow_list
  if [[ $# -eq 1 ]]; then file=${1:-}; protocol=mixed; fi
  [[ -n "${file}" && -f "${file}" && ! -L "${file}" ]] || return 1
  file_size=$(wc -c < "${file}") || return 1
  [[ "${file_size}" =~ ^[0-9]+$ && ${file_size} -le 1048576 ]] || return 1
  filter=$(structured_instance_record_jq_filter) || return 1
  jq -es "${filter}"'
    length == 1 and (.[0] |
      type == "object" and
      (keys|sort) == ["default_instance_id","instances","protocol","revision","schema_version"] and
      .schema_version == 1 and .protocol == $protocol and
      (.revision|type=="number" and floor==. and .>=0 and .<=9007199254740991) and
      (.default_instance_id|type=="string" and (test("^[a-zA-Z0-9][a-zA-Z0-9_-]{0,63}$") or .=="")) and
      (. as $root | if (.instances|length)==0 then .default_instance_id==""
        else .default_instance_id!="" and any(.instances[]; .id==$root.default_instance_id) end) and
      (.instances|type=="array" and length<=128 and all(.[]; valid_instance($protocol)) and
        (map(.id)|unique|length)==length and (map(.tag)|unique|length)==length and
        (map([.listen.address,.listen.port,
          (if $protocol == "shadowtls" then ["tcp"]
           elif $protocol == "hy2" or $protocol == "tuic" or $protocol == "hysteria" then ["udp"]
           elif $protocol == "trojan" or $protocol == "vmess" then
             (if .transport.type == "quic" then ["udp"] else ["tcp"] end)
           else (.listen.network // ["tcp"]) end)]|@json)|unique|length)==length))
  ' --arg protocol "${protocol}" "${file}" >/dev/null 2>&1 || return 1
  if [[ "${protocol}" == "trojan" || "${protocol}" == "vmess" || "${protocol}" == "vless-plain" ]]; then
    transport_list=$(jq -c '.instances[] | [.transport, .tls.enabled, (.authentication.users | map(.flow // ""))]' "${file}") || return 1
    while IFS= read -r transport_record; do
      [[ -n "${transport_record}" ]] || continue
      transport_json=$(jq -c '.[0]' <<< "${transport_record}") || return 1
      tls_mode=$(jq -r 'if .[1] then "tls" else "disabled" end' <<< "${transport_record}") || return 1
      if [[ "${protocol}" == "vless-plain" ]]; then
        flow_list=$(jq -r '.[2][]' <<< "${transport_record}") || return 1
      else
        flow_list=""
      fi
      while IFS= read -r flow; do
        build_v2ray_transport_profile_json "${protocol/vless-plain/vless}" "${transport_json}" "${tls_mode}" "${flow}" "$(resolve_config_target_singbox_version)" >/dev/null || return 1
      done <<< "${flow_list}"
    done <<< "${transport_list}"
  fi
}

validate_structured_instance_store() {
  local protocol file addresses address listener_input listener_plan
  protocol=$(structured_instance_store_protocol "${1:-}") || {
    structured_instance_store_error validate unsupported_protocol
    return 1
  }
  file=${2:-}
  structured_instance_store_validate_common_json "${protocol}" "${file}" || {
    structured_instance_store_error validate invalid_store
    return 1
  }
  addresses=$(jq -r '.instances[].listen.address' "${file}" 2>/dev/null) || {
    structured_instance_store_error validate invalid_address
    return 1
  }
  while IFS= read -r address; do
    [[ -n "${address}" ]] || continue
    structured_instance_store_validate_address "${address}" || {
      structured_instance_store_error validate invalid_address
      return 1
    }
  done <<< "${addresses}"
  if [[ "${protocol}" == "shadowtls" ]]; then
    jq -e '(.instances | all(.[]; .detour.listen.address == "127.0.0.1" and .detour.listen.port != .listen.port)) and
      (([.instances[].listen.port] + [.instances[].detour.listen.port]) as $ports | ($ports|unique|length) == ($ports|length))' "${file}" >/dev/null 2>&1 || {
      structured_instance_store_error validate invalid_shadowtls_detour
      return 1
    }
    while IFS= read -r address; do
      [[ -n "${address}" ]] || continue
      structured_instance_store_validate_address "${address}" || {
        structured_instance_store_error validate invalid_detour_address
        return 1
      }
    done < <(jq -r '.instances[].detour.listen.address' "${file}")
  fi
  listener_input=$(jq -c --arg protocol "${protocol}" '{inbounds:[.instances[] | {type:(if $protocol == "vless-plain" then "vless" elif $protocol == "hy2" then "hysteria2" else $protocol end),tag:.tag,listen:.listen.address,listen_port:.listen.port} + (if $protocol == "shadowsocks" or $protocol == "naive" then {network:.listen.network} elif $protocol == "trojan" or $protocol == "vmess" or $protocol == "vless-plain" then {transport:.transport} else {} end)]}' "${file}") || return 1
  if [[ "${protocol}" == "shadowtls" ]]; then
    listener_input=$(jq -c '{inbounds:(.instances | map([
      ({type:"shadowtls",tag:.tag,listen:.listen.address,listen_port:.listen.port,detour:.detour.tag,version:.version,handshake:.handshake} +
       (if .version == 2 then {password:.authentication.password} elif .version == 3 then {users:.authentication.users} else {} end)),
      {type:"mixed",tag:.detour.tag,listen:.detour.listen.address,listen_port:.detour.listen.port}
    ]) | add // [])}' "${file}") || return 1
  fi
  listener_plan=$(managed_listener_plan_json <<< "${listener_input}") || return 1
  validate_listener_plan_json <<< "${listener_plan}" || return 1
  : "${protocol}"
}

# Build a complete typed plain-proxy inventory from the live configuration.  This is
# intentionally a read-only candidate builder: it never sources JSON as shell
# state and it never writes the root .env or the instance store.  The takeover
# transaction owns publication of the returned document.
plain_proxy_config_store_candidate() (
  umask 077
  local protocol config_file existing_file protocol_label
  protocol=$(structured_instance_store_protocol "${1:-}") || return 1
  case "${protocol}" in
    mixed) protocol_label="Mixed" ;;
    socks) protocol_label="SOCKS" ;;
    http) protocol_label="HTTP" ;;
    shadowsocks) protocol_label="Shadowsocks" ;;
    trojan) protocol_label="Trojan" ;;
    vmess) protocol_label="VMess" ;;
    vless-plain) protocol_label="VLESS" ;;
    anytls) protocol_label="AnyTLS" ;;
    hy2) protocol_label="Hysteria2" ;;
    snell) protocol_label="Snell" ;;
    tuic) protocol_label="TUIC" ;;
    hysteria) protocol_label="Hysteria" ;;
    naive) protocol_label="NaiveProxy" ;;
    shadowtls) protocol_label="ShadowTLS" ;;
    *) return 1 ;;
  esac
  shift
  if [[ "${protocol}" == shadowtls ]]; then
    shadowtls_config_store_candidate "$@"
    return $?
  fi
  config_file=${1:-${SINGBOX_CONFIG_FILE:-}}
  existing_file=${2:-}
  local state_file state_schema legacy_name active_state store_file
  local temp_dir inbound_json inbound_count inbound_index tag address port
  local username password auth_enabled policy id name base digest suffix tls_json
  local ss_method ss_password ss_users_json network_json trojan_users_json='[]' trojan_transport_json='{"type":"none"}' trojan_client_trust=certificate trojan_profile
  local vmess_users_json='[]' vmess_transport_json='{"type":"none"}' vmess_client_trust=system vmess_profile
  local vless_users_json='[]' vless_transport_json='{"type":"none"}' vless_client_trust=system vless_profile vless_flow_list vless_flow
  local anytls_users_json='[]' anytls_tls_json='{"enabled":false}' anytls_client_trust=system
  local hy2_users_json='[]' hy2_tls_json='{"enabled":false}' hy2_client_trust=system
  local hy2_bandwidth_json='{"down_mbps":null,"up_mbps":null}' hy2_obfs_json='{"enabled":false,"password":"","type":""}' hy2_masquerade=""
  local snell_version=6 snell_psk="" snell_users_json='[]' snell_obfs_mode="" snell_obfs_host="" snell_mode=""
  local tuic_users_json='[]' tuic_tls_json='{"enabled":false}' tuic_client_trust=system tuic_congestion_control=bbr tuic_auth_timeout_seconds=3 tuic_heartbeat_seconds=10 tuic_zero_rtt_handshake=false tuic_udp_relay_mode=native tuic_udp_over_stream=false
  local hysteria_users_json='[]' hysteria_tls_json='{"enabled":false}' hysteria_client_trust=system hysteria_bandwidth_json='{"down_mbps":100,"up_mbps":100}' hysteria_obfs_json='{"enabled":false,"password":""}' hysteria_quic_json='{"connection_receive_window":"","disable_path_mtu_discovery":false,"initial_packet_size":0,"max_concurrent_streams":0,"stream_receive_window":""}'
  local naive_users_json='[]' naive_tls_json='{"enabled":false}' naive_client_trust=system naive_network_json='["tcp","udp"]' naive_quic_congestion_control=bbr naive_quic=false naive_insecure_concurrency=0 naive_stream_receive_window="" naive_quic_session_receive_window="" naive_extra_headers_json='{}'
  local existing_instance existing_store_json existing_match existing_snell_obfs_host default_id old_revision old_semantics new_semantics
  local candidate_revision status
  local marker_schema2=n store_instances=0

  [[ -n "${config_file}" && -f "${config_file}" && ! -L "${config_file}" ]] || {
    printf '[ERROR] %s_store_candidate: live configuration is unavailable.\n' "${protocol}" >&2
    return 1
  }

  temp_dir=$(mktemp -d) || return $?
  trap 'rm -rf -- "${temp_dir}"' EXIT
  trap 'return 130' INT
  trap 'return 143' TERM
  trap 'return 129' HUP

  # Canonicalize one complete snapshot before any inventory or route reads.
  # This keeps a concurrently rewritten config from producing a mixed record
  # assembled from different generations, without truncating arbitrary JSON.
  if ! jq -cS . "${config_file}" > "${temp_dir}/live.json"; then
    printf '[ERROR] %s_store_candidate: live configuration is invalid.\n' "${protocol}" >&2
    return 1
  fi
  config_file="${temp_dir}/live.json"
  if ! validate_live_inbound_inventory "${config_file}"; then
    printf '[ERROR] %s_store_candidate: live inbound inventory is not trusted.\n' "${protocol}" >&2
    return 1
  fi

  # Reject fields that this typed schema cannot reproduce.  In particular,
  # TLS, multiple users, and listen options must never disappear during a
  # takeover.  Missing users means unauthenticated Mixed; set_system_proxy is
  # accepted only in its generated/default false form.
  if [[ "$(config_protocol_inbound_count "${protocol}" "${config_file}" 2>/dev/null || printf 0)" -le 0 ]]; then
    printf '[ERROR] %s_store_candidate: no plain-proxy inbound found.\n' "${protocol}" >&2
    return 1
  fi
  if ! jq -e '
    def target:
      if $protocol == "vless-plain" then (.type == "vless" and (.tls.reality? == null))
      else .type == $protocol end;
    def valid_snell_obfs_host:
      if . == "" then true
      else type == "string" and length > 0 and utf8bytelength <= 255 and
        (test("[\u0000-\u001F\u007F]") | not)
      end;
    (.inbounds // []) | all(.[];
      if (target | not) then true
      else
        ((keys_unsorted - (["type", "tag", "listen", "listen_port", "users", "set_system_proxy"] +
          (if $protocol == "http" then ["tls"]
           elif $protocol == "shadowsocks" then ["network", "method", "password"]
           elif $protocol == "trojan" or $protocol == "vmess" or $protocol == "vless-plain" then ["tls", "transport"]
           elif $protocol == "anytls" then ["tls"]
           elif $protocol == "hy2" then ["tls", "up_mbps", "down_mbps", "obfs", "masquerade"]
           elif $protocol == "snell" then ["version", "psk", "users", "obfs_mode", "obfs_host", "mode"]
           elif $protocol == "tuic" then ["tls", "users", "congestion_control", "auth_timeout", "zero_rtt_handshake", "heartbeat"]
           elif $protocol == "hysteria" then ["tls", "users", "up_mbps", "down_mbps", "obfs", "initial_packet_size", "disable_path_mtu_discovery", "stream_receive_window", "connection_receive_window", "max_concurrent_streams"]
           elif $protocol == "naive" then ["tls", "users", "network", "quic_congestion_control"]
           else [] end)) | length == 0))
        and (if has("tag") then (.tag | type == "string" and length > 0 and (test("[\u0000-\u001F\u007F]") | not)) else true end)
        and (if has("listen") then (.listen | type == "string" and length > 0) else true end)
        and (if has("listen_port") then (.listen_port | type == "number" and floor == . and . >= 1 and . <= 65535) else true end)
        and (if $protocol == "shadowsocks" then
              (has("method") and (.method | type == "string" and
                IN("none", "aes-128-gcm", "aes-192-gcm", "aes-256-gcm",
                   "chacha20-ietf-poly1305", "xchacha20-ietf-poly1305",
                   "2022-blake3-aes-128-gcm", "2022-blake3-aes-256-gcm",
                   "2022-blake3-chacha20-poly1305"))) and
              (has("password") and (.password | type == "string" and index("\u0000") == null)) and
              (if has("users") then
                (.users | type == "array" and length <= 128 and all(.[];
                  type == "object" and ((keys_unsorted | sort) == ["name", "password"]) and
                  (.name | type == "string" and length > 0 and (test("[\u0000-\u001F\u007F]") | not)) and
                  (.password | type == "string" and length > 0 and index("\u0000") == null)))
               else true end)
             elif $protocol == "anytls" then
              (.users | type == "array" and length >= 1 and length <= 128 and
                all(.[]; type == "object" and ((keys_unsorted | sort) == ["name", "password"]) and
                  (.name | type == "string" and length > 0 and utf8bytelength <= 256 and (test("[\u0000-\u001F\u007F]") | not)) and
                  (.password | type == "string" and length > 0 and utf8bytelength <= 4096 and index("\u0000") == null)) and
                (map(.name) | unique | length) == length and (map(.password) | unique | length) == length)
             elif $protocol == "hy2" then
              (.users | type == "array" and length >= 1 and length <= 128 and
                all(.[]; type == "object" and ((keys_unsorted | sort) == ["name", "password"]) and
                  (.name | type == "string" and length > 0 and utf8bytelength <= 256 and (test("[\u0000-\u001F\u007F]") | not)) and
                  (.password | type == "string" and length > 0 and utf8bytelength <= 4096 and index("\u0000") == null)) and
                (map(.name) | unique | length) == length and (map(.password) | unique | length) == length)
             elif $protocol == "snell" then
              (.version | type == "number" and floor == . and IN(5,6)) and
              (.psk | type == "string" and length > 0 and utf8bytelength <= 255 and index("\u0000") == null and
                (test("[\u0000-\u001F\u007F]") | not)) and
              (.users // [] | type == "array" and length <= 128 and
                all(.[]; type == "object" and (keys_unsorted | sort) == ["name", "userkey"] and
                  (.name | type == "string" and length > 0 and utf8bytelength <= 256 and
                    (test("[\u0000-\u001F\u007F]") | not)) and
                  (.userkey | type == "string" and length > 0 and utf8bytelength <= 255 and
                    index("\u0000") == null and (test("[\u0000-\u001F\u007F]") | not))) and
                (map(.name) | unique | length) == length and (map(.userkey) | unique | length) == length) and
              (if .version == 5 then
                 (.mode // "") == "" and ((.obfs_mode // "none") | IN("none", "http")) and
                 # Snell v5 inbound config does not require the outbound
                 # obfs_host hint. Preserve it from typed metadata when
                 # available; a missing value is rejected later by the
                 # typed-record validator if no metadata can supply it.
                 (
                   ((.obfs_mode // "none") == "none" and (.obfs_host // "") == "") or
                   ((.obfs_mode // "none") == "http" and ((.obfs_host // "") | valid_snell_obfs_host))
                 )
               else
                 (.obfs_mode // "") == "" and (.obfs_host // "") == "" and
                 ((.mode // "") | IN("","default","unshaped","unsafe-raw")) and
                 (.psk | utf8bytelength >= 12)
               end)
             elif $protocol == "hysteria" then
              (.users | type == "array" and length >= 1 and length <= 128 and
                all(.[]; type == "object" and (keys_unsorted | sort) == ["auth_str","name"] and
                  (.name | type == "string" and length > 0 and utf8bytelength <= 256 and (test("[\u0000-\u001F\u007F]") | not)) and
                  (.auth_str | type == "string" and length > 0 and utf8bytelength <= 4096 and (test("[\u0000-\u001F\u007F]") | not))) and
                (map(.name) | unique | length) == length and (map(.auth_str) | unique | length) == length) and
              (.up_mbps | type == "number" and floor == . and . >= 1 and . <= 1000000) and
              (.down_mbps | type == "number" and floor == . and . >= 1 and . <= 1000000) and
              (if has("obfs") then (.obfs | type == "string" and length <= 4096 and (test("[\u0000-\u001F\u007F]") | not)) else true end) and
              (if has("initial_packet_size") then (.initial_packet_size | type == "number" and floor == . and . >= 0 and . <= 65535) else true end) and
              (if has("max_concurrent_streams") then (.max_concurrent_streams | type == "number" and floor == . and . >= 0 and . <= 65535) else true end) and
              (if has("disable_path_mtu_discovery") then (.disable_path_mtu_discovery | type == "boolean") else true end) and
              (if has("stream_receive_window") then (.stream_receive_window | type == "string" and length <= 64 and test("^$|^[0-9]+( ?(B|KB|MB|GB))$")) else true end) and
              (if has("connection_receive_window") then (.connection_receive_window | type == "string" and length <= 64 and test("^$|^[0-9]+( ?(B|KB|MB|GB))$")) else true end)
             elif $protocol == "naive" then
              (.users | type == "array" and length >= 1 and length <= 128 and
                all(.[]; type == "object" and (keys_unsorted | sort) == ["password","username"] and
                  (.username | type == "string" and length > 0 and utf8bytelength <= 4096 and index(":") == null and (test("[\u0000-\u001F\u007F]") | not)) and
                  (.password | type == "string" and length > 0 and utf8bytelength <= 4096 and (test("[\u0000-\u001F\u007F]") | not))) and
                (map(.username) | unique | length) == length)
             elif $protocol == "tuic" then
              (.users | type == "array" and length >= 1 and length <= 128 and
                all(.[]; type == "object" and (keys_unsorted | sort) == ["name","password","uuid"] and
                  (.name | type == "string" and length > 0 and utf8bytelength <= 256 and (test("[\u0000-\u001F\u007F]") | not)) and
                  (.password | type == "string" and length > 0 and utf8bytelength <= 4096 and index("\u0000") == null) and
                  (.uuid | type == "string" and test("^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$"))) and
                (map(.name) | unique | length) == length and (map(.uuid) | unique | length) == length and (map(.password) | unique | length) == length) and
              (if has("congestion_control") then (.congestion_control | type == "string" and IN("cubic","new_reno","bbr")) else true end) and
              (if has("auth_timeout") then (.auth_timeout | type == "string" and test("^[0-9]+s$") and (sub("s$";"")|tonumber) <= 86400) else true end) and
              (if has("heartbeat") then (.heartbeat | type == "string" and test("^[0-9]+s$") and (sub("s$";"")|tonumber) <= 86400) else true end) and
              (if has("zero_rtt_handshake") then (.zero_rtt_handshake | type == "boolean") else true end)
             elif $protocol == "trojan" then
              (.users | type == "array" and length >= 1 and length <= 128 and
                all(.[]; type == "object" and ((keys_unsorted | sort) == ["name", "password"]) and
                  (.name | type == "string" and length > 0 and utf8bytelength <= 256 and (test("[\u0000-\u001F\u007F]") | not)) and
                  (.password | type == "string" and length > 0 and utf8bytelength <= 4096 and index("\u0000") == null)) and
                (map(.name) | unique | length) == length and (map(.password) | unique | length) == length)
             elif $protocol == "vmess" then
              (.users | type == "array" and length >= 1 and length <= 128 and
                all(.[]; type == "object" and ((keys_unsorted | sort) == ["alterId", "name", "uuid"]) and
                  (.name | type == "string" and length > 0 and utf8bytelength <= 256 and (test("[\u0000-\u001F\u007F]") | not)) and
                  (.uuid | type == "string" and test("^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$")) and
                  (.alterId | type == "number" and floor == . and . >= 0 and . <= 65535)) and
                (map(.name) | unique | length) == length and (map(.uuid) | unique | length) == length)
             elif $protocol == "vless-plain" then
              (.users | type == "array" and length >= 1 and length <= 128 and
                all(.[]; type == "object" and
                  ((keys_unsorted | sort) == ["name", "uuid"] or
                   (keys_unsorted | sort) == ["flow", "name", "uuid"]) and
                  (.name | type == "string" and length > 0 and utf8bytelength <= 256 and (test("[\u0000-\u001F\u007F]") | not)) and
                  (.uuid | type == "string" and test("^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$")) and
                  ((.flow // "") | type == "string" and IN("", "xtls-rprx-vision"))) and
                (map(.name) | unique | length) == length and (map(.uuid) | unique | length) == length)
             elif has("users") then
              (.users | type == "array" and length <= 1 and
                all(.[ ]; type == "object" and
                  ((keys_unsorted | sort) == ["password", "username"]) and
                  (.username | type == "string" and length > 0 and index("\u0000") == null) and
                  (.password | type == "string" and length > 0 and index("\u0000") == null)) )
             else true end)
        and (if $protocol == "shadowsocks" or $protocol == "naive" then
              (if has("network") then
                (.network | if type == "string" then [.]
                  elif type == "array" then (if length == 0 then ["tcp", "udp"] else . end)
                  elif . == null then ["tcp", "udp"]
                  else error("invalid network") end) |
                (length > 0 and length <= 2 and all(.[]; . == "tcp" or . == "udp") and
                 (sort | unique) == .)
               else true end)
             else true end)
        and (if $protocol == "mixed" then
             (if has("set_system_proxy") then .set_system_proxy == false else true end)
             elif $protocol == "http" or $protocol == "trojan" or $protocol == "vmess" or $protocol == "vless-plain" or $protocol == "anytls" or $protocol == "hy2" or $protocol == "tuic" or $protocol == "hysteria" or $protocol == "naive" then
              ((if has("set_system_proxy") then $protocol == "http" and .set_system_proxy == false else true end)
              and (if has("tls") then
                (.tls | type == "object") and
                  (if .tls.enabled == false then
                    ($protocol != "anytls" and $protocol != "hy2" and $protocol != "tuic" and $protocol != "hysteria" and $protocol != "naive" and (.tls | keys_unsorted | sort) == ["enabled"])
                  elif .tls.enabled == true then
                    ((.tls | (if $protocol == "trojan" or $protocol == "vmess" or $protocol == "vless-plain" or $protocol == "tuic" or $protocol == "hysteria" or $protocol == "naive" then del(.alpn) else . end) | keys_unsorted | sort) == ["certificate_path", "enabled", "key_path", "server_name"]) and
                    (.tls.server_name | type == "string" and length > 0 and (test("[\u0000-\u001F\u007F]") | not)) and
                    (.tls.certificate_path | type == "string" and startswith("/") and (test("[\u0000-\u001F\u007F]") | not)) and
                    (.tls.key_path | type == "string" and startswith("/") and (test("[\u0000-\u001F\u007F]") | not))
                  else false end)
                else $protocol != "anytls" end))
             else
              (has("set_system_proxy") | not)
             end)
      end)
    ' --arg protocol "${protocol}" "${config_file}" >/dev/null 2>&1; then
    printf '[ERROR] %s_store_candidate: plain-proxy inbound contains unsupported or lossy fields.\n' "${protocol}" >&2
    return 1
  fi

  # Existing structured metadata is authoritative only when the root marker
  # says that schema 2 is active.  A valid but orphaned JSON file must not
  # silently rename legacy nodes.  The helper is supplied by the structured
  # state layer; the raw schema check keeps this function usable during the
  # pre-publication phase of takeover.
  state_file=$(protocol_state_file "${protocol}") || return 1
  if [[ -f "${state_file}" ]] &&
     grep -Eq "^[[:space:]]*CONFIG_SCHEMA_VERSION=" "${state_file}"; then
    if [[ "${protocol}" == "mixed" ]]; then
      validate_protocol_state_schema "${protocol}" "${state_file}" || return 1
    else
      plain_proxy_structured_marker_is_valid "${state_file}" || return 1
    fi
  fi
  active_state=n
  if plain_proxy_structured_state_active "${protocol}" >/dev/null 2>&1; then
    active_state=y
  fi
  state_schema="1"
  if [[ -f "${state_file}" ]]; then
    state_schema=$(sed -n 's/^[[:space:]]*CONFIG_SCHEMA_VERSION=//p' "${state_file}" | head -n1) || return 1
    state_schema=${state_schema//\"/}
    state_schema=${state_schema//\'/}
  fi
  if [[ -z "${existing_file}" ]]; then
    if existing_file=$(plain_proxy_structured_store_file "${protocol}" 2>/dev/null); then :; else existing_file="${SB_PROTOCOL_STATE_DIR}/instances/${protocol}.json"; fi
  fi
  store_file="${existing_file}"
  if [[ "${state_schema}" == "2" ]]; then
    marker_schema2=y
  fi
  if [[ "${protocol}" != "mixed" && "${protocol}" != "anytls" && "${protocol}" != "hy2" && "${protocol}" != "tuic" && "${protocol}" != "hysteria" && "${protocol}" != "naive" && -f "${state_file}" && "${state_schema}" != "2" ]]; then
    printf '[ERROR] %s_store_candidate: legacy state migration is unsupported.\n' "${protocol}" >&2
    return 1
  fi
  if [[ "${marker_schema2}" == "y" || "${active_state}" == "y" ]]; then
    [[ -f "${store_file}" && ! -L "${store_file}" ]] || {
      printf '[ERROR] %s_store_candidate: active %s store is missing.\n' "${protocol}" "${protocol_label}" >&2
      return 1
    }
    validate_structured_instance_store "${protocol}" "${store_file}" || return 1
    store_instances=$(jq -r '.instances | length' "${store_file}") || return 1
    [[ "${store_instances}" =~ ^[0-9]+$ && "${store_instances}" -gt 0 ]] || {
      printf '[ERROR] %s_store_candidate: empty or orphaned %s store cannot be reused.\n' "${protocol}" "${protocol_label}" >&2
      return 1
    }
    active_state=y
  elif [[ -e "${store_file}" || -L "${store_file}" ]]; then
    # A tombstone belongs to the delete transaction and is not legacy
    # metadata.  Refuse both empty and non-empty orphan stores so a fresh
    # takeover cannot accidentally reuse stale identities.
    printf '[ERROR] %s_store_candidate: orphaned %s store requires explicit recovery.\n' "${protocol}" "${protocol_label}" >&2
    return 1
  else
    store_file=""
  fi

  legacy_name=""
  if [[ -f "${state_file}" && "${state_schema}" == "1" ]]; then
    legacy_name=$(
      unset NODE_NAME
      # shellcheck disable=SC1090
      source "${state_file}"
      # Keep the sentinel outside command substitution's newline-stripping
      # boundary so a legacy name ending in one or more newlines is exact.
      printf '%s\1' "${NODE_NAME:-}"
    ) || return 1
    legacy_name=${legacy_name%$'\1'}
  fi

  if [[ -n "${store_file}" ]]; then
    existing_store_json=$(jq -cS . "${store_file}") || return 1
    old_revision=$(jq -r '.revision' <<< "${existing_store_json}") || return 1
  else
    existing_store_json=$(structured_instance_store_empty_json "${protocol}") || return 1
    old_revision=0
  fi

  inbound_count=$(config_protocol_inbound_count "${protocol}" "${config_file}") || return 1
  [[ "${inbound_count}" =~ ^[0-9]+$ && "${inbound_count}" -gt 0 ]] || return 1
  : > "${temp_dir}/instances.jsonl" || return 1

  # Config order is not identity.  Stable tags select the prior record; a
  # previously unseen tag gets a deterministic, collision-free ID and keeps
  # the live tag verbatim.
  for ((inbound_index = 0; inbound_index < inbound_count; inbound_index++)); do
    inbound_json=$(config_protocol_inbounds_jsonl "${protocol}" "${config_file}" | sed -n "$((inbound_index + 1))p") || return 1
    tag=$(jq -r '.tag // empty' <<< "${inbound_json}") || return 1
    if [[ -z "${tag}" ]]; then
      if [[ "${inbound_count}" == "1" && "${active_state}" != "y" ]]; then
        tag="${protocol}-in"
      else
        printf '[ERROR] %s_store_candidate: %s inbound tag is required for stable identity.\n' "${protocol}" "${protocol_label}" >&2
        return 1
      fi
    fi
    # sing-box's plain-proxy listener defaults to loopback, while an omitted port
    # means an ephemeral listener.  The former is safe to materialize; the
    # latter cannot be represented in typed state and must fail closed for
    # every migration path.
    jq -e 'has("listen_port")' <<< "${inbound_json}" >/dev/null 2>&1 || {
      printf '[ERROR] %s_store_candidate: %s listen_port must be explicit; ephemeral ports are not recoverable.\n' "${protocol}" "${protocol_label}" >&2
      return 1
    }
    address=$(jq -r '.listen // empty' <<< "${inbound_json}") || return 1
    if [[ -z "${address}" ]]; then
      address='127.0.0.1'
    fi
    port=$(jq -r '.listen_port' <<< "${inbound_json}") || return 1
    structured_instance_store_validate_address "${address}" || {
      printf '[ERROR] %s_store_candidate: %s listen address is unsupported.\n' "${protocol}" "${protocol_label}" >&2
      return 1
    }

    network_json='["tcp","udp"]'
    ss_method=""
    ss_password=""
    ss_users_json='[]'
    if [[ "${protocol}" == "shadowsocks" ]]; then
      ss_method=$(jq -r '.method' <<< "${inbound_json}") || return 1
      ss_password=$(jq -j '.password, "\u0001"' <<< "${inbound_json}") || return 1
      ss_password=${ss_password%$'\1'}
      ss_users_json=$(jq -c '.users // []' <<< "${inbound_json}") || return 1
      network_json=$(jq -c '
        if (.network == null or .network == []) then ["tcp", "udp"]
        elif (.network | type) == "string" then [.network]
        else .network
        end | sort | unique
      ' <<< "${inbound_json}") || return 1
    fi

    tls_json='null'
    if [[ "${protocol}" == "http" || "${protocol}" == "trojan" || "${protocol}" == "vmess" || "${protocol}" == "vless-plain" || "${protocol}" == "anytls" || "${protocol}" == "hy2" || "${protocol}" == "tuic" || "${protocol}" == "hysteria" || "${protocol}" == "naive" ]]; then
      tls_json=$(jq -c '.tls // {enabled:false}' <<< "${inbound_json}") || return 1
    fi

    username=""
    password=""
    auth_enabled=false
    if [[ "${protocol}" == "trojan" ]]; then
      trojan_users_json=$(jq -c '.users' <<< "${inbound_json}") || return 1
      trojan_transport_json=$(jq -c '.transport // {type:"none"}' <<< "${inbound_json}") || return 1
      trojan_client_trust=certificate
      if jq -e '.enabled == true' <<< "${tls_json}" >/dev/null 2>&1; then
        :
      else
        trojan_client_trust=system
      fi
      trojan_profile=$(build_v2ray_transport_profile_json trojan "${trojan_transport_json}" \
        "$(jq -r 'if .enabled == true then "tls" else "disabled" end' <<< "${tls_json}")" "" \
        "$(resolve_config_target_singbox_version)") || {
        printf '[ERROR] %s_store_candidate: unsupported Trojan transport profile.\n' "${protocol}" >&2
        return 1
      }
      # Accept only the ALPN implied by the managed transport. Arbitrary live
      # ALPN cannot be discarded during takeover. The typed TLS record stores
      # user-owned trust paths; its renderer derives this ALPN again.
      if ! jq -e --argjson profile "${trojan_profile}" \
          'if has("alpn") then .alpn == $profile.tls_alpn else true end' <<< "${tls_json}" >/dev/null; then
        printf '[ERROR] trojan_store_candidate: unsupported TLS ALPN; 已保留原配置。\n' >&2
        return 1
      fi
      tls_json=$(jq -c 'del(.alpn)' <<< "${tls_json}") || return 1
    elif [[ "${protocol}" == "vmess" ]]; then
      vmess_users_json=$(jq -c '.users' <<< "${inbound_json}") || return 1
      vmess_users_json=$(jq -c 'map({name,uuid,alter_id:(.alterId // 0),security:"auto"})' <<< "${vmess_users_json}") || return 1
      vmess_transport_json=$(jq -c '.transport // {type:"none"}' <<< "${inbound_json}") || return 1
      vmess_client_trust=system
      if jq -e '.enabled == true' <<< "${tls_json}" >/dev/null 2>&1; then :; else vmess_client_trust=system; fi
      vmess_profile=$(build_v2ray_transport_profile_json vmess "${vmess_transport_json}" "$(jq -r 'if .enabled == true then "tls" else "disabled" end' <<< "${tls_json}")" "" "$(resolve_config_target_singbox_version)") || {
        printf '[ERROR] %s_store_candidate: unsupported VMess transport profile.\n' "${protocol}" >&2
        return 1
      }
      if ! jq -e --argjson profile "${vmess_profile}" 'if has("alpn") then .alpn == $profile.tls_alpn else true end' <<< "${tls_json}" >/dev/null; then
        printf '[ERROR] vmess_store_candidate: unsupported TLS ALPN; 已保留原配置。\n' >&2
        return 1
      fi
      tls_json=$(jq -c 'del(.alpn)' <<< "${tls_json}") || return 1
    elif [[ "${protocol}" == "vless-plain" ]]; then
      vless_users_json=$(jq -c '.users | map({name,uuid,flow:(.flow // "")})' <<< "${inbound_json}") || return 1
      vless_transport_json=$(jq -c '.transport // {type:"none"}' <<< "${inbound_json}") || return 1
      vless_client_trust=system
      if jq -e '.enabled == true' <<< "${tls_json}" >/dev/null 2>&1; then
        vless_client_trust=certificate
      fi
      vless_flow_list=$(jq -r '.[] | .flow // ""' <<< "${vless_users_json}") || return 1
      while IFS= read -r vless_flow; do
        vless_profile=$(build_v2ray_transport_profile_json vless "${vless_transport_json}" \
          "$(jq -r 'if .enabled == true then "tls" else "disabled" end' <<< "${tls_json}")" \
          "${vless_flow}" "$(resolve_config_target_singbox_version)") || {
          printf '[ERROR] %s_store_candidate: unsupported VLESS transport profile.\n' "${protocol}" >&2
          return 1
        }
      done <<< "${vless_flow_list}"
      if ! jq -e --argjson profile "${vless_profile}" 'if has("alpn") then .alpn == $profile.tls_alpn else true end' <<< "${tls_json}" >/dev/null; then
        printf '[ERROR] vless_store_candidate: unsupported TLS ALPN; 已保留原配置。\n' >&2
        return 1
      fi
      tls_json=$(jq -c 'del(.alpn)' <<< "${tls_json}") || return 1
    elif [[ "${protocol}" == "anytls" ]]; then
      anytls_users_json=$(jq -c '.users' <<< "${inbound_json}") || return 1
      anytls_tls_json=$(jq -c '.tls' <<< "${inbound_json}") || return 1
      jq -e '.enabled == true and (keys_unsorted | sort) == ["certificate_path","enabled","key_path","server_name"]' <<< "${anytls_tls_json}" >/dev/null 2>&1 || {
        printf '[ERROR] %s_store_candidate: AnyTLS requires a manual TLS certificate that the typed state can preserve.\n' "${protocol}" >&2
        return 1
      }
      anytls_client_trust=system
    elif [[ "${protocol}" == "hy2" ]]; then
      hy2_users_json=$(jq -c '.users' <<< "${inbound_json}") || return 1
      hy2_tls_json=$(jq -c '.tls' <<< "${inbound_json}") || return 1
      jq -e '(.enabled == true) and ((del(.alpn) | keys_unsorted | sort) == ["certificate_path","enabled","key_path","server_name"]) and ((.alpn // ["h3"]) == ["h3"])' <<< "${hy2_tls_json}" >/dev/null 2>&1 || {
        printf '[ERROR] %s_store_candidate: Hysteria2 ACME/provider or unsupported TLS cannot be represented by the typed state.\n' "${protocol}" >&2
        return 1
      }
      hy2_tls_json=$(jq -c 'del(.alpn)' <<< "${hy2_tls_json}") || return 1
      hy2_bandwidth_json=$(jq -c '{up_mbps:(.up_mbps // null),down_mbps:(.down_mbps // null)}' <<< "${inbound_json}") || return 1
      hy2_obfs_json=$(jq -c 'if .obfs == null then {enabled:false,type:"",password:""} else {enabled:true,type:(.obfs.type // ""),password:(.obfs.password // "")} end' <<< "${inbound_json}") || return 1
      hy2_masquerade=$(jq -j '.masquerade // "", "\u0001"' <<< "${inbound_json}") || return 1
      hy2_masquerade=${hy2_masquerade%$'\1'}
      hy2_client_trust=system
    elif [[ "${protocol}" == "snell" ]]; then
      snell_version=$(jq -r '.version // 6' <<< "${inbound_json}") || return 1
      snell_psk=$(jq -j '.psk // "", "\u0001"' <<< "${inbound_json}") || return 1
      snell_psk=${snell_psk%$'\1'}
      snell_users_json=$(jq -c '.users // []' <<< "${inbound_json}") || return 1
      snell_obfs_mode=$(jq -j '.obfs_mode // "", "\u0001"' <<< "${inbound_json}") || return 1
      snell_obfs_mode=${snell_obfs_mode%$'\1'}
      snell_obfs_host=$(jq -j '.obfs_host // "", "\u0001"' <<< "${inbound_json}") || return 1
      snell_obfs_host=${snell_obfs_host%$'\1'}
      snell_mode=$(jq -j '.mode // "", "\u0001"' <<< "${inbound_json}") || return 1
      snell_mode=${snell_mode%$'\1'}
      [[ "${snell_version}" =~ ^(5|6)$ && -n "${snell_psk}" ]] || {
        printf '[ERROR] %s_store_candidate: Snell version or PSK is invalid.\n' "${protocol}" >&2
        return 1
      }
      if [[ "${snell_version}" == "5" ]]; then
        [[ -n "${snell_obfs_mode}" ]] || snell_obfs_mode=none
        [[ "${snell_obfs_mode}" == "none" || "${snell_obfs_mode}" == "http" ]] || return 1
        snell_mode=""
      else
        snell_obfs_mode=""
        snell_mode=${snell_mode:-default}
        [[ "${snell_mode}" == "default" || "${snell_mode}" == "unshaped" || "${snell_mode}" == "unsafe-raw" ]] || return 1
      fi
    elif [[ "${protocol}" == "tuic" ]]; then
      tuic_users_json=$(jq -c '.users' <<< "${inbound_json}") || return 1
      tuic_tls_json=$(jq -c '.tls' <<< "${inbound_json}") || return 1
      jq -e '(.enabled == true) and ((del(.alpn) | keys_unsorted | sort) == ["certificate_path","enabled","key_path","server_name"]) and ((.alpn // ["h3"]) == ["h3"])' <<< "${tuic_tls_json}" >/dev/null 2>&1 || {
        printf '[ERROR] %s_store_candidate: TUIC requires manual TLS certificate material and h3 ALPN.\n' "${protocol}" >&2
        return 1
      }
      tuic_tls_json=$(jq -c 'del(.alpn)' <<< "${tuic_tls_json}") || return 1
      tuic_congestion_control=$(jq -r '.congestion_control // "bbr"' <<< "${inbound_json}") || return 1
      tuic_auth_timeout_seconds=$(jq -r '(.auth_timeout // "3s") | sub("s$";"") | tonumber' <<< "${inbound_json}") || return 1
      tuic_heartbeat_seconds=$(jq -r '(.heartbeat // "10s") | sub("s$";"") | tonumber' <<< "${inbound_json}") || return 1
      tuic_zero_rtt_handshake=$(jq -r 'if .zero_rtt_handshake == true then true else false end' <<< "${inbound_json}") || return 1
      tuic_udp_relay_mode=$(jq -r '.udp_relay_mode // "native"' <<< "${inbound_json}") || return 1
      tuic_udp_over_stream=$(jq -r 'if .udp_over_stream == true then true else false end' <<< "${inbound_json}") || return 1
      [[ "${tuic_congestion_control}" == cubic || "${tuic_congestion_control}" == new_reno || "${tuic_congestion_control}" == bbr ]] || return 1
      [[ "${tuic_auth_timeout_seconds}" =~ ^[0-9]+$ && "${tuic_auth_timeout_seconds}" -le 86400 ]] || return 1
      [[ "${tuic_heartbeat_seconds}" =~ ^[0-9]+$ && "${tuic_heartbeat_seconds}" -le 86400 ]] || return 1
      if [[ "${tuic_udp_over_stream}" == true ]]; then
        [[ "${tuic_udp_relay_mode}" == native ]] && tuic_udp_relay_mode=""
        [[ -z "${tuic_udp_relay_mode}" ]] || return 1
      else
        [[ "${tuic_udp_relay_mode}" == native || "${tuic_udp_relay_mode}" == quic ]] || return 1
      fi
    elif [[ "${protocol}" == "hysteria" ]]; then
      hysteria_users_json=$(jq -c '.users' <<< "${inbound_json}") || return 1
      hysteria_tls_json=$(jq -c '.tls' <<< "${inbound_json}") || return 1
      jq -e '(.enabled == true) and ((del(.alpn) | keys_unsorted | sort) == ["certificate_path","enabled","key_path","server_name"]) and ((.alpn // ["h3"]) == ["h3"])' <<< "${hysteria_tls_json}" >/dev/null 2>&1 || {
        printf '[ERROR] %s_store_candidate: Hysteria requires manual TLS certificate material and h3 ALPN.\n' "${protocol}" >&2
        return 1
      }
      hysteria_tls_json=$(jq -c 'del(.alpn)' <<< "${hysteria_tls_json}") || return 1
      hysteria_bandwidth_json=$(jq -c '{up_mbps:.up_mbps,down_mbps:.down_mbps}' <<< "${inbound_json}") || return 1
      jq -e '.up_mbps | type == "number" and floor == . and . >= 1 and . <= 1000000' <<< "${hysteria_bandwidth_json}" >/dev/null 2>&1 || return 1
      jq -e '.down_mbps | type == "number" and floor == . and . >= 1 and . <= 1000000' <<< "${hysteria_bandwidth_json}" >/dev/null 2>&1 || return 1
      hysteria_obfs_json=$(jq -c 'if has("obfs") then {enabled:true,password:.obfs} else {enabled:false,password:""} end' <<< "${inbound_json}") || return 1
      hysteria_quic_json=$(jq -c '{connection_receive_window:(.connection_receive_window // ""),disable_path_mtu_discovery:(.disable_path_mtu_discovery // false),initial_packet_size:(.initial_packet_size // 0),max_concurrent_streams:(.max_concurrent_streams // 0),stream_receive_window:(.stream_receive_window // "")}' <<< "${inbound_json}") || return 1
      jq -e '(.initial_packet_size | type == "number" and floor == . and . >= 0 and . <= 65535) and (.max_concurrent_streams | type == "number" and floor == . and . >= 0 and . <= 65535) and (.disable_path_mtu_discovery | type == "boolean") and (.stream_receive_window | type == "string" and length <= 64 and test("^$|^[0-9]+( ?(B|KB|MB|GB))$")) and (.connection_receive_window | type == "string" and length <= 64 and test("^$|^[0-9]+( ?(B|KB|MB|GB))$"))' <<< "${hysteria_quic_json}" >/dev/null 2>&1 || return 1
      hysteria_client_trust=system
    elif [[ "${protocol}" == "naive" ]]; then
      naive_users_json=$(jq -c '.users | map({name:(.username),username,password})' <<< "${inbound_json}") || return 1
      naive_tls_json=$(jq -c '.tls' <<< "${inbound_json}") || return 1
      jq -e '(.enabled == true) and ((del(.alpn) | keys_unsorted | sort) == ["certificate_path","enabled","key_path","server_name"]) and
        (.server_name | type == "string" and length > 0 and (test("[\u0000-\u001F\u007F]") | not)) and
        (.certificate_path | type == "string" and startswith("/")) and (.key_path | type == "string" and startswith("/"))' <<< "${naive_tls_json}" >/dev/null 2>&1 || {
        printf '[ERROR] %s_store_candidate: NaiveProxy requires manual TLS certificate material.\n' "${protocol}" >&2
        return 1
      }
      naive_tls_json=$(jq -c 'del(.alpn)' <<< "${naive_tls_json}") || return 1
      naive_network_json=$(jq -c 'if .network == null then ["tcp","udp"] elif (.network | type) == "string" then [.network] else .network end | sort | unique' <<< "${inbound_json}") || return 1
      naive_quic_congestion_control=$(jq -r '.quic_congestion_control // "bbr"' <<< "${inbound_json}") || return 1
      [[ "${naive_quic_congestion_control}" == bbr || "${naive_quic_congestion_control}" == cubic || "${naive_quic_congestion_control}" == reno ]] || return 1
      # The live inbound has no client-only Naive options. Keep their typed
      # defaults, or preserve them when a tag already exists below.
      naive_client_trust=system
    elif jq -e '.users | length > 0' <<< "${inbound_json}" >/dev/null 2>&1; then
      auth_enabled=true
      username=$(jq -j '.users[0].username, "\u0001"' <<< "${inbound_json}") || return 1
      username=${username%$'\1'}
      password=$(jq -j '.users[0].password, "\u0001"' <<< "${inbound_json}") || return 1
      password=${password%$'\1'}
    fi
    # This extractor deliberately rejects more than one matching route.  A
    # route target unknown to the managed model is equally unsafe to flatten.
    if ! policy=$(vless_reality_outbound_policy_from_config "${tag}" "${config_file}"); then
      printf '[ERROR] %s_store_candidate: %s outbound policy is ambiguous or unsupported.\n' "${protocol}" "${protocol_label}" >&2
      return 1
    fi

    id=""
    name=""
    if [[ -n "${store_file}" ]]; then
      existing_match=$(jq -c --arg tag "${tag}" '[.instances[] | select(.tag == $tag)]' "${store_file}") || return 1
      if [[ "$(jq 'length' <<< "${existing_match}")" == "1" ]]; then
        id=$(jq -r '.[0].id' <<< "${existing_match}")
        name=$(jq -j '.[0].name, "\u0001"' <<< "${existing_match}") || return 1
        name=${name%$'\1'}
        if [[ "${protocol}" == "trojan" ]]; then
          trojan_client_trust=$(jq -r '.[0].client_trust // "certificate"' <<< "${existing_match}") || return 1
        elif [[ "${protocol}" == "vmess" ]]; then
          vmess_client_trust=$(jq -r '.[0].client_trust // "system"' <<< "${existing_match}") || return 1
          vmess_users_json=$(jq -c --argjson live "${vmess_users_json}" '.[0].authentication.users as $old | $live | map(. as $u | (($old[]? | select(.name == $u.name and .uuid == $u.uuid) | .security) // "auto") as $security | .security=$security)' <<< "${existing_match}") || return 1
        elif [[ "${protocol}" == "vless-plain" ]]; then
          vless_client_trust=$(jq -r '.[0].client_trust // "system"' <<< "${existing_match}") || return 1
        elif [[ "${protocol}" == "anytls" ]]; then
          anytls_client_trust=$(jq -r '.[0].client_trust // "system"' <<< "${existing_match}") || return 1
        elif [[ "${protocol}" == "hy2" ]]; then
          hy2_client_trust=$(jq -r '.[0].client_trust // "system"' <<< "${existing_match}") || return 1
        elif [[ "${protocol}" == "snell" ]]; then
          existing_snell_obfs_host=$(jq -r '.[0].obfs_host // ""' <<< "${existing_match}") || return 1
          [[ -z "${existing_snell_obfs_host}" ]] || snell_obfs_host=${existing_snell_obfs_host}
        elif [[ "${protocol}" == "tuic" ]]; then
          tuic_client_trust=$(jq -r '.[0].client_trust // "system"' <<< "${existing_match}") || return 1
          if ! jq -e 'has("congestion_control")' <<< "${inbound_json}" >/dev/null 2>&1; then tuic_congestion_control=$(jq -r '.[0].tuic.congestion_control // "bbr"' <<< "${existing_match}") || return 1; fi
          if ! jq -e 'has("auth_timeout")' <<< "${inbound_json}" >/dev/null 2>&1; then tuic_auth_timeout_seconds=$(jq -r '.[0].tuic.auth_timeout_seconds // 3' <<< "${existing_match}") || return 1; fi
          if ! jq -e 'has("heartbeat")' <<< "${inbound_json}" >/dev/null 2>&1; then tuic_heartbeat_seconds=$(jq -r '.[0].tuic.heartbeat_seconds // 10' <<< "${existing_match}") || return 1; fi
          if ! jq -e 'has("zero_rtt_handshake")' <<< "${inbound_json}" >/dev/null 2>&1; then tuic_zero_rtt_handshake=$(jq -r '.[0].tuic.zero_rtt_handshake // false' <<< "${existing_match}") || return 1; fi
          if ! jq -e 'has("udp_relay_mode") or has("udp_over_stream")' <<< "${inbound_json}" >/dev/null 2>&1; then
            tuic_udp_relay_mode=$(jq -r '.[0].tuic.udp_relay_mode // "native"' <<< "${existing_match}") || return 1
            tuic_udp_over_stream=$(jq -r '.[0].tuic.udp_over_stream // false' <<< "${existing_match}") || return 1
          elif ! jq -e 'has("udp_relay_mode")' <<< "${inbound_json}" >/dev/null 2>&1; then
            tuic_udp_relay_mode=""
          elif ! jq -e 'has("udp_over_stream")' <<< "${inbound_json}" >/dev/null 2>&1; then
            tuic_udp_over_stream=false
          fi
        elif [[ "${protocol}" == "hysteria" ]]; then
          hysteria_client_trust=$(jq -r '.[0].client_trust // "system"' <<< "${existing_match}") || return 1
          if ! jq -e 'has("up_mbps")' <<< "${inbound_json}" >/dev/null 2>&1; then hysteria_bandwidth_json=$(jq -c '.[0].bandwidth' <<< "${existing_match}") || return 1; fi
          if ! jq -e 'has("obfs")' <<< "${inbound_json}" >/dev/null 2>&1; then hysteria_obfs_json=$(jq -c '.[0].obfs' <<< "${existing_match}") || return 1; fi
          if ! jq -e 'has("initial_packet_size") or has("disable_path_mtu_discovery") or has("stream_receive_window") or has("connection_receive_window") or has("max_concurrent_streams")' <<< "${inbound_json}" >/dev/null 2>&1; then hysteria_quic_json=$(jq -c '.[0].hysteria' <<< "${existing_match}") || return 1; fi
        elif [[ "${protocol}" == "naive" ]]; then
          naive_client_trust=$(jq -r '.[0].client_trust // "system"' <<< "${existing_match}") || return 1
          if ! jq -e 'has("quic_congestion_control")' <<< "${inbound_json}" >/dev/null 2>&1; then naive_quic_congestion_control=$(jq -r '.[0].naive.quic_congestion_control // "bbr"' <<< "${existing_match}") || return 1; fi
          naive_quic=$(jq -r 'if .[0].naive.quic then true else false end' <<< "${existing_match}") || return 1
          naive_insecure_concurrency=$(jq -r '.[0].naive.insecure_concurrency // 0' <<< "${existing_match}") || return 1
          naive_stream_receive_window=$(jq -r '.[0].naive.stream_receive_window // ""' <<< "${existing_match}") || return 1
          naive_quic_session_receive_window=$(jq -r '.[0].naive.quic_session_receive_window // ""' <<< "${existing_match}") || return 1
          naive_extra_headers_json=$(jq -c '.[0].naive.extra_headers // {}' <<< "${existing_match}") || return 1
        fi
      elif [[ "$(jq 'length' <<< "${existing_match}")" -gt 1 ]]; then
        printf '[ERROR] %s_store_candidate: duplicate stored %s identity.\n' "${protocol}" "${protocol_label}" >&2
        return 1
      fi
    elif [[ "${inbound_count}" == "1" && "${state_schema}" == "1" ]]; then
      id="main"
      name="${legacy_name}"
    fi

    if [[ -z "${id}" ]]; then
      if structured_instance_store_validate_id "${tag}"; then
        base="${tag}"
      else
        digest=$(printf '%s' "${tag}" | sha256sum) || return 1
        base="${protocol}-${digest%% *}"
        base=${base:0:48}
      fi
      id="${base}"
      suffix=2
      while {
        jq -e -s --arg id "${id}" '[.[] | select(.id == $id)] | length > 0' "${temp_dir}/instances.jsonl" >/dev/null 2>&1 ||
          { [[ -n "${store_file}" ]] && jq -e --arg id "${id}" 'any(.instances[]; .id == $id)' "${store_file}" >/dev/null 2>&1; };
      }; do
        id="${base}-${suffix}"
        suffix=$((suffix + 1))
      done
      name="${tag}"
    fi
    [[ -n "${name}" ]] || name="${tag}"
    if [[ "${protocol}" == "http" ]]; then
      jq -n -cS \
      --arg id "${id}" --arg name "${name}" --arg tag "${tag}" \
      --arg address "${address}" --argjson port "${port}" \
      --argjson auth_enabled "${auth_enabled}" --arg username "${username}" --arg password "${password}" \
      --arg policy "${policy}" --argjson tls "${tls_json}" \
      '{id:$id,name:$name,tag:$tag,listen:{address:$address,port:$port},authentication:{enabled:$auth_enabled,username:$username,password:$password},outbound_policy:$policy,tls:$tls,dependencies:[]}' \
      >> "${temp_dir}/instances.jsonl" || return 1
    elif [[ "${protocol}" == "trojan" ]]; then
      jq -n -cS \
      --arg id "${id}" --arg name "${name}" --arg tag "${tag}" \
      --arg address "${address}" --argjson port "${port}" --argjson users "${trojan_users_json}" \
      --arg policy "${policy}" --argjson tls "${tls_json}" --argjson transport "${trojan_transport_json}" \
      --arg client_trust "${trojan_client_trust}" \
      '{id:$id,name:$name,tag:$tag,listen:{address:$address,port:$port},authentication:{users:$users},tls:$tls,transport:$transport,client_trust:$client_trust,outbound_policy:$policy,dependencies:[]}' \
      >> "${temp_dir}/instances.jsonl" || return 1
    elif [[ "${protocol}" == "vmess" ]]; then
      jq -n -cS \
      --arg id "${id}" --arg name "${name}" --arg tag "${tag}" \
      --arg address "${address}" --argjson port "${port}" --argjson users "${vmess_users_json}" \
      --arg policy "${policy}" --argjson tls "${tls_json}" --argjson transport "${vmess_transport_json}" \
      --arg client_trust "${vmess_client_trust}" \
      '{id:$id,name:$name,tag:$tag,listen:{address:$address,port:$port},authentication:{users:$users},tls:$tls,transport:$transport,client_trust:$client_trust,outbound_policy:$policy,dependencies:[]}' \
      >> "${temp_dir}/instances.jsonl" || return 1
    elif [[ "${protocol}" == "vless-plain" ]]; then
      jq -n -cS \
      --arg id "${id}" --arg name "${name}" --arg tag "${tag}" \
      --arg address "${address}" --argjson port "${port}" --argjson users "${vless_users_json}" \
      --arg policy "${policy}" --argjson tls "${tls_json}" --argjson transport "${vless_transport_json}" \
      --arg client_trust "${vless_client_trust}" \
      '{id:$id,name:$name,tag:$tag,listen:{address:$address,port:$port},authentication:{users:$users},tls:$tls,transport:$transport,client_trust:$client_trust,outbound_policy:$policy,dependencies:[]}' \
      >> "${temp_dir}/instances.jsonl" || return 1
    elif [[ "${protocol}" == "anytls" ]]; then
      jq -n -cS \
      --arg id "${id}" --arg name "${name}" --arg tag "${tag}" \
      --arg address "${address}" --argjson port "${port}" --argjson users "${anytls_users_json}" \
      --argjson tls "${anytls_tls_json}" --arg client_trust "${anytls_client_trust}" --arg policy "${policy}" \
      '{id:$id,name:$name,tag:$tag,listen:{address:$address,port:$port},authentication:{users:$users},tls:$tls,client_trust:$client_trust,outbound_policy:$policy,dependencies:[]}' \
      >> "${temp_dir}/instances.jsonl" || return 1
    elif [[ "${protocol}" == "hy2" ]]; then
      jq -n -cS \
      --arg id "${id}" --arg name "${name}" --arg tag "${tag}" \
      --arg address "${address}" --argjson port "${port}" --argjson users "${hy2_users_json}" \
      --argjson tls "${hy2_tls_json}" --arg client_trust "${hy2_client_trust}" \
      --argjson bandwidth "${hy2_bandwidth_json}" --argjson obfs "${hy2_obfs_json}" \
      --arg masquerade "${hy2_masquerade}" --arg policy "${policy}" \
      '{id:$id,name:$name,tag:$tag,listen:{address:$address,port:$port},authentication:{users:$users},tls:$tls,client_trust:$client_trust,bandwidth:$bandwidth,obfs:$obfs,masquerade:$masquerade,outbound_policy:$policy,dependencies:[]}' \
      >> "${temp_dir}/instances.jsonl" || return 1
    elif [[ "${protocol}" == "snell" ]]; then
      jq -n -cS \
      --arg id "${id}" --arg name "${name}" --arg tag "${tag}" \
      --arg address "${address}" --argjson port "${port}" --argjson version "${snell_version}" \
      --arg psk "${snell_psk}" --argjson users "${snell_users_json}" \
      --arg obfs_mode "${snell_obfs_mode}" --arg obfs_host "${snell_obfs_host}" --arg mode "${snell_mode}" \
      --arg policy "${policy}" \
      '{id:$id,name:$name,tag:$tag,listen:{address:$address,port:$port},authentication:{psk:$psk,users:$users},version:$version,obfs_mode:$obfs_mode,obfs_host:$obfs_host,mode:$mode,outbound_policy:$policy,dependencies:[]}' \
      >> "${temp_dir}/instances.jsonl" || return 1
    elif [[ "${protocol}" == "tuic" ]]; then
      jq -n -cS \
      --arg id "${id}" --arg name "${name}" --arg tag "${tag}" \
      --arg address "${address}" --argjson port "${port}" --argjson users "${tuic_users_json}" \
      --argjson tls "${tuic_tls_json}" --arg trust "${tuic_client_trust}" \
      --arg congestion_control "${tuic_congestion_control}" --argjson auth_timeout_seconds "${tuic_auth_timeout_seconds}" \
      --argjson heartbeat_seconds "${tuic_heartbeat_seconds}" --argjson zero_rtt_handshake "${tuic_zero_rtt_handshake}" \
      --arg udp_relay_mode "${tuic_udp_relay_mode}" --argjson udp_over_stream "${tuic_udp_over_stream}" --arg policy "${policy}" \
      '{id:$id,name:$name,tag:$tag,listen:{address:$address,port:$port},authentication:{users:$users},tls:$tls,client_trust:$trust,tuic:{auth_timeout_seconds:$auth_timeout_seconds,congestion_control:$congestion_control,heartbeat_seconds:$heartbeat_seconds,udp_over_stream:$udp_over_stream,udp_relay_mode:$udp_relay_mode,zero_rtt_handshake:$zero_rtt_handshake},outbound_policy:$policy,dependencies:[]}' \
      >> "${temp_dir}/instances.jsonl" || return 1
    elif [[ "${protocol}" == "hysteria" ]]; then
      jq -n -cS \
      --arg id "${id}" --arg name "${name}" --arg tag "${tag}" \
      --arg address "${address}" --argjson port "${port}" --argjson users "${hysteria_users_json}" \
      --argjson tls "${hysteria_tls_json}" --arg trust "${hysteria_client_trust}" \
      --argjson bandwidth "${hysteria_bandwidth_json}" --argjson obfs "${hysteria_obfs_json}" --argjson hysteria "${hysteria_quic_json}" --arg policy "${policy}" \
      '{id:$id,name:$name,tag:$tag,listen:{address:$address,port:$port},authentication:{users:$users},tls:$tls,client_trust:$trust,bandwidth:$bandwidth,obfs:$obfs,hysteria:$hysteria,outbound_policy:$policy,dependencies:[]}' \
      >> "${temp_dir}/instances.jsonl" || return 1
    elif [[ "${protocol}" == "naive" ]]; then
      jq -n -cS \
      --arg id "${id}" --arg name "${name}" --arg tag "${tag}" \
      --arg address "${address}" --argjson port "${port}" --argjson users "${naive_users_json}" \
      --argjson tls "${naive_tls_json}" --arg trust "${naive_client_trust}" --argjson network "${naive_network_json}" \
      --arg cc "${naive_quic_congestion_control}" --argjson quic "${naive_quic}" --argjson insecure_concurrency "${naive_insecure_concurrency}" \
      --arg stream_receive_window "${naive_stream_receive_window}" --arg quic_session_receive_window "${naive_quic_session_receive_window}" \
      --argjson extra_headers "${naive_extra_headers_json}" --arg policy "${policy}" \
      '{id:$id,name:$name,tag:$tag,listen:{address:$address,port:$port,network:$network},authentication:{users:$users},tls:$tls,client_trust:$trust,naive:{extra_headers:$extra_headers,insecure_concurrency:$insecure_concurrency,quic:$quic,quic_congestion_control:$cc,quic_session_receive_window:$quic_session_receive_window,stream_receive_window:$stream_receive_window},outbound_policy:$policy,dependencies:[]}' \
      >> "${temp_dir}/instances.jsonl" || return 1
    elif [[ "${protocol}" == "shadowsocks" ]]; then
      jq -n -cS \
      --arg id "${id}" --arg name "${name}" --arg tag "${tag}" \
      --arg address "${address}" --argjson port "${port}" --argjson network "${network_json}" \
      --arg method "${ss_method}" --arg password "${ss_password}" --argjson users "${ss_users_json}" \
      --arg policy "${policy}" \
      '{id:$id,name:$name,tag:$tag,listen:{address:$address,port:$port,network:$network},authentication:{method:$method,password:$password,users:$users},outbound_policy:$policy,dependencies:[]}' \
      >> "${temp_dir}/instances.jsonl" || return 1
    else
      jq -n -cS \
      --arg id "${id}" --arg name "${name}" --arg tag "${tag}" \
      --arg address "${address}" --argjson port "${port}" \
      --argjson auth_enabled "${auth_enabled}" --arg username "${username}" --arg password "${password}" \
      --arg policy "${policy}" \
      '{id:$id,name:$name,tag:$tag,listen:{address:$address,port:$port},authentication:{enabled:$auth_enabled,username:$username,password:$password},outbound_policy:$policy,dependencies:[]}' \
      >> "${temp_dir}/instances.jsonl" || return 1
    fi
  done

  default_id=""
  if [[ -n "${store_file}" ]]; then
    default_id=$(jq -r '.default_instance_id' "${store_file}") || return 1
  fi
  if [[ -z "${default_id}" || ! $(jq -s --arg id "${default_id}" 'any(.[]; .id == $id)' "${temp_dir}/instances.jsonl") == true ]]; then
    default_id=$(jq -r -s 'sort_by(.tag) | .[0].id' "${temp_dir}/instances.jsonl") || return 1
  fi
  new_semantics=$(jq -s --arg default_id "${default_id}" '{default_instance_id:$default_id,instances:(sort_by(.tag))}' "${temp_dir}/instances.jsonl") || return 1
  old_semantics=$(jq -cS '{default_instance_id,instances:(.instances | sort_by(.tag))}' <<< "${existing_store_json}") || return 1
  new_semantics=$(jq -cS . <<< "${new_semantics}") || return 1
  candidate_revision="${old_revision}"
  if [[ "${old_semantics}" != "${new_semantics}" ]]; then
    [[ "${old_revision}" -lt 9007199254740991 ]] || {
      printf '[ERROR] %s_store_candidate: revision exhausted.\n' "${protocol}" >&2
      return 1
    }
    candidate_revision=$((old_revision + 1))
  fi
  candidate_json=$(jq -n -cS --arg protocol "${protocol}" --argjson revision "${candidate_revision}" --argjson semantics "${new_semantics}" '{schema_version:1,protocol:$protocol,revision:$revision,default_instance_id:$semantics.default_instance_id,instances:$semantics.instances}') || return 1
  printf '%s\n' "${candidate_json}" > "${temp_dir}/candidate.json" || return 1
  validate_structured_instance_store "${protocol}" "${temp_dir}/candidate.json" || return 1
  rm -rf -- "${temp_dir}" || { status=$?; trap - EXIT INT TERM HUP; return "${status}"; }
  trap - EXIT INT TERM HUP
  printf '%s\n' "${candidate_json}"
)

